/* 10వ తరగతి – soc పూర్తి పాఠాలు (tools/split/split_class10.py) */
((window.RAAY_TBF=window.RAAY_TBF||{})[10]=window.RAAY_TBF[10]||{})["soc"]=[{"id":"hs1","no":1,"t":"ఐరోపాలో జాతీయవాదం ఆవిర్భావం (The Rise of Nationalism in Europe)","m":[6],"ty":"చరిత్ర – అధ్యాయం 1","by":"సాంఘిక శాస్త్రం – చరిత్ర 10వ తరగతి (పుటలు 2–55)","th":"ఫ్రెంచి విప్లవం, నెపోలియన్ కోడ్, ఉదారవాద జాతీయవాదం, 1830–1848 విప్లవాలు, జర్మనీ–ఇటలీ ఏకీకరణ, బ్రిటన్, బాల్కన్ సమస్య, జాతి దృశ్యీకరణ","sum":"1848లో ఫ్రెడరిక్ సోరియు చిత్రం “ప్రజాస్వామ్య, సామాజిక గణతంత్రాల ప్రపంచ స్వప్నం” – జాతి–రాజ్యాల (nation-states) ఆదర్శ ప్రపంచం. 19వ శతాబ్దంలో ఐరోపాలో జాతీయవాదం బహుళ రాజవంశ సామ్రాజ్యాల స్థానంలో జాతి–రాజ్యాలను తెచ్చింది. జాతీయవాదపు మొదటి స్పష్టమైన వ్యక్తీకరణ 1789 ఫ్రెంచి విప్లవం – సార్వభౌమాధికారం రాజు నుండి పౌరులకు; “పితృభూమి”, “పౌరుడు” భావనలు, త్రివర్ణ పతాకం, జాతీయ సభ, ఏకరీతి కొలతలు, ఫ్రెంచి భాష. నెపోలియన్ 1804 సివిల్ కోడ్ – జన్మ ఆధారిత హక్కుల రద్దు, చట్టం ముందు సమానత్వం, ఆస్తి హక్కు, ఫ్యూడల్ వ్యవస్థ రద్దు, ఏకరీతి కొలతలు, కరెన్సీ – కానీ పన్నులు, సెన్సార్‌షిప్, బలవంతపు సైనిక భర్తీతో వ్యతిరేకత. ఐరోపాలో కులీనులు, రైతులు; కొత్త మధ్యతరగతి ఉదారవాదం (వ్యక్తి స్వేచ్ఛ, చట్టం ముందు సమానత్వం, ఆస్తిపరులకే ఓటు; ఆర్థిక రంగంలో స్వేచ్ఛా మార్కెట్ – జోల్‌వెరీన్ 1834 కస్టమ్స్ యూనియన్). 1815 వియన్నా సమావేశం (మెటర్నిక్) – సంప్రదాయవాదం, బోర్బన్ రాజవంశ పునరుద్ధరణ, సెన్సార్‌షిప్. రహస్య సంఘాలు – గియుసెప్పే మాజినీ (యంగ్ ఇటలీ, యంగ్ యూరప్) – “మన సామాజిక వ్యవస్థకు అత్యంత ప్రమాదకరమైన వ్యక్తి” (మెటర్నిక్). 1830 జూలై విప్లవం (ఫ్రాన్స్), గ్రీకు స్వాతంత్ర్య యుద్ధం (1832 కాన్‌స్టాంటినోపుల్ ఒప్పందం). రొమాంటిసిజం – భాష, జానపద సంస్కృతి ద్వారా జాతీయ భావన (హెర్డర్ – volksgeist, గ్రిమ్ సోదరులు, పోలిష్ భాష). 1848 – ఆకలి, నిరుద్యోగం, సిలేషియా నేతకారుల తిరుగుబాటు (1845); ఉదారవాదుల విప్లవం – ఫ్రాంక్‌ఫర్ట్ పార్లమెంటు (సెయింట్ పాల్ చర్చి) విఫలం, మహిళలకు ఓటు హక్కు నిరాకరణ. జర్మనీ ఏకీకరణ – ప్రష్యా, బిస్మార్క్ (రక్తం–ఇనుము విధానం), ఆస్ట్రియా, డెన్మార్క్, ఫ్రాన్స్‌లతో 3 యుద్ధాలు, 1871 వర్సైల్స్‌లో కైజర్ విలియం I. ఇటలీ ఏకీకరణ – సార్డీనియా–పీడ్‌మాంట్ రాజు విక్టర్ ఇమ్మాన్యుయేల్ II, కావూర్, గారిబాల్డి (ఎర్ర చొక్కాలు), 1861 ఇటలీ రాజు. బ్రిటన్ – క్రమమైన ప్రక్రియ, 1707 Act of Union (ఇంగ్లాండ్–స్కాట్లాండ్), 1801 ఐర్లాండ్ విలీనం – ఆంగ్ల ఆధిపత్యం. జాతిని స్త్రీ రూపంలో – మేరియన్ (ఫ్రాన్స్), జర్మేనియా (జర్మనీ). బాల్కన్ – ఒట్టోమన్ సామ్రాజ్య విచ్ఛిన్నం, స్లావ్ జాతీయవాదం, పెద్ద శక్తుల పోటీ → మొదటి ప్రపంచ యుద్ధం (1914).","pts":["జాతి–రాజ్యం: పౌరులు, పాలకులు ఉమ్మడి గుర్తింపు, చరిత్ర, సంతతి భావన పంచుకునే దేశం.","ఫ్రెంచి విప్లవం (1789): la patrie (పితృభూమి), le citoyen (పౌరుడు), త్రివర్ణ పతాకం, జాతీయ సభ, కొత్త గీతాలు, ఏకరీతి తూనికలు–కొలతలు, అంతర్గత సుంకాల రద్దు, పారిస్ ఫ్రెంచి జాతీయ భాష.","నెపోలియన్ కోడ్ (1804): చట్టం ముందు సమానత్వం, ఆస్తి హక్కు, ఫ్యూడల్ బకాయిల రద్దు, గిల్డ్ ఆంక్షల తొలగింపు, మెరుగైన రవాణా–సమాచారం.","ఉదారవాదం (liber = స్వేచ్ఛ): వ్యక్తి స్వేచ్ఛ, చట్టం ముందు సమానత్వం, రాజ్యాంగం, పార్లమెంటు; కానీ ఓటు ఆస్తిపరులైన పురుషులకే.","జోల్‌వెరీన్ (1834): ప్రష్యా చొరవతో కస్టమ్స్ యూనియన్ – సుంకాల రద్దు, కరెన్సీలు 30 నుండి 2కు.","వియన్నా ఒప్పందం (1815): ఆస్ట్రియా ఛాన్సలర్ మెటర్నిక్ ఆతిథ్యం – బోర్బన్ రాజుల పునరుద్ధరణ, ఫ్రాన్స్ సరిహద్దుల్లో రాజ్యాల ఏర్పాటు; సంప్రదాయవాదం.","మాజినీ (1807–72): కార్బొనారీ, యంగ్ ఇటలీ (మార్సెయిల్స్), యంగ్ యూరప్ (బెర్న్) – ఏకీకృత ఇటాలియన్ గణతంత్రం.","గ్రీకు స్వాతంత్ర్య యుద్ధం (1821–1832): ఒట్టోమన్ పాలనకు వ్యతిరేకం; లార్డ్ బైరన్ మద్దతు; 1832 కాన్‌స్టాంటినోపుల్ ఒప్పందం.","సాంస్కృతిక జాతీయవాదం: రొమాంటిసిజం, హెర్డర్ – జానపద పాటలు, కవిత్వం (das volk); గ్రిమ్ సోదరుల జానపద కథలు; పోలాండ్‌లో పోలిష్ భాష ఆయుధం.","1848: ఉదారవాదుల విప్లవం; ఫ్రాంక్‌ఫర్ట్ పార్లమెంటు (18 మే 1848, 831 ప్రతినిధులు) – ప్రష్యా రాజు ఫ్రెడరిక్ విల్హెల్మ్ IV కిరీటం తిరస్కరణ.","జర్మనీ ఏకీకరణ: ఓటో వాన్ బిస్మార్క్ – ప్రష్యా సైన్యం, అధికార యంత్రాంగం; 1871 జనవరి 18 వర్సైల్స్ – కైజర్ విలియం I.","ఇటలీ ఏకీకరణ: కావూర్ (దౌత్యం, ఫ్రాన్స్‌తో పొత్తు, 1859 ఆస్ట్రియా ఓటమి), గారిబాల్డి (1860 దక్షిణ ఇటలీ, రెండు సిసిలీల రాజ్యం); 1861 విక్టర్ ఇమ్మాన్యుయేల్ II.","బ్రిటన్: 1688 తర్వాత పార్లమెంటు అధికారం; 1707 యాక్ట్ ఆఫ్ యూనియన్ → యునైటెడ్ కింగ్‌డమ్ ఆఫ్ గ్రేట్ బ్రిటన్; 1801 ఐర్లాండ్; యూనియన్ జాక్, “God Save Our Noble King”.","జాతి ప్రతీకలు: మేరియన్ – ఫ్రాన్స్ (ఎర్ర టోపీ, త్రివర్ణం, కాకేడ్); జర్మేనియా – ఓక్ ఆకుల కిరీటం (వీరత్వం).","బాల్కన్: రుమేనియా, బల్గేరియా, గ్రీస్, సెర్బియా... స్లావ్‌లు; ఒట్టోమన్ బలహీనత; రష్యా, జర్మనీ, ఇంగ్లాండ్, ఆస్ట్రియా–హంగేరీ పోటీ → 1914 యుద్ధం."],"w":[["జాతీయవాదం","Nationalism"],["జాతి–రాజ్యం","Nation-state"],["నిరంకుశత్వం","Absolutism"],["ఆదర్శ రాజ్యం","Utopian"],["ప్లెబిసైట్ (ప్రజాభిప్రాయ సేకరణ)","Plebiscite"],["ఉదారవాదం","Liberalism"],["సంప్రదాయవాదం","Conservatism"],["సుంకాల సంఘం","Zollverein (Customs union)"],["రాజకీయ భూస్వాములు (జర్మనీ)","Junkers"],["ప్రజా ఆత్మ","Volksgeist"],["రూపకాలంకారం / ప్రతీక","Allegory"],["జాతి (వర్గం)","Ethnic"],["సైద్ధాంతిక భావజాలం","Ideology"],["సార్వత్రిక వయోజన ఓటు హక్కు","Universal suffrage"],["రొమాంటిసిజం","Romanticism"]],"gr":{"t":"ముఖ్య సంవత్సరాలు","p":["1789 ఫ్రెంచి విప్లవం | 1804 నెపోలియన్ కోడ్ | 1814–15 నెపోలియన్ పతనం, వియన్నా ఒప్పందం","1821 గ్రీకు స్వాతంత్ర్య పోరాటం | 1832 గ్రీస్ స్వతంత్రం | 1834 జోల్‌వెరీన్","1848 ఐరోపాలో విప్లవాలు, ఫ్రాంక్‌ఫర్ట్ పార్లమెంటు | 1859–1870 ఇటలీ ఏకీకరణ | 1861 ఇటలీ రాజ్యం","1866–1871 జర్మనీ ఏకీకరణ | 1871 జనవరి 18 జర్మన్ సామ్రాజ్యం (వర్సైల్స్)","1905 స్లావ్ జాతీయవాదం | 1914 మొదటి ప్రపంచ యుద్ధం"]},"qa":[["ఐరోపాలో జాతీయవాదపు మొదటి స్పష్టమైన వ్యక్తీకరణ ఏది?","1789 ఫ్రెంచి విప్లవం."],["నెపోలియన్ కోడ్ అంటే?","1804 సివిల్ కోడ్ – జన్మ ఆధారిత హక్కుల రద్దు, చట్టం ముందు సమానత్వం, ఆస్తి హక్కు."],["జోల్‌వెరీన్ అంటే?","1834లో ప్రష్యా చొరవతో ఏర్పడిన జర్మన్ రాజ్యాల కస్టమ్స్ యూనియన్ (సుంకాల సంఘం)."],["యంగ్ ఇటలీ స్థాపకుడు?","గియుసెప్పే మాజినీ."],["జర్మనీ ఏకీకరణ రూపశిల్పి?","ప్రష్యా ప్రధాని ఓటో వాన్ బిస్మార్క్."],["ఇటలీ ఏకీకరణకు నాయకత్వం వహించినవారు?","విక్టర్ ఇమ్మాన్యుయేల్ II, కావూర్, గారిబాల్డి (మాజినీ ప్రేరణ)."],["మేరియన్, జర్మేనియా ఎవరు?","ఫ్రాన్స్, జర్మనీ జాతులను సూచించే స్త్రీ రూప ప్రతీకలు."],["ఫ్రాంక్‌ఫర్ట్ పార్లమెంటు ఎక్కడ, ఎప్పుడు సమావేశమైంది?","18 మే 1848న సెయింట్ పాల్ చర్చిలో."],["వియన్నా ఒప్పందం లక్ష్యం?","నెపోలియన్ కాలపు మార్పులను రద్దు చేసి రాజవంశాలను, పాత వ్యవస్థను పునరుద్ధరించడం."],["బాల్కన్ ప్రాంతాన్ని “పౌడర్ కెగ్” అని ఎందుకు అంటారు?","జాతీయవాద ఉద్రిక్తతలు, పెద్ద శక్తుల పోటీ వల్ల ఎప్పుడైనా యుద్ధం పేలే ప్రాంతం కాబట్టి."]],"act":"ఐరోపా పటంలో 1815 వియన్నా ఒప్పందం తర్వాతి సరిహద్దులు, 1871 జర్మనీ, 1861 ఇటలీ గుర్తించండి. మన భారతమాత చిత్రాన్ని జర్మేనియా, మేరియన్‌తో పోల్చి చార్ట్ తయారు చేయండి.","kn":"నెపోలియన్ ఓటమి తర్వాత ఆస్ట్రియా ఛాన్సలర్ మెటర్నిక్ “ఫ్రాన్స్ తుమ్మితే, ఐరోపాకు జలుబు చేస్తుంది” అన్నాడు! ఇటలీ ఏకీకరణకు ముందు ఏడు రాజ్యాలుగా విడిపోయి ఉండేది.","qz":[["ఐరోపాలో జాతీయవాదపు మొదటి స్పష్టమైన వ్యక్తీకరణ?","ఫ్రెంచి విప్లవం (1789)","వియన్నా ఒప్పందం","గ్రీకు యుద్ధం","1848 విప్లవం"],["నెపోలియన్ సివిల్ కోడ్ వచ్చిన సంవత్సరం?","1804","1789","1815","1848"],["జోల్‌వెరీన్ (కస్టమ్స్ యూనియన్) ఏర్పడినది?","1834, ప్రష్యా చొరవతో","1815, ఆస్ట్రియా","1848, ఫ్రాన్స్","1871, ఇటలీ"],["యంగ్ ఇటలీ, యంగ్ యూరప్ సంస్థల స్థాపకుడు?","మాజినీ","కావూర్","గారిబాల్డి","బిస్మార్క్"],["వియన్నా సమావేశానికి ఆతిథ్యం ఇచ్చినది?","మెటర్నిక్","నెపోలియన్","బిస్మార్క్","విక్టర్ ఇమ్మాన్యుయేల్"],["1871లో జర్మన్ చక్రవర్తిగా ప్రకటించబడినది?","కైజర్ విలియం I","ఫ్రెడరిక్ విల్హెల్మ్ IV","బిస్మార్క్","లూయీ ఫిలిప్"],["జర్మనీ ఏకీకరణ ఎక్కడ ప్రకటించారు?","వర్సైల్స్ రాజభవనం","ఫ్రాంక్‌ఫర్ట్","వియన్నా","బెర్లిన్ పార్లమెంటు"],["గారిబాల్డి సైన్యాన్ని ఏమనేవారు?","ఎర్ర చొక్కాలు","నల్ల చొక్కాలు","యంగ్ ఇటలీ","కార్బొనారీ"],["ఫ్రాన్స్‌ను సూచించే స్త్రీ ప్రతీక?","మేరియన్","జర్మేనియా","బ్రిటానియా","భారతమాత"],["గ్రీస్‌కు స్వతంత్ర దేశ గుర్తింపు ఇచ్చిన ఒప్పందం?","కాన్‌స్టాంటినోపుల్ ఒప్పందం (1832)","వియన్నా ఒప్పందం","వర్సైల్స్ ఒప్పందం","పారిస్ ఒప్పందం"],["1707 యాక్ట్ ఆఫ్ యూనియన్ ఏ దేశాలను కలిపింది?","ఇంగ్లాండ్, స్కాట్లాండ్","ఇంగ్లాండ్, ఐర్లాండ్","ఫ్రాన్స్, జర్మనీ","ఇటలీ, సార్డీనియా"],["జానపద పాటలు, కవిత్వం ద్వారా జాతి ఆత్మ (volksgeist) తెలుస్తుందన్నది?","హెర్డర్","మెటర్నిక్","రెనాన్","మాజినీ"],["ఉదారవాదులు ఓటు హక్కు ఎవరికి ఇవ్వాలన్నారు?","ఆస్తిపరులైన పురుషులకు","అందరు వయోజనులకు","మహిళలకు మాత్రమే","రైతులకు"],["ఇటలీ ఏకీకరణకు నాయకత్వం వహించిన రాజ్యం?","సార్డీనియా–పీడ్‌మాంట్","రెండు సిసిలీల రాజ్యం","పాపల్ రాజ్యాలు","వెనీషియా"],["సిలేషియా నేతకారుల తిరుగుబాటు జరిగిన సంవత్సరం?","1845","1848","1830","1815"],["మొదటి ప్రపంచ యుద్ధానికి కారణమైన ప్రాంతం?","బాల్కన్","స్కాండినేవియా","ఐబీరియా","అల్సాస్"]],"wb":{"mis":"ఉదారవాదులు “అందరికీ” ఓటు కోరలేదు – ఆస్తిపరులైన పురుషులకే. జర్మనీ ఏకీకరణ ప్రజా ఉద్యమం కాదు – ప్రష్యా రాచరికం, సైన్యం (బిస్మార్క్) సాధించింది. బ్రిటన్‌లో జాతి–రాజ్యం విప్లవంతో కాదు, దీర్ఘ ప్రక్రియతో ఏర్పడింది.","qz":[],"pg":"2–55","f":"books/10/Class10_Social_History_Textbook.pdf","p":8,"lb":"పాఠ్యపుస్తకం","ws":["కృత్యం – సోరియు చిత్రం (Fig. 1) (పుట 4)","చర్చించండి – రెనాన్ దృష్టిలో జాతి (పుట 6)","చర్చించండి – ఫ్రెడరిక్ లిస్ట్ (జోల్‌వెరీన్) (పుట 18)","కృత్యం, చర్చించండి – వియన్నా ఒప్పందం, ఆలోచనాపరుల క్లబ్ (పుట 20)","చర్చించండి – భాష, జానపద సంప్రదాయాలు (పుట 28)","చర్చించండి, కృత్యం – సిలేషియా నేతకారులు (పుట 30)","చర్చించండి – మహిళల హక్కులపై ముగ్గురు రచయితల వైఖరి (పుట 34)","కృత్యం – బిస్మార్క్ వ్యంగ్య చిత్రం (పుట 38)","కృత్యం – ఇటలీ పటాలు (Fig. 14) (పుట 40)","కృత్యం – గారిబాల్డి వ్యంగ్య చిత్రం (Fig. 15) (పుట 42)","కృత్యం – వీట్ జర్మేనియా, హ్యూబ్నర్ పతన జర్మేనియా (పుట 46)","కృత్యం – ఫ్రాంక్‌ఫర్ట్ పార్లమెంటులో జర్మేనియా బ్యానర్ (పుట 48)","అభ్యాసాలు – Write in brief (1–5) (పుట 54)","అభ్యాసాలు – Discuss (1–5), ప్రాజెక్ట్ (పుట 54)"]},"tg":[["కృత్యం – సోరియు చిత్రం (Fig. 1) (పుట 4)",["సోరియు చిత్రంలో అన్ని దేశాల ప్రజలు తమ జాతీయ జెండాలతో స్వేచ్ఛా విగ్రహానికి నమస్కరిస్తూ ఊరేగింపుగా వెళ్తారు; కింద రాచరిక చిహ్నాలు ధ్వంసమై ఉంటాయి; పైన స్వర్గం నుండి క్రీస్తు, సాధువులు, దేవదూతలు చూస్తుంటారు. ప్రపంచమంతా స్వతంత్ర, ప్రజాస్వామ్య జాతి–రాజ్యాలుగా ఐక్యంగా ఉండటం – ఇది వాస్తవంలో లేని ఆదర్శ (utopian) దృశ్యం."]],["చర్చించండి – రెనాన్ దృష్టిలో జాతి (పుట 6)",["ఎర్నెస్ట్ రెనాన్ ప్రకారం జాతి ఒకే భాష, జాతి, మతం, భూభాగంతో ఏర్పడదు. అది సుదీర్ఘ ప్రయత్నాలు, త్యాగాలు, అంకితభావాల పరాకాష్ఠ; గతంలో ఉమ్మడి వీరోచిత వారసత్వం, వర్తమానంలో కలిసి జీవించాలనే ఉమ్మడి సంకల్పం ఉండాలి – జాతి ఉనికి “రోజువారీ ప్రజాభిప్రాయ సేకరణ (plebiscite)”. జాతులు ముఖ్యం ఎందుకంటే అవి స్వేచ్ఛకు హామీ; జాతులు లేకపోతే స్వేచ్ఛ అంతరిస్తుంది."]],["చర్చించండి – ఫ్రెడరిక్ లిస్ట్ (జోల్‌వెరీన్) (పుట 18)",["లిస్ట్ కస్టమ్స్ యూనియన్ (జోల్‌వెరీన్) ద్వారా జర్మన్ ప్రజలను ఆర్థికంగా ఒక జాతిగా బంధించాలని ఆశించాడు. సుంకాల అడ్డంకులు తొలగితే వస్తువులు, మనుషులు, మూలధనం స్వేచ్ఛగా తిరిగి, ఏకీకృత మార్కెట్ ఏర్పడుతుంది; ఆర్థిక ఐక్యత జాతీయ భావనను బలపరిచి, రాజకీయ ఏకీకరణకు దారితీస్తుంది – ఇదే అతని రాజకీయ లక్ష్యం."]],["కృత్యం, చర్చించండి – వియన్నా ఒప్పందం, ఆలోచనాపరుల క్లబ్ (పుట 20)",["కృత్యం (పటం): ఫ్రాన్స్‌లో బోర్బన్ రాజవంశం పునరుద్ధరణ; ఉత్తర సరిహద్దులో నెదర్లాండ్స్ రాజ్యం (బెల్జియంతో), దక్షిణాన పీడ్‌మాంట్‌కు జెనోవా; ప్రష్యాకు పశ్చిమ సరిహద్దులోని ముఖ్య భూభాగాలు; ఆస్ట్రియాకు ఉత్తర ఇటలీ; 39 రాజ్యాల జర్మన్ సమాఖ్య యథాతథం; రష్యాకు పోలాండ్‌లో భాగం, ప్రష్యాకు సాక్సనీలో భాగం.","చర్చ (Fig. 6): వ్యంగ్య చిత్రకారుడు నోటికి తాళాలు వేసుకున్న “ఆలోచనాపరుల క్లబ్” ద్వారా సంప్రదాయవాద ప్రభుత్వాల సెన్సార్‌షిప్, మాట్లాడే–ఆలోచించే స్వేచ్ఛ అణచివేతను ఎగతాళి చేస్తున్నాడు – “ఈ రోజు ఎంతసేపు ఆలోచించడానికి అనుమతి?”."]],["చర్చించండి – భాష, జానపద సంప్రదాయాలు (పుట 28)",["రొమాంటిక్ కళాకారులు, కవులు ఉమ్మడి సాంస్కృతిక గతాన్ని గుర్తుచేసి జాతీయ భావన పెంచారు. హెర్డర్ – నిజమైన జర్మన్ సంస్కృతి సామాన్య ప్రజల జానపద పాటలు, కవిత్వం, నృత్యాల్లో ఉంటుంది. గ్రిమ్ సోదరులు జానపద కథలు సేకరించారు. రష్యా ఆక్రమణలో పోలాండ్‌లో పోలిష్ భాషను ప్రతిఘటన ఆయుధంగా వాడారు – చర్చిలో పోలిష్ ప్రార్థనలు; కరోల్ కుర్పిన్స్కీ ఒపేరాలు, జానపద నృత్యాలు (పొలొనైస్, మజుర్కా). ఇలా భాష, సంప్రదాయాలు జాతి ఐక్యతకు పునాది అయ్యాయి."]],["చర్చించండి, కృత్యం – సిలేషియా నేతకారులు (పుట 30)",["కారణం: కాంట్రాక్టర్లు ముడిసరుకు ఇచ్చి నేసిన వస్త్రానికి అతి తక్కువ ధర చెల్లించారు; కూలి పెంచమన్న అభ్యర్థనను తిరస్కరించి అవమానించారు. పత్రికా విలేఖరి విల్హెల్మ్ వోల్ఫ్ నేతకారుల దుర్భర పరిస్థితి, కాంట్రాక్టర్ల క్రూరత్వం పట్ల సానుభూతితో రాశాడు – సైన్యం కాల్పుల్లో 11 మంది మరణం.","కృత్యం (నేతకారుని నివేదిక): 4 జూన్ 1845 – మేము కూలి పెంచమని కాంట్రాక్టర్ ఇంటికి గుంపుగా వెళ్ళాం. అతను మమ్మల్ని అవమానించి బెదిరించాడు. కోపంతో కిటికీలు, ఫర్నిచర్ ధ్వంసమయ్యాయి. అతను పారిపోయి సైన్యాన్ని తెచ్చాడు. కాల్పుల్లో పదకొండు మంది నా తోటి నేతకారులు మరణించారు. మా ఆకలి, కష్టం ఎవరికీ పట్టలేదు."]],["చర్చించండి – మహిళల హక్కులపై ముగ్గురు రచయితల వైఖరి (పుట 34)",["కార్ల్ వెల్కర్ – స్త్రీలు బలహీనులు, ఇంటికే పరిమితం, పురుషులు రక్షకులు; రాజకీయ హక్కులు అవసరం లేదు. లూయిస్ ఓటో-పీటర్స్ – స్వేచ్ఛ అవిభాజ్యం, మహిళలకూ సమాన హక్కులు కావాలి. ఒక పేరు లేని పాఠకురాలు – మహిళలు కష్టపడి పనిచేస్తూ, పన్నులు కడుతున్నా ఓటు హక్కు లేదు, ఇది అన్యాయం. దీని ద్వారా ఉదారవాద భావజాలంలోని వైరుధ్యం తెలుస్తుంది – అది స్వేచ్ఛ, సమానత్వం అని చెప్పినా మహిళలకు రాజకీయ హక్కులు నిరాకరించింది."]],["కృత్యం – బిస్మార్క్ వ్యంగ్య చిత్రం (పుట 38)",["చిత్రంలో బిస్మార్క్ కొరడా పట్టుకుని నిలుచుని ఉంటాడు; పార్లమెంటు సభ్యులు భయంతో బల్లల కింద దాక్కుంటారు. బిస్మార్క్ పార్లమెంటును లెక్కచేయకుండా నియంతలా పాలించాడని, ఎన్నికైన ప్రతినిధులు నిస్సహాయులని, జర్మనీలో ప్రజాస్వామ్యం కేవలం పేరుకే అని చిత్రకారుడు చూపుతున్నాడు."]],["కృత్యం – ఇటలీ పటాలు (Fig. 14) (పుట 40)",["Fig. 14(a): 1858లో ఇటలీ ఏడు రాజ్యాలుగా ఉంది; ప్రజలు ఎక్కువగా తమ ప్రాంతీయ గుర్తింపుతోనే (ఇటాలియన్‌గా కాదు) ఉన్నారు, చాలామందికి ఇటాలియన్ భాష కూడా రాదు. Fig. 14(b): మొదట ఏకీకృత ఇటలీలో భాగమైంది సార్డీనియా–పీడ్‌మాంట్ (1858కి ముందు); చివరిగా చేరింది పాపల్ రాజ్యాలు/రోమ్ (1870); అత్యధిక రాజ్యాలు చేరింది 1860లో."]],["కృత్యం – గారిబాల్డి వ్యంగ్య చిత్రం (Fig. 15) (పుట 42)",["ఇటలీ పటం బూటు ఆకారంలో ఉంటుంది. గారిబాల్డి దక్షిణ ఇటలీ (బూటు కింది భాగం)ని జయించి, సార్డీనియా రాజు విక్టర్ ఇమ్మాన్యుయేల్ II కు “ఇటలీ” బూటు తొడగడంలో సహాయం చేస్తున్నాడు – అంటే ఇటలీ ఏకీకరణలో గారిబాల్డి పాత్ర కీలకమైనా, ఆ ఫలం (అధికారం) సార్డీనియా రాజుకు దక్కింది; ఏకీకరణ పై నుండి రాచరికం ద్వారా జరిగింది."]],["కృత్యం – వీట్ జర్మేనియా, హ్యూబ్నర్ పతన జర్మేనియా (పుట 46)",["వీట్ జర్మేనియా (1848): విరిగిన సంకెళ్ళు – విముక్తి; గద్దతో కవచం – జర్మన్ సామ్రాజ్య శక్తి; ఓక్ ఆకుల కిరీటం – వీరత్వం; కత్తి – పోరాటానికి సిద్ధం; కత్తి చుట్టూ ఆలివ్ కొమ్మ – శాంతి కోరిక; నలుపు–ఎరుపు–బంగారు త్రివర్ణం – ఉదారవాద జాతీయవాదుల జెండా; ఉదయించే సూర్యుని కిరణాలు – కొత్త యుగ ఆరంభం. 1836లో సంకెళ్ళు విరగడం (విముక్తి) చూపగా, 1848లో జర్మేనియా ఆయుధాలతో జాతిని రక్షించే శక్తిగా – స్వేచ్ఛ సాధించాక జాతి నిర్మాణం వైపు మార్పు.","Fig. 18 (హ్యూబ్నర్, 1850): జర్మేనియా కిరీటం, జెండా కింద పడిపోయి, నిరాశతో కూలబడి ఉంటుంది. ఇది 1848 ఉదారవాదుల విప్లవ వైఫల్యాన్ని, ఫ్రాంక్‌ఫర్ట్ పార్లమెంటు రద్దు, రాచరిక శక్తుల అణచివేతను సూచిస్తుంది."]],["కృత్యం – ఫ్రాంక్‌ఫర్ట్ పార్లమెంటులో జర్మేనియా బ్యానర్ (పుట 48)",["(a) డిప్యూటీగా పురుషుడు: జర్మేనియా బ్యానర్ చూసి గర్వం, ఉత్సాహం – మేమే ఏకీకృత, ఉదారవాద జర్మనీకి రాజ్యాంగం రాస్తున్నామనే భావన. (b) గ్యాలరీలో మహిళగా: జర్మేనియా స్త్రీ రూపంలో జాతికి ప్రతీక అయినా, మహిళలకు ఓటు, సభలో స్థానం లేవు – కేవలం ప్రేక్షకురాలిగా ఉండాల్సి వచ్చిన బాధ, వైరుధ్యం."]],["అభ్యాసాలు – Write in brief (1–5) (పుట 54)",["1) a) మాజినీ (1807–72): జెనోవాలో జన్మించిన ఇటాలియన్ విప్లవకారుడు; కార్బొనారీ సభ్యుడు; యంగ్ ఇటలీ (మార్సెయిల్స్), యంగ్ యూరప్ (బెర్న్) స్థాపకుడు; దేవుడు మానవాళిని జాతులుగా ఏర్పరిచాడని, ఇటలీ ఏకీకృత గణతంత్రం కావాలని నమ్మాడు; మెటర్నిక్ అతన్ని “అత్యంత ప్రమాదకర వ్యక్తి” అన్నాడు.","b) కావూర్: సార్డీనియా–పీడ్‌మాంట్ ప్రధాని; విప్లవకారుడు కాదు; దౌత్యంతో ఫ్రాన్స్‌తో పొత్తు పెట్టుకుని 1859లో ఆస్ట్రియాను ఓడించి ఇటలీ ఏకీకరణకు బాట వేశాడు.","c) గ్రీకు స్వాతంత్ర్య యుద్ధం: 1821 నుండి ఒట్టోమన్ పాలనకు వ్యతిరేకం; ప్రవాస గ్రీకులు, ప్రాచీన గ్రీకు సంస్కృతిని ఆరాధించే పశ్చిమ ఐరోపా కవులు (లార్డ్ బైరన్) మద్దతు; 1832 కాన్‌స్టాంటినోపుల్ ఒప్పందంతో స్వతంత్ర దేశం.","d) ఫ్రాంక్‌ఫర్ట్ పార్లమెంటు: 18 మే 1848న సెయింట్ పాల్ చర్చిలో 831 మంది ఎన్నికైన ప్రతినిధులు; రాచరిక జర్మన్ రాజ్యాంగం రాసి ప్రష్యా రాజు ఫ్రెడరిక్ విల్హెల్మ్ IV కి కిరీటం ఇవ్వజూపారు – అతను తిరస్కరించాడు; మధ్యతరగతి ఆధిపత్యం, కార్మికులు–మహిళల పట్ల వివక్ష; చివరికి సైన్యంతో రద్దు.","e) మహిళల పాత్ర: రాజకీయ సంఘాలు, వార్తాపత్రికలు స్థాపించారు, ప్రదర్శనల్లో పాల్గొన్నారు; అయినా ఓటు హక్కు, సభలో స్థానం నిరాకరించబడ్డాయి – ఫ్రాంక్‌ఫర్ట్‌లో గ్యాలరీలో ప్రేక్షకులుగానే.","2) la patrie (పితృభూమి), le citoyen (పౌరుడు) భావనలు; కొత్త త్రివర్ణ పతాకం; Estates General ను జాతీయ సభగా మార్చడం; కొత్త గీతాలు, ప్రమాణాలు, అమరవీరుల స్మరణ; కేంద్రీకృత పాలన, అందరికీ ఒకే చట్టాలు; అంతర్గత సుంకాల రద్దు, ఏకరీతి తూనికలు–కొలతలు; ప్రాంతీయ మాండలికాలను తగ్గించి పారిస్ ఫ్రెంచిని జాతీయ భాషగా ప్రోత్సహించడం.","3) మేరియన్ – ఫ్రెంచి జాతికి, జర్మేనియా – జర్మన్ జాతికి స్త్రీ రూప ప్రతీకలు. మేరియన్‌కు ఎర్ర టోపీ, త్రివర్ణం, కాకేడ్ – స్వేచ్ఛ, గణతంత్రం; ఆమె విగ్రహాలు బహిరంగ స్థలాల్లో, నాణేలు–స్టాంపులపై. జర్మేనియాకు ఓక్ ఆకుల కిరీటం (వీరత్వం), కత్తి. ప్రాముఖ్యం: జాతి అనే అమూర్త భావనను ప్రజలకు అర్థమయ్యే దృశ్య రూపంలో చూపి, ఐక్యత, దేశభక్తి పెంచాయి.","4) 1848లో ఉదారవాదుల ఫ్రాంక్‌ఫర్ట్ పార్లమెంటు ఏకీకరణ ప్రయత్నం విఫలం. తర్వాత ప్రష్యా నాయకత్వం వహించింది. ప్రధాని బిస్మార్క్ ప్రష్యా సైన్యం, అధికార యంత్రాంగం సహాయంతో ఏడేళ్లలో ఆస్ట్రియా, డెన్మార్క్, ఫ్రాన్స్‌లతో మూడు యుద్ధాలు చేసి గెలిచాడు. 1871 జనవరి 18న వర్సైల్స్ అద్దాల మందిరంలో ప్రష్యా రాజు విలియం I జర్మన్ చక్రవర్తి (కైజర్)గా ప్రకటించబడ్డాడు. కొత్త రాజ్యం కరెన్సీ, బ్యాంకింగ్, చట్టాలు, న్యాయవ్యవస్థను ఆధునీకరించింది.","5) నెపోలియన్ కోడ్ (1804) – జన్మ ఆధారిత ప్రత్యేక హక్కుల రద్దు, చట్టం ముందు సమానత్వం, ఆస్తి హక్కు; డచ్ రిపబ్లిక్, స్విట్జర్లాండ్, ఇటలీ, జర్మనీలలో పాలనా విభాగాల సరళీకరణ; ఫ్యూడల్ వ్యవస్థ రద్దు, రైతులకు బానిసత్వం, భూస్వామ్య బకాయిల నుండి విముక్తి; పట్టణాల్లో గిల్డ్ ఆంక్షల తొలగింపు; రవాణా, సమాచార వ్యవస్థల మెరుగుదల; ఏకరీతి తూనికలు, కొలతలు, జాతీయ కరెన్సీ."]],["అభ్యాసాలు – Discuss (1–5), ప్రాజెక్ట్ (పుట 54)",["1) 1848 ఉదారవాదుల విప్లవం: రైతులు, కార్మికుల తిరుగుబాట్లతో పాటు విద్యావంతులైన మధ్యతరగతి ఉదారవాదులు జాతీయ ఐక్యత, రాజ్యాంగం, పార్లమెంటు కోసం చేసిన విప్లవం (ఫ్రాన్స్‌లో గణతంత్రం, జర్మనీలో ఫ్రాంక్‌ఫర్ట్ పార్లమెంటు). రాజకీయ భావాలు – ప్రజల సమ్మతితో ప్రభుత్వం, నిరంకుశత్వం–మతాధిపతుల ప్రత్యేక హక్కుల రద్దు, రాజ్యాంగం, ప్రాతినిధ్య ప్రభుత్వం; సామాజిక – చట్టం ముందు సమానత్వం, వ్యక్తి స్వేచ్ఛ, పత్రికా స్వేచ్ఛ (కానీ ఆస్తిపరులకే ఓటు); ఆర్థిక – స్వేచ్ఛా మార్కెట్, వస్తువులు–మూలధనాల స్వేచ్ఛా రవాణా, రాజ్య ఆంక్షల తొలగింపు, సుంకాల రద్దు (జోల్‌వెరీన్).","2) (i) రొమాంటిసిజం – హెర్డర్, గ్రిమ్ సోదరుల జానపద పాటలు, కథల సేకరణ ద్వారా జర్మన్ జాతీయ ఆత్మను చాటడం. (ii) పోలాండ్‌లో రష్యా ఆధిపత్యానికి వ్యతిరేకంగా పోలిష్ భాష, సంగీతం (కుర్పిన్స్కీ ఒపేరాలు, పొలొనైస్, మజుర్కా నృత్యాలు). (iii) గ్రీకు యుద్ధంలో కవులు, కళాకారులు గ్రీస్‌ను ఐరోపా నాగరికత జన్మస్థలంగా కీర్తించడం; యూజీన్ డెలక్రోయా “కియోస్ ఊచకోత” చిత్రం. ఇంకా – మేరియన్, జర్మేనియా ప్రతీకలు.","3) జర్మనీ: 1848 ఉదారవాద ప్రయత్నం విఫలం → ప్రష్యా, బిస్మార్క్ “రక్తం–ఇనుము” విధానం → 3 యుద్ధాలు → 1871 జర్మన్ సామ్రాజ్యం (పై నుండి, సైనిక శక్తితో). ఇటలీ: 7 రాజ్యాలుగా విభజన → మాజినీ విప్లవ ప్రయత్నాలు విఫలం → సార్డీనియా–పీడ్‌మాంట్ రాజు విక్టర్ ఇమ్మాన్యుయేల్ II, కావూర్ దౌత్యం (ఫ్రాన్స్‌తో పొత్తు, 1859 ఆస్ట్రియా ఓటమి) → 1860 గారిబాల్డి ఎర్ర చొక్కాల దక్షిణ ఇటలీ విజయం → 1861 ఇటలీ రాజ్యం → 1870 రోమ్ విలీనం.","4) బ్రిటన్‌లో జాతి–రాజ్యం ఆకస్మిక విప్లవం/తిరుగుబాటుతో కాదు, దీర్ఘకాలిక ప్రక్రియతో ఏర్పడింది. 1688 తర్వాత ఇంగ్లాండ్ పార్లమెంటు అధికారం చేజిక్కించుకుని ఇంగ్లాండ్ ఆధిపత్యంలో జాతిని నిర్మించింది. 1707 యాక్ట్ ఆఫ్ యూనియన్ (స్కాట్లాండ్) – స్కాటిష్ సంస్కృతి, గేలిక్ భాష అణచివేత; 1801 ఐర్లాండ్ బలవంతపు విలీనం (కాథలిక్ తిరుగుబాట్ల అణచివేత). కొత్త “బ్రిటిష్” జాతి – యూనియన్ జాక్, జాతీయ గీతం, ఆంగ్ల భాష – ఆంగ్ల సంస్కృతి ఆధిపత్యంలో రూపొందింది.","5) బాల్కన్‌లో (నేటి రుమేనియా, బల్గేరియా, అల్బేనియా, గ్రీస్, మాసిడోనియా, క్రొయేషియా, బోస్నియా–హెర్జెగోవినా, స్లొవేనియా, సెర్బియా, మాంటెనెగ్రో) వివిధ జాతుల ప్రజలు – స్లావ్‌లు. ఒట్టోమన్ సామ్రాజ్యం బలహీనపడటంతో రొమాంటిక్ జాతీయవాద భావనలు వ్యాపించి ఒక్కొక్క జాతి స్వాతంత్ర్యం కోరింది; గతంలో స్వతంత్రంగా ఉన్నామని వాదించాయి. రాజ్యాలు ఒకదానిపై ఒకటి అసూయతో ఎక్కువ భూభాగం కోరాయి. అదే సమయంలో రష్యా, జర్మనీ, ఇంగ్లాండ్, ఆస్ట్రియా–హంగేరీ పెద్ద శక్తులు తమ ఆధిపత్యం కోసం పోటీపడ్డాయి – ఇది వరుస యుద్ధాలకు, చివరికి మొదటి ప్రపంచ యుద్ధానికి (1914) దారితీసింది.","ప్రాజెక్ట్: భారత్ – భారతమాత చిత్రం, త్రివర్ణ పతాకం, “వందేమాతరం”; ఇండోనేషియా/వియత్నాం – జాతీయ పతాకాలు, పోస్టర్లు. తేడా: ఐరోపా ప్రతీకలు ఎక్కువగా ఏకీకరణ, రాజ్య శక్తిని చూపగా, వలస దేశాల ప్రతీకలు వలస పాలనకు వ్యతిరేక పోరాటం, స్వదేశీ సంస్కృతిని చూపుతాయి."]]]},{"id":"hs2","no":2,"t":"భారతదేశంలో జాతీయవాదం (Nationalism in India)","m":[7],"ty":"చరిత్ర – అధ్యాయం 2","by":"సాంఘిక శాస్త్రం – చరిత్ర 10వ తరగతి (పుటలు 56–99)","th":"మొదటి ప్రపంచ యుద్ధం, సత్యాగ్రహం, రౌలట్ చట్టం, జలియన్‌వాలా బాగ్, ఖిలాఫత్, సహాయ నిరాకరణ, శాసనోల్లంఘన, ఉప్పు సత్యాగ్రహం, సామూహిక ఐక్యతా భావన","sum":"భారత్‌లో ఆధునిక జాతీయవాదం వలసవాద వ్యతిరేక ఉద్యమంతో ముడిపడి ఉంది – వలస పాలనలో అణచివేత అనుభవం ప్రజలను ఏకం చేసింది. మొదటి ప్రపంచ యుద్ధం (1914–18) – రక్షణ ఖర్చు, పన్నులు, ధరలు రెట్టింపు, బలవంతపు సైనిక భర్తీ, పంటల వైఫల్యం, ఇన్‌ఫ్లుయెంజా – ప్రజల్లో ఆగ్రహం. గాంధీజీ జనవరి 1915లో దక్షిణాఫ్రికా నుండి వచ్చి సత్యాగ్రహం (సత్యం, అహింస) ప్రవేశపెట్టారు – చంపారన్ (1917, నీలిమందు రైతులు), ఖేడా (1917, పన్ను మినహాయింపు), అహ్మదాబాద్ (1918, పత్తి మిల్లు కార్మికులు). రౌలట్ చట్టం (1919) – విచారణ లేకుండా రెండేళ్ల నిర్బంధం; 6 ఏప్రిల్ హర్తాళ్; 13 ఏప్రిల్ 1919 జలియన్‌వాలా బాగ్ ఊచకోత (జనరల్ డయ్యర్). ఖిలాఫత్ ఉద్యమం (మహమ్మద్ అలీ, షౌకత్ అలీ) – హిందూ–ముస్లిం ఐక్యత. సహాయ నిరాకరణ ఉద్యమం (1920 నాగ్‌పూర్ కాంగ్రెస్ ఆమోదం, జనవరి 1921) – బిరుదులు త్యజించడం, ప్రభుత్వ సేవలు, సైన్యం, పోలీసు, కోర్టులు, శాసనసభలు, పాఠశాలలు, విదేశీ వస్తువుల బహిష్కరణ. పట్టణాల్లో – విదేశీ వస్త్ర దహనం, ఖాదీ; గ్రామాల్లో – అవధ్ రైతులు (బాబా రామ్‌చంద్ర, తాలూక్దార్లకు వ్యతిరేకం), ఆంధ్రలో గూడెం కొండల గిరిజనులు (అల్లూరి సీతారామరాజు – గెరిల్లా పోరాటం, 1924 ఉరి), అస్సాం తేయాకు తోటల కార్మికులు – ప్రతి వర్గం స్వరాజ్యాన్ని తమ దృష్టితో అర్థం చేసుకుంది. ఫిబ్రవరి 1922 చౌరీచౌరా హింస తర్వాత గాంధీజీ ఉద్యమం విరమించారు. స్వరాజ్ పార్టీ (C.R. దాస్, మోతీలాల్ నెహ్రూ). సైమన్ కమిషన్ (1928) – “సైమన్ గో బ్యాక్”; 1929 లాహోర్ కాంగ్రెస్ (నెహ్రూ) – పూర్ణ స్వరాజ్, 26 జనవరి 1930 స్వాతంత్ర్య దినం. ఉప్పు సత్యాగ్రహం – 11 డిమాండ్లు, సబర్మతి నుండి దండి 240 మైళ్లు (12 మార్చి – 6 ఏప్రిల్ 1930) – శాసనోల్లంఘన ఉద్యమం; ధనిక రైతులు, పేద రైతులు, వ్యాపారులు, కార్మికులు, మహిళలు పాల్గొన్నారు; గాంధీ–ఇర్విన్ ఒప్పందం (5 మార్చి 1931), రెండో రౌండ్ టేబుల్ సమావేశం విఫలం. దళితులు (అంబేద్కర్ – ప్రత్యేక నియోజకవర్గాలు, 1932 పూనా ఒప్పందం), ముస్లిం సంఘాల దూరం (ఇక్బాల్, 1930 ముస్లిం లీగ్). సామూహిక ఐక్యతా భావన – భారతమాత (బంకించంద్ర “వందేమాతరం”, అబనీంద్రనాథ్ ఠాగూర్ చిత్రం), జానపద కథలు, త్రివర్ణ పతాకం (స్వరాజ్ పతాకం 1921), చరిత్ర పునర్వ్యాఖ్యానం.","pts":["వలస దేశాల్లో జాతీయవాదం = వలసవాద వ్యతిరేక ఉద్యమం; అణచివేత అనుభవమే ప్రజలను ఏకం చేసింది.","మొదటి ప్రపంచ యుద్ధ ప్రభావం: రక్షణ ఖర్చు, కస్టమ్స్ సుంకాలు, ఆదాయపు పన్ను; 1913–18 ధరలు రెట్టింపు; గ్రామాల్లో బలవంతపు సైనిక భర్తీ; 1918–21 పంటల వైఫల్యం, ఇన్‌ఫ్లుయెంజా – 1.2–1.3 కోట్ల మరణాలు.","సత్యాగ్రహం: సత్యం కోసం పోరాటం; ప్రతీకారం, దౌర్జన్యం లేకుండా అహింసతో అణచివేతదారుని మనసు మార్చడం.","చంపారన్ (బీహార్, 1917) – నీలిమందు రైతులు; ఖేడా (గుజరాత్, 1917) – పన్ను వసూలు సడలింపు; అహ్మదాబాద్ (1918) – మిల్లు కార్మికులు.","రౌలట్ చట్టం (1919): రాజకీయ ఖైదీలను విచారణ లేకుండా రెండేళ్లు నిర్బంధం; 6 ఏప్రిల్ హర్తాళ్.","జలియన్‌వాలా బాగ్ (అమృత్‌సర్, 13 ఏప్రిల్ 1919, బైసాఖీ): జనరల్ డయ్యర్ నిరాయుధ ప్రజలపై కాల్పులు – వందల మంది మృతి.","ఖిలాఫత్ ఉద్యమం (1919, మహమ్మద్ అలీ, షౌకత్ అలీ): ఒట్టోమన్ ఖలీఫాకు మద్దతు – గాంధీజీ హిందూ–ముస్లిం ఐక్యతకు అవకాశంగా భావించారు.","సహాయ నిరాకరణ (1921–22): “హింద్ స్వరాజ్” (1909) – భారతీయుల సహకారంతోనే బ్రిటిష్ పాలన నిలిచింది; బిరుదులు, సేవలు, సంస్థలు, విదేశీ వస్తువుల బహిష్కరణ.","అల్లూరి సీతారామరాజు: ఆంధ్ర గూడెం కొండల్లో గిరిజన గెరిల్లా తిరుగుబాటు (1920ల ప్రారంభం); అడవి చట్టాలు, వెట్టిచాకిరికి వ్యతిరేకం; 1924లో పట్టుబడి ఉరితీయబడ్డారు.","చౌరీచౌరా (గోరఖ్‌పూర్, ఫిబ్రవరి 1922): హింసాత్మక ఘటన – ఉద్యమ విరమణ.","సైమన్ కమిషన్ (1928): ఒక్క భారతీయుడూ లేడు – “సైమన్ గో బ్యాక్”; లాహోర్ కాంగ్రెస్ (డిసెంబర్ 1929, నెహ్రూ) – పూర్ణ స్వరాజ్.","ఉప్పు సత్యాగ్రహం: 31 జనవరి 1930 ఇర్విన్‌కు 11 డిమాండ్లు; 78 మంది వాలంటీర్లతో సబర్మతి–దండి 240 మైళ్లు, 24 రోజులు; 6 ఏప్రిల్ 1930 ఉప్పు తయారీ.","పూనా ఒప్పందం (సెప్టెంబర్ 1932): అణగారిన వర్గాలకు కేంద్ర, రాష్ట్ర శాసనసభల్లో రిజర్వుడు స్థానాలు, కానీ సాధారణ ఓటర్ల ద్వారా ఎన్నిక.","భారతమాత: బంకించంద్ర “వందేమాతరం” (1870లు, ఆనందమఠ్); అబనీంద్రనాథ్ ఠాగూర్ చిత్రం – సన్యాసినిలా; స్వరాజ్ పతాకం (1921, గాంధీజీ) – త్రివర్ణం, మధ్యలో రాట్నం.","జానపద సంప్రదాయాలు: రవీంద్రనాథ్ ఠాగూర్ (బెంగాల్), నటేశ శాస్త్రి (“The Folklore of Southern India” – తమిళం) – జాతీయ గుర్తింపు కోసం జానపద కథల సేకరణ."],"w":[["సత్యాగ్రహం","Satyagraha"],["హర్తాళ్","Hartal (general strike)"],["సహాయ నిరాకరణ","Non-Cooperation"],["శాసనోల్లంఘన","Civil Disobedience"],["పూర్ణ స్వరాజ్యం","Purna Swaraj"],["బహిష్కరణ","Boycott"],["ఖిలాఫత్","Khilafat"],["వెట్టిచాకిరి","Begar (forced labour)"],["పికెటింగ్","Picketing"],["బలవంతపు సైనిక భర్తీ","Forced recruitment"],["ఒప్పంద కూలీ","Indentured labour"],["ప్రత్యేక నియోజకవర్గాలు","Separate electorates"],["మతతత్వం","Communalism"],["భారతమాత","Bharat Mata"],["జానపద సాహిత్యం","Folklore"]],"gr":{"t":"ముఖ్య సంవత్సరాలు","p":["1915 జనవరి – గాంధీజీ భారత్‌కు | 1917 చంపారన్, ఖేడా | 1918 అహ్మదాబాద్","1919 – రౌలట్ చట్టం, 13 ఏప్రిల్ జలియన్‌వాలా బాగ్, ఖిలాఫత్ కమిటీ","1920 సెప్టెంబర్ కలకత్తా, డిసెంబర్ నాగ్‌పూర్ కాంగ్రెస్ – సహాయ నిరాకరణ | 1921 జనవరి ఉద్యమ ఆరంభం | 1922 ఫిబ్రవరి చౌరీచౌరా – విరమణ","1928 సైమన్ కమిషన్ | 1929 డిసెంబర్ లాహోర్ – పూర్ణ స్వరాజ్ | 1930 జనవరి 26 స్వాతంత్ర్య దినం","1930 మార్చి 12 – ఏప్రిల్ 6 దండి యాత్ర | 1931 మార్చి 5 గాంధీ–ఇర్విన్ ఒప్పందం, డిసెంబర్ రెండో రౌండ్ టేబుల్ | 1932 పూనా ఒప్పందం | 1934 శాసనోల్లంఘన ముగింపు"]},"qa":[["సత్యాగ్రహం అంటే ఏమిటి?","సత్యం, అహింసల ఆధారంగా ప్రతీకారం లేకుండా, అణచివేతదారుని మనసును ఆకర్షించి మార్చే పోరాట పద్ధతి."],["రౌలట్ చట్టం ఎందుకు భారతీయులకు ఆగ్రహం తెప్పించింది?","భారత సభ్యుల వ్యతిరేకత ఉన్నా ఆమోదించి, రాజకీయ కార్యకలాపాలను అణచడానికి, విచారణ లేకుండా రెండేళ్లు నిర్బంధానికి అధికారం ఇచ్చింది."],["జలియన్‌వాలా బాగ్ ఊచకోత ఎప్పుడు జరిగింది?","13 ఏప్రిల్ 1919, అమృత్‌సర్ – జనరల్ డయ్యర్ కాల్పులు."],["గాంధీజీ సహాయ నిరాకరణ ఉద్యమాన్ని ఎందుకు విరమించారు?","ఫిబ్రవరి 1922 చౌరీచౌరా హింస; ఉద్యమం హింసాత్మకమవుతోందని, సత్యాగ్రహులకు ఇంకా శిక్షణ అవసరమని భావించారు."],["సైమన్ కమిషన్‌ను ఎందుకు బహిష్కరించారు?","దానిలో ఒక్క భారతీయ సభ్యుడూ లేడు."],["పూర్ణ స్వరాజ్ డిమాండ్ ఎప్పుడు?","డిసెంబర్ 1929 లాహోర్ కాంగ్రెస్ (నెహ్రూ అధ్యక్షత); 26 జనవరి 1930 స్వాతంత్ర్య దినం."],["ఉప్పు సత్యాగ్రహం ఎందుకు ప్రభావవంతమైన ప్రతీక?","ఉప్పు ధనిక–పేద అందరూ వాడే నిత్యావసరం; దానిపై పన్ను బ్రిటిష్ పాలన అణచివేత ముఖమని అందరికీ అర్థమైంది."],["పూనా ఒప్పందం ఎవరి మధ్య?","గాంధీజీ, డా. బి.ఆర్. అంబేద్కర్ (1932)."],["అల్లూరి సీతారామరాజు ఎక్కడ ఉద్యమం నడిపారు?","ఆంధ్రప్రదేశ్ గూడెం కొండలు (విశాఖ మన్యం) – గిరిజన గెరిల్లా ఉద్యమం."],["భారతమాత చిత్రాన్ని మొదట చిత్రించినది?","అబనీంద్రనాథ్ ఠాగూర్."]],"act":"దండి యాత్ర మార్గాన్ని (సబర్మతి–దండి) భారత పటంలో గీయండి. అల్లూరి సీతారామరాజు జీవితంపై ఒక చిన్న చార్ట్ / నాటిక తయారు చేసి తరగతిలో ప్రదర్శించండి.","kn":"దండి యాత్రలో గాంధీజీ రోజుకు సుమారు 10 మైళ్లు నడిచారు – అప్పుడు ఆయన వయసు 60 ఏళ్లు! అల్లూరి సీతారామరాజు జయంతి (జూలై 4) ఆంధ్రప్రదేశ్ ప్రభుత్వ వేడుకగా జరుగుతుంది.","qz":[["గాంధీజీ దక్షిణాఫ్రికా నుండి భారత్‌కు వచ్చినది?","జనవరి 1915","1919","1909","1920"],["నీలిమందు రైతుల కోసం గాంధీజీ సత్యాగ్రహం?","చంపారన్ (1917)","ఖేడా","అహ్మదాబాద్","బార్డోలీ"],["రౌలట్ చట్టం ఏ సంవత్సరం?","1919","1915","1922","1928"],["జలియన్‌వాలా బాగ్ ఊచకోతకు బాధ్యుడు?","జనరల్ డయ్యర్","లార్డ్ ఇర్విన్","సైమన్","లార్డ్ కర్జన్"],["ఖిలాఫత్ ఉద్యమ నాయకులు?","మహమ్మద్ అలీ, షౌకత్ అలీ","జిన్నా, ఇక్బాల్","నెహ్రూ, పటేల్","C.R. దాస్, మోతీలాల్"],["సహాయ నిరాకరణ ఉద్యమాన్ని ఆమోదించిన కాంగ్రెస్ సమావేశం?","నాగ్‌పూర్ (డిసెంబర్ 1920)","లాహోర్ (1929)","కలకత్తా (1928)","మద్రాస్ (1927)"],["సహాయ నిరాకరణ విరమణకు కారణమైన ఘటన?","చౌరీచౌరా","జలియన్‌వాలా బాగ్","దండి యాత్ర","సైమన్ కమిషన్"],["గూడెం కొండల గిరిజన ఉద్యమ నాయకుడు?","అల్లూరి సీతారామరాజు","బాబా రామ్‌చంద్ర","బిర్సా ముండా","వల్లభ్‌భాయ్ పటేల్"],["స్వరాజ్ పార్టీ స్థాపకులు?","C.R. దాస్, మోతీలాల్ నెహ్రూ","గాంధీ, నెహ్రూ","తిలక్, గోఖలే","పటేల్, బోస్"],["పూర్ణ స్వరాజ్ తీర్మానం చేసిన కాంగ్రెస్ సమావేశం?","లాహోర్ (1929)","నాగ్‌పూర్ (1920)","కరాచీ (1931)","సూరత్ (1907)"],["దండి యాత్ర ప్రారంభం?","12 మార్చి 1930","26 జనవరి 1930","6 ఏప్రిల్ 1930","5 మార్చి 1931"],["గాంధీ–ఇర్విన్ ఒప్పందం?","5 మార్చి 1931","1932","1928","1919"],["పూనా ఒప్పందం (1932) గాంధీజీ ఎవరితో చేశారు?","డా. బి.ఆర్. అంబేద్కర్","జిన్నా","ఇర్విన్","ఇక్బాల్"],["“హింద్ స్వరాజ్” గ్రంథ రచయిత?","మహాత్మా గాంధీ","నెహ్రూ","తిలక్","ఠాగూర్"],["“వందేమాతరం” గీత రచయిత?","బంకించంద్ర ఛటర్జీ","రవీంద్రనాథ్ ఠాగూర్","అబనీంద్రనాథ్ ఠాగూర్","నటేశ శాస్త్రి"],["అవధ్ రైతు ఉద్యమ నాయకుడు?","బాబా రామ్‌చంద్ర","అల్లూరి సీతారామరాజు","వల్లభ్‌భాయ్ పటేల్","C.R. దాస్"]],"wb":{"mis":"సహాయ నిరాకరణ (1921–22) మరియు శాసనోల్లంఘన (1930–34) ఒకటి కాదు – మొదటిది సహకరించకపోవడం, రెండోది చట్టాలను ఉల్లంఘించడం. పూర్ణ స్వరాజ్ 1929 లాహోర్‌లో, 1920 నాగ్‌పూర్‌లో కాదు. అన్ని వర్గాలూ “స్వరాజ్యాన్ని” ఒకేలా అర్థం చేసుకోలేదు.","qz":[],"pg":"56–99","f":"books/10/Class10_Social_History_Textbook.pdf","p":62,"lb":"పాఠ్యపుస్తకం","ws":["కృత్యం – Source A (సత్యాగ్రహం చురుకైన ప్రతిఘటన) (పుట 60)","కృత్యం – సహాయ నిరాకరణ పోస్టర్ (1921) (పుట 66)","కృత్యం – ఉత్తరప్రదేశ్ రైతుగా (1920) (పుట 68)","కృత్యం – బ్రిటిష్ వారు ఉరితీసిన ఇతర పోరాటయోధులు (పుట 70)","చర్చించండి – శాసనోల్లంఘనలో వివిధ వర్గాలు (పుట 84)","చర్చించండి – Source D (ఇక్బాల్ మతతత్వ భావన) (పుట 88)","కృత్యం – Fig. 12, 14 అందరినీ ఆకర్షిస్తాయా? (పుట 94)","అభ్యాసాలు – Write in brief (1–4) (పుట 98)","అభ్యాసాలు – Discuss (1–4), ప్రాజెక్ట్ (పుట 98)"]},"tg":[["కృత్యం – Source A (సత్యాగ్రహం చురుకైన ప్రతిఘటన) (పుట 60)",["గాంధీజీ ఉద్దేశం: సత్యాగ్రహం బలహీనుల ఆయుధం (passive resistance) కాదు – అది ఆత్మబలంతో చేసే చురుకైన పోరాటం. సత్యాగ్రహి ఆయుధం వాడడు, ప్రతీకారం తీర్చుకోడు, ద్వేషించడు; కానీ అన్యాయానికి లొంగకుండా, బాధను స్వీకరిస్తూ, ప్రత్యర్థి మనసును సత్యంతో మార్చడానికి నిరంతరం ప్రయత్నిస్తాడు. అందుకే అది అత్యంత చైతన్యవంతమైన (active) ప్రతిఘటన."]],["కృత్యం – సహాయ నిరాకరణ పోస్టర్ (1921) (పుట 66)",["నమూనా పోస్టర్: “విద్యార్థులారా, గాంధీజీ పిలుపు! ప్రభుత్వ పాఠశాలలను బహిష్కరించండి – జాతీయ పాఠశాలల్లో చేరండి! విదేశీ వస్త్రాలను దహనం చేయండి – ఖాదీ ధరించండి! బానిస విద్య వద్దు – స్వరాజ్య విద్య కావాలి! ఏడాదిలో స్వరాజ్యం! వందేమాతరం!” (రాట్నం, త్రివర్ణ బొమ్మలతో)."]],["కృత్యం – ఉత్తరప్రదేశ్ రైతుగా (1920) (పుట 68)",["నేను గాంధీజీ పిలుపుకు ఉత్సాహంగా స్పందిస్తాను. తాలూక్దార్లు, భూస్వాములు అధిక కౌలు, అనేక పన్నులు వసూలు చేస్తున్నారు, వెట్టిచాకిరి (బేగార్) చేయిస్తున్నారు, కౌలు భూమి నుండి తొలగిస్తున్నారు. స్వరాజ్యం అంటే నాకు – కౌలు తగ్గింపు, వెట్టిచాకిరి రద్దు, భూస్వాముల బహిష్కరణ, భూమిపై భద్రత. అందుకే బాబా రామ్‌చంద్ర, కిసాన్ సభతో కలిసి “నాయీ–ధోబీ బంద్” వంటి సామాజిక బహిష్కరణల్లో పాల్గొంటాను (అహింసతో)."]],["కృత్యం – బ్రిటిష్ వారు ఉరితీసిన ఇతర పోరాటయోధులు (పుట 70)",["భగత్ సింగ్, సుఖ్‌దేవ్, రాజ్‌గురు (1931, లాహోర్), అష్ఫాఖుల్లా ఖాన్, రామ్‌ప్రసాద్ బిస్మిల్ (కాకోరీ, 1927), ఖుదీరామ్ బోస్ (1908), ఉద్దమ్ సింగ్ (1940), అల్లూరి సీతారామరాజు (1924 – కాల్చివేత), చంద్రశేఖర్ ఆజాద్ (1931 – పోలీసులతో పోరాటంలో మరణం). ఇండో–చైనాలో ఇలాంటి ఉదాహరణ: ఫ్రెంచి పాలనకు వ్యతిరేకంగా పోరాడిన ఫాన్ బోయ్ చౌ (ప్రవాసం), వియత్నాం జాతీయవాదులు – యెన్ బై తిరుగుబాటు (1930) తర్వాత నాయకుల ఉరి."]],["చర్చించండి – శాసనోల్లంఘనలో వివిధ వర్గాలు (పుట 84)",["ధనిక రైతులు (పాటిదార్లు, జాట్లు) – మాంద్యంలో ధరలు పడి, భూమి శిస్తు తగ్గించకపోవడంతో; పేద రైతులు – కౌలు మాఫీ కోసం; వ్యాపారులు, పారిశ్రామికవేత్తలు (G.D. బిర్లా, పురుషోత్తమదాస్ ఠాకూర్‌దాస్) – విదేశీ వస్తువుల దిగుమతి ఆంక్షలు, రూపాయి–స్టెర్లింగ్ మారకం రేటు మార్పు కోసం, వలస ఆర్థిక విధానాలకు వ్యతిరేకంగా; పారిశ్రామిక కార్మికులు (నాగ్‌పూర్) – తక్కువ వేతనాలు, పని పరిస్థితులకు వ్యతిరేకంగా; మహిళలు – గాంధీజీ పిలుపుతో దేశసేవ పవిత్ర కర్తవ్యమని భావించి. ప్రతి వర్గం స్వరాజ్యాన్ని తమ సమస్యల పరిష్కారంగా చూసింది."]],["చర్చించండి – Source D (ఇక్బాల్ మతతత్వ భావన) (పుట 88)",["ఇక్బాల్ (1930 ముస్లిం లీగ్ అధ్యక్ష ప్రసంగం) – ముస్లింలు ప్రత్యేక సమాజమని, ఇతర మతాల ప్రత్యేకతలను గౌరవిస్తూనే తమ ప్రత్యేక గుర్తింపు కోసం ప్రత్యేక నియోజకవర్గాలు కావాలని “మతతత్వం”ను సమర్థించాడు. నేను పూర్తిగా ఏకీభవించను – ప్రతి వర్గం గుర్తింపును గౌరవించాలి కానీ మతం ఆధారంగా రాజకీయ విభజన జాతీయ ఐక్యతను దెబ్బతీస్తుంది. నా నిర్వచనం: మతతత్వం అంటే ఒక మతం వారి ప్రయోజనాలు ఇతర మతాల వారి ప్రయోజనాలకు విరుద్ధమని భావించి, మతాన్ని రాజకీయ ఐక్యతకు/విభజనకు ఆధారంగా చేయడం."]],["కృత్యం – Fig. 12, 14 అందరినీ ఆకర్షిస్తాయా? (పుట 94)",["భారతమాత చిత్రాలు (సన్యాసిని రూపం, త్రిశూలం, సింహం, ఏనుగు) ఎక్కువగా హిందూ దేవతా చిహ్నాలపై ఆధారపడ్డాయి. కాబట్టి హిందువులకు ఆకర్షణీయమైనా, ఇతర మతాల వారు, కొన్ని కులాల వారు తమను వీటిలో చూసుకోకపోవచ్చు – దూరమైనట్లు భావించవచ్చు. అందుకే ఐక్యత కోసం వాడిన ప్రతీకలు కూడా అందరినీ కలుపుకోవాలి."]],["అభ్యాసాలు – Write in brief (1–4) (పుట 98)",["1) a) వలస పాలనలో అణచివేత, దోపిడీని అన్ని వర్గాలూ అనుభవించాయి; ఉమ్మడి శత్రువుకు వ్యతిరేక పోరాటంలో ప్రజలు తమ ఐక్యతను కనుగొన్నారు – అందుకే వలస దేశాల్లో జాతీయవాదం వలసవాద వ్యతిరేక ఉద్యమంతో ముడిపడింది.","b) యుద్ధ ఖర్చు కోసం పన్నులు, సుంకాలు పెంచారు; ధరలు రెట్టింపు; గ్రామాల్లో బలవంతపు సైనిక భర్తీ; పంటల వైఫల్యం, ఇన్‌ఫ్లుయెంజా – ప్రజల్లో ఆగ్రహం పెరిగి జాతీయ ఉద్యమానికి బలం చేకూరింది.","c) భారత సభ్యుల వ్యతిరేకత ఉన్నా హడావిడిగా ఆమోదించారు; ప్రభుత్వానికి రాజకీయ కార్యకలాపాల అణచివేతకు అపారమైన అధికారం, విచారణ లేకుండా రెండేళ్లు నిర్బంధం – పౌర హక్కుల హననం.","d) ఫిబ్రవరి 1922 చౌరీచౌరాలో హింస (పోలీసు స్టేషన్ దహనం); ఉద్యమం హింసాత్మకమవుతోందని, సత్యాగ్రహులకు సరైన శిక్షణ అవసరమని గాంధీజీ భావించారు.","2) సత్యాగ్రహం – సత్యం, అహింసలపై ఆధారపడిన పోరాటం. లక్ష్యం న్యాయమైనదైతే, అణచివేతదారునితో పోరాడటానికి భౌతిక బలం అవసరం లేదు; ప్రతీకారం, దౌర్జన్యం లేకుండా సత్యాన్ని చూడమని ప్రత్యర్థి మనసుకు విజ్ఞప్తి చేసి గెలవవచ్చు. చంపారన్, ఖేడా, అహ్మదాబాద్ ఉదాహరణలు.","3) a) “అమృత్‌సర్‌లో ఘోర ఊచకోత” – 13 ఏప్రిల్ 1919: బైసాఖీ పండుగ రోజు జలియన్‌వాలా బాగ్‌లో ప్రభుత్వ దమనకాండకు వ్యతిరేకంగా సమావేశమైన వేలాది మంది నిరాయుధ ప్రజలపై జనరల్ డయ్యర్ ఆదేశంతో సైనికులు కాల్పులు జరిపారు. ఒకే ద్వారాన్ని మూసివేయడంతో తప్పించుకోలేక వందల మంది మరణించారు. ఉత్తర భారతంలో ఆగ్రహావేశాలు – సమ్మెలు, ఘర్షణలు.","b) “సైమన్ గో బ్యాక్!” – 1928: భారత రాజ్యాంగ సంస్కరణల పరిశీలనకు వచ్చిన సర్ జాన్ సైమన్ కమిషన్‌లో ఒక్క భారతీయుడూ లేనందున కాంగ్రెస్, ముస్లిం లీగ్ సహా అన్ని పార్టీలు నల్లజెండాలతో నిరసన తెలిపాయి.","4) భారతమాత (అబనీంద్రనాథ్ ఠాగూర్) – ప్రశాంతమైన, ఆధ్యాత్మిక సన్యాసిని; చేతుల్లో విద్య, ఆహారం, వస్త్రం; తర్వాతి చిత్రాల్లో త్రిశూలం, సింహం, ఏనుగు – శక్తి. జర్మేనియా – ఓక్ కిరీటం, కత్తి, కవచం – యుద్ధ వీరత్వం, సైనిక శక్తి. పోలిక: రెండూ జాతిని స్త్రీ రూపంలో చూపిన ప్రతీకలు; తేడా – భారతమాత ఆధ్యాత్మిక, మాతృత్వం; జర్మేనియా సైనిక శక్తి."]],["అభ్యాసాలు – Discuss (1–4), ప్రాజెక్ట్ (పుట 98)",["1) సహాయ నిరాకరణలో చేరిన వర్గాలు: పట్టణ మధ్యతరగతి (విద్యార్థులు, ఉపాధ్యాయులు, న్యాయవాదులు), వ్యాపారులు, రైతులు, గిరిజనులు, తోటల కార్మికులు, ముస్లింలు (ఖిలాఫత్). (i) అవధ్ రైతులు – తాలూక్దార్ల అధిక కౌలు, వెట్టిచాకిరికి వ్యతిరేకం; కౌలు తగ్గింపు, బేగార్ రద్దు, భూస్వాముల సామాజిక బహిష్కరణ. (ii) గూడెం కొండల గిరిజనులు (అల్లూరి సీతారామరాజు) – అడవుల్లోకి ప్రవేశం, కట్టెలు, పశువుల మేత నిషేధం, రోడ్ల నిర్మాణానికి వెట్టిచాకిరికి వ్యతిరేకం – గెరిల్లా పోరాటం. (iii) అస్సాం తేయాకు తోటల కార్మికులు – 1859 Inland Emigration Act తోటలు విడిచి వెళ్ళే స్వేచ్ఛ లేదు; “స్వరాజ్యం” అంటే స్వగ్రామానికి వెళ్ళే హక్కు అని భావించి తోటలు విడిచారు.","2) ఉప్పు ధనిక–పేద అందరూ వాడే ప్రాథమిక ఆహార పదార్థం; దానిపై పన్ను, ఉత్పత్తిపై ప్రభుత్వ గుత్తాధిపత్యం బ్రిటిష్ పాలన అన్యాయానికి స్పష్టమైన ప్రతీక. 31 జనవరి 1930 ఇర్విన్‌కు 11 డిమాండ్ల లేఖ; స్పందన లేకపోవడంతో 78 మంది వాలంటీర్లతో సబర్మతి నుండి దండికి 240 మైళ్లు, 24 రోజులు నడిచారు; దారిపొడవునా వేలాది మంది కలిశారు; 6 ఏప్రిల్ దండిలో ఉప్పు తయారుచేసి చట్టం ఉల్లంఘించారు – శాసనోల్లంఘన ఉద్యమం దేశమంతా వ్యాపించింది. అందుకే ఇది ప్రభావవంతమైన ప్రతీక.","3) నమూనా: నేను ఒక గృహిణిని. గాంధీజీ పిలుపుతో జీవితంలో తొలిసారి ఇంటి నుండి బయటకు వచ్చి ఊరేగింపుల్లో పాల్గొన్నాను, ఉప్పు తయారు చేశాను, విదేశీ వస్త్రాలు, మద్యం దుకాణాల ముందు పికెటింగ్ చేశాను. చాలామంది స్త్రీలు జైలుకు వెళ్ళారు. దేశసేవ పవిత్ర కర్తవ్యమని భావించాను. ఈ అనుభవం నాకు ఆత్మవిశ్వాసం, గౌరవం, బయటి ప్రపంచంలో భాగస్వామ్యం ఇచ్చింది – అయితే అధికార పదవుల్లో మహిళలకు అవకాశం తక్కువే.","4) ప్రత్యేక నియోజకవర్గాలపై భేదాలు: డా. అంబేద్కర్ – దళితుల రాజకీయ సాధికారత, శాసనసభల్లో ప్రాతినిధ్యం కోసం దళితులకు ప్రత్యేక నియోజకవర్గాలు కావాలన్నారు (1930 Depressed Classes Association). గాంధీజీ – ఇది దళితులను సమాజం నుండి శాశ్వతంగా వేరు చేస్తుందని, సమైక్యతను దెబ్బతీస్తుందని నిరాహార దీక్ష చేశారు → పూనా ఒప్పందం (1932). ముస్లిం లీగ్ (జిన్నా, ఇక్బాల్) – ముస్లింలకు ప్రత్యేక నియోజకవర్గాలు, ముస్లిం మెజారిటీ ప్రాంతాల్లో జనాభా నిష్పత్తిలో ప్రాతినిధ్యం కోరింది; హిందూ మహాసభ (M.R. జయకర్) వ్యతిరేకించింది – అందుకే 1928 అఖిల పక్ష సమావేశంలో రాజీ కుదరలేదు. కారణం: ప్రతి వర్గం తమ రాజకీయ ప్రాతినిధ్యం, అధికారం గురించి ఆందోళన.","ప్రాజెక్ట్: ఇండో–చైనా (వియత్నాం) – ఫ్రెంచి వలస పాలనకు వ్యతిరేకంగా ఫాన్ బోయ్ చౌ, హో చి మిన్ నాయకత్వం, కమ్యూనిస్ట్ పార్టీ, సాయుధ పోరాటం, 1945 స్వాతంత్ర్య ప్రకటన, ఫ్రాన్స్, అమెరికాలతో దీర్ఘ యుద్ధాలు (1954 దియెన్ బియెన్ ఫు, 1975 ఏకీకరణ). భారత్ – ప్రధానంగా అహింసాత్మక ప్రజా ఉద్యమం (సత్యాగ్రహం), చర్చలు, 1947లో స్వాతంత్ర్యం. పోలిక: రెండూ వలసవాద వ్యతిరేక జాతీయవాదం; తేడా: పోరాట పద్ధతి (సాయుధ vs అహింస), విదేశీ జోక్యం."]]]},{"id":"hs3","no":3,"t":"ప్రపంచ ఆర్థిక వ్యవస్థ రూపకల్పన (The Making of a Global World)","m":[8],"ty":"చరిత్ర – అధ్యాయం 3","by":"సాంఘిక శాస్త్రం – చరిత్ర 10వ తరగతి (పుటలు 100–151)","th":"పూర్వ ఆధునిక ప్రపంచం, సిల్క్ మార్గాలు, అమెరికాల ఆక్రమణ, 19వ శతాబ్ద ప్రపంచ ఆర్థిక వ్యవస్థ, ఒప్పంద కూలీలు, యుద్ధాల మధ్య ఆర్థిక వ్యవస్థ, మహా మాంద్యం, బ్రెట్టన్ వుడ్స్, ప్రపంచీకరణ","sum":"ప్రపంచీకరణ కొత్తది కాదు – ప్రాచీన కాలం నుండే వ్యాపారులు, యాత్రికులు, పూజారులు, వలసదారులు దూర ప్రాంతాలకు ప్రయాణించి వస్తువులు, డబ్బు, నైపుణ్యాలు, ఆలోచనలు, వ్యాధులను తీసుకెళ్లారు (సింధు నాగరికత–పశ్చిమాసియా, గవ్వలు). సిల్క్ మార్గాలు – చైనా పట్టు, భారత వస్త్రాలు, సుగంధ ద్రవ్యాలు; బౌద్ధం వ్యాప్తి. ఆహారం – నూడుల్స్ (చైనా నుండి పశ్చిమానికి – స్పఘెట్టి), అమెరికా నుండి బంగాళదుంప, సోయా, వేరుశనగ, మొక్కజొన్న, టమోటా, మిరపకాయలు, చిలగడదుంప – ఐరిష్ బంగాళదుంప కరువు (1845–49). 16వ శతాబ్దం – యూరోపియన్ నావికులు అమెరికాలకు సముద్ర మార్గం కనుగొనడం (ప్రపంచం “కుంచించుకుపోయింది”); పెరూ, మెక్సికో వెండి; స్పానిష్ ఆక్రమణకు ఆయుధాలు కాదు – మశూచి వంటి సూక్ష్మక్రిముల వ్యాప్తి ప్రధాన కారణం. 19వ శతాబ్దం (1815–1914): ఆర్థిక, రాజకీయ, సాంకేతిక అంశాలు – వాణిజ్యం, శ్రమ (వలస), మూలధనం మూడు ప్రవాహాలు. బ్రిటన్ కార్న్ చట్టాల రద్దు → చౌక ఆహార దిగుమతి, బ్రిటిష్ వ్యవసాయం దెబ్బ, అమెరికా–ఆస్ట్రేలియాకు వలసలు. సాంకేతికత – రైల్వేలు, స్టీమ్‌షిప్‌లు, టెలిగ్రాఫ్, రిఫ్రిజిరేటెడ్ ఓడలు (మాంసం). వలసవాదం – 1885 బెర్లిన్ సమావేశంలో ఆఫ్రికా విభజన; రిండర్‌పెస్ట్ (1890లు) పశువుల మరణం → ఆఫ్రికన్లు కూలీలుగా మారడం. భారత ఒప్పంద కూలీలు (indentured labour) – కరీబియన్ (ట్రినిడాడ్, గయానా, సురినాం), మారిషస్, ఫిజీ, శ్రీలంక, మలయా; “కొత్త బానిసత్వం”; హోసే, చట్నీ సంగీతం, రస్తాఫరియనిజం; 1921లో రద్దు. భారత వ్యాపారులు, బ్యాంకర్లు (శికార్‌పురి ష్రాఫ్‌లు, నట్టుకోట్టై చెట్టియార్లు). భారత్ నుండి బ్రిటన్‌కు “హోం చార్జీలు”. మొదటి ప్రపంచ యుద్ధం (1914–18) – మొదటి ఆధునిక పారిశ్రామిక యుద్ధం, పనిచేసే వయసు పురుషుల మరణం, అమెరికా రుణదాతగా. యుద్ధానంతరం – అమెరికాలో భారీ ఉత్పత్తి (హెన్రీ ఫోర్డ్ అసెంబ్లీ లైన్, రోజుకు $5). మహా మాంద్యం (1929 – 1930ల మధ్య) – వ్యవసాయ అధికోత్పత్తి, ధరల పతనం, అమెరికా రుణాల ఉపసంహరణ; భారత్‌లో ఎగుమతులు–దిగుమతులు సగానికి, ధరల పతనం, రైతుల రుణభారం, బంగారం ఎగుమతి; శాసనోల్లంఘనకు నేపథ్యం. రెండో ప్రపంచ యుద్ధం తర్వాత బ్రెట్టన్ వుడ్స్ ఒప్పందం (జూలై 1944) – IMF, ప్రపంచ బ్యాంకు (బ్రెట్టన్ వుడ్స్ కవలలు), స్థిర మారకం రేట్లు ($35 = 1 ఔన్స్ బంగారం). వలస విముక్తి, G-77 – నూతన అంతర్జాతీయ ఆర్థిక వ్యవస్థ (NIEO) డిమాండ్. 1970ల నుండి MNC ల ఉత్పత్తి ఆసియాకు తరలింపు, చైనా – నేటి ప్రపంచీకరణ.","pts":["ప్రాచీన వాణిజ్యం: సింధు నాగరికత–పశ్చిమాసియా; మాల్దీవుల గవ్వలు చైనా, తూర్పు ఆఫ్రికా వరకు కరెన్సీగా.","సిల్క్ మార్గాలు: చైనా పట్టు, కుండలు, భారత–ఆగ్నేయాసియా వస్త్రాలు, సుగంధ ద్రవ్యాలు; ఐరోపా నుండి బంగారం, వెండి; బౌద్ధ, క్రైస్తవ, ఇస్లాం మతాల వ్యాప్తి.","అమెరికా ఆహార పంటలు: బంగాళదుంప, సోయా, వేరుశనగ, మొక్కజొన్న, టమోటా, మిరపకాయలు, చిలగడదుంప – ఐరోపా, ఆసియాకు.","ఐర్లాండ్ బంగాళదుంప కరువు (1845–49): సుమారు 10 లక్షల మంది మరణం, అంతే మంది వలస.","స్పానిష్ ఆక్రమణ: సైనిక శక్తి కంటే మశూచి వంటి సూక్ష్మక్రిములు అమెరికా స్థానికులను నాశనం చేయడం ప్రధాన ఆయుధం.","19వ శతాబ్ద అంతర్జాతీయ ఆర్థిక మార్పిడిలో మూడు ప్రవాహాలు: వస్తువులు (వాణిజ్యం), శ్రమ (ప్రజల వలస), మూలధనం (దీర్ఘకాల పెట్టుబడులు).","కార్న్ చట్టాలు: బ్రిటన్‌లో మొక్కజొన్న/ధాన్యం దిగుమతిపై ఆంక్షలు; రద్దు తర్వాత చౌక దిగుమతులు – బ్రిటిష్ రైతులు నష్టం, ప్రపంచమంతా భూముల సాగు, వలసలు.","రిండర్‌పెస్ట్ (1880ల చివర): పశువుల ప్లేగు – ఆఫ్రికాలో 90% పశువుల మరణం; ఆఫ్రికన్లు జీవనోపాధి కోల్పోయి వలస పాలకుల కూలీలుగా మారారు.","ఒప్పంద కూలీలు: నిర్ణీత కాలం (సాధారణంగా 5 ఏళ్లు) పనిచేస్తామని ఒప్పందంతో వెళ్ళిన కార్మికులు – తూర్పు UP, బీహార్, మధ్య భారత్, తమిళనాడు నుండి; 1921లో రద్దు.","మొదటి ప్రపంచ యుద్ధం: మిత్రరాజ్యాలు (బ్రిటన్, ఫ్రాన్స్, రష్యా, తర్వాత అమెరికా) vs కేంద్ర రాజ్యాలు (జర్మనీ, ఆస్ట్రియా–హంగేరీ, ఒట్టోమన్ టర్కీ); 90 లక్షల మంది మృతి.","భారీ ఉత్పత్తి: హెన్రీ ఫోర్డ్ – డెట్రాయిట్ అసెంబ్లీ లైన్ (T-మోడల్ కారు), కార్మికులకు రోజుకు $5.","మహా మాంద్యం (1929–1930ల మధ్య): ఉత్పత్తి, ఉపాధి, ఆదాయాలు, వాణిజ్యం భారీ పతనం; కారణాలు – వ్యవసాయ అధికోత్పత్తి, అమెరికా రుణాల ఉపసంహరణ.","భారత్‌పై మాంద్యం: 1928–34 ఎగుమతులు, దిగుమతులు దాదాపు సగం; గోధుమ ధర 50% పతనం; బెంగాల్ జనపనార రైతులు; బంగారం ఎగుమతి.","బ్రెట్టన్ వుడ్స్ (న్యూ హాంప్‌షైర్, జూలై 1944): IMF (బాహ్య మిగులు/లోటు), IBRD/ప్రపంచ బ్యాంకు (పునర్నిర్మాణం); 1947లో పని ప్రారంభం; అమెరికా వీటో అధికారం.","G-77: 77 అభివృద్ధి చెందుతున్న దేశాల సమూహం – తమ వనరులపై నియంత్రణ, ముడిసరుకులకు న్యాయమైన ధర, మార్కెట్లలో ప్రవేశం కోసం NIEO డిమాండ్."],"w":[["ప్రపంచీకరణ","Globalisation"],["సిల్క్ మార్గాలు","Silk routes"],["ఒప్పంద కూలీ","Indentured labour"],["కార్న్ చట్టాలు","Corn Laws"],["రిండర్‌పెస్ట్ (పశువుల ప్లేగు)","Rinderpest"],["ఎల్ డొరాడో (బంగారు నగరం)","El Dorado"],["అసెంబ్లీ లైన్","Assembly line"],["మహా మాంద్యం","Great Depression"],["హోం చార్జీలు","Home charges"],["బ్రెట్టన్ వుడ్స్ కవలలు","Bretton Woods twins (IMF, World Bank)"],["స్థిర మారకం రేట్లు","Fixed exchange rates"],["వీటో","Veto"],["సుంకం","Tariff"],["మారకం రేటు","Exchange rate"],["ఉత్పత్తి తరలింపు","Relocation of production"]],"gr":{"t":"ముఖ్య సంవత్సరాలు","p":["16వ శతాబ్దం – అమెరికాల ఆక్రమణ | 1845–49 ఐర్లాండ్ కరువు | 1885 బెర్లిన్ సమావేశం (ఆఫ్రికా విభజన)","1890లు రిండర్‌పెస్ట్ | 1914–18 మొదటి ప్రపంచ యుద్ధం | 1921 ఒప్పంద కూలీ వ్యవస్థ రద్దు","1929 మహా మాంద్యం ఆరంభం | 1939–45 రెండో ప్రపంచ యుద్ధం","1944 జూలై బ్రెట్టన్ వుడ్స్ | 1947 IMF, ప్రపంచ బ్యాంకు పని ప్రారంభం | 1960ల G-77, 1970ల నుండి MNC ల ఉత్పత్తి ఆసియాకు"]},"qa":[["సిల్క్ మార్గాలు అంటే?","చైనాను పశ్చిమ దేశాలతో కలిపిన భూ, సముద్ర వాణిజ్య మార్గాలు – చైనా పట్టు ప్రధాన వస్తువు కాబట్టి ఆ పేరు."],["అమెరికా నుండి ఐరోపా, ఆసియాకు వచ్చిన రెండు పంటలు?","బంగాళదుంప, మొక్కజొన్న (టమోటా, మిరపకాయలు, వేరుశనగ, సోయా)."],["స్పానిష్ ఆక్రమణదారుల అత్యంత శక్తివంతమైన ఆయుధం?","మశూచి వంటి సూక్ష్మక్రిములు (వ్యాధులు)."],["కార్న్ చట్టాలు రద్దు చేశాక ఏమైంది?","చౌక ధాన్యం దిగుమతి, బ్రిటిష్ రైతులు నష్టపోయారు, భూములు బీడు, ఉద్యోగాల కోసం వలసలు."],["రిండర్‌పెస్ట్ ఆఫ్రికాను ఎలా ప్రభావితం చేసింది?","90% పశువులు మరణించి ఆఫ్రికన్ల జీవనాధారం నాశనమైంది; వారు బలవంతంగా గనులు, తోటల్లో కూలీలయ్యారు."],["ఒప్పంద కూలీ వ్యవస్థను ఎందుకు “కొత్త బానిసత్వం” అన్నారు?","కఠిన పని, దుర్భర జీవన పరిస్థితులు, తక్కువ వేతనాలు, చట్టపరమైన హక్కులు లేకపోవడం."],["హెన్రీ ఫోర్డ్ ప్రవేశపెట్టిన ఉత్పత్తి పద్ధతి?","అసెంబ్లీ లైన్ – భారీ ఉత్పత్తి (T-మోడల్ కారు)."],["బ్రెట్టన్ వుడ్స్ కవలలు ఏవి?","అంతర్జాతీయ ద్రవ్య నిధి (IMF), ప్రపంచ బ్యాంకు."],["మహా మాంద్యం భారత్‌పై ప్రభావం?","ఎగుమతులు–దిగుమతులు సగానికి, వ్యవసాయ ధరల పతనం, రైతుల రుణభారం, బంగారం ఎగుమతి."],["G-77 అంటే?","నూతన అంతర్జాతీయ ఆర్థిక వ్యవస్థ (NIEO) కోసం ఏకమైన 77 అభివృద్ధి చెందుతున్న దేశాల సమూహం."]],"act":"ప్రపంచ పటంలో సిల్క్ మార్గాలు, భారత ఒప్పంద కూలీలు వెళ్ళిన దేశాలు (ట్రినిడాడ్, గయానా, సురినాం, మారిషస్, ఫిజీ) గుర్తించండి. మన వంటింట్లో అమెరికా నుండి వచ్చిన పదార్థాల (మిరపకాయ, టమోటా, వేరుశనగ, బంగాళదుంప) జాబితా రాయండి.","kn":"మిరపకాయలు భారత్‌కు 16వ శతాబ్దంలో పోర్చుగీసు వారి ద్వారా అమెరికా నుండి వచ్చాయి – అంతకుముందు మన వంటల్లో కారం కోసం మిరియాలు వాడేవారు! వెస్టిండీస్ క్రికెటర్లు శివనారాయణ్ చందర్‌పాల్, రామ్‌నరేష్ సర్వాన్ ఒప్పంద కూలీల వారసులు.","qz":[["మాల్దీవుల గవ్వలు దేనిగా వాడబడ్డాయి?","కరెన్సీ (డబ్బు)","ఆభరణాలు","ఆహారం","ఎరువు"],["సిల్క్ మార్గాలకు ఆ పేరు రావడానికి కారణం?","చైనా పట్టు ప్రధాన వస్తువు","పట్టు పురుగుల పెంపకం","పట్టు వస్త్రాల రోడ్లు","భారత పట్టు"],["ఐర్లాండ్ కరువుకు కారణమైన పంట వైఫల్యం?","బంగాళదుంప","గోధుమ","మొక్కజొన్న","వరి"],["స్పానిష్ ఆక్రమణదారుల ప్రధాన “ఆయుధం”?","మశూచి సూక్ష్మక్రిములు","తుపాకులు","గుర్రాలు","ఓడలు"],["ఆఫ్రికా విభజనకు 1885లో సమావేశం జరిగిన నగరం?","బెర్లిన్","లండన్","పారిస్","వియన్నా"],["రిండర్‌పెస్ట్ అంటే?","పశువుల ప్లేగు వ్యాధి","పంట తెగులు","మనుషుల జ్వరం","కరువు"],["ఒప్పంద కూలీ వ్యవస్థ రద్దయిన సంవత్సరం?","1921","1947","1885","1900"],["ట్రినిడాడ్‌లో ముహర్రం ఊరేగింపు మారిన కార్నివాల్ పేరు?","హోసే","చట్నీ","రెగె","సల్సా"],["అసెంబ్లీ లైన్ ఉత్పత్తి ప్రవేశపెట్టినది?","హెన్రీ ఫోర్డ్","జేమ్స్ వాట్","కీన్స్","ఎడిసన్"],["మహా మాంద్యం ప్రారంభమైన సంవత్సరం?","1929","1914","1939","1944"],["బ్రెట్టన్ వుడ్స్ సమావేశం జరిగిన దేశం?","అమెరికా","బ్రిటన్","ఫ్రాన్స్","స్విట్జర్లాండ్"],["IMF, ప్రపంచ బ్యాంకులను ఏమంటారు?","బ్రెట్టన్ వుడ్స్ కవలలు","G-77","మిత్రరాజ్యాలు","WTO"],["బ్రెట్టన్ వుడ్స్ వ్యవస్థలో 1 ఔన్స్ బంగారం = ?","$35","$5","$100","$50"],["మొదటి ప్రపంచ యుద్ధం తర్వాత అంతర్జాతీయ రుణదాతగా మారిన దేశం?","అమెరికా","బ్రిటన్","జర్మనీ","జపాన్"],["“శికార్‌పురి ష్రాఫ్‌లు”, “నట్టుకోట్టై చెట్టియార్లు” ఎవరు?","భారత బ్యాంకర్లు, వ్యాపారులు","ఒప్పంద కూలీలు","సైనికులు","రైతులు"],["మాంద్యం కాలంలో భారత్ ఏ లోహాన్ని ఎగుమతి చేసింది?","బంగారం","ఇనుము","రాగి","అల్యూమినియం"]],"wb":{"mis":"ప్రపంచీకరణ 20వ శతాబ్దంలో మొదలైంది అనుకోవడం తప్పు – ప్రాచీన కాలం నుండే వాణిజ్యం, వలసలు ఉన్నాయి. బ్రెట్టన్ వుడ్స్ ఒప్పందం 1944, పని ప్రారంభం 1947. మాంద్యం భారత పట్టణ భూస్వాములు, జీతగాళ్లకు (ధరలు తగ్గి) కొంత మేలు చేసింది – అందరికీ నష్టం కాదు.","qz":[],"pg":"100–151","f":"books/10/Class10_Social_History_Textbook.pdf","p":106,"lb":"పాఠ్యపుస్తకం","ws":["చర్చించండి – 1500లలో ప్రపంచం “కుంచించుకుపోయింది” (పుట 106)","కృత్యాలు – ఫ్లో చార్ట్, ఐరిష్ వ్యవసాయ కార్మికుడు (పుట 112)","చర్చించండి – ఒప్పంద కూలీలు (పుట 122)","చర్చించండి – జనపనార సాగు ఎవరికి లాభం? (పుట 140)","చర్చించండి – యుద్ధాల మధ్య అనుభవం నుండి రెండు పాఠాలు (పుట 144)","అభ్యాసాలు – Write in brief (1–5) (పుట 150)","అభ్యాసాలు – Discuss (6–9), ప్రాజెక్ట్ (పుట 150)"]},"tg":[["చర్చించండి – 1500లలో ప్రపంచం “కుంచించుకుపోయింది” (పుట 106)",["16వ శతాబ్దంలో యూరోపియన్ నావికులు ఆసియాకు సముద్ర మార్గం, అమెరికాలకు దారి కనుగొన్నారు. దూర దేశాల మధ్య ప్రయాణం, వాణిజ్యం, ప్రజలు, పంటలు, వ్యాధులు, సంపద మార్పిడి వేగంగా, విస్తృతంగా జరిగింది. గతంలో వేరుగా ఉన్న ఖండాలు ఒకదానితో ఒకటి అనుసంధానమై, దూరాలు “తగ్గినట్లు” అనిపించింది – అందుకే ప్రపంచం కుంచించుకుపోయిందని అంటారు."]],["కృత్యాలు – ఫ్లో చార్ట్, ఐరిష్ వ్యవసాయ కార్మికుడు (పుట 112)",["ఫ్లో చార్ట్: బ్రిటన్‌లో జనాభా పెరుగుదల → ఆహార డిమాండ్ పెరుగుదల → కార్న్ చట్టాల రద్దు → చౌక ఆహార దిగుమతులు → బ్రిటిష్ రైతులు పోటీలో ఓటమి, భూములు బీడు, నిరుద్యోగం → ఆహార ధరలు తగ్గి డిమాండ్ ఇంకా పెరుగుదల → తూర్పు ఐరోపా, రష్యా, అమెరికా, ఆస్ట్రేలియాలో భూముల సాగు → రైల్వేలు, ఓడరేవుల నిర్మాణం, కూలీల అవసరం → అమెరికా, ఆస్ట్రేలియాకు భారీ వలసలు (19వ శతాబ్దంలో సుమారు 5 కోట్ల మంది).","ఐరిష్ కార్మికుని పేరా: ఐర్లాండ్‌లో బంగాళదుంప పంట నాశనమై కరువు వచ్చింది; ఆకలి, పేదరికంతో నా కుటుంబం బతకలేకపోయింది. అమెరికాలో చౌక భూమి, పని దొరుకుతుందని విని ఓడలో వచ్చాను. ఇప్పుడు మధ్య పశ్చిమ అమెరికాలో ఒక పెద్ద గోధుమ పొలంలో, రైల్వే లైన్ల నిర్మాణంలో కూలీగా పనిచేసి కొద్ది డబ్బు సంపాదిస్తున్నాను; కొంత ఇంటికి పంపుతున్నాను. ఒక రోజు సొంత పొలం కొనాలని ఆశ."]],["చర్చించండి – ఒప్పంద కూలీలు (పుట 122)",["(పుస్తకంలో ఇక్కడ అధ్యాయం 1 ప్రశ్న “భాష, జానపద సంప్రదాయాల ప్రాముఖ్యం” ముద్రించబడింది – దాని జవాబు అధ్యాయం 1 లో చూడండి.)","ఒప్పంద కూలీలపై చర్చ: ఏజెంట్లు తప్పుడు సమాచారంతో, కొన్నిసార్లు బలవంతంగా తీసుకెళ్లారు; తోటల్లో కఠిన పని, తక్కువ వేతనం, చట్టపరమైన హక్కులు లేవు – “కొత్త బానిసత్వం”. అయినా కార్మికులు తప్పించుకోవడం, హోసే కార్నివాల్, రస్తాఫరియనిజం, చట్నీ సంగీతం వంటి కొత్త సాంస్కృతిక రూపాల ద్వారా తమ గుర్తింపును నిలుపుకున్నారు – భాష, సంప్రదాయాలు సమూహ గుర్తింపుకు ఎంత ముఖ్యమో ఇది చూపుతుంది."]],["చర్చించండి – జనపనార సాగు ఎవరికి లాభం? (పుట 140)",["బెంగాల్ జనపనార రైతుల పాట ప్రకారం లాభం రైతులకు కాదు – ఇంట్లో కూర్చున్న వ్యాపారులు, దళారులు, జనపనార మిల్లుల యజమానులకే. రైతులు అప్పులు చేసి ఎక్కువ పండించినా మాంద్యంలో ధర 60% పైగా పడిపోయి (మణుగుకు ₹5 మాత్రమే) ఇంకా అప్పుల్లో మునిగారు."]],["చర్చించండి – యుద్ధాల మధ్య అనుభవం నుండి రెండు పాఠాలు (పుట 144)",["(1) భారీ ఉత్పత్తి వ్యవస్థ నిలవాలంటే భారీ వినియోగం (స్థిరమైన ఆదాయాలు, కొనుగోలు శక్తి) కావాలి; దానికి పూర్తి ఉపాధి అవసరం – ప్రభుత్వాలు ధరలు, ఉత్పత్తి, ఉపాధిలో హెచ్చుతగ్గులను తగ్గించడానికి జోక్యం చేసుకోవాలి. (2) ఒక దేశం పూర్తి ఉపాధి సాధించాలంటే వస్తువులు, మూలధనం, శ్రమ రాకపోకలపై నియంత్రణ ఉండాలి – అంటే ప్రపంచంతో ఆర్థిక సంబంధాలను కొంత నియంత్రించాలి. ఈ లక్ష్యాలతోనే బ్రెట్టన్ వుడ్స్ వ్యవస్థ ఏర్పడింది."]],["అభ్యాసాలు – Write in brief (1–5) (పుట 150)",["1) ఆసియా: సిల్క్ మార్గాల ద్వారా చైనా పట్టు, కుండలు, భారత వస్త్రాలు, సుగంధ ద్రవ్యాలు పశ్చిమానికి; బౌద్ధమతం వ్యాప్తి. అమెరికాలు: అమెరికా నుండి బంగాళదుంప, మొక్కజొన్న, టమోటా, మిరపకాయలు, వేరుశనగ ఐరోపా, ఆసియాకు; పెరూ, మెక్సికో వెండి ఐరోపా సంపదను పెంచింది.","2) 16వ శతాబ్దంలో స్పానిష్, పోర్చుగీసు ఆక్రమణదారులు తమతో మశూచి వంటి సూక్ష్మక్రిములను తెచ్చారు. అమెరికా స్థానికులు దీర్ఘకాలం ప్రపంచం నుండి వేరుగా ఉన్నందున వీటిపై రోగనిరోధక శక్తి లేదు. మశూచి వేగంగా వ్యాపించి సమాజాలను నాశనం చేసింది – ఆక్రమణకు మార్గం సుగమమైంది. ఆయుధాల కంటే వ్యాధే శక్తివంతమైన ఆయుధం.","3) a) కార్న్ చట్టాల రద్దుతో చౌక ధాన్యం దిగుమతి అయింది; బ్రిటిష్ రైతులు పోటీపడలేక భూములు బీడుపెట్టారు; కార్మికులు నిరుద్యోగులై నగరాలకు, విదేశాలకు వలస వెళ్ళారు; ప్రపంచవ్యాప్తంగా సాగు, రవాణా విస్తరించాయి.","b) రిండర్‌పెస్ట్ (1880ల చివర) ఆఫ్రికాలో 90% పశువులను చంపింది; పశువులపై ఆధారపడిన ఆఫ్రికన్ల జీవనోపాధి నాశనమై, వలస పాలకులు భూములు ఆక్రమించి, ఆఫ్రికన్లను కూలీలుగా మార్చారు.","c) పనిచేసే వయసు పురుషులు మరణించడం/గాయపడటంతో ఐరోపాలో శ్రామిక శక్తి తగ్గింది; కుటుంబ ఆదాయాలు పడిపోయాయి; మహిళలు పురుషుల పనులు చేపట్టారు.","d) ఎగుమతులు, దిగుమతులు దాదాపు సగానికి తగ్గాయి; వ్యవసాయ ధరలు పడిపోయాయి (గోధుమ 50%); రైతుల రుణభారం పెరిగింది; బెంగాల్ జనపనార రైతులు దెబ్బతిన్నారు; భారత్ బంగారం ఎగుమతి చేసింది; గ్రామీణ అసంతృప్తి శాసనోల్లంఘనకు ఆధారమైంది.","e) చైనా, భారత్ వంటి ఆసియా దేశాల్లో తక్కువ వేతనాలు, చౌక శ్రమ కారణంగా MNC లు ఉత్పత్తిని తరలించాయి; ఈ దేశాల్లో ఉద్యోగాలు, ఎగుమతులు, ఆర్థిక వృద్ధి పెరిగి ప్రపంచ ఆర్థిక భౌగోళిక స్వరూపం మారింది.","4) (i) రిఫ్రిజిరేటెడ్ ఓడలు – అమెరికా, ఆస్ట్రేలియా, న్యూజిలాండ్ నుండి మాంసాన్ని ఐరోపాకు తేవడం సాధ్యమై, ఐరోపాలో మాంసం ధర తగ్గింది, పేదలకూ అందింది. (ii) రైల్వేలు, స్టీమ్‌షిప్‌లు – ధాన్యం పండే ప్రాంతాలను ఓడరేవులతో కలిపి, ఆహారాన్ని దూర మార్కెట్లకు చౌకగా, వేగంగా చేర్చాయి.","5) జూలై 1944లో అమెరికాలోని న్యూ హాంప్‌షైర్ బ్రెట్టన్ వుడ్స్‌లో జరిగిన ఐక్యరాజ్యసమితి ద్రవ్య, ఆర్థిక సమావేశ ఒప్పందం. యుద్ధానంతర ఆర్థిక స్థిరత్వం, పూర్తి ఉపాధి లక్ష్యం. IMF (సభ్య దేశాల బాహ్య మిగులు, లోటుల నిర్వహణ), ప్రపంచ బ్యాంకు (యుద్ధానంతర పునర్నిర్మాణం) ఏర్పడ్డాయి. స్థిర మారకం రేట్లు – జాతీయ కరెన్సీలు డాలర్‌తో, డాలర్ బంగారంతో ($35 = 1 ఔన్స్) అనుసంధానం."]],["అభ్యాసాలు – Discuss (6–9), ప్రాజెక్ట్ (పుట 150)",["6) లేఖ: ప్రియమైన అమ్మ, నాన్నా – ట్రినిడాడ్ చెరకు తోట నుండి రాస్తున్నాను. ఏజెంట్ చెప్పినట్లు ఇక్కడ సులభమైన పని, మంచి జీతం లేవు. ఉదయం నుండి సాయంత్రం వరకు ఎండలో కష్టపడాలి; చిన్న తప్పుకు జీతం కోత, శిక్ష. ఇరుకైన గుడిసెల్లో ఉంటున్నాం; అనారోగ్యం వస్తే సరైన వైద్యం లేదు. ఒప్పందం ముగిసే వరకు బయటకు వెళ్ళలేను. అయినా ఇక్కడ వేర్వేరు ప్రాంతాల భారతీయులం కలిసి ముహర్రం (హోసే) పండుగ, పాటలతో ఊరట పొందుతున్నాం. మిమ్మల్ని చాలా తలచుకుంటున్నాను. ఒప్పందం పూర్తయ్యాక వస్తాను – మీ కొడుకు.","7) (i) వస్తువుల ప్రవాహం (వాణిజ్యం) – భారత్ నుండి పత్తి, నీలిమందు, గోధుమలు ఎగుమతి, బ్రిటిష్ మిల్లు వస్త్రాలు దిగుమతి. (ii) శ్రమ ప్రవాహం (వలసలు) – భారత ఒప్పంద కూలీలు కరీబియన్, ఫిజీ, మారిషస్ తోటలకు. (iii) మూలధన ప్రవాహం (పెట్టుబడి) – బ్రిటిష్ పెట్టుబడిదారులు భారత రైల్వేలు, తేయాకు తోటల్లో పెట్టుబడి; భారత బ్యాంకర్లు (నట్టుకోట్టై చెట్టియార్లు) ఆగ్నేయాసియాలో రుణాలు.","8) (1) వ్యవసాయ అధికోత్పత్తి – ధరలు పడిపోయి, రైతులు ఇంకా ఎక్కువ పండించడంతో ధరలు ఇంకా తగ్గి ఆదాయాలు పతనం; (2) 1920ల మధ్యలో అమెరికా రుణాలపై ఆధారపడిన దేశాలు – 1928 తర్వాత అమెరికా రుణాలు ఆపి, వెనక్కి తీసుకోవడంతో ఐరోపా బ్యాంకులు దివాలా, కరెన్సీల పతనం; (3) అమెరికా దిగుమతి సుంకాలు రెట్టింపు చేయడం – ప్రపంచ వాణిజ్యం కుంగింది; (4) అమెరికా బ్యాంకులు రుణాలు నిలిపివేసి, వసూళ్లు చేయడంతో వేలాది బ్యాంకులు దివాలా, ఉపాధి, ఆదాయాల పతనం.","9) G-77 – వలస పాలన నుండి స్వాతంత్ర్యం పొందిన 77 అభివృద్ధి చెందుతున్న దేశాల సమూహం. బ్రెట్టన్ వుడ్స్ సంస్థలు (IMF, ప్రపంచ బ్యాంకు) అభివృద్ధి చెందిన దేశాల అవసరాలకే పనిచేశాయి; పాశ్చాత్య MNC లు కొత్త దేశాల వనరులను దోచుకున్నాయి. దీనికి ప్రతిస్పందనగా G-77 నూతన అంతర్జాతీయ ఆర్థిక వ్యవస్థ (NIEO) కోరింది – తమ సహజ వనరులపై నిజమైన నియంత్రణ, ముడిసరుకులకు న్యాయమైన ధరలు, అభివృద్ధి సహాయం, తమ తయారీ వస్తువులకు అభివృద్ధి చెందిన దేశాల మార్కెట్లలో ప్రవేశం.","ప్రాజెక్ట్: 19వ శతాబ్దం దక్షిణాఫ్రికా వజ్రాలు (కింబర్లీ, 1867), బంగారం (విట్వాటర్స్‌రాండ్, 1886) – సెసిల్ రోడ్స్ (De Beers), బ్రిటిష్ కంపెనీల నియంత్రణ; కార్మికులు నల్లజాతి ఆఫ్రికన్లు (వలస కూలీలు) – తక్కువ వేతనాలు, కాంపౌండ్లలో బందీ జీవితం, ప్రమాదకర పరిస్థితులు, జాతి వివక్ష."]]]},{"id":"hs4","no":4,"t":"పారిశ్రామికీకరణ యుగం (The Age of Industrialisation)","m":[9],"ty":"చరిత్ర – అధ్యాయం 4","by":"సాంఘిక శాస్త్రం – చరిత్ర 10వ తరగతి (పుటలు 152–199)","th":"పూర్వ పారిశ్రామికీకరణ, కర్మాగారాల రాక, పారిశ్రామిక మార్పు వేగం, చేతి శ్రమ–ఆవిరి శక్తి, కార్మికుల జీవితం, వలసల్లో పారిశ్రామికీకరణ, భారత నేతకారులు, కర్మాగారాల రాక, చిన్న పరిశ్రమలు, మార్కెట్ ప్రకటనలు","sum":"ఇంగ్లాండ్, ఐరోపాలో కర్మాగారాలు రాకముందే అంతర్జాతీయ మార్కెట్ కోసం పెద్ద ఎత్తున పారిశ్రామిక ఉత్పత్తి జరిగింది – పూర్వ పారిశ్రామికీకరణ (proto-industrialisation): పట్టణ గిల్డ్‌ల ఆంక్షల వల్ల వ్యాపారులు గ్రామాల రైతులు, చేతివృత్తుల వారికి ముడిసరుకు ఇచ్చి ఉత్పత్తి చేయించారు. 1730ల్లో ఇంగ్లాండ్‌లో తొలి కర్మాగారాలు; 18వ శతాబ్దం చివర నుండి పెరిగాయి – రిచర్డ్ ఆర్క్‌రైట్ కాటన్ మిల్లు, జేమ్స్ వాట్ ఆవిరి యంత్రం (1781 పేటెంట్). పత్తి, లోహ పరిశ్రమలు వేగంగా పెరిగాయి, కానీ సాంప్రదాయ పరిశ్రమలే ఎక్కువ; మార్పు నెమ్మదిగా జరిగింది. విక్టోరియన్ బ్రిటన్‌లో శ్రమకు కొరత లేదు, వేతనాలు తక్కువ – అందుకే చాలా మంది పారిశ్రామికవేత్తలు యంత్రాల కంటే చేతి శ్రమకే మొగ్గు చూపారు (కాలానుగుణ డిమాండ్, వైవిధ్యమైన, చేతితో చేసిన ఉత్పత్తులకు ఉన్నత వర్గాల ఇష్టం). కార్మికుల జీవితం – ఉద్యోగాల కొరత, కాలానుగుణ పని, తక్కువ వేతనాలు, పేదరికం; స్పిన్నింగ్ జెన్నీకి వ్యతిరేకంగా మహిళల దాడులు. భారత్ – యంత్రయుగానికి ముందు అంతర్జాతీయ వస్త్ర మార్కెట్‌లో భారత సిల్క్, కాటన్ ఆధిపత్యం; సూరత్, మచిలీపట్నం, హుగ్లీ ఓడరేవులు. 1750ల తర్వాత యూరోపియన్ కంపెనీల రాక – సూరత్, హుగ్లీ క్షీణత, బొంబాయి, కలకత్తా పెరుగుదల. ఈస్ట్ ఇండియా కంపెనీ గుమాస్తాలను నియమించి, నేతకారులకు ముందస్తు రుణాలు ఇచ్చి, ఇతరులకు అమ్మకుండా కట్టడి చేసింది – నేతకారుల ఘర్షణలు. 19వ శతాబ్దంలో మాంచెస్టర్ వస్త్రాల దిగుమతి, భారత వస్త్ర ఎగుమతుల పతనం; అమెరికా అంతర్యుద్ధంతో భారత ముడి పత్తి బ్రిటన్‌కు ఎగుమతి – నేతకారులకు పత్తి కొరత. భారత కర్మాగారాలు – బొంబాయిలో మొదటి కాటన్ మిల్లు (1854), బెంగాల్ జనపనార మిల్లు (1855); ద్వారకానాథ్ ఠాగూర్, డిన్‌షా పెటిట్, జమ్‌సెట్‌జీ టాటా (1912 జంషెడ్‌పూర్ ఉక్కు), సేఠ్ హుకుమ్‌చంద్, G.D. బిర్లా. కార్మికులు – చుట్టుపక్కల జిల్లాల నుండి; జాబర్ (jobber) ద్వారా నియామకం. మొదటి ప్రపంచ యుద్ధంలో భారత పరిశ్రమల వృద్ధి. ఫ్లై షటిల్ వల్ల చేనేత ఉత్పాదకత పెరిగింది; చిన్న పరిశ్రమలు కొనసాగాయి. మార్కెట్ కోసం – లేబుళ్లు, క్యాలెండర్లు, దేవతలు, నాయకుల బొమ్మలతో ప్రకటనలు; స్వదేశీ ప్రచారం.","pts":["పూర్వ పారిశ్రామికీకరణ: కర్మాగారాలకు ముందు, వ్యాపారుల నియంత్రణలో గ్రామీణ గృహాల్లో అంతర్జాతీయ మార్కెట్ కోసం ఉత్పత్తి.","గిల్డ్‌లు: పట్టణాల్లో చేతివృత్తుల వారి సంఘాలు – పోటీ, ధరలు, కొత్తవారి ప్రవేశాన్ని నియంత్రించేవి.","ఆర్క్‌రైట్ కాటన్ మిల్లు: అన్ని ప్రక్రియలు ఒకే చోట, యాజమాన్య పర్యవేక్షణ.","జేమ్స్ వాట్: న్యూకమెన్ యంత్రాన్ని మెరుగుపరిచి 1781లో పేటెంట్; మాథ్యూ బౌల్టన్ తయారీ.","పత్తి, ఇనుము–ఉక్కు, రైల్వేలు వేగవంతమైన రంగాలు; అయినా 1840ల వరకు ఆవిరి శక్తి పరిమితం.","చేతి శ్రమకు ప్రాధాన్యం: చౌక శ్రమ, ఖరీదైన యంత్రాలు–మరమ్మతు, కాలానుగుణ డిమాండ్, సున్నితమైన డిజైన్లు; ఉన్నత వర్గాలు చేతితో చేసినవి ఇష్టపడటం.","స్పిన్నింగ్ జెన్నీ (జేమ్స్ హార్గ్రీవ్స్, 1764): ఒకేసారి అనేక కదురులు – ఉద్యోగాలు పోతాయని మహిళా కార్మికుల దాడి.","భారత ఓడరేవులు: సూరత్ (గుజరాత్ తీరం – గల్ఫ్, ఎర్ర సముద్రం), మచిలీపట్నం (కోరమండల్), హుగ్లీ (బెంగాల్ – ఆగ్నేయాసియా).","గుమాస్తా: నేతకారులను పర్యవేక్షించి, సరుకు సేకరించి, నాణ్యత పరిశీలించడానికి ఈస్ట్ ఇండియా కంపెనీ నియమించిన జీతగాళ్లు.","భారత నేతకారుల సమస్యలు: ఎగుమతి మార్కెట్ పతనం, స్థానిక మార్కెట్లో మాంచెస్టర్ దిగుమతులు, ముడి పత్తి కొరత–అధిక ధర (అమెరికా అంతర్యుద్ధం), తర్వాత భారత మిల్లుల పోటీ.","భారత తొలి మిల్లులు: బొంబాయి కాటన్ మిల్లు 1854, బెంగాల్ రిష్రా జనపనార మిల్లు 1855; 1862 నాటికి 4, కాన్పూర్ ఎల్జిన్ మిల్లు 1860ల్లో, మద్రాస్ 1874.","జాబర్: కార్మికులను గ్రామాల నుండి తెచ్చి, ఉద్యోగం ఇప్పించి, అప్పులిచ్చే విశ్వసనీయ పాత కార్మికుడు – తర్వాత బహుమానాలు కోరి నియంత్రించేవాడు.","మొదటి ప్రపంచ యుద్ధం: మాంచెస్టర్ దిగుమతులు తగ్గడం, సైన్యానికి వస్తువుల డిమాండ్ – భారత పరిశ్రమల వృద్ధి.","ఫ్లై షటిల్: తాడుతో నడిచే నేత పరికరం – ఉత్పాదకత పెంచి, శ్రమ తగ్గించింది; 1941 నాటికి భారత చేనేత మగ్గాల్లో 35% పైగా.","ప్రకటనలు: మాంచెస్టర్ వస్త్రాలపై “Made in Manchester” లేబుళ్లు, భారత దేవతల బొమ్మలు; క్యాలెండర్లు; స్వదేశీ – “భారత వస్తువులను కొనండి”."],"w":[["పారిశ్రామికీకరణ","Industrialisation"],["పూర్వ పారిశ్రామికీకరణ","Proto-industrialisation"],["వర్తక సంఘం (గిల్డ్)","Guild"],["స్టేప్లర్ (ఉన్ని వర్గీకరణదారు)","Stapler"],["ఫుల్లర్ (బట్ట మడతలు చేసేవాడు)","Fuller"],["ఆవిరి యంత్రం","Steam engine"],["స్పిన్నింగ్ జెన్నీ","Spinning Jenny"],["గుమాస్తా","Gomastha"],["ముందస్తు రుణం","Advance"],["కాలానుగుణ పని","Seasonal work"],["ఓరియంట్ (తూర్పు దేశాలు)","Orient"],["జాబర్","Jobber"],["ఫ్లై షటిల్","Fly shuttle"],["ప్రకటన","Advertisement"],["స్వదేశీ","Swadeshi"]],"gr":{"t":"ముఖ్య సంవత్సరాలు, వ్యక్తులు","p":["1730లు – ఇంగ్లాండ్‌లో తొలి కర్మాగారాలు | 1764 స్పిన్నింగ్ జెన్నీ | 1781 జేమ్స్ వాట్ ఆవిరి యంత్రం పేటెంట్","1760 – బ్రిటన్ దిగుమతి చేసుకున్న ముడి పత్తి 25 లక్షల పౌండ్లు → 1787 2.2 కోట్ల పౌండ్లు","1750లు – భారత ఓడరేవుల క్షీణత ఆరంభం | 1854 బొంబాయి తొలి కాటన్ మిల్లు | 1855 బెంగాల్ జనపనార మిల్లు","1861–65 అమెరికా అంతర్యుద్ధం – భారత పత్తి ఎగుమతి | 1912 టాటా ఉక్కు (జంషెడ్‌పూర్) | 1914–18 యుద్ధంలో భారత పరిశ్రమల వృద్ధి","భారత పారిశ్రామికవేత్తలు: ద్వారకానాథ్ ఠాగూర్ (బెంగాల్), డిన్‌షా పెటిట్, జమ్‌సెట్‌జీ టాటా (బొంబాయి), సేఠ్ హుకుమ్‌చంద్ (కలకత్తా జనపనార), G.D. బిర్లా"]},"qa":[["పూర్వ పారిశ్రామికీకరణ అంటే?","కర్మాగారాలు రాకముందు వ్యాపారుల నియంత్రణలో గ్రామీణ గృహాల్లో అంతర్జాతీయ మార్కెట్ కోసం జరిగిన పారిశ్రామిక ఉత్పత్తి దశ."],["17వ శతాబ్దంలో యూరోపియన్ వ్యాపారులు గ్రామాలకు ఎందుకు వెళ్ళారు?","పట్టణాల్లో గిల్డ్‌లు, వర్తక సంఘాల ఆంక్షల వల్ల ఉత్పత్తి పెంచలేక; గ్రామాల్లో పేద రైతులు ఆదాయం కోసం సిద్ధంగా ఉన్నారు."],["ఆవిరి యంత్రాన్ని మెరుగుపరిచినది?","జేమ్స్ వాట్ (1781 పేటెంట్)."],["స్పిన్నింగ్ జెన్నీని ఎవరు వ్యతిరేకించారు, ఎందుకు?","మహిళా నూలు వడికే కార్మికులు – ఉద్యోగాలు, జీవనోపాధి పోతాయని."],["గుమాస్తాలు ఎవరు?","నేతకారులను పర్యవేక్షించి, వస్త్రం సేకరించి, నాణ్యత పరిశీలించడానికి ఈస్ట్ ఇండియా కంపెనీ నియమించిన జీతగాళ్లు."],["18వ శతాబ్దం చివరికి సూరత్ ఎందుకు క్షీణించింది?","యూరోపియన్ కంపెనీల అధికారం, గుత్తాధిపత్యం పెరిగి పాత వ్యాపారులు దివాలా; వాణిజ్యం బొంబాయి, కలకత్తాకు మారింది."],["భారత్‌లో మొదటి కాటన్ మిల్లు?","1854, బొంబాయి."],["జాబర్ ఎవరు?","పారిశ్రామికవేత్తలు కార్మికుల నియామకానికి వాడిన పాత, విశ్వసనీయ కార్మికుడు."],["మొదటి ప్రపంచ యుద్ధంలో భారత పారిశ్రామిక ఉత్పత్తి ఎందుకు పెరిగింది?","మాంచెస్టర్ దిగుమతులు తగ్గి దేశీయ మార్కెట్ దొరికింది; సైన్యానికి జనపనార సంచులు, యూనిఫారాలు, టెంట్లు, బూట్లు వంటి సరఫరా డిమాండ్."],["ఫ్లై షటిల్ ఉపయోగం?","చేనేత కార్మికుల ఉత్పాదకత పెంచి, ఉత్పత్తి ఖర్చు తగ్గించింది."]],"act":"మీ ప్రాంతంలోని ఒక పరిశ్రమ (ఉదా: వెంకటగిరి చేనేత చీరలు, గూడూరు మైకా/నిమ్మ వ్యాపారం) చరిత్ర – సాంకేతికత, కార్మికులు, మార్కెట్ – గురించి పెద్దలను అడిగి ప్రాజెక్ట్ రాయండి.","kn":"మన గూడూరుకు దగ్గరలోని వెంకటగిరి (తిరుపతి జిల్లా) చేనేత చీరలకు భౌగోళిక గుర్తింపు (GI ట్యాగ్) ఉంది! మచిలీపట్నం (బందరు) కలంకారీ వస్త్రాలు 17వ శతాబ్దంలో ఐరోపా, పర్షియాకు ఎగుమతి అయ్యేవి.","qz":[["ఇంగ్లాండ్‌లో తొలి కర్మాగారాలు ఏర్పడినది?","1730లు","1830లు","1660లు","1900లు"],["ఆవిరి యంత్రానికి 1781లో పేటెంట్ పొందినది?","జేమ్స్ వాట్","న్యూకమెన్","ఆర్క్‌రైట్","హార్గ్రీవ్స్"],["మహిళా కార్మికులు దాడి చేసిన యంత్రం?","స్పిన్నింగ్ జెన్నీ","ఫ్లై షటిల్","ఆవిరి యంత్రం","పవర్ లూమ్"],["కాటన్ మిల్లును రూపొందించినది?","రిచర్డ్ ఆర్క్‌రైట్","జేమ్స్ వాట్","హెన్రీ ఫోర్డ్","టాటా"],["నేతకారులను పర్యవేక్షించడానికి కంపెనీ నియమించినవారు?","గుమాస్తాలు","జాబర్లు","స్టేప్లర్లు","ఫుల్లర్లు"],["18వ శతాబ్దం చివరికి క్షీణించిన ఓడరేవు?","సూరత్","బొంబాయి","కలకత్తా","మద్రాస్"],["భారత్‌లో తొలి కాటన్ మిల్లు స్థాపన?","1854, బొంబాయి","1855, బెంగాల్","1874, మద్రాస్","1912, జంషెడ్‌పూర్"],["భారత్‌లో తొలి జనపనార మిల్లు?","1855, బెంగాల్","1854, బొంబాయి","1860, కాన్పూర్","1900, అహ్మదాబాద్"],["జంషెడ్‌పూర్‌లో ఉక్కు కర్మాగారం స్థాపించినది?","జమ్‌సెట్‌జీ టాటా","G.D. బిర్లా","ద్వారకానాథ్ ఠాగూర్","డిన్‌షా పెటిట్"],["కార్మికులను నియమించుకోవడానికి వాడిన మధ్యవర్తి?","జాబర్","గుమాస్తా","జమీందార్","సాహుకార్"],["అమెరికా అంతర్యుద్ధం వల్ల భారత్ నుండి బ్రిటన్‌కు పెరిగిన ఎగుమతి?","ముడి పత్తి","నీలిమందు","జనపనార","తేయాకు"],["చేనేత ఉత్పాదకత పెంచిన పరికరం?","ఫ్లై షటిల్","స్పిన్నింగ్ జెన్నీ","ఆవిరి యంత్రం","కదురు"],["పూర్వ పారిశ్రామికీకరణలో ఉత్పత్తి ఎక్కడ జరిగింది?","గ్రామీణ గృహాల్లో","పెద్ద కర్మాగారాల్లో","ప్రభుత్వ కేంద్రాల్లో","ఓడరేవుల్లో"],["19వ శతాబ్ద బ్రిటన్‌లో చేతి శ్రమకు ప్రాధాన్యం కారణం?","చౌకగా శ్రమ లభ్యత","యంత్రాలు లేకపోవడం","ప్రభుత్వ నిషేధం","విద్యుత్ లేకపోవడం"],["ద్వారకానాథ్ ఠాగూర్ పెట్టుబడులు పెట్టిన ప్రాంతం?","బెంగాల్","బొంబాయి","మద్రాస్","పంజాబ్"],["మొదటి ప్రపంచ యుద్ధంలో భారత పరిశ్రమలు?","వృద్ధి చెందాయి","మూతపడ్డాయి","మారలేదు","బ్రిటన్‌కు తరలాయి"]],"wb":{"mis":"పారిశ్రామిక విప్లవం ఒక్కసారిగా అన్ని పరిశ్రమలను మార్చలేదు – మార్పు నెమ్మదిగా, అసమానంగా జరిగింది. యంత్రాలు వచ్చాక చేనేత పూర్తిగా అంతరించలేదు – ఫ్లై షటిల్‌తో కొన్ని రంగాల్లో పెరిగింది. 1900 నాటికి కూడా ఐరోపా శ్రామికుల్లో ఎక్కువ మంది సాంకేతిక ఆధునిక పరిశ్రమల్లో లేరు.","qz":[],"pg":"152–199","f":"books/10/Class10_Social_History_Textbook.pdf","p":158,"lb":"పాఠ్యపుస్తకం","ws":["కృత్యం – ప్రగతి తెచ్చిన సమస్యలు (పుట 154)","కృత్యాలు – చరిత్రకారుల దృష్టి, Fig. 4–5 పోలిక (పుట 160)","కృత్యం – కొత్త యంత్రం వద్దని వ్యాపారి లేఖ (పుట 164)","చర్చించండి – స్పిన్నింగ్ జెన్నీ వ్యతిరేకత (పుట 168)","కృత్యం – భారత వస్త్ర వాణిజ్య మార్గాలు (ఆసియా పటం) (పుట 172)","అభ్యాసాలు – Write in brief (1–3) (పుట 198)","అభ్యాసాలు – Discuss (1–4), ప్రాజెక్ట్ (పుట 198)"]},"tg":[["కృత్యం – ప్రగతి తెచ్చిన సమస్యలు (పుట 154)",["(1) పారిశ్రామికీకరణ, వాహనాలు – వాయు కాలుష్యం, వాతావరణ మార్పు (గ్లోబల్ వార్మింగ్), నదుల కలుషితం. (2) అణుశక్తి – అణ్వాయుధాల ముప్పు, హిరోషిమా–నాగసాకి, చెర్నోబిల్ ప్రమాదం. (ఇతరాలు: ప్లాస్టిక్ కాలుష్యం, యాంటీబయాటిక్ నిరోధక వ్యాధులు, పురుగుమందుల వల్ల క్యాన్సర్.)"]],["కృత్యాలు – చరిత్రకారుల దృష్టి, Fig. 4–5 పోలిక (పుట 160)",["నా జీవితంలో పెద్దలు ముఖ్యం కాదనుకున్నా నాకు ముఖ్యమైనది: స్నేహితులతో క్రికెట్ మ్యాచ్ గెలవడం, నా మొదటి సొంత కథ/బొమ్మ, పెంపుడు జంతువుతో అనుబంధం – ఇవి నా ఆత్మవిశ్వాసం, ఆనందానికి ముఖ్యం.","Fig. 4 (పారిశ్రామిక ప్రగతి దేవదూత/చిత్రం) పారిశ్రామికీకరణను కొత్త యుగం, అభివృద్ధి, ఆధునికతగా కీర్తిస్తూ చూపుతుంది. Fig. 5 (పారిశ్రామిక మాంచెస్టర్) పొగలు చిమ్మే చిమ్నీలు, కాలుష్యం, రద్దీ, దుర్భర పరిస్థితులతో దాని చీకటి కోణాన్ని చూపుతుంది. ఒకటి సానుకూల, మరొకటి ప్రతికూల దృష్టి."]],["కృత్యం – కొత్త యంత్రం వద్దని వ్యాపారి లేఖ (పుట 164)",["ప్రియమైన సేల్స్‌మన్ గారికి – మీ కొత్త యంత్రం గురించి విన్నాను. కానీ అది చాలా ఖరీదైనది, తరచూ పాడవుతుందని, మరమ్మతు ఖర్చు ఎక్కువని, ప్రచారం చేసినంత సమర్థవంతంగా పనిచేయదని వింటున్నాను. నా వ్యాపారం కాలానుగుణం – ఏడాదిలో కొన్ని నెలలే డిమాండ్; ఆ సమయంలో చౌకగా దొరికే కార్మికులను నియమించుకుంటే చాలు. నా వినియోగదారులు చేతితో చేసిన సున్నితమైన, వైవిధ్యమైన డిజైన్లను ఇష్టపడతారు – యంత్రం ఒకేలాంటివి తయారుచేస్తుంది. కాబట్టి ఇప్పుడు పెట్టుబడి పెట్టను. – ఇట్లు, ఒక వ్యాపారి."]],["చర్చించండి – స్పిన్నింగ్ జెన్నీ వ్యతిరేకత (పుట 168)",["Figs. 3, 7, 11, Source B ప్రకారం – నూలు వడకడం ఎక్కువగా గ్రామీణ పేద మహిళలు ఇంట్లో చేసే పని; అదే వారి జీవనాధారం. స్పిన్నింగ్ జెన్నీతో ఒక్కరే ఒకేసారి అనేక కదురులు తిప్పగలరు – శ్రమ అవసరం తగ్గి ఉద్యోగాలు పోయాయి. కాలానుగుణ, అస్థిరమైన పనిలో ఉన్న కార్మికులు నిరుద్యోగ భయంతో యంత్రాలను వ్యతిరేకించి, వాటిపై దాడులు చేశారు."]],["కృత్యం – భారత వస్త్ర వాణిజ్య మార్గాలు (ఆసియా పటం) (పుట 172)",["భూమార్గం: ఉత్తర భారతం నుండి పంజాబ్, అఫ్ఘానిస్తాన్, తూర్పు పర్షియా మీదుగా మధ్య ఆసియాకు (కైబర్ కనుమ). సముద్ర మార్గాలు: సూరత్ (గుజరాత్) నుండి గల్ఫ్, ఎర్ర సముద్ర ఓడరేవులకు (పశ్చిమాసియా); మచిలీపట్నం (కోరమండల్ తీరం), హుగ్లీ (బెంగాల్) నుండి ఆగ్నేయాసియా ఓడరేవులకు (మలక్కా, జావా, సుమత్రా). పటంలో బాణాలతో గీయండి."]],["అభ్యాసాలు – Write in brief (1–3) (పుట 198)",["1) a) స్పిన్నింగ్ జెన్నీ ఒక్కరే అనేక కదురులు తిప్పేలా చేసి, చేతితో నూలు వడికే మహిళల ఉద్యోగాలను తగ్గించింది; జీవనోపాధి పోతుందనే భయంతో వారు దాడి చేశారు.","b) పట్టణాల్లో శక్తిమంతమైన గిల్డ్‌లు ఉత్పత్తి, పోటీ, ధరలను నియంత్రించి కొత్త వ్యాపారులను అడ్డుకున్నాయి; ప్రపంచ వాణిజ్యం, వస్తువుల డిమాండ్ పెరిగినందున ఉత్పత్తి పెంచడానికి వ్యాపారులు గ్రామాలకు వెళ్ళారు; గ్రామాల్లో భూమి కోల్పోయిన పేద రైతులు, చేతివృత్తుల వారు అదనపు ఆదాయం కోసం సిద్ధంగా ఉన్నారు.","c) యూరోపియన్ కంపెనీల అధికారం పెరిగి, స్థానిక కోర్టుల నుండి రాయితీలు, వాణిజ్య గుత్తాధిపత్యం పొందాయి; సూరత్, హుగ్లీ పాత వ్యాపారులు, బ్యాంకర్లు దివాలా తీశారు; ఎగుమతులు తగ్గి, వాణిజ్యం కొత్తగా పెరుగుతున్న బొంబాయి, కలకత్తాకు మారింది.","d) నేతకారులపై ప్రత్యక్ష నియంత్రణ కోసం, మధ్యవర్తులైన వ్యాపారులను తొలగించి, నేతకారులను పర్యవేక్షించడానికి, సరుకు సేకరించడానికి, వస్త్ర నాణ్యత పరిశీలించడానికి కంపెనీ జీతంపై గుమాస్తాలను నియమించింది.","2) a) తప్పు (False) b) ఒప్పు (True) c) తప్పు (False) – అమెరికా అంతర్యుద్ధంతో భారత పత్తి ఎగుమతులు పెరిగాయి d) ఒప్పు (True)","3) కర్మాగారాలు రాకముందే, ఇంగ్లాండ్, ఐరోపాలో అంతర్జాతీయ మార్కెట్ కోసం పెద్ద ఎత్తున జరిగిన పారిశ్రామిక ఉత్పత్తి దశ. పట్టణ వ్యాపారులు గ్రామీణ రైతులు, చేతివృత్తుల వారికి ముందస్తు డబ్బు, ముడిసరుకు ఇచ్చి వారి ఇళ్ళలోనే ఉత్పత్తి చేయించారు; కుటుంబ సభ్యులందరూ పనిచేసేవారు. ఇది వ్యాపారుల నియంత్రణలో పట్టణ–గ్రామ అనుసంధాన వ్యవస్థ."]],["అభ్యాసాలు – Discuss (1–4), ప్రాజెక్ట్ (పుట 198)",["1) శ్రమకు కొరత లేదు, వేతనాలు తక్కువ – పేద రైతులు, వలసదారులు పని కోసం నగరాలకు వచ్చారు; యంత్రాలు ఖరీదైనవి, మరమ్మతు ఖర్చు ఎక్కువ, ఆవిష్కర్తలు చెప్పినంత సమర్థం కావు; గ్యాస్ వర్క్స్, బ్రూవరీలు, పుస్తక బైండింగ్, ఓడరేవుల వంటి కాలానుగుణ పరిశ్రమల్లో సీజన్‌కే కార్మికులు చాలు; ఉన్నత వర్గాలు చేతితో చేసిన, సున్నితమైన, వైవిధ్యమైన వస్తువులను ఇష్టపడ్డారు – యంత్ర ఉత్పత్తులు వలస దేశాలకు ఎగుమతి; ప్రత్యేక డిజైన్లు, నిర్దిష్ట ఆకారాలు యంత్రాలతో సాధ్యం కాదు.","2) కంపెనీ ఇతర యూరోపియన్ కంపెనీలతో పోటీని, పాత వ్యాపారులు, దళారులను తొలగించి, నేతకారులపై ప్రత్యక్ష నియంత్రణ కోసం జీతంపై గుమాస్తాలను నియమించింది. నేతకారులకు ముందస్తు రుణాలు (advance) ఇచ్చి, ఉత్పత్తి వస్త్రాన్ని తప్పనిసరిగా గుమాస్తాకే ఇవ్వాలని, ఇతర కొనుగోలుదారులకు అమ్మకూడదని కట్టడి చేసింది. రుణం తీసుకున్న నేతకారులు సొంత భూమి సాగు మానేసి పూర్తిగా కంపెనీపై ఆధారపడ్డారు.","3) వ్యాసం – “బ్రిటన్, పత్తి చరిత్ర”: 17వ శతాబ్దంలో బ్రిటిష్ వ్యాపారులు గ్రామీణ గృహాల్లో వస్త్రాలు తయారు చేయించారు (పూర్వ పారిశ్రామికీకరణ). 18వ శతాబ్దంలో స్పిన్నింగ్ జెన్నీ, ఆర్క్‌రైట్ కాటన్ మిల్లు, వాట్ ఆవిరి యంత్రంతో ఉత్పత్తి వేగంగా పెరిగింది – ముడి పత్తి దిగుమతి 1760లో 25 లక్షల పౌండ్ల నుండి 1787లో 2.2 కోట్ల పౌండ్లు. పత్తి బ్రిటన్ పారిశ్రామికీకరణకు ప్రధాన రంగం అయింది. అదే సమయంలో భారత్ నుండి సిల్క్, కాటన్ వస్త్రాల దిగుమతిపై సుంకాలు విధించి, తర్వాత భారత్‌ను ముడి పత్తి సరఫరాదారుగా, మాంచెస్టర్ వస్త్రాల మార్కెట్‌గా మార్చారు. కార్మికులు తక్కువ వేతనాలు, కాలానుగుణ పని, పేదరికం ఎదుర్కొన్నారు; స్పిన్నింగ్ జెన్నీకి వ్యతిరేకంగా దాడులు. మొదటి ప్రపంచ యుద్ధం తర్వాత భారత మిల్లుల పోటీతో బ్రిటిష్ పత్తి పరిశ్రమ ప్రాధాన్యం తగ్గింది.","4) యుద్ధంలో బ్రిటిష్ మిల్లులు సైన్యానికి ఉత్పత్తి చేయడంతో మాంచెస్టర్ దిగుమతులు తగ్గి భారత మిల్లులకు పెద్ద దేశీయ మార్కెట్ దొరికింది; సైన్యం కోసం జనపనార సంచులు, యూనిఫారాలు, టెంట్లు, తోలు బూట్లు, గుర్రపు జీనుల డిమాండ్ పెరిగింది; కొత్త కర్మాగారాలు, పాతవి ఎక్కువ షిఫ్టులతో నడిచాయి.","ప్రాజెక్ట్: ఉదా: వెంకటగిరి చేనేత – చరిత్ర (రాజుల పోషణ), సాంకేతికత మార్పు (గుంత మగ్గం → జాకార్డ్ → పవర్ లూమ్ పోటీ), కార్మికులు (స్థానిక పద్మశాలి కుటుంబాలు), మార్కెటింగ్ (సహకార సంఘాలు, ఆప్కో, ఆన్‌లైన్, GI ట్యాగ్), యజమానులు–కార్మికుల అభిప్రాయాలు సేకరించి నివేదిక."]]]},{"id":"hs5","no":5,"t":"ముద్రణ సంస్కృతి, ఆధునిక ప్రపంచం (Print Culture and the Modern World)","m":[10],"ty":"చరిత్ర – అధ్యాయం 5","by":"సాంఘిక శాస్త్రం – చరిత్ర 10వ తరగతి (పుటలు 200–247)","th":"తూర్పు ఆసియాలో ముద్రణ, ఐరోపాకు ముద్రణ, గుటెన్‌బర్గ్ ప్రెస్, ముద్రణ విప్లవం, పఠన ఉన్మాదం, ఫ్రెంచి విప్లవం, భారత్‌లో ముద్రణ, మత సంస్కరణలు, మహిళలు–పేదలు, సెన్సార్‌షిప్","sum":"తొలి ముద్రణ సాంకేతికత చైనా, జపాన్, కొరియాలో – చైనాలో సుమారు క్రీ.శ. 594 నుండి చెక్క దిమ్మెలతో (woodblock) ముద్రణ; పౌర సేవా పరీక్షల కోసం పుస్తకాలు; 17వ శతాబ్దం నాటికి పట్టణ సంస్కృతితో వ్యాపారులు, మహిళల పఠనం. జపాన్‌కు బౌద్ధ సన్యాసులు (క్రీ.శ. 768–770) – అత్యంత పాత జపనీస్ ముద్రిత పుస్తకం డైమండ్ సూత్ర (868); ఎడో (టోక్యో) – కిటగావా ఉటమారో చిత్రాలు (ukiyo). మార్కో పోలో 1295లో చైనా నుండి ఇటలీకి చెక్క దిమ్మెల ముద్రణ జ్ఞానం తెచ్చాడు. జోహాన్ గుటెన్‌బర్గ్ (జర్మనీ, స్ట్రాస్‌బర్గ్) 1430లలో ఆలివ్/వైన్ ప్రెస్ నమూనాలో లోహ అచ్చుల ముద్రణ యంత్రం తయారుచేశాడు – మొదటి పుస్తకం బైబిల్ (180 ప్రతులు, 3 ఏళ్లు). 1450–1550 మధ్య ఐరోపాలో ముద్రణాలయాలు; ముద్రణ విప్లవం – పుస్తకాలు చౌక, ఎక్కువ మంది పాఠకులు, మౌఖిక సంస్కృతి నుండి పఠన సంస్కృతి; మతపరమైన చర్చలు – మార్టిన్ లూథర్ 95 సిద్ధాంతాలు (1517) – ప్రొటెస్టంట్ సంస్కరణ, “ముద్రణ దేవుని గొప్ప వరం”; భిన్నాభిప్రాయాల భయం – కాథలిక్ చర్చి నిషేధిత పుస్తకాల సూచిక (1558 నుండి), మెనోకియో విచారణ. 17–18వ శతాబ్దాల్లో పఠన ఉన్మాదం (reading mania) – పంచాంగాలు, జానపద కథలు, చాప్‌బుక్స్ (పెన్నీ పుస్తకాలు), బిబ్లియోథెక్ బ్లూ (ఫ్రాన్స్), పత్రికలు, శాస్త్రీయ రచనలు (న్యూటన్), తత్వవేత్తలు (రూసో, వోల్టేర్) – జ్ఞానోదయం; ముద్రణ నిరంకుశత్వాన్ని అంతం చేస్తుందని లూయిస్-సెబాస్టియన్ మెర్సియర్. ముద్రణ ఫ్రెంచి విప్లవానికి పునాది వేసిందని కొందరు చరిత్రకారుల వాదన. 19వ శతాబ్దం – పిల్లలు, మహిళలు, కార్మికులు కొత్త పాఠకులు; గ్రిమ్ సోదరులు, జేన్ ఆస్టెన్, బ్రాంటీ సోదరీమణులు, జార్జ్ ఎలియట్; లెండింగ్ లైబ్రరీలు; రిచర్డ్ ఎం. హో సిలిండ్రికల్ ప్రెస్ (గంటకు 8000 కాగితాలు), ఆఫ్‌సెట్ ప్రెస్; షిల్లింగ్ సిరీస్, డస్ట్ కవర్లు. భారత్ – తాళపత్ర, చేతిరాత ప్రతులు; 16వ శతాబ్దంలో పోర్చుగీస్ మిషనరీలు గోవాకు ముద్రణాలయం; కొంకణి, తమిళం (1579 కొచ్చిన్), మలయాళం (1713); జేమ్స్ ఆగస్టస్ హికీ బెంగాల్ గెజెట్ (1780); రాజా రామ్‌మోహన్ రాయ్ – సంబాద్ కౌముది (1821); మత చర్చలు – దేవబంద్ ఫత్వాలు, తులసీదాస్ రామచరితమానస్ (1810 కలకత్తా); ప్రాంతీయ భాషల్లో పత్రికలు. మహిళలు – రషసుందరీ దేవి “అమర్ జీబన్” (1876, తొలి పూర్తి ఆత్మకథ), పండిత రమాబాయి, తారాబాయి షిండే; పేదలు – చౌక పుస్తకాలు, గ్రంథాలయాలు; జ్యోతిబా ఫూలే “గులాంగిరి” (1871), అంబేద్కర్, పెరియార్; కాశీబాబా (కాన్పూర్ కార్మికుడు) “చోటే ఔర్ బడే కా సవాల్” (1938). సెన్సార్‌షిప్ – 1878 వెర్నాక్యులర్ ప్రెస్ చట్టం (ఐరిష్ ప్రెస్ చట్టాల నమూనా); బాలగంగాధర్ తిలక్ “కేసరి” – 1908 జైలు. గాంధీజీ – “స్వరాజ్ పోరాటం వాక్‌స్వాతంత్ర్యం, పత్రికా స్వాతంత్ర్యం, సంఘాలు ఏర్పరచుకునే స్వాతంత్ర్యం కోసం పోరాటం”.","pts":["చైనా: క్రీ.శ. 594 నుండి చెక్క దిమ్మెల (woodblock) ముద్రణ; అకార్డియన్ పుస్తకం; సివిల్ సర్వీస్ పరీక్షల పుస్తకాలు; షాంఘై – పాశ్చాత్య ముద్రణకు కేంద్రం.","జపాన్: బౌద్ధ సన్యాసులు క్రీ.శ. 768–770లో ముద్రణ తెచ్చారు; డైమండ్ సూత్ర (క్రీ.శ. 868) – అత్యంత పాత జపనీస్ ముద్రిత పుస్తకం; ఉటమారో (ukiyo చిత్రాలు).","మార్కో పోలో 1295లో చైనా నుండి ఇటలీకి తిరిగి వచ్చి చెక్క దిమ్మెల ముద్రణ జ్ఞానం తెచ్చాడు.","గుటెన్‌బర్గ్ ప్రెస్ (1430లు): లోహ అచ్చులు, ఆలివ్ ప్రెస్ నమూనా; మొదటి పుస్తకం బైబిల్ (1448 నాటికి పూర్తి యంత్రం; 180 ప్రతులు).","ముద్రణ విప్లవం: పుస్తకాల ఉత్పత్తి వేగం, తక్కువ ఖర్చు, కొత్త పాఠక వర్గం; వినే ప్రజలు (hearing public) → చదివే ప్రజలు (reading public).","మార్టిన్ లూథర్ (1517): 95 సిద్ధాంతాలు – రోమన్ కాథలిక్ చర్చి ఆచారాల విమర్శ → ప్రొటెస్టంట్ సంస్కరణ; “ముద్రణ దేవుని అత్యున్నత, గొప్ప వరం”.","మెనోకియో: ఇటలీ మిల్లర్ – బైబిల్‌ను కొత్తగా వ్యాఖ్యానించినందుకు విచారణ, ఉరి; చర్చి 1558 నుండి నిషేధిత పుస్తకాల సూచిక (Index of Prohibited Books).","ఎరాస్మస్ (లాటిన్ పండితుడు): ముద్రణ వల్ల అర్థంలేని, అపవాద, అల్లకల్లోల పుస్తకాలు పెరుగుతాయని ఆందోళన.","పఠన ఉన్మాదం: 18వ శతాబ్దం – చాప్‌బుక్స్ (ఇంగ్లాండ్, పెన్నీకి), బిబ్లియోథెక్ బ్లూ (ఫ్రాన్స్), పత్రికలు, జ్ఞానోదయ రచనలు (వోల్టేర్, రూసో).","ఫ్రెంచి విప్లవంలో ముద్రణ పాత్ర: జ్ఞానోదయ ఆలోచనల వ్యాప్తి, చర్చా సంస్కృతి, రాచరికం–చర్చి నైతికతను వెక్కిరించే సాహిత్యం, కార్టూన్లు.","భారత్‌లో ముద్రణ: 16వ శతాబ్దం గోవా (పోర్చుగీస్); 1674 నాటికి కొంకణి, కన్నడ పుస్తకాలు; 1579 కొచ్చిన్‌లో తొలి తమిళ పుస్తకం; 1713 తొలి మలయాళ పుస్తకం.","బెంగాల్ గెజెట్ (1780): జేమ్స్ ఆగస్టస్ హికీ – కంపెనీ అధికారుల విమర్శ; వారెన్ హేస్టింగ్స్ ఆగ్రహం.","మత సంస్కరణలు: రామ్‌మోహన్ రాయ్ సంబాద్ కౌముది (1821) vs సమాచార్ చంద్రిక; ఉలేమాలు – ఉర్దూ, పర్షియన్ పత్రికలు, దేవబంద్ సెమినరీ (1867) ఫత్వాలు.","మహిళలు: రషసుందరీ దేవి – “అమర్ జీబన్” (1876); కైలాశ్‌బాషినీ దేవి; తారాబాయి షిండే, పండిత రమాబాయి (మరాఠీ) – ఉన్నత కుల వితంతువుల దుస్థితిపై.","పేదలు, కులవివక్ష: జ్యోతిబా ఫూలే “గులాంగిరి” (1871); అంబేద్కర్ (మహారాష్ట్ర), పెరియార్ E.V. రామస్వామి నాయకర్ (మద్రాస్); కాశీబాబా, సుదర్శన్ చక్ర (కార్మికుల రచనలు).","వెర్నాక్యులర్ ప్రెస్ చట్టం (1878): ఐరిష్ ప్రెస్ చట్టాల నమూనా – ప్రాంతీయ భాషా పత్రికల్లో అభ్యంతరకర వార్తలు సెన్సార్, ప్రెస్ జప్తు అధికారం."],"w":[["ముద్రణ సంస్కృతి","Print culture"],["చెక్క దిమ్మెల ముద్రణ","Woodblock printing"],["అకార్డియన్ పుస్తకం","Accordion book"],["కాలిగ్రఫీ (అందమైన చేతిరాత)","Calligraphy"],["వెల్లుమ్ (చర్మపు కాగితం)","Vellum"],["ప్లాటెన్","Platen"],["కంపోజిటర్","Compositor"],["గ్యాలీ","Galley"],["మతద్రోహ భావాలు","Heretical ideas"],["నిరంకుశత్వం","Despotism"],["చాప్‌బుక్ (చౌక పుస్తకం)","Chapbook"],["సెన్సార్‌షిప్","Censorship"],["ప్రాంతీయ భాష","Vernacular"],["ఫత్వా","Fatwa"],["ఉలేమా","Ulama"]],"gr":{"t":"ముఖ్య సంవత్సరాలు","p":["594 చైనా woodblock ముద్రణ | 768–770 జపాన్‌కు ముద్రణ | 868 డైమండ్ సూత్ర","1295 మార్కో పోలో ఇటలీకి | 1430లు గుటెన్‌బర్గ్ ప్రెస్ | 1450–1550 ఐరోపాలో ముద్రణాలయాల వ్యాప్తి","1517 మార్టిన్ లూథర్ 95 సిద్ధాంతాలు | 1558 నిషేధిత పుస్తకాల సూచిక | 1780 బెంగాల్ గెజెట్","1810 రామచరితమానస్ (కలకత్తా) | 1821 సంబాద్ కౌముది | 1871 గులాంగిరి | 1876 అమర్ జీబన్","1878 వెర్నాక్యులర్ ప్రెస్ చట్టం | 1908 తిలక్ జైలు | 1938 కాశీబాబా “చోటే ఔర్ బడే కా సవాల్”"]},"qa":[["ముద్రణ సాంకేతికతను మొదట అభివృద్ధి చేసిన దేశం?","చైనా (తర్వాత జపాన్, కొరియా)."],["అత్యంత పాత జపనీస్ ముద్రిత పుస్తకం?","డైమండ్ సూత్ర (క్రీ.శ. 868)."],["గుటెన్‌బర్గ్ ముద్రించిన మొదటి పుస్తకం?","బైబిల్."],["మార్టిన్ లూథర్ ముద్రణను ఎందుకు ప్రశంసించాడు?","అతని 95 సిద్ధాంతాలు ముద్రణ ద్వారా వేలాది మందికి చేరి ప్రొటెస్టంట్ సంస్కరణకు దారితీశాయి – “ముద్రణ దేవుని అత్యున్నత వరం” అన్నాడు."],["కాథలిక్ చర్చి నిషేధిత పుస్తకాల సూచిక ఎందుకు ప్రారంభించింది?","చర్చి బోధనలకు విరుద్ధమైన మతద్రోహ భావాలు ముద్రణ ద్వారా వ్యాపించకుండా అడ్డుకోవడానికి (1558 నుండి)."],["చాప్‌బుక్స్ అంటే?","పెన్నీకి అమ్మే చౌక, జేబు పరిమాణ పుస్తకాలు (ఇంగ్లాండ్)."],["భారత్‌కు ముద్రణాలయం తెచ్చినవారు?","16వ శతాబ్దం మధ్యలో పోర్చుగీస్ మిషనరీలు, గోవాకు."],["బెంగాల్ గెజెట్ ప్రారంభించినది?","జేమ్స్ ఆగస్టస్ హికీ (1780)."],["వెర్నాక్యులర్ ప్రెస్ చట్టం ఎప్పుడు?","1878."],["“గులాంగిరి” రచయిత?","జ్యోతిబా ఫూలే (1871)."]],"act":"మీ ఊరిలో వచ్చే తెలుగు వార్తాపత్రికల పేర్లు, అవి ఎప్పుడు ప్రారంభమయ్యాయో తెలుసుకోండి. పాత పుస్తకం (తాళపత్రం / చేతిరాత ప్రతి) దొరికితే చిత్రం తీసి నేటి ముద్రిత పుస్తకంతో పోల్చండి.","kn":"తెలుగులో తొలి వార్తాపత్రికగా “వర్తమాన తరంగిణి” (1838, మద్రాస్) ని చెబుతారు! కందుకూరి వీరేశలింగం “వివేకవర్ధని” పత్రిక (1874) ద్వారా స్త్రీ విద్య, వితంతు పునర్వివాహాల కోసం ప్రచారం చేశారు.","qz":[["ముద్రణ సాంకేతికత మొదట అభివృద్ధి చెందిన దేశం?","చైనా","జర్మనీ","ఇంగ్లాండ్","భారత్"],["అత్యంత పాత జపనీస్ ముద్రిత పుస్తకం?","డైమండ్ సూత్ర","బైబిల్","రామాయణం","95 సిద్ధాంతాలు"],["చెక్క దిమ్మెల ముద్రణను ఇటలీకి తెచ్చినది?","మార్కో పోలో","గుటెన్‌బర్గ్","లూథర్","కొలంబస్"],["లోహ అచ్చుల ముద్రణ యంత్రాన్ని తయారుచేసినది?","జోహాన్ గుటెన్‌బర్గ్","రిచర్డ్ హో","ఎరాస్మస్","మెర్సియర్"],["గుటెన్‌బర్గ్ ముద్రించిన మొదటి పుస్తకం?","బైబిల్","ఖురాన్","డైమండ్ సూత్ర","రామచరితమానస్"],["95 సిద్ధాంతాలు రాసినది?","మార్టిన్ లూథర్","ఎరాస్మస్","మెనోకియో","వోల్టేర్"],["నిషేధిత పుస్తకాల సూచిక ప్రారంభించినది?","రోమన్ కాథలిక్ చర్చి","ఫ్రెంచి రాజు","బ్రిటిష్ ప్రభుత్వం","ప్రొటెస్టంట్లు"],["ఇంగ్లాండ్‌లో పెన్నీకి అమ్మే చౌక పుస్తకాలు?","చాప్‌బుక్స్","బిబ్లియోథెక్ బ్లూ","అల్మనాక్స్","షిల్లింగ్ సిరీస్"],["గంటకు 8000 కాగితాలు ముద్రించే సిలిండ్రికల్ ప్రెస్ రూపొందించినది?","రిచర్డ్ ఎం. హో","గుటెన్‌బర్గ్","జేమ్స్ వాట్","హికీ"],["భారత్‌కు ముద్రణాలయం మొదట వచ్చిన ప్రదేశం?","గోవా","కలకత్తా","బొంబాయి","మద్రాస్"],["బెంగాల్ గెజెట్ (1780) సంపాదకుడు?","జేమ్స్ ఆగస్టస్ హికీ","రామ్‌మోహన్ రాయ్","తిలక్","వారెన్ హేస్టింగ్స్"],["“సంబాద్ కౌముది” ప్రచురించినది?","రాజా రామ్‌మోహన్ రాయ్","ఈశ్వరచంద్ర విద్యాసాగర్","తిలక్","ఫూలే"],["“అమర్ జీబన్” ఆత్మకథ రచయిత్రి?","రషసుందరీ దేవి","పండిత రమాబాయి","తారాబాయి షిండే","కైలాశ్‌బాషినీ దేవి"],["వెర్నాక్యులర్ ప్రెస్ చట్టం వచ్చిన సంవత్సరం?","1878","1857","1905","1919"],["“కేసరి” పత్రిక సంపాదకుడు, 1908లో జైలు?","బాలగంగాధర్ తిలక్","గాంధీజీ","గోఖలే","నెహ్రూ"],["“గులాంగిరి” గ్రంథ రచయిత?","జ్యోతిబా ఫూలే","అంబేద్కర్","పెరియార్","కాశీబాబా"]],"wb":{"mis":"ముద్రణను ఐరోపాలో కనుగొనలేదు – చైనా, జపాన్, కొరియాలో ముందే ఉంది; గుటెన్‌బర్గ్ లోహ అచ్చుల ప్రెస్ తయారుచేశాడు. ముద్రణను అందరూ స్వాగతించలేదు – చర్చి, రాజులు, సంప్రదాయవాదులు భయపడ్డారు. వెర్నాక్యులర్ ప్రెస్ చట్టం (1878) ఆంగ్ల పత్రికలకు కాదు, ప్రాంతీయ భాషా పత్రికలకు.","qz":[],"pg":"200–247","f":"books/10/Class10_Social_History_Textbook.pdf","p":206,"lb":"పాఠ్యపుస్తకం","ws":["కృత్యం – మార్కో పోలో లేఖ (పుట 206)","కృత్యం – పుస్తక విక్రేత పోస్టర్ (పుట 212)","చర్చించండి – ముద్రణ భిన్నాభిప్రాయాలను పెంచుతుందనే భయం (పుట 216)","కృత్యం, చర్చించండి – ముద్రణ, ఫ్రెంచి విప్లవం (పుట 222)","కృత్యం – ప్రకటనల ప్రభావం (Fig. 13) (పుట 226)","కృత్యం – Figs. 19–21 సామాజిక మార్పులు (పుట 242)","అభ్యాసాలు – Write in brief (1–3) (పుట 246)","అభ్యాసాలు – Discuss (1–4), ప్రాజెక్ట్ (పుట 246)"]},"tg":[["కృత్యం – మార్కో పోలో లేఖ (పుట 206)",["ప్రియమైన కుటుంబ సభ్యులకు – చైనా నుండి మార్కో పోలో. ఇక్కడ నేను అద్భుతమైన విషయం చూశాను! చైనీయులు చెక్క దిమ్మెలపై అక్షరాలు చెక్కి, సిరా పూసి కాగితంపై అద్ది పుస్తకాలు ముద్రిస్తారు – చేతిరాత అవసరం లేదు. కాగితాన్ని ఒకవైపే ముద్రించి అకార్డియన్ లాగా మడతపెడతారు. పరీక్షల కోసం పుస్తకాలు, పంచాంగాలు, కథలు, బొమ్మలు, కాగితపు డబ్బు కూడా ముద్రిస్తారు. వ్యాపారులు, సామాన్యులు కూడా చదువుతున్నారు. ఈ జ్ఞానాన్ని మన ఇటలీకి తెస్తాను – మన దేశంలోనూ పుస్తకాలు చౌకగా, ఎక్కువగా వస్తాయి."]],["కృత్యం – పుస్తక విక్రేత పోస్టర్ (పుట 212)",["“కొత్త ముద్రిత పుస్తకాలు వచ్చేశాయి! చౌక ధరలకే – బైబిల్, పంచాంగాలు, జానపద కథలు, కవిత్వం, ప్రయాణ కథలు, వైద్య, వ్యవసాయ పుస్తకాలు! చేతిరాత ప్రతుల కంటే సగం కంటే తక్కువ ధర! అందరూ చదవండి – జ్ఞానం పొందండి! – ……. పుస్తకశాల, మార్కెట్ వీధి.” (చిత్రాలు, పెద్ద అక్షరాలతో)."]],["చర్చించండి – ముద్రణ భిన్నాభిప్రాయాలను పెంచుతుందనే భయం (పుట 216)",["ముద్రిత పుస్తకాలు చౌకగా, వేగంగా అందరికీ చేరాయి; దేనిని ఎవరు చదవాలో నియంత్రించడం కష్టమైంది. ప్రజలు మత గ్రంథాలను తమదైన రీతిలో వ్యాఖ్యానించడం, చర్చి, రాచరిక అధికారాన్ని ప్రశ్నించడం మొదలుపెట్టారు (లూథర్, మెనోకియో). సంప్రదాయవాదులు, మతాధికారులు, రాజులు – తిరుగుబాటు, మతద్రోహ, అనైతిక భావాలు వ్యాపించి సమాజ వ్యవస్థ దెబ్బతింటుందని భయపడ్డారు."]],["కృత్యం, చర్చించండి – ముద్రణ, ఫ్రెంచి విప్లవం (పుట 222)",["కృత్యం (కార్టూన్ ఆలోచన): ఒక బక్కచిక్కిన రైతు తన వీపుపై లావాటి కులీనుడిని, మతాధికారిని మోస్తూ నడుస్తున్నట్లు; పక్కన “పన్నులు, సుంకాలు, ఉచిత శ్రమ” అని రాసి – సామాన్యుల దోపిడీని వెక్కిరించడం.","చర్చ: (1) ముద్రణ జ్ఞానోదయ తత్వవేత్తల (వోల్టేర్, రూసో) ఆలోచనలను వ్యాప్తి చేసింది – సంప్రదాయం, మూఢనమ్మకం, నిరంకుశత్వాలను విమర్శించి, హేతువాదానికి ప్రాధాన్యం. (2) చర్చా, సంవాద కొత్త సంస్కృతిని సృష్టించింది – ప్రజలు విలువలు, సంస్థలు, ఆచారాలను ప్రశ్నించారు. (3) 1780ల నాటికి రాచరికం, దాని నైతికతను వెక్కిరించే సాహిత్యం, కార్టూన్లు పెరిగి రాచరికం పట్ల శత్రుభావం పెంచాయి. అందుకే ముద్రణ ఫ్రెంచి విప్లవానికి ప్రాతిపదిక వేసిందని కొందరు చరిత్రకారులు భావిస్తారు (అయితే ప్రజలు అన్ని భావాలనూ గుడ్డిగా అంగీకరించలేదు)."]],["కృత్యం – ప్రకటనల ప్రభావం (Fig. 13) (పుట 226)",["ఇలాంటి ముద్రిత ప్రకటనలు ప్రజల్లో కొత్త కోరికలు సృష్టించి, ఆకర్షణీయ బొమ్మలు, మాటలతో వస్తువులు కొనేలా ప్రేరేపిస్తాయి; బ్రాండ్‌పై నమ్మకం, ఫ్యాషన్ భావన కలిగిస్తాయి. కానీ అందరూ ఒకేలా స్పందించరు – చదువు, ఆదాయం, అవసరం, అనుభవాన్ని బట్టి కొందరు ఆకర్షితులవుతారు, కొందరు ఆలోచించి తిరస్కరిస్తారు; పాఠకులు ముద్రిత విషయాన్ని తమదైన రీతిలో అర్థం చేసుకుంటారు."]],["కృత్యం – Figs. 19–21 సామాజిక మార్పులు (పుట 242)",["ఈ చిత్రాలు పాశ్చాత్య ప్రభావంతో మారుతున్న కుటుంబ, స్త్రీ–పురుష పాత్రలను చూపుతాయి – మహిళలు చదవడం, బయటకు రావడం, పాశ్చాత్య జీవనశైలి, మద్యం, సంగీతం వంటి మార్పులు. కళాకారుల వైఖరి ఎక్కువగా వ్యంగ్యం, విమర్శ – పాశ్చాత్య అనుకరణ, సంప్రదాయ కుటుంబ విలువల క్షీణత పట్ల ఆందోళన; కొందరు సంస్కర్తలు మాత్రం స్త్రీ విద్యను సానుకూల మార్పుగా స్వాగతించారు."]],["అభ్యాసాలు – Write in brief (1–3) (పుట 246)",["1) a) చెక్క దిమ్మెల ముద్రణ చైనాలో అభివృద్ధి చెందింది; 1295లో మార్కో పోలో చైనాలో చాలా ఏళ్లు గడిపి ఇటలీకి తిరిగి వచ్చినప్పుడు ఆ జ్ఞానాన్ని తెచ్చాడు – అందుకే అంతకుముందు ఐరోపాకు రాలేదు.","b) ముద్రణ వల్ల అతని 95 సిద్ధాంతాలు, బైబిల్ అనువాదం వేలాది ప్రతులుగా వేగంగా ప్రజలకు చేరి చర్చి విమర్శ, ప్రొటెస్టంట్ సంస్కరణకు దారితీసింది; అందుకే “ముద్రణ దేవుని అత్యున్నత, గొప్ప వరం” అన్నాడు.","c) ముద్రిత పుస్తకాల ద్వారా ప్రజలు బైబిల్‌ను తమదైన రీతిలో వ్యాఖ్యానించడం, చర్చి బోధనలను ప్రశ్నించడం (మెనోకియో) మొదలైంది; మతద్రోహ భావాల వ్యాప్తిని అడ్డుకోవడానికి, ప్రచురణకర్తలు–పుస్తక విక్రేతలను నియంత్రించడానికి చర్చి 1558 నుండి నిషేధిత పుస్తకాల సూచిక నిర్వహించింది.","d) ముద్రణ, పత్రికలు జాతీయవాద భావాల వ్యాప్తికి, ప్రభుత్వ విమర్శకు ప్రధాన సాధనం; బ్రిటిష్ ప్రభుత్వం సెన్సార్‌షిప్ (వెర్నాక్యులర్ ప్రెస్ చట్టం), అరెస్టులతో వాటిని అణచింది. వాక్, పత్రికా, సంఘాల స్వాతంత్ర్యం లేకుండా ప్రజలు తమ అభిప్రాయాలు, ఉద్యమం నిర్వహించలేరు – అందుకే గాంధీజీ ఈ స్వేచ్ఛల కోసం పోరాటమే స్వరాజ్య పోరాటం అన్నారు (1922).","2) a) గుటెన్‌బర్గ్ ప్రెస్: జర్మనీ (స్ట్రాస్‌బర్గ్)లో వ్యాపారి కుమారుడు, బంగారు పనివాడు జోహాన్ గుటెన్‌బర్గ్ 1430లలో ఆలివ్/వైన్ ప్రెస్ నమూనాలో, సీసం అచ్చులతో ముద్రణ యంత్రం తయారుచేశాడు (1448 నాటికి పూర్తి). మొదటి పుస్తకం బైబిల్ – 3 ఏళ్లలో 180 ప్రతులు. 1450–1550 మధ్య ఐరోపా అంతా ముద్రణాలయాలు – ముద్రణ విప్లవం.","b) ఎరాస్మస్ (లాటిన్ పండితుడు, కాథలిక్ సంస్కర్త) ముద్రణను తీవ్రంగా విమర్శించాడు – పుస్తకాలు ఈగల గుంపులా ప్రపంచమంతా వ్యాపిస్తాయని, వాటిలో కొన్ని మాత్రమే విలువైనవని, మిగతావి అర్థంలేనివి, మూర్ఖమైనవి, అపవాదపూరితమైనవి, మతవ్యతిరేక, తిరుగుబాటు భావాలు కలవని భయపడ్డాడు.","c) వెర్నాక్యులర్ ప్రెస్ చట్టం (1878): 1857 తిరుగుబాటు తర్వాత ఐరిష్ ప్రెస్ చట్టాల నమూనాలో రూపొందించిన చట్టం; ప్రాంతీయ భాషా పత్రికల్లో అభ్యంతరకర (ప్రభుత్వ వ్యతిరేక) వార్తలను సెన్సార్ చేయడానికి, హెచ్చరికలు ఇవ్వడానికి, ప్రెస్, ముద్రణ యంత్రాలను జప్తు చేయడానికి ప్రభుత్వానికి విస్తృత అధికారాలు ఇచ్చింది.","3) a) మహిళలు: చదవడం, రాయడం నేర్చుకున్నారు; వారి కోసం పత్రికలు, పుస్తకాలు వచ్చాయి; కొందరు రహస్యంగా చదివి స్వయంగా రచయిత్రులయ్యారు – రషసుందరీ దేవి “అమర్ జీబన్”, తారాబాయి షిండే, పండిత రమాబాయి – ఉన్నత కుల మహిళల, వితంతువుల దుస్థితిపై రాశారు.","b) పేదలు: మద్రాస్ పట్టణాల్లో చౌక పుస్తకాలు, బహిరంగ గ్రంథాలయాలు; కార్మికులు తమ అనుభవాలు, కుల–వర్గ అన్యాయాలపై రాశారు (కాశీబాబా, సుదర్శన్ చక్ర); చదువు, ఆత్మగౌరవం పెరిగాయి.","c) సంస్కర్తలు: సతీ, బాల్య వివాహాలు, విగ్రహారాధన, కులవివక్ష వంటి సామాజిక–మత దురాచారాలపై తమ ఆలోచనలను పత్రికలు, కరపత్రాల ద్వారా విస్తృతంగా ప్రచారం చేశారు (రామ్‌మోహన్ రాయ్ – సంబాద్ కౌముది, ఫూలే – గులాంగిరి); వాదప్రతివాదాలు ప్రజల్లోకి చేరాయి."]],["అభ్యాసాలు – Discuss (1–4), ప్రాజెక్ట్ (పుట 246)",["1) ముద్రణ వల్ల పుస్తకాలు చౌకగా అందరికీ చేరి జ్ఞానం, హేతుబద్ధమైన ఆలోచన వ్యాపిస్తాయని; సంప్రదాయం, మూఢనమ్మకం, నిరంకుశత్వాన్ని ప్రశ్నించే జ్ఞానోదయ రచనలు (వోల్టేర్, రూసో) ప్రజలను చైతన్యపరుస్తాయని నమ్మారు. మెర్సియర్ – “ముద్రణ యంత్రం ప్రగతికి అత్యంత శక్తివంతమైన సాధనం; ప్రజాభిప్రాయం నిరంకుశత్వాన్ని తుడిచిపెడుతుంది; నిరంకుశులారా, రచయితల ముందు వణకండి!”","2) ఐరోపా: రోమన్ కాథలిక్ చర్చి – మెనోకియో వంటి సామాన్యులు బైబిల్‌ను కొత్తగా వ్యాఖ్యానించి చర్చిని ప్రశ్నించడం; అందుకే నిషేధిత పుస్తకాల సూచిక; ఎరాస్మస్ ఆందోళన. భారత్: ఉలేమాలు – ముస్లిం పర్సనల్ లా మార్పులు, ఇతర మతాల ప్రభావం భయంతో ఫత్వాలు; సంప్రదాయ హిందువులు – మహిళలు చదివితే వితంతువులవుతారని భయం; బ్రిటిష్ ప్రభుత్వం – జాతీయవాద పత్రికల వల్ల తిరుగుబాటు భయం (వెర్నాక్యులర్ ప్రెస్ చట్టం).","3) చౌక పుస్తకాలు, గ్రంథాలయాలతో పేదలు చదవడం ప్రారంభించారు; కుల వివక్ష, అన్యాయాలపై ఫూలే (గులాంగిరి), అంబేద్కర్, పెరియార్ రచనలు విస్తృతంగా చదవబడ్డాయి; కార్మికులు తాగుడు నిర్మూలన, అక్షరాస్యత కోసం గ్రంథాలయాలు ఏర్పరచుకున్నారు; కాశీబాబా (1938) కుల–వర్గ దోపిడీపై రాశారు – పేదల్లో చైతన్యం, సంఘటిత శక్తి పెరిగాయి.","4) జాతీయవాద పత్రికలు (కేసరి, అమృత బజార్ పత్రిక, ది హిందూ) బ్రిటిష్ అన్యాయాలను, దోపిడీని బహిర్గతం చేశాయి; దేశమంతా ప్రజలను అనుసంధానం చేసి ఉమ్మడి గుర్తింపు భావన పెంచాయి; స్వదేశీ, సహాయ నిరాకరణ వంటి ఉద్యమాల సమాచారం, నాయకుల ప్రసంగాలు ప్రజలకు చేరాయి; అణచివేత (తిలక్ అరెస్టు) పెరిగినకొద్దీ పత్రికలు ఇంకా ఉద్యమించి జాతీయవాదాన్ని పెంచాయి; భారతమాత చిత్రాలు, జానపద కథల ప్రచురణ కూడా ఐక్యతకు తోడ్పడ్డాయి.","ప్రాజెక్ట్: గత 100 ఏళ్లలో – లైనోటైప్/మోనోటైప్ → ఆఫ్‌సెట్ ముద్రణ → కంప్యూటర్ DTP (డెస్క్‌టాప్ పబ్లిషింగ్) → లేజర్, ఇంక్‌జెట్ ప్రింటర్లు → డిజిటల్ ప్రింటింగ్, ప్రింట్-ఆన్-డిమాండ్, 3D ప్రింటింగ్ → ఈ-బుక్స్, ఆన్‌లైన్ పత్రికలు. కారణాలు: వేగం, తక్కువ ఖర్చు, రంగుల నాణ్యత, కంప్యూటర్–ఇంటర్నెట్. ప్రభావాలు: పుస్తకాలు, పత్రికలు సులభంగా, చౌకగా అందరికీ; స్థానిక భాషల్లో ప్రచురణ పెరుగుదల; కాగితం వినియోగం తగ్గడం; తప్పుడు సమాచార వ్యాప్తి కూడా."]]]},{"id":"gs1","no":6,"t":"వనరులు, అభివృద్ధి (Resources and Development)","m":[6],"ty":"భూగోళం – అధ్యాయం 1","by":"సాంఘిక శాస్త్రం – భూగోళం 10వ తరగతి (పుటలు 2–27)","th":"వనరుల రకాలు, వనరుల అభివృద్ధి, సుస్థిర అభివృద్ధి, వనరుల ప్రణాళిక, భూ వనరులు, భూ వినియోగం, భూక్షయం, మృత్తికలు, నేల కోత–సంరక్షణ","sum":"పర్యావరణంలో సాంకేతికంగా అందుబాటులో, ఆర్థికంగా సాధ్యమయ్యే, సాంస్కృతికంగా ఆమోదయోగ్యమైన, మన అవసరాలు తీర్చే ప్రతిదీ వనరే. వనరుల వర్గీకరణ: మూలం – జీవ, నిర్జీవ; పునరుద్ధరణ – పునరుద్ధరించగల (సౌర, పవన, నీరు, అడవులు), పునరుద్ధరించలేని (ఖనిజాలు, శిలాజ ఇంధనాలు); యాజమాన్యం – వ్యక్తిగత, సామాజిక, జాతీయ, అంతర్జాతీయ (ప్రాదేశిక జలాలు 12 నాటికల్ మైళ్లు, ప్రత్యేక ఆర్థిక మండలి 200 నాటికల్ మైళ్లు); అభివృద్ధి స్థాయి – సంభావ్య (potential – రాజస్థాన్, గుజరాత్ పవన–సౌర శక్తి), అభివృద్ధి చెందిన, నిల్వ (stock – హైడ్రోజన్ ఇంధనం), నిక్షేపాలు (reserves – డ్యామ్ నీరు). విచక్షణారహిత వాడకం వల్ల క్షీణత, సంపద కొద్దిమంది చేతుల్లో, పర్యావరణ సంక్షోభం (భూతాపం, ఓజోన్ క్షయం, కాలుష్యం). సుస్థిర అభివృద్ధి – 1992 రియో డి జనీరో భూ శిఖరాగ్ర సమావేశం, ఎజెండా 21. వనరుల ప్రణాళిక – గుర్తింపు–జాబితా, సాంకేతికత–నైపుణ్యం–సంస్థాగత ప్రణాళిక, జాతీయ అభివృద్ధి ప్రణాళికతో సమన్వయం; వనరులు ఉన్నా వెనుకబడిన ప్రాంతాలు (జార్ఖండ్, ఛత్తీస్‌గఢ్), వనరులు లేకపోయినా అభివృద్ధి చెందినవి (జపాన్). గాంధీజీ – “అందరి అవసరాలకు సరిపడా ఉంది, ఒక్కరి దురాశకూ కాదు”; క్లబ్ ఆఫ్ రోమ్ (1968), షూమాకర్ “Small is Beautiful” (1974), బ్రండ్ట్‌లాండ్ నివేదిక (1987). భూమి – మైదానాలు 43%, పర్వతాలు 30%, పీఠభూములు 27%. భూ వినియోగం – అడవులు (33% లక్ష్యం – జాతీయ అటవీ విధానం 1952), సాగుకు పనికిరాని భూమి, బీడు భూములు, నికర సాగు విస్తీర్ణం (పంజాబ్, హర్యానా 80% పైగా; అరుణాచల్, మిజోరం, మణిపూర్, అండమాన్ 10% లోపు). భూక్షయం – మైనింగ్ (జార్ఖండ్, ఛత్తీస్‌గఢ్, మధ్యప్రదేశ్, ఒడిశా), అతిగా మేపడం (గుజరాత్, రాజస్థాన్, మధ్యప్రదేశ్, మహారాష్ట్ర), అధిక నీటిపారుదల – లవణీకరణ (పంజాబ్, హర్యానా, పశ్చిమ UP), పరిశ్రమల వ్యర్థాలు. మృత్తికలు: ఒండ్రు (ఉత్తర మైదానాలు, తీర డెల్టాలు – బంగర్ పాత, ఖాదర్ కొత్త; పొటాష్, ఫాస్ఫారిక్ ఆమ్లం, సున్నం – చెరకు, వరి, గోధుమ), నల్లరేగడి (రెగర్ – దక్కన్ ట్రాప్, బసాల్ట్; తేమ నిలుపుకుంటుంది – పత్తి; మహారాష్ట్ర, సౌరాష్ట్ర, మాళ్వా, మధ్యప్రదేశ్, గోదావరి–కృష్ణా లోయలు), ఎర్ర–పసుపు (స్ఫటిక శిలలు, ఇనుము – దక్కన్ తూర్పు, దక్షిణ), లేటరైట్ (అధిక ఉష్ణోగ్రత, భారీ వర్షం, లీచింగ్ – జీడిమామిడి, తేయాకు, కాఫీ), శుష్క (ఇసుక, లవణం – రాజస్థాన్), అటవీ మృత్తికలు. నేల కోత – అడవుల నరికివేత, అతిగా మేపడం; లోయ కోత (gullies, చంబల్ – బాడ్‌లాండ్స్), పొర కోత (sheet erosion). సంరక్షణ – కాంటూర్ దున్నకం, టెర్రస్ వ్యవసాయం, పట్టీ సాగు (strip cropping), రక్షక చెట్ల వరుసలు (shelter belts).","pts":["వనరు: సాంకేతికంగా అందుబాటు, ఆర్థికంగా సాధ్యం, సాంస్కృతికంగా ఆమోదయోగ్యం – మానవుడే వనరులను సృష్టించే కీలక భాగం.","మూలం ఆధారంగా: జీవ (మనుషులు, వృక్ష–జంతుజాలం), నిర్జీవ (రాళ్ళు, లోహాలు).","పునరుద్ధరణ ఆధారంగా: పునరుద్ధరించగల (సౌర, పవన, నీరు, అడవులు, వన్యప్రాణులు), పునరుద్ధరించలేని (శిలాజ ఇంధనాలు – లక్షల సంవత్సరాలు; లోహాలు పునర్వినియోగం).","యాజమాన్యం: వ్యక్తిగత, సామాజిక (పచ్చిక బయళ్ళు, శ్మశానాలు), జాతీయ, అంతర్జాతీయ (200 నాటికల్ మైళ్లకు ఆవల సముద్రం).","అభివృద్ధి స్థాయి: సంభావ్య, అభివృద్ధి చెందిన, నిల్వ (stock – సాంకేతికత లేదు), నిక్షేపాలు (reserves – నిల్వలో భాగం, భవిష్యత్ ఉపయోగం).","సుస్థిర అభివృద్ధి: భావితరాల అవసరాలకు భంగం కలగకుండా పర్యావరణానికి హాని లేని అభివృద్ధి; 1992 రియో భూ శిఖరాగ్ర సమావేశం (100+ దేశాధినేతలు), ఎజెండా 21.","వనరుల ప్రణాళిక మూడు దశలు: (i) సర్వే, మ్యాపింగ్‌తో వనరుల జాబితా, (ii) సాంకేతికత, నైపుణ్యం, సంస్థాగత ప్రణాళిక, (iii) జాతీయ అభివృద్ధి ప్రణాళికలతో సమన్వయం.","భారత భూభాగం: మైదానాలు 43%, పర్వతాలు 30%, పీఠభూములు 27%; మొత్తం విస్తీర్ణం 32.8 లక్షల చ.కి.మీ.","అటవీ విస్తీర్ణం: జాతీయ అటవీ విధానం (1952) లక్ష్యం 33% – వాస్తవం చాలా తక్కువ.","భూక్షయ కారణాలు: అడవుల నరికివేత, అతిగా మేపడం, మైనింగ్, క్వారీలు, అధిక నీటిపారుదల (నీరు నిల్వ, లవణీకరణ, క్షారీకరణ), సిమెంట్, సున్నపురాయి ధూళి, పరిశ్రమల వ్యర్థాలు.","ఒండ్రు మృత్తిక: అత్యంత విస్తృతం, అత్యంత సారవంతం; బంగర్ (పాత, కంకర్ గుళికలు), ఖాదర్ (కొత్త, సన్నని, ఎక్కువ సారం).","నల్లరేగడి (రెగర్): బసాల్ట్ లావా శిలల నుండి; కాల్షియం కార్బొనేట్, మెగ్నీషియం, పొటాష్, సున్నం; తేమ నిలుపుకుంటుంది, ఎండితే లోతైన పగుళ్ళు – పత్తికి అనుకూలం.","ఎర్ర–పసుపు మృత్తిక: స్ఫటిక, రూపాంతర శిలల్లో ఇనుము విస్తరణ వల్ల ఎరుపు; తేమతో పసుపు; ఒడిశా, ఛత్తీస్‌గఢ్, మధ్య గంగా మైదానం దక్షిణ భాగాలు.","లేటరైట్: లాటిన్ “later” = ఇటుక; అధిక ఉష్ణం, భారీ వర్షంతో లీచింగ్; హ్యూమస్ తక్కువ; కర్ణాటక, కేరళ, తమిళనాడు, MP, ఒడిశా, అస్సాం కొండలు – జీడిమామిడి (కర్ణాటక, కేరళ, తమిళనాడు).","నేల సంరక్షణ: కాంటూర్ దున్నకం, టెర్రస్ సాగు (పశ్చిమ, మధ్య హిమాలయాలు), పట్టీ సాగు, షెల్టర్ బెల్ట్‌లు (పశ్చిమ భారత ఇసుక దిబ్బల స్థిరీకరణ)."],"w":[["వనరులు","Resources"],["జీవ వనరులు","Biotic resources"],["నిర్జీవ వనరులు","Abiotic resources"],["పునరుద్ధరించగల","Renewable"],["పునరుద్ధరించలేని","Non-renewable"],["సంభావ్య వనరులు","Potential resources"],["నిల్వ","Stock"],["నిక్షేపాలు","Reserves"],["సుస్థిర అభివృద్ధి","Sustainable development"],["నికర సాగు విస్తీర్ణం","Net sown area"],["బీడు భూమి","Fallow land"],["భూక్షయం","Land degradation"],["ఒండ్రు మృత్తిక","Alluvial soil"],["నల్లరేగడి మృత్తిక","Black (Regur) soil"],["నేల కోత","Soil erosion"],["కాంటూర్ దున్నకం","Contour ploughing"],["పట్టీ సాగు","Strip cropping"],["రక్షక చెట్ల వరుసలు","Shelter belts"]],"gr":{"t":"ముఖ్య గణాంకాలు, తేదీలు","p":["మైదానాలు 43% | పర్వతాలు 30% | పీఠభూములు 27%","ప్రాదేశిక జలాలు 12 నాటికల్ మైళ్లు | ప్రత్యేక ఆర్థిక మండలి (EEZ) 200 నాటికల్ మైళ్లు","1968 క్లబ్ ఆఫ్ రోమ్ | 1974 షూమాకర్ “Small is Beautiful” | 1987 బ్రండ్ట్‌లాండ్ కమిషన్ “Our Common Future” | 1992 జూన్ రియో డి జనీరో భూ శిఖరాగ్రం, ఎజెండా 21","జాతీయ అటవీ విధానం 1952 – 33% అడవులు | నికర సాగు: పంజాబ్, హర్యానా > 80%","బంగర్ = పాత ఒండ్రు | ఖాదర్ = కొత్త ఒండ్రు | రెగర్ = నల్లరేగడి"]},"qa":[["వనరు అంటే?","సాంకేతికంగా అందుబాటులో, ఆర్థికంగా సాధ్యమై, సాంస్కృతికంగా ఆమోదయోగ్యమై మన అవసరాలు తీర్చే పర్యావరణంలోని ప్రతిదీ."],["సంభావ్య వనరులకు ఉదాహరణ?","రాజస్థాన్, గుజరాత్‌లో పవన, సౌర శక్తి – ఇంకా పూర్తిగా వాడుకోలేదు."],["ఎజెండా 21 అంటే?","1992 రియో భూ శిఖరాగ్ర సమావేశంలో ఆమోదించిన ప్రకటన – పర్యావరణ నష్టం, పేదరికం, వ్యాధులపై ప్రపంచ సహకారంతో సుస్థిర అభివృద్ధి సాధన."],["ఏ మృత్తిక పత్తికి అనుకూలం?","నల్లరేగడి (రెగర్) మృత్తిక."],["బంగర్, ఖాదర్ తేడా?","బంగర్ – పాత ఒండ్రు, కంకర్ గుళికలు, తక్కువ సారం; ఖాదర్ – కొత్త ఒండ్రు, సన్నని, ఎక్కువ సారం."],["పంజాబ్‌లో భూక్షయానికి ప్రధాన కారణం?","అధిక నీటిపారుదల – నీరు నిల్వ, లవణీకరణ, క్షారీకరణ."],["లేటరైట్ మృత్తిక ఎలా ఏర్పడుతుంది?","అధిక ఉష్ణోగ్రత, భారీ వర్షం ఉన్న ప్రాంతాల్లో తీవ్ర లీచింగ్ వల్ల."],["టెర్రస్ వ్యవసాయం ఎక్కడ?","కొండ వాలుల్లో – పశ్చిమ, మధ్య హిమాలయాలు (ఉత్తరాఖండ్)."],["షెల్టర్ బెల్ట్‌లు అంటే?","గాలి వేగం తగ్గించడానికి వరుసగా నాటే చెట్లు – ఇసుక దిబ్బల స్థిరీకరణ."],["రాష్ట్ర అటవీ విధానం ప్రకారం అడవుల లక్ష్యం?","భౌగోళిక విస్తీర్ణంలో 33% (జాతీయ అటవీ విధానం 1952)."]],"act":"మీ పాఠశాల/ఇంట్లో వాడే వనరుల జాబితా చేసి – పునరుద్ధరించగల/లేని, జీవ/నిర్జీవ అని వర్గీకరించండి. మీ పొలంలో మట్టి నమూనా తెచ్చి రంగు, ఆకృతి చూసి ఏ రకం మృత్తికో గుర్తించండి.","kn":"మన SPSR నెల్లూరు జిల్లాలో తీర ప్రాంతాల్లో ఒండ్రు, లోపలి ప్రాంతాల్లో ఎర్ర మృత్తికలు ఎక్కువ – అందుకే వరి, నిమ్మ, వేరుశనగ బాగా పండుతాయి. 1 సెం.మీ. మట్టి పొర ఏర్పడటానికి వందల సంవత్సరాలు పడుతుంది!","qz":[["పంజాబ్‌లో భూక్షయానికి ప్రధాన కారణం?","అధిక నీటిపారుదల","అడవుల నరికివేత","తీవ్ర సాగు","అతిగా మేపడం"],["టెర్రస్ సాగు చేసే రాష్ట్రం?","ఉత్తరాఖండ్","పంజాబ్","హర్యానా","ఉత్తరప్రదేశ్ మైదానాలు"],["నల్లరేగడి మృత్తిక ఎక్కువగా ఉన్న రాష్ట్రం?","మహారాష్ట్ర","ఉత్తరప్రదేశ్","రాజస్థాన్","జార్ఖండ్"],["తూర్పు తీర నదీ డెల్టాల్లోని మృత్తిక?","ఒండ్రు","నల్లరేగడి","లేటరైట్","శుష్క"],["రియో డి జనీరో భూ శిఖరాగ్ర సమావేశం?","1992","1987","1968","2002"],["భారత భూభాగంలో మైదానాల శాతం?","43%","30%","27%","50%"],["ప్రత్యేక ఆర్థిక మండలి (EEZ) పరిమితి?","200 నాటికల్ మైళ్లు","12 నాటికల్ మైళ్లు","100 కి.మీ.","50 నాటికల్ మైళ్లు"],["పత్తికి అనుకూలమైన మృత్తిక?","నల్లరేగడి (రెగర్)","లేటరైట్","శుష్క","అటవీ"],["లీచింగ్ వల్ల ఏర్పడే మృత్తిక?","లేటరైట్","ఒండ్రు","నల్లరేగడి","ఎర్ర"],["కొత్త ఒండ్రు మృత్తికను ఏమంటారు?","ఖాదర్","బంగర్","రెగర్","కంకర్"],["పునరుద్ధరించలేని వనరు?","బొగ్గు","సౌర శక్తి","అడవులు","నీరు"],["జాతీయ అటవీ విధానం (1952) సూచించిన అటవీ విస్తీర్ణం?","33%","20%","50%","10%"],["“Small is Beautiful” రచయిత?","షూమాకర్","గాంధీజీ","బ్రండ్ట్‌లాండ్","క్లబ్ ఆఫ్ రోమ్"],["ఇసుక దిబ్బల స్థిరీకరణకు?","షెల్టర్ బెల్ట్‌లు","టెర్రస్ సాగు","కాంటూర్ దున్నకం","అధిక నీటిపారుదల"],["చంబల్ లోయలోని కోతకు గురైన భూములను ఏమంటారు?","బాడ్‌లాండ్స్ (లోయ కోత)","టెర్రస్‌లు","డెల్టాలు","ఖాదర్"],["నిల్వ (stock) వనరుకు ఉదాహరణ?","నీటి నుండి హైడ్రోజన్ ఇంధనం","డ్యామ్ నీరు","బొగ్గు గనులు","అడవులు"]],"wb":{"mis":"“వనరులు ప్రకృతి ఉచిత కానుకలు” అనుకోవడం తప్పు – మానవ కార్యకలాపాలు, సాంకేతికత, సంస్థలతోనే అవి వనరులవుతాయి. నిల్వ (stock) మరియు నిక్షేపాలు (reserves) ఒకటి కాదు. పంజాబ్ భూక్షయానికి కారణం అడవుల నరికివేత కాదు – అధిక నీటిపారుదల.","qz":[],"pg":"2–27","f":"books/10/Class10_Social_Geography_Textbook.pdf","p":8,"lb":"పాఠ్యపుస్తకం","ws":["ఆలోచించండి – సౌకర్యాల వస్తువులు, పదార్థాలు (పుట 6)","ఆలోచించండి – వనరులున్నా వెనుకబడిన, లేకపోయినా అభివృద్ధి చెందిన ప్రాంతాలు (పుట 10)","కనుగొనండి – తక్కువ నికర సాగు విస్తీర్ణం (పుట 14)","అభ్యాసాలు – Exercises (పుట 26)"]},"tg":[["ఆలోచించండి – సౌకర్యాల వస్తువులు, పదార్థాలు (పుట 6)",["గ్రామాలు, పట్టణాల్లో వాడే వస్తువులు – ఇల్లు (ఇటుకలు, సిమెంట్, ఇనుము, ఇసుక, కలప), ఫ్యాన్ (ఇనుము, రాగి, అల్యూమినియం, ప్లాస్టిక్), వాహనాలు (ఉక్కు, రబ్బరు, పెట్రోలు), బట్టలు (పత్తి, పాలిస్టర్), పాత్రలు (స్టీలు, అల్యూమినియం, మట్టి), ఫోన్ (ప్లాస్టిక్, గాజు, లోహాలు), ఫర్నిచర్ (కలప). ఇవన్నీ ప్రకృతి నుండి వచ్చిన వనరులను మానవుడు సాంకేతికతతో మార్చినవే."]],["ఆలోచించండి – వనరులున్నా వెనుకబడిన, లేకపోయినా అభివృద్ధి చెందిన ప్రాంతాలు (పుట 10)",["వనరులు ఉన్నా వెనుకబడినవి: జార్ఖండ్, ఛత్తీస్‌గఢ్, మధ్యప్రదేశ్ (ఖనిజాలు, బొగ్గు), అరుణాచల్ ప్రదేశ్ (జల వనరులు) – కారణం: సాంకేతికత, మూలధనం, మౌలిక సదుపాయాలు, నైపుణ్యం లేకపోవడం, వనరులు బయటకు తరలిపోవడం. వనరులు తక్కువైనా అభివృద్ధి చెందినవి: జపాన్, సింగపూర్, పంజాబ్ (వ్యవసాయ సాంకేతికత) – కారణం: సాంకేతికత, నైపుణ్యం గల మానవ వనరులు, సంస్థలు, వాణిజ్యం."]],["కనుగొనండి – తక్కువ నికర సాగు విస్తీర్ణం (పుట 14)",["అరుణాచల్, మిజోరం, మణిపూర్, అండమాన్–నికోబార్‌లో కొండలు, ఏటవాలు భూభాగం, దట్టమైన అడవులు, భారీ వర్షం, నేల కోత, సారం తక్కువ మృత్తికలు, రవాణా లోపం, జూమ్ (పోడు) సాగు, దీవుల చిన్న విస్తీర్ణం – అందుకే నికర సాగు విస్తీర్ణం 10% లోపు."]],["అభ్యాసాలు – Exercises (పుట 26)",["1) (i) (c) అధిక నీటిపారుదల (Over irrigation) (ii) (d) ఉత్తరాఖండ్ (iii) (b) మహారాష్ట్ర","2) (i) మహారాష్ట్ర, గుజరాత్ (సౌరాష్ట్ర), మధ్యప్రదేశ్ (మాళ్వా) – ప్రధాన పంట పత్తి.","(ii) ఒండ్రు మృత్తిక – చాలా సారవంతం; పొటాష్, ఫాస్ఫారిక్ ఆమ్లం, సున్నం అధికం; చెరకు, వరి, గోధుమ, పప్పు పంటలకు అనుకూలం; సన్నని, మృదువైన కణాలు (ఖాదర్).","(iii) కాంటూర్ దున్నకం (వాలుకు అడ్డంగా), వాలులపై టెర్రస్‌లు (మెట్లు), పట్టీ సాగు, చెట్లు నాటడం, అతిగా మేపడం నియంత్రణ, చెక్‌డ్యామ్‌లు.","3) (i) భూ వినియోగం: అడవులు; సాగుకు అందుబాటులో లేని భూమి (బంజరు, వ్యర్థ భూమి; నివాసాలు, రోడ్లు, పరిశ్రమలు); ఇతర సాగుచేయని భూమి (శాశ్వత పచ్చిక బయళ్ళు, వివిధ చెట్ల తోటలు, సాగుకు అనువైన వ్యర్థ భూమి); బీడు భూములు (ప్రస్తుత, ఇతర); నికర సాగు విస్తీర్ణం (సుమారు 45%); ఏడాదిలో ఒకటి కంటే ఎక్కువసార్లు సాగు = స్థూల సాగు విస్తీర్ణం. 1960–61 నుండి అడవులు పెద్దగా పెరగలేదు – కారణం: జనాభా పెరుగుదల, వ్యవసాయ విస్తరణ, పట్టణీకరణ, పారిశ్రామికీకరణ, మైనింగ్, పెద్ద డ్యామ్‌లు, రోడ్లు, పోడు సాగు, కలప కోసం నరికివేత; మొక్కలు నాటడం కంటే నరికివేత వేగంగా జరిగింది.","3) (ii) సాంకేతిక, ఆర్థిక అభివృద్ధితో వనరులను వేగంగా, భారీగా వెలికితీయడం, ఉత్పత్తి చేయడం సాధ్యమైంది (యంత్రాలు, మైనింగ్, పరిశ్రమలు); ఆదాయాలు పెరిగి వస్తువుల డిమాండ్, విలాసాలు పెరిగాయి; వలసవాదం కాలంలో వనరుల దోపిడీ; జనాభా పెరుగుదల; వినియోగ సంస్కృతి – దీనితో వనరుల వినియోగం భారీగా పెరిగి క్షీణత, పర్యావరణ సంక్షోభం వచ్చాయి.","ప్రాజెక్ట్: (1) మీ ప్రాంతంలో నీరు, విద్యుత్, ఇంధనం, కాగితం వినియోగం–సంరక్షణ పద్ధతులపై సర్వే, చార్ట్. (2) పాఠశాలలో – నీటి కుళాయిలు కట్టడం, అనవసర లైట్లు–ఫ్యాన్లు ఆపడం, కాగితం రెండు వైపులా వాడటం, తడి–పొడి చెత్త వేరు, మొక్కలు నాటడం. (3) చమురు అయిపోతే – వాహనాలు, విమానాలు ఆగిపోతాయి; రవాణా, వస్తువుల ధరలు పెరుగుతాయి; ప్లాస్టిక్, ఎరువులు తగ్గుతాయి; విద్యుత్ వాహనాలు, సౌర–పవన శక్తి, సైకిళ్ళు, ప్రజా రవాణాపై ఆధారపడాల్సి వస్తుంది."]]]},{"id":"gs2","no":7,"t":"అటవీ, వన్యప్రాణి వనరులు (Forest and Wildlife Resources)","m":[7],"ty":"భూగోళం – అధ్యాయం 2","by":"సాంఘిక శాస్త్రం – భూగోళం 10వ తరగతి (పుటలు 30–41)","th":"జీవ వైవిధ్యం, వృక్ష–జంతుజాల క్షీణత, సంరక్షణ, ప్రాజెక్ట్ టైగర్, అడవుల రకాలు, సమాజ భాగస్వామ్యం (చిప్కో, JFM, బిష్ణోయిలు)","sum":"భూమి మీద మనం జీవ వైవిధ్యంతో పరస్పర ఆధారిత వ్యవస్థలో భాగం. ఇటీవల పర్యావరణం పట్ల నిర్లక్ష్యంతో వృక్ష–జంతుజాలం తీవ్ర ఒత్తిడిలో ఉన్నాయి. క్షీణత కారణాలు – వ్యవసాయ విస్తరణ, పోడు సాగు, పెద్ద నదీ లోయ ప్రాజెక్టులు, మైనింగ్, పశువుల మేత, కలప, వేట, కాలుష్యం, అటవీ అగ్నిప్రమాదాలు. జీవ వైవిధ్య క్షీణత సాంస్కృతిక వైవిధ్యాన్ని కూడా దెబ్బతీస్తుంది – గిరిజనులు, మహిళలు ఎక్కువ బాధితులు. సంరక్షణ – భారత వన్యప్రాణి (రక్షణ) చట్టం 1972, జాతీయ ఉద్యానవనాలు, అభయారణ్యాలు; సంరక్షణ పర్యావరణ వైవిధ్యాన్ని, నీరు–గాలి–నేల వంటి జీవాధార వ్యవస్థలను, జన్యు వైవిధ్యాన్ని కాపాడుతుంది; ప్రాజెక్ట్ టైగర్ (1973 – 1,827 పులులే మిగిలాయి; కార్బెట్, సుందర్‌బన్స్, బాంధవ్‌గఢ్, సరిస్కా, మానస్, పెరియార్); 1980, 1986 చట్టాల్లో కీటకాలు, 1991లో మొక్కలు రక్షిత జాబితాలోకి. అడవుల రకాలు – రిజర్వ్ అడవులు (సగానికి పైగా, అత్యంత విలువైనవి), రక్షిత అడవులు (మూడో వంతు, మరింత క్షీణత నుండి రక్షణ), అవర్గీకృత అడవులు (ప్రభుత్వ, ప్రైవేటు, సమాజాల ఇతర అడవులు, వ్యర్థ భూములు – ఈశాన్య రాష్ట్రాలు, గుజరాత్). మధ్యప్రదేశ్‌లో అత్యధిక శాశ్వత అడవులు (75%). సమాజ భాగస్వామ్యం – సరిస్కాలో గ్రామస్తుల మైనింగ్ వ్యతిరేకత, అల్వార్ (రాజస్థాన్) భైరోదేవ్ డాకవ్ సోంచూరి (1200 హెక్టార్లు), చిప్కో ఉద్యమం (హిమాలయాలు), బీజ్ బచావో ఆందోళన (టెహ్రి), నవదాన్య, సంయుక్త అటవీ నిర్వహణ (JFM – ఒడిశా 1988), పవిత్ర వనాలు, బిష్ణోయి గ్రామాల్లో కృష్ణజింకలు, నెమళ్ళ రక్షణ, ముండాలు–సంతాల్‌లు (మహువా, కదంబం), ఒడిశా–బీహార్ గిరిజనులు (చింత, మామిడి).","pts":["జీవ వైవిధ్యం: రూపం, విధుల్లో వైవిధ్యమైన జీవులు – పరస్పర ఆధారితం; మనిషి ఈ పర్యావరణ వ్యవస్థలో ఒక భాగం మాత్రమే.","సంరక్షణ ఎందుకు: పర్యావరణ వైవిధ్యం, జీవాధార వ్యవస్థలు (నీరు, గాలి, నేల), మొక్కలు–జంతువుల జన్యు వైవిధ్యం (సాంప్రదాయ వంగడాలు, మత్స్య సంపద) కాపాడటానికి.","క్షీణత కారణాలు: వ్యవసాయ విస్తరణ, పోడు సాగు, పెద్ద డ్యామ్‌లు, మైనింగ్, పశువుల మేత, ఇంధన కలప, వాణిజ్య అడవులు, వేట, కాలుష్యం, అగ్నిప్రమాదాలు.","భారత వన్యప్రాణి (రక్షణ) చట్టం 1972: రక్షిత జాతుల జాబితా, వేట నిషేధం, ఆవాసాల రక్షణ, వన్యప్రాణుల వ్యాపార నియంత్రణ.","ప్రాజెక్ట్ టైగర్ (1973): 1973లో 1,827 పులులు మాత్రమే (శతాబ్దం ప్రారంభంలో 55,000); ఇప్పుడు దేశమంతా అనేక టైగర్ రిజర్వులు.","టైగర్ రిజర్వులు: కార్బెట్ (ఉత్తరాఖండ్), సుందర్‌బన్స్ (ప.బెంగాల్), బాంధవ్‌గఢ్ (MP), సరిస్కా (రాజస్థాన్), మానస్ (అస్సాం), పెరియార్ (కేరళ); మన AP లో నాగార్జునసాగర్–శ్రీశైలం.","రిజర్వ్ అడవులు: మొత్తం అటవీ భూమిలో సగానికి పైగా – అత్యంత విలువైనవి; రక్షిత అడవులు: మూడో వంతు; అవర్గీకృత అడవులు: ఇతర అడవులు, వ్యర్థ భూములు.","చిప్కో ఉద్యమం: హిమాలయాల్లో చెట్లను కౌగిలించుకుని నరికివేతను అడ్డుకున్న ప్రజా ఉద్యమం.","బీజ్ బచావో ఆందోళన (టెహ్రి), నవదాన్య: రసాయనాలు లేకుండా వైవిధ్యమైన పంటల సాగు.","సంయుక్త అటవీ నిర్వహణ (JFM): 1988 ఒడిశా మొదటి తీర్మానం – క్షీణించిన అడవుల పునరుద్ధరణలో గ్రామ సంఘాలు; బదులుగా కలపేతర అటవీ ఉత్పత్తులు, కలపలో వాటా.","పవిత్ర వనాలు: ప్రకృతి ఆరాధనతో సంరక్షించే అడవులు; బిష్ణోయిలు (రాజస్థాన్) – కృష్ణజింకలు, చింకారాలు, నెమళ్ళ రక్షణ."],"w":[["జీవ వైవిధ్యం","Biodiversity"],["వృక్షజాలం","Flora"],["జంతుజాలం","Fauna"],["జన్యు వైవిధ్యం","Genetic diversity"],["జీవాధార వ్యవస్థలు","Life support systems"],["వేట","Poaching"],["పోడు / విస్థాపన సాగు","Shifting cultivation"],["రిజర్వ్ అడవులు","Reserved forests"],["రక్షిత అడవులు","Protected forests"],["అవర్గీకృత అడవులు","Unclassed forests"],["జాతీయ ఉద్యానవనం","National park"],["అభయారణ్యం","Wildlife sanctuary"],["సంయుక్త అటవీ నిర్వహణ","Joint Forest Management (JFM)"],["పవిత్ర వనాలు","Sacred groves"]],"gr":{"t":"ముఖ్య తేదీలు, గణాంకాలు","p":["జీవ వైవిధ్యం → సంరక్షణ → రిజర్వ్/రక్షిత/అవర్గీకృత అడవులు → సమాజ భాగస్వామ్యం","1972 భారత వన్యప్రాణి (రక్షణ) చట్టం | 1973 ప్రాజెక్ట్ టైగర్ | 1980, 1986 కీటకాలు రక్షిత జాబితాలో | 1991 మొక్కలు (6 జాతులు)","1988 ఒడిశా – సంయుక్త అటవీ నిర్వహణ తొలి తీర్మానం","మధ్యప్రదేశ్ – శాశ్వత అడవులు 75% (అత్యధికం)","పులులు: 1900 ~55,000 → 1973 1,827"]},"qa":[["జీవ వైవిధ్యం అంటే?","భూమి మీద ఉన్న వివిధ రకాల జీవుల (వృక్ష, జంతు, సూక్ష్మజీవుల) వైవిధ్యం – అవి పరస్పర ఆధారితంగా జీవిస్తాయి."],["ప్రాజెక్ట్ టైగర్ ఎప్పుడు ప్రారంభం?","1973."],["భారత వన్యప్రాణి (రక్షణ) చట్టం?","1972."],["పులుల సంఖ్యకు ప్రధాన ముప్పులు?","వేట (చర్మం, ఎముకల వ్యాపారం), ఆవాసాలు తగ్గడం, ఆహార జంతువుల తగ్గుదల, జనాభా పెరుగుదల."],["రిజర్వ్ అడవులను అత్యంత విలువైనవి అని ఎందుకు అంటారు?","అటవీ, వన్యప్రాణి సంరక్షణకు అవి ఎక్కువ రక్షణ ఇస్తాయి – ప్రవేశం, వినియోగంపై కఠిన నియంత్రణ."],["చిప్కో ఉద్యమం ఏమిటి?","హిమాలయ ప్రాంతంలో చెట్లను కౌగిలించుకుని నరికివేతను అడ్డుకున్న ప్రజా (మహిళల) ఉద్యమం."],["సంయుక్త అటవీ నిర్వహణ (JFM) అంటే?","స్థానిక సమాజాల భాగస్వామ్యంతో క్షీణించిన అడవుల నిర్వహణ, పునరుద్ధరణ – 1988 ఒడిశా."],["బిష్ణోయిలు ఏ జంతువులను రక్షిస్తారు?","కృష్ణజింకలు (నల్ల జింకలు), చింకారాలు, నీల్‌గాయ్, నెమళ్ళు."],["అడవులు, వన్యప్రాణులను ఎందుకు సంరక్షించాలి?","పర్యావరణ వైవిధ్యం, నీరు–గాలి–నేల వంటి జీవాధార వ్యవస్థలు, జన్యు వైవిధ్యం కాపాడటానికి."],["అత్యధిక శాశ్వత అడవులు గల రాష్ట్రం?","మధ్యప్రదేశ్ (75%)."]],"act":"మీ ప్రాంతంలో ఉన్న పవిత్ర వృక్షాలు (రావి, వేప, మర్రి, తులసి) వాటికి సంబంధించిన నమ్మకాలు సేకరించండి. పాఠశాలలో “ఒక విద్యార్థి – ఒక మొక్క” కార్యక్రమం చేయండి.","kn":"మన ఆంధ్రప్రదేశ్‌లోని నాగార్జునసాగర్–శ్రీశైలం టైగర్ రిజర్వ్ దేశంలోనే అతిపెద్ద టైగర్ రిజర్వు! మనకు దగ్గరలోని పులికాట్ సరస్సు, నేలపట్టు (తిరుపతి జిల్లా) పక్షుల అభయారణ్యాలకు శీతాకాలంలో ఫ్లెమింగోలు, పెలికాన్‌లు వస్తాయి.","qz":[["సమాజ భాగస్వామ్యం నేరుగా లేని సంరక్షణ వ్యూహం?","వన్యప్రాణి అభయారణ్యాల సరిహద్దులు నిర్ణయించడం","సంయుక్త అటవీ నిర్వహణ","బీజ్ బచావో ఆందోళన","చిప్కో ఉద్యమం"],["అత్యంత విలువైన అడవులుగా పరిగణించేవి?","రిజర్వ్ అడవులు","రక్షిత అడవులు","అవర్గీకృత అడవులు","సామాజిక అడవులు"],["ప్రాజెక్ట్ టైగర్ ప్రారంభమైన సంవత్సరం?","1973","1972","1988","1991"],["భారత వన్యప్రాణి (రక్షణ) చట్టం?","1972","1952","1980","1992"],["సంయుక్త అటవీ నిర్వహణ మొదట ప్రారంభించిన రాష్ట్రం?","ఒడిశా","రాజస్థాన్","ఉత్తరాఖండ్","మధ్యప్రదేశ్"],["చిప్కో ఉద్యమం జరిగిన ప్రాంతం?","హిమాలయాలు","థార్ ఎడారి","పశ్చిమ కనుమలు","సుందర్‌బన్స్"],["కృష్ణజింకలు, నెమళ్ళను రక్షించే సమాజం?","బిష్ణోయిలు","ముండాలు","సంతాల్‌లు","గోండులు"],["అత్యధిక శాశ్వత అడవులు గల రాష్ట్రం?","మధ్యప్రదేశ్","అస్సాం","కేరళ","ఒడిశా"],["1973లో భారత్‌లో పులుల సంఖ్య?","1,827","55,000","5,000","10,000"],["ఇతర అడవులు, వ్యర్థ భూములు (ప్రభుత్వ, ప్రైవేటు, సమాజాలవి)?","అవర్గీకృత అడవులు","రిజర్వ్ అడవులు","రక్షిత అడవులు","జాతీయ ఉద్యానవనాలు"],["సంరక్షణ కాపాడే జీవాధార వ్యవస్థలు?","నీరు, గాలి, నేల","బొగ్గు, చమురు","రోడ్లు, రైల్వేలు","పరిశ్రమలు"],["వన్యప్రాణి చట్టం (1980, 1986) నోటిఫికేషన్‌లో రక్షిత జాబితాలో చేరినవి?","సీతాకోకచిలుకలు, చిమ్మటలు, బీటిల్స్","పులులు మాత్రమే","చెట్లు మాత్రమే","చేపలు"],["1991లో రక్షిత జాబితాలో మొదటిసారి చేరినవి?","మొక్కలు (6 జాతులు)","పులులు","పక్షులు","కీటకాలు"],["బీజ్ బచావో ఆందోళన ఎక్కడ?","టెహ్రి (ఉత్తరాఖండ్)","అల్వార్","ఒడిశా","సరిస్కా"],["సరిస్కా టైగర్ రిజర్వ్ ఏ రాష్ట్రంలో?","రాజస్థాన్","అస్సాం","కేరళ","మధ్యప్రదేశ్"],["భైరోదేవ్ డాకవ్ సోంచూరి ఏ రాష్ట్రంలో?","రాజస్థాన్ (అల్వార్)","ఉత్తరాఖండ్","ఒడిశా","కర్ణాటక"]],"wb":{"mis":"రక్షిత అడవులు అత్యంత విలువైనవి కావు – రిజర్వ్ అడవులే. అభయారణ్యాల సరిహద్దులు నిర్ణయించడం ప్రభుత్వ చర్య – సమాజ భాగస్వామ్యం కాదు. ప్రాజెక్ట్ టైగర్ పులులను మాత్రమే కాదు, మొత్తం పర్యావరణ వ్యవస్థను కాపాడే కార్యక్రమం.","qz":[],"pg":"30–41","f":"books/10/Class10_Social_Geography_Textbook.pdf","p":36,"lb":"పాఠ్యపుస్తకం","ws":["కనుగొనండి – మనిషి–ప్రకృతి సామరస్య కథలు (పుట 30)","ఆలోచించండి – సమస్యలకు కారణాలు (పుట 36)","అభ్యాసాలు – Exercises (పుట 40)"]},"tg":[["కనుగొనండి – మనిషి–ప్రకృతి సామరస్య కథలు (పుట 30)",["ఉదాహరణలు: రావి, వేప, మర్రి చెట్లను పూజించడం, నరకకపోవడం; నాగుల చవితికి పుట్టలకు పూజ – పాములను చంపకపోవడం; తిరుపతి కొండల్లో శ్రీవారి ఏడుకొండలపై చెట్లు నరకకపోవడం; పులికాట్ దగ్గర పక్షులను గ్రామస్తులు కాపాడటం (నేలపట్టు – పెలికాన్‌లను శుభంగా భావించడం); బిష్ణోయిల అమృతాదేవి కథ – చెట్ల కోసం 363 మంది ప్రాణత్యాగం."]],["ఆలోచించండి – సమస్యలకు కారణాలు (పుట 36)",["అడవులు, వన్యప్రాణుల సమస్యలకు కారణాలు: జనాభా పెరుగుదల, వ్యవసాయ విస్తరణ, పోడు సాగు, పెద్ద డ్యామ్‌లు, మైనింగ్, పరిశ్రమలు, రోడ్లు–రైల్వేలు, కలప–ఇంధనం కోసం నరికివేత, అతిగా మేపడం, వేట, అక్రమ వన్యప్రాణి వ్యాపారం (పులి చర్మం, ఏనుగు దంతాలు), కాలుష్యం, అగ్నిప్రమాదాలు, స్థానిక సమాజాలను సంరక్షణలో భాగస్వాములను చేయకపోవడం."]],["అభ్యాసాలు – Exercises (పుట 40)",["1) (i) (d) వన్యప్రాణి అభయారణ్యాల సరిహద్దులు నిర్ణయించడం","2) రిజర్వ్ అడవులు – అటవీ, వన్యప్రాణి సంరక్షణలో అత్యంత విలువైనవిగా పరిగణించే అడవులు; రక్షిత అడవులు – అటవీ భూములను మరింత క్షీణత నుండి రక్షిస్తారు; అవర్గీకృత అడవులు – ప్రభుత్వ, ప్రైవేటు వ్యక్తులు, సమాజాలకు చెందిన ఇతర అడవులు, వ్యర్థ భూములు.","3) (i) జీవ వైవిధ్యం – భూమిపై రూపం, విధుల్లో వేర్వేరుగా ఉన్నా పరస్పర ఆధారితంగా జీవించే వృక్ష, జంతు, సూక్ష్మజీవుల వైవిధ్యం. ప్రాముఖ్యం: గాలి (ఆక్సిజన్), నీరు, నేల సారం, ఆహారం, మందులు, కలప, పరాగసంపర్కం; పర్యావరణ సమతుల్యత; మనిషి కూడా ఈ వ్యవస్థలో భాగం – ఒకటి నశిస్తే మిగతావీ ప్రభావితమవుతాయి.","(ii) వ్యవసాయ విస్తరణ, పోడు సాగు, పెద్ద నదీ లోయ ప్రాజెక్టులు, మైనింగ్, వాణిజ్య అడవులు (ఏకపంట తోటలు – టేకు, యూకలిప్టస్), పశువుల మేత, కలప, వేట, వన్యప్రాణి వ్యాపారం, కాలుష్యం, అగ్నిప్రమాదాలు – ఆవాసాలు నాశనమై జాతులు క్షీణించాయి.","4) (i) సమాజాల సంరక్షణ: సరిస్కాలో గ్రామస్తులు వన్యప్రాణి చట్టాన్ని ఉపయోగించి మైనింగ్‌కు వ్యతిరేకంగా పోరాడారు; అల్వార్ జిల్లాలో 5 గ్రామాలు 1200 హెక్టార్ల అడవిని “భైరోదేవ్ డాకవ్ సోంచూరి”గా ప్రకటించి సొంత నియమాలతో వేట నిషేధించాయి; హిమాలయాల్లో చిప్కో ఉద్యమం; టెహ్రిలో బీజ్ బచావో ఆందోళన, నవదాన్య; ఒడిశాలో సంయుక్త అటవీ నిర్వహణ (1988); పవిత్ర వనాలు; బిష్ణోయిలు కృష్ణజింకలు, నెమళ్ళను రక్షించడం; ముండాలు, సంతాల్‌లు మహువా, కదంబ చెట్లను పూజించడం; మర్రి, రావి చెట్ల పూజ.","(ii) మంచి పద్ధతులు: మొక్కలు నాటడం, సామాజిక అడవులు; వన్యప్రాణి చట్టాల కఠిన అమలు, వేట–అక్రమ వ్యాపార నిరోధం; జాతీయ ఉద్యానవనాలు, అభయారణ్యాలు, టైగర్ రిజర్వులు; స్థానిక సమాజాల భాగస్వామ్యం (JFM), వారికి అటవీ ఉత్పత్తుల్లో వాటా; పోడు సాగు, అతిగా మేపడం నియంత్రణ; కాగితం–కలప వినియోగం తగ్గించడం, రీసైక్లింగ్; అటవీ అగ్నిప్రమాదాల నివారణ; ప్రజల్లో అవగాహన, పవిత్ర వనాల సంరక్షణ."]]]},{"id":"gs3","no":8,"t":"జల వనరులు (Water Resources)","m":[8],"ty":"భూగోళం – అధ్యాయం 3","by":"సాంఘిక శాస్త్రం – భూగోళం 10వ తరగతి (పుటలు 42–63)","th":"నీటి కొరత, జల సంరక్షణ–నిర్వహణ, బహుళార్థ సాధక నదీ ప్రాజెక్టులు, వర్షపు నీటి సంరక్షణ","sum":"భూమి ఉపరితలంలో మూడొంతులు నీరే అయినా మంచినీరు చాలా తక్కువ; జలచక్రం ద్వారా నీరు పునరుద్ధరించగల వనరు. నీటి కొరతకు కారణాలు – వర్షపాతంలో ప్రాంతీయ, కాలానుగుణ వ్యత్యాసాలు కాకుండా ఎక్కువగా అతి వినియోగం, అసమాన అందుబాటు: పెరుగుతున్న జనాభా, ఎక్కువ ఆహారం కోసం సాగునీరు (బోరుబావులు, భూగర్భ జల క్షీణత), పారిశ్రామికీకరణ (నీరు, విద్యుత్ అవసరం), పట్టణీకరణ, పట్టణ జీవనశైలి; నీరు సమృద్ధిగా ఉన్నా గృహ, పారిశ్రామిక, వ్యవసాయ వ్యర్థాలతో కాలుష్యం – నాణ్యత కొరత. ప్రాచీన భారత జల నిర్మాణాలు – క్రీ.పూ. 1వ శతాబ్దం శృంగవేరపురం (అలహాబాద్ దగ్గర) గంగా వరద నీటి వ్యవస్థ; చంద్రగుప్త మౌర్య కాలంలో డ్యామ్‌లు, సరస్సులు; కళింగ (ఒడిశా), నాగార్జునకొండ (ఆంధ్ర), బెన్నూర్ (కర్ణాటక), కొల్హాపూర్ సాగునీటి పనులు; 11వ శతాబ్దం భోపాల్ సరస్సు; 14వ శతాబ్దం హౌజ్ ఖాస్ (ఇల్టుట్‌మిష్). బహుళార్థ సాధక నదీ ప్రాజెక్టులు – సాగునీరు, విద్యుత్, గృహ–పారిశ్రామిక నీరు, వరద నియంత్రణ, వినోదం, జల రవాణా, చేపల పెంపకం; భాక్రా–నంగల్ (సట్లెజ్–బియాస్), హీరాకుడ్ (మహానది); నెహ్రూ – “ఆధునిక భారత దేవాలయాలు”. సర్దార్ సరోవర్ (నర్మదా, గుజరాత్ – 4 రాష్ట్రాలు; 18.45 లక్షల హెక్టార్లు). విమర్శలు – నదుల సహజ ప్రవాహం, అవక్షేప ప్రవాహం ఆగిపోవడం, జలాశయాల అడుగున అవక్షేపం, జలచరాల వలసకు అడ్డు, అటవీ మునక, ప్రజల నిర్వాసితం (నర్మదా బచావో ఆందోళన, టెహ్రి డ్యామ్ ఆందోళన), పంటల సరళి మార్పు – లవణీకరణ, సామాజిక అసమానతలు, అంతర్రాష్ట్ర జల వివాదాలు (కృష్ణా–గోదావరి – కోయ్నా వద్ద నీటి మళ్లింపుపై కర్ణాటక, AP అభ్యంతరం), వరదల నియంత్రణ బదులు వరదలు, భూకంపాలు, నీటి ద్వారా వ్యాధులు. వర్షపు నీటి సంరక్షణ – కొండ ప్రాంతాల్లో “గుల్‌లు”, “కుల్‌లు” (పశ్చిమ హిమాలయాలు); రాజస్థాన్‌లో ఇంటి పైకప్పు నీటి సేకరణ – “టాంకాలు” (భూగర్భ ట్యాంకులు), “పాలర్ పానీ” (వర్షపు నీరు – అత్యంత స్వచ్ఛం); వరద నీటి కాలువలు (బెంగాల్), జైసల్మేర్ “ఖదీన్‌లు”, రాజస్థాన్ “జోహడ్‌లు”; ఇందిరాగాంధీ కాలువ వల్ల పశ్చిమ రాజస్థాన్‌లో ఈ పద్ధతి క్షీణిస్తోంది. మేఘాలయ వెదురు బిందు సేద్యం (200 ఏళ్లు, నిమిషానికి 20–80 చుక్కలు); కర్ణాటక మైసూరు గెందతూర్ గ్రామంలో 200 ఇళ్ల పైకప్పు సేకరణ (ఏటా 1,00,000 లీటర్లు); షిల్లాంగ్ (మేఘాలయ) పైకప్పు సేకరణ – చిరపుంజీ, మాసిన్‌రామ్ దగ్గరైనా కొరత; తమిళనాడు – అన్ని ఇళ్ళకు పైకప్పు వర్షపు నీటి సంరక్షణ తప్పనిసరి చేసిన తొలి రాష్ట్రం.","pts":["నీరు పునరుద్ధరించగల వనరు – జలచక్రం (ఆవిరి, మేఘాలు, వర్షం, ప్రవాహం) ద్వారా నిరంతరం పునరుద్ధరణ.","నీటి కొరత కారణాలు: అధిక జనాభా, సాగునీటి డిమాండ్, భూగర్భ జలాల అతి వినియోగం, పారిశ్రామికీకరణ, పట్టణీకరణ, అసమాన పంపిణీ, కాలుష్యం.","నీరు ఉన్నా కొరత: గృహ, పారిశ్రామిక వ్యర్థాలు, రసాయనాలు, పురుగుమందులతో కలుషితమై తాగడానికి పనికిరాకపోవడం.","ప్రాచీన జల నిర్మాణాలు: శృంగవేరపురం (క్రీ.పూ. 1వ శ.), చంద్రగుప్త మౌర్య కాలంలో డ్యామ్‌లు, సరస్సులు; కళింగ, నాగార్జునకొండ, బెన్నూర్, కొల్హాపూర్; భోపాల్ సరస్సు (11వ శ.); హౌజ్ ఖాస్ (14వ శ., ఇల్టుట్‌మిష్).","డ్యామ్: ప్రవహించే నీటిని అడ్డుకుని నిల్వ చేసే నిర్మాణం – జలాశయం, సరస్సు ఏర్పడతాయి; స్పిల్‌వే ద్వారా నియంత్రిత విడుదల.","బహుళార్థ సాధక ప్రాజెక్టులు: సాగునీరు, జల విద్యుత్, గృహ–పారిశ్రామిక నీరు, వరద నియంత్రణ, వినోదం, జల రవాణా, చేపల పెంపకం.","భాక్రా–నంగల్ (సట్లెజ్–బియాస్) – విద్యుత్ + సాగునీరు; హీరాకుడ్ (మహానది) – జల సంరక్షణ + వరద నియంత్రణ.","జవహర్‌లాల్ నెహ్రూ డ్యామ్‌లను “ఆధునిక భారత దేవాలయాలు” అన్నారు – వ్యవసాయం, గ్రామ ఆర్థిక వ్యవస్థను పారిశ్రామికీకరణతో కలుపుతాయని.","సర్దార్ సరోవర్ (నర్మదా, గుజరాత్): మహారాష్ట్ర, మధ్యప్రదేశ్, గుజరాత్, రాజస్థాన్ – 18.45 లక్షల హెక్టార్లకు సాగునీరు (గుజరాత్ 15 జిల్లాలు, 3112 గ్రామాలు).","ప్రాజెక్టుల ప్రతికూలతలు: సహజ ప్రవాహం–అవక్షేపం ఆగిపోవడం, జలచరాలకు ముప్పు, అడవుల మునక, ప్రజల నిర్వాసితం, అంతర్రాష్ట్ర వివాదాలు, లవణీకరణ, ప్రేరేపిత భూకంపాలు, వ్యాధులు.","నర్మదా బచావో ఆందోళన: నర్మదా సర్దార్ సరోవర్ డ్యామ్‌కు వ్యతిరేకంగా గిరిజనులు, రైతులు, పర్యావరణవేత్తల ఉద్యమం.","సంప్రదాయ పద్ధతులు: గుల్/కుల్ (పశ్చిమ హిమాలయ మళ్లింపు కాలువలు), పైకప్పు సేకరణ (రాజస్థాన్), వరద కాలువలు (బెంగాల్), ఖదీన్ (జైసల్మేర్), జోహడ్ (రాజస్థాన్).","టాంకా: బికనీర్, ఫలోడి, బార్మర్ ఇళ్లలో భూగర్భ నీటి ట్యాంకులు – పెద్ద గదంత; వేసవిలో చల్లదనం; “పాలర్ పానీ” అత్యంత స్వచ్ఛమైన నీరు.","వెదురు బిందు సేద్యం (మేఘాలయ): 200 ఏళ్ల పద్ధతి – కొండ ఊటల నీటిని వెదురు గొట్టాలతో మొక్కల వద్దకు, నిమిషానికి 20–80 చుక్కలు.","తమిళనాడు: రాష్ట్రంలోని అన్ని ఇళ్ళకు పైకప్పు వర్షపు నీటి సంరక్షణ నిర్మాణాలు తప్పనిసరి చేసిన తొలి రాష్ట్రం."],"w":[["జల వనరులు","Water resources"],["నీటి కొరత","Water scarcity"],["జలచక్రం","Hydrological cycle"],["భూగర్భ జలం","Groundwater"],["డ్యామ్ / ఆనకట్ట","Dam"],["జలాశయం","Reservoir"],["బహుళార్థ సాధక ప్రాజెక్ట్","Multi-purpose river project"],["జల విద్యుత్","Hydroelectricity"],["అవక్షేపం","Sediment"],["నిర్వాసితం","Displacement"],["వర్షపు నీటి సంరక్షణ","Rainwater harvesting"],["పైకప్పు నీటి సేకరణ","Rooftop rainwater harvesting"],["టాంకా","Tanka (underground tank)"],["బిందు సేద్యం","Drip irrigation"],["అంతర్రాష్ట్ర జల వివాదం","Inter-state water dispute"]],"gr":{"t":"ముఖ్య ప్రాజెక్టులు, పద్ధతులు","p":["భాక్రా–నంగల్ – సట్లెజ్–బియాస్ | హీరాకుడ్ – మహానది | సర్దార్ సరోవర్ – నర్మదా | నాగార్జునసాగర్ – కృష్ణా (AP–తెలంగాణ)","గుల్/కుల్ – పశ్చిమ హిమాలయాలు | ఖదీన్ – జైసల్మేర్ | జోహడ్ – రాజస్థాన్ | టాంకా – బికనీర్, ఫలోడి, బార్మర్","వెదురు బిందు సేద్యం – మేఘాలయ | పైకప్పు సేకరణ – షిల్లాంగ్, గెందతూర్ (మైసూరు, కర్ణాటక)","గెందతూర్: వర్షపాతం 1,000 మి.మీ.; 80% సేకరణ సామర్థ్యం; ఒక్కో ఇంటికి ఏటా సుమారు 50,000 లీటర్లు; 200 ఇళ్లు – ఏటా 1,00,000 లీటర్లు (పుస్తకం ప్రకారం)"]},"qa":[["నీరు పునరుద్ధరించగల వనరు ఎలా?","జలచక్రం ద్వారా – ఆవిరైన నీరు మేఘాలుగా మారి వర్షంగా మళ్ళీ భూమికి వస్తుంది."],["నీటి కొరతకు ప్రధాన కారణాలు?","అధిక జనాభా, సాగు–పరిశ్రమల డిమాండ్, అతి వినియోగం, అసమాన పంపిణీ, కాలుష్యం."],["బహుళార్థ సాధక ప్రాజెక్టు అంటే?","సాగునీరు, విద్యుత్, వరద నియంత్రణ, తాగునీరు, జల రవాణా, చేపల పెంపకం వంటి అనేక ప్రయోజనాల కోసం నదిపై నిర్మించే ప్రాజెక్టు."],["“ఆధునిక భారత దేవాలయాలు” అని డ్యామ్‌లను ఎవరు అన్నారు?","జవహర్‌లాల్ నెహ్రూ."],["హీరాకుడ్ ప్రాజెక్టు ఏ నదిపై?","మహానది (ఒడిశా)."],["సర్దార్ సరోవర్ డ్యామ్ ఏ నదిపై?","నర్మదా (గుజరాత్)."],["టాంకాలు అంటే?","రాజస్థాన్ ఇళ్లలో పైకప్పు వర్షపు నీటిని నిల్వ చేసే భూగర్భ ట్యాంకులు."],["పాలర్ పానీ అంటే?","రాజస్థాన్‌లో వర్షపు నీటికి పేరు – అత్యంత స్వచ్ఛమైన నీరుగా భావిస్తారు."],["పైకప్పు వర్షపు నీటి సంరక్షణ తప్పనిసరి చేసిన తొలి రాష్ట్రం?","తమిళనాడు."],["మేఘాలయలో ఏ సంప్రదాయ సేద్యం?","వెదురు బిందు సేద్యం (200 ఏళ్ల పద్ధతి)."]],"act":"మీ ఇల్లు/పాఠశాల పైకప్పు విస్తీర్ణం కొలిచి, ఏటా ఎంత వర్షపు నీరు సేకరించవచ్చో లెక్కించండి (విస్తీర్ణం m² × వర్షపాతం m × 1000 = లీటర్లు). మీ ఊరిలో ఇంకుడు గుంతలు, చెరువులు ఎన్ని ఉన్నాయో సర్వే చేయండి.","kn":"మన ఆంధ్రప్రదేశ్‌లోని నాగార్జునసాగర్ ప్రపంచంలోని అతి పెద్ద రాతి కట్టడపు (masonry) డ్యామ్‌లలో ఒకటి! నెల్లూరు జిల్లాలోని సోమశిల జలాశయం (పెన్నా నది) మన జిల్లాకు ప్రధాన సాగునీటి వనరు.","qz":[["బహుళార్థ సాధక ప్రాజెక్టులకు అనుకూలం కాని వాదన?","పెద్ద ఎత్తున నిర్వాసితం, జీవనోపాధి నష్టం","నీటి కొరత ప్రాంతాలకు నీరు","వరద నియంత్రణ","పరిశ్రమలు, ఇళ్ళకు విద్యుత్"],["భాక్రా–నంగల్ ప్రాజెక్టు ఏ నదీ బేసిన్‌లో?","సట్లెజ్–బియాస్","మహానది","నర్మదా","కృష్ణా"],["హీరాకుడ్ ప్రాజెక్టు నది?","మహానది","దామోదర్","గోదావరి","సట్లెజ్"],["“ఆధునిక భారత దేవాలయాలు” అన్నది?","జవహర్‌లాల్ నెహ్రూ","గాంధీజీ","అంబేద్కర్","పటేల్"],["సర్దార్ సరోవర్ డ్యామ్ ఏ రాష్ట్రంలో?","గుజరాత్","మధ్యప్రదేశ్","మహారాష్ట్ర","రాజస్థాన్"],["పశ్చిమ హిమాలయాల్లో మళ్లింపు కాలువలు?","గుల్‌లు, కుల్‌లు","టాంకాలు","ఖదీన్‌లు","జోహడ్‌లు"],["జైసల్మేర్‌లో వర్షపు నీరు నిలిపి నేలను తడిపే పద్ధతి?","ఖదీన్","కుల్","టాంకా","వెదురు బిందు"],["రాజస్థాన్ ఇళ్లలో భూగర్భ నీటి ట్యాంకులు?","టాంకాలు","కుల్‌లు","ఖదీన్‌లు","చెక్‌డ్యామ్‌లు"],["వెదురు బిందు సేద్యం ఏ రాష్ట్రంలో?","మేఘాలయ","రాజస్థాన్","కర్ణాటక","తమిళనాడు"],["పైకప్పు వర్షపు నీటి సంరక్షణ తప్పనిసరి చేసిన తొలి రాష్ట్రం?","తమిళనాడు","కర్ణాటక","రాజస్థాన్","కేరళ"],["గెందతూర్ గ్రామం (పైకప్పు సేకరణ) ఎక్కడ?","మైసూరు, కర్ణాటక","షిల్లాంగ్","బికనీర్","జైసల్మేర్"],["11వ శతాబ్దంలో నిర్మించిన పెద్ద కృత్రిమ సరస్సు?","భోపాల్ సరస్సు","హౌజ్ ఖాస్","దాల్ సరస్సు","చిల్కా"],["ఎక్కువ వర్షపాతం ఉన్నా నీటి కొరత ఎదుర్కొనే నగరం (పాఠం ప్రకారం)?","షిల్లాంగ్","జైపూర్","బికనీర్","చెన్నై"],["కృష్ణా–గోదావరి వివాదం దేనిపై?","కోయ్నా వద్ద మహారాష్ట్ర నీటి మళ్లింపు","సర్దార్ సరోవర్","భాక్రా డ్యామ్","హీరాకుడ్"],["నర్మదా బచావో ఆందోళన దేనికి వ్యతిరేకం?","సర్దార్ సరోవర్ డ్యామ్","టెహ్రి డ్యామ్","భాక్రా–నంగల్","హీరాకుడ్"],["పశ్చిమ రాజస్థాన్‌లో పైకప్పు సేకరణ క్షీణించడానికి కారణం?","ఇందిరాగాంధీ కాలువ ద్వారా నీరు","వర్షపాతం పెరుగుదల","జనాభా తగ్గుదల","ప్రభుత్వ నిషేధం"]],"wb":{"mis":"వర్షపాతం ఎక్కువైతే నీటి కొరత ఉండదు అనుకోవడం తప్పు – జనాభా, కాలుష్యం, అసమాన పంపిణీ వల్ల కొరత రావచ్చు (షిల్లాంగ్, కలుషిత నీరు). డ్యామ్‌లు నది సహజ ప్రవాహాన్ని, అవక్షేప ప్రవాహాన్ని ప్రభావితం చేస్తాయి. రాజస్థాన్‌లో ఇందిరాగాంధీ కాలువ వచ్చాక పైకప్పు సేకరణ తగ్గింది – పెరగలేదు.","qz":[],"pg":"42–63","f":"books/10/Class10_Social_Geography_Textbook.pdf","p":48,"lb":"పాఠ్యపుస్తకం","ws":["కనుగొనండి – సంప్రదాయ డ్యామ్/సాగునీటి పద్ధతి (పుట 48)","కృత్యం – అంతర్రాష్ట్ర జల వివాదాలు (పుట 50)","కనుగొనండి – మీ ప్రాంతంలో వర్షపు నీటి సంరక్షణ (పుట 58)","అభ్యాసాలు – Exercises (పుట 62)"]},"tg":[["కనుగొనండి – సంప్రదాయ డ్యామ్/సాగునీటి పద్ధతి (పుట 48)",["ఉదాహరణ: మన ఆంధ్రప్రదేశ్‌లో చెరువుల వ్యవస్థ – కాకతీయులు, విజయనగర రాజుల కాలంలో గొలుసు చెరువులు (ఒక చెరువు నిండి మిగులు నీరు తర్వాతి చెరువుకు). గ్రామస్తులు కలిసి పూడికతీత (మరమ్మతు), నీటి వాటా “నీరడి” ద్వారా పంపిణీ. ఇంకా – కావేరిపై కరికాల చోళుడు నిర్మించిన గ్రాండ్ ఆనకట్ట (కల్లణై, సుమారు 2000 ఏళ్లు), కర్ణాటక కెరెలు, రాజస్థాన్ జోహడ్‌లు."]],["కృత్యం – అంతర్రాష్ట్ర జల వివాదాలు (పుట 50)",["కావేరి జల వివాదం (కర్ణాటక, తమిళనాడు, కేరళ, పుదుచ్చేరి); కృష్ణా జల వివాదం (మహారాష్ట్ర, కర్ణాటక, ఆంధ్రప్రదేశ్, తెలంగాణ); గోదావరి (మహారాష్ట్ర, AP, తెలంగాణ, ఛత్తీస్‌గఢ్, ఒడిశా, MP, కర్ణాటక); నర్మదా (గుజరాత్, MP, మహారాష్ట్ర, రాజస్థాన్); రావి–బియాస్ (పంజాబ్, హర్యానా, రాజస్థాన్); మహాదాయి/మాండోవి (గోవా, కర్ణాటక, మహారాష్ట్ర); వంశధార (ఆంధ్రప్రదేశ్, ఒడిశా); మహానది (ఒడిశా, ఛత్తీస్‌గఢ్)."]],["కనుగొనండి – మీ ప్రాంతంలో వర్షపు నీటి సంరక్షణ (పుట 58)",["మా ప్రాంతంలో (గూడూరు, SPSR నెల్లూరు): గ్రామ చెరువులు, కుంటలు; ఇళ్ళ వద్ద ఇంకుడు గుంతలు; పొలాల్లో ఫారం పాండ్‌లు (నీటి కుంటలు); చెక్‌డ్యామ్‌లు; ప్రభుత్వ భవనాల పైకప్పు నీటి సేకరణ; పాఠశాలల్లో ఇంకుడు గుంతలు; ఉపాధి హామీ ద్వారా చెరువుల పూడికతీత."]],["అభ్యాసాలు – Exercises (పుట 62)",["1) (i) (a) అధిక వర్షపాతం ఉన్న ప్రాంతం – నీటి కొరత లేదు; (b) అధిక వర్షపాతం, అధిక జనాభా – నీటి కొరత; (c) అధిక వర్షపాతం కానీ నీరు బాగా కలుషితం – నీటి కొరత; (d) తక్కువ వర్షపాతం, తక్కువ జనాభా – నీటి కొరత లేదు (పరిమిత అవసరం కాబట్టి; కొన్ని సందర్భాల్లో కొరత ఉండవచ్చు).","(ii) (c) బహుళార్థ ప్రాజెక్టులు పెద్ద ఎత్తున నిర్వాసితం, జీవనోపాధి నష్టానికి దారితీస్తాయి.","1) (iii) సరిచేసిన వాక్యాలు: (a) పెద్ద, దట్టమైన జనాభా గల పట్టణ కేంద్రాలు, పట్టణ జీవనశైలి పెరగడం నీటి వనరుల అతి వినియోగానికి, క్షీణతకు దారితీసింది. (b) నదులపై ఆనకట్టలు కట్టి నియంత్రించడం నది సహజ ప్రవాహాన్ని, అవక్షేప ప్రవాహాన్ని ప్రభావితం చేస్తుంది. (c) ఈ రోజు పశ్చిమ రాజస్థాన్‌లో ఇందిరాగాంధీ కాలువ ద్వారా నీరు అందుబాటులోకి రావడంతో పైకప్పు వర్షపు నీటి సంరక్షణ పద్ధతి క్షీణిస్తోంది.","2) (i) జలచక్రం ద్వారా – సముద్రాలు, నదుల నీరు సూర్యుని వేడికి ఆవిరై మేఘాలుగా మారి వర్షం/మంచుగా కురుస్తుంది; నదులు, భూగర్భ జలాలు నిండి మళ్ళీ సముద్రానికి చేరుతుంది – నిరంతరం పునరుద్ధరణ.","(ii) అవసరాలకు సరిపడా నాణ్యమైన నీరు అందుబాటులో లేకపోవడమే నీటి కొరత. కారణాలు: అధిక జనాభా, ఆహార ఉత్పత్తికి సాగునీరు, భూగర్భ జలాల అతి వినియోగం, పారిశ్రామికీకరణ, పట్టణీకరణ, అసమాన అందుబాటు, కాలుష్యం.","(iii) ప్రయోజనాలు: సాగునీరు, జల విద్యుత్, తాగు–పారిశ్రామిక నీరు, వరద నియంత్రణ, జల రవాణా, చేపల పెంపకం, పర్యాటకం. నష్టాలు: నదుల సహజ ప్రవాహం–అవక్షేపం ఆగిపోవడం, జలచరాలకు ముప్పు, అడవుల మునక, ప్రజల నిర్వాసితం, అంతర్రాష్ట్ర వివాదాలు, లవణీకరణ, భూకంపాలు, వ్యాధులు, సామాజిక అసమానతలు.","3) (i) రాజస్థాన్ అర్ధ శుష్క ప్రాంతాల్లో (బికనీర్, ఫలోడి, బార్మర్) ప్రతి ఇంటిలో భూగర్భ ట్యాంకులు (టాంకాలు) నిర్మిస్తారు – పెద్ద గదంత. ఇవి ఇంటి లోపల లేదా ప్రాంగణంలో ఉంటాయి. ఏటవాలు పైకప్పుల నుండి పైపుల ద్వారా వర్షపు నీరు టాంకాలోకి చేరుతుంది. మొదటి వాన నీటిని పైకప్పు, పైపులు శుభ్రమవ్వడానికి వదిలేస్తారు. ఈ “పాలర్ పానీ” అత్యంత స్వచ్ఛమైన నీరు – తర్వాతి వర్షాకాలం వరకు, ఇతర నీటి వనరులు ఎండిపోయిన వేసవిలో కూడా తాగునీరుగా వాడతారు. టాంకాల పక్కన భూగర్భ గదులు చల్లగా ఉంటాయి. జైసల్మేర్‌లో ఖదీన్‌లు, ఇతర ప్రాంతాల్లో జోహడ్‌లు – వర్షపు నీటిని నిలిపి నేలను తడిపే పద్ధతులు.","(ii) ఆధునిక అనుసరణలు: కర్ణాటక గెందతూర్ గ్రామంలో 200 ఇళ్ల పైకప్పు సేకరణ (ఏటా 1,00,000 లీటర్లు); షిల్లాంగ్‌లో ఇళ్ళ పైకప్పు నీటి సేకరణ (నీటి అవసరాల్లో 15–25%); తమిళనాడు – అన్ని ఇళ్ళకు పైకప్పు సంరక్షణ తప్పనిసరి; నగరాల్లో ఇంకుడు గుంతల ద్వారా భూగర్భ జలాల పునరుద్ధరణ; మేఘాలయ వెదురు బిందు సేద్యం స్ఫూర్తితో ఆధునిక బిందు, తుంపర సేద్యం; చెక్‌డ్యామ్‌లు, ఫారం పాండ్‌లు; ప్రభుత్వ పథకాలు (జల్ శక్తి అభియాన్)."]]]},{"id":"gs4","no":9,"t":"వ్యవసాయం (Agriculture)","m":[9],"ty":"భూగోళం – అధ్యాయం 4","by":"సాంఘిక శాస్త్రం – భూగోళం 10వ తరగతి (పుటలు 64–87)","th":"వ్యవసాయ రకాలు, పంట కాలాలు, ప్రధాన పంటలు, సాంకేతిక–సంస్థాగత సంస్కరణలు, భూదాన్–గ్రామదాన్","sum":"భారత్ వ్యవసాయ దేశం – మూడింట రెండొంతుల జనాభా వ్యవసాయంలో; ఆహారం, పరిశ్రమలకు ముడిసరుకు, ఎగుమతులు (తేయాకు, కాఫీ, సుగంధ ద్రవ్యాలు). వ్యవసాయ రకాలు: (1) ప్రాచీన జీవనాధార వ్యవసాయం – చిన్న భూకమతాలు, గొడ్డలి, కర్ర వంటి పాత పనిముట్లు, కుటుంబ శ్రమ; వర్షం, సహజ సారంపై ఆధారం; “నరికి–కాల్చు” (slash and burn) పోడు సాగు – ఈశాన్యంలో ఝూమింగ్, మణిపూర్ పామ్లౌ, బస్తర్ (ఛత్తీస్‌గఢ్) దీపా, అండమాన్–నికోబార్; (మెక్సికో, మధ్య అమెరికా – మిల్పా; వెనిజులా – కొనుకో; బ్రెజిల్ – రోకా; మధ్య ఆఫ్రికా – మసోలె; ఇండోనేషియా – లడాంగ్; వియత్నాం – రే); అస్సాం దిఫు దగ్గర రింఝా కుటుంబం. (2) సాంద్ర జీవనాధార వ్యవసాయం – జనాభా ఒత్తిడి ఎక్కువ ప్రాంతాల్లో; అధిక శ్రమ, రసాయన ఎరువులు, నీటిపారుదల; వారసత్వ హక్కుతో భూకమతాల విభజన. (3) వాణిజ్య వ్యవసాయం – అధిక దిగుబడి వంగడాలు (HYV), ఎరువులు, పురుగుమందులు; పంజాబ్, హర్యానాలో వరి వాణిజ్య పంట, ఒడిశాలో జీవనాధారం; తోటల పెంపకం (plantation) – ఒకే పంట పెద్ద విస్తీర్ణంలో – తేయాకు, కాఫీ, రబ్బరు, చెరకు, అరటి. పంట కాలాలు: రబీ (శీతాకాలం అక్టోబర్–డిసెంబర్ విత్తు, వేసవి ఏప్రిల్–జూన్ కోత – గోధుమ, బార్లీ, బఠాణి, శనగ, ఆవాలు; పశ్చిమ విక్షోభాల వర్షం), ఖరీఫ్ (రుతుపవనాల ప్రారంభంతో విత్తు, సెప్టెంబర్–అక్టోబర్ కోత – వరి, మొక్కజొన్న, జొన్న, సజ్జ, కంది, పెసర, మినుము, పత్తి, జనపనార, వేరుశనగ, సోయాబీన్; ఆంధ్ర, తెలంగాణ, తమిళనాడు, ఒడిశా, అస్సాం, బెంగాల్‌లో ఏడాదికి 3 వరి పంటలు – ఆస్, అమన్, బోరో), జైద్ (వేసవి – పుచ్చ, కర్బూజ, దోస, కూరగాయలు, పశుగ్రాసం). ప్రధాన పంటలు: వరి (చైనా తర్వాత రెండో పెద్ద ఉత్పత్తిదారు; 25°C పైన, అధిక తేమ, 100 సెం.మీ. పైగా వర్షం), గోధుమ (రబీ; 50–75 సెం.మీ. వర్షం; గంగా–సట్లెజ్ మైదానాలు, దక్కన్ నల్లరేగడి), తృణధాన్యాలు (జొన్న, సజ్జ, రాగి – అధిక పోషక విలువ), మొక్కజొన్న, పప్పు ధాన్యాలు (నత్రజని స్థిరీకరణ – పంట మార్పిడి), చెరకు, నూనెగింజలు (వేరుశనగ, ఆవాలు, కొబ్బరి, నువ్వులు, సోయాబీన్, ఆముదం, పత్తి గింజలు, లిన్సీడ్, పొద్దుతిరుగుడు), తేయాకు, కాఫీ, ఉద్యాన పంటలు, రబ్బరు, పత్తి (నల్లరేగడి, 210 మంచు లేని రోజులు), జనపనార (“బంగారు నార”). సాంకేతిక–సంస్థాగత సంస్కరణలు: స్వాతంత్ర్యం తర్వాత జమీందారీ రద్దు, కమతాల ఏకీకరణ, సహకార సంఘాలు; 1960–70ల్లో హరిత విప్లవం (ప్యాకేజీ సాంకేతికత), శ్వేత విప్లవం (ఆపరేషన్ ఫ్లడ్); పంట బీమా, గ్రామీణ బ్యాంకులు, సహకార రుణాలు, కిసాన్ క్రెడిట్ కార్డ్ (KCC), వ్యక్తిగత ప్రమాద బీమా పథకం (PAIS), రేడియో–టీవీ వ్యవసాయ కార్యక్రమాలు, కనీస మద్దతు ధర. భూదాన్–గ్రామదాన్ – వినోబా భావే (గాంధీజీ ఆధ్యాత్మిక వారసుడు); ఆంధ్రప్రదేశ్ పోచంపల్లిలో భూమిలేని పేదల కోరికకు స్పందించి శ్రీ రామచంద్రారెడ్డి 80 ఎకరాలు దానం – “రక్తరహిత విప్లవం”.","pts":["ప్రాచీన జీవనాధార వ్యవసాయం: చిన్న కమతాలు, పాత పనిముట్లు, కుటుంబ శ్రమ, వర్షాధారం; పోడు (నరికి–కాల్చు) సాగు.","పోడు సాగు పేర్లు: ఝూమింగ్ (అస్సాం, మేఘాలయ, మిజోరం, నాగాలాండ్), పామ్లౌ (మణిపూర్), దీపా (బస్తర్, ఛత్తీస్‌గఢ్), అండమాన్–నికోబార్.","సాంద్ర జీవనాధార వ్యవసాయం: జనాభా ఒత్తిడి ఎక్కువ; శ్రమ, రసాయనాలు, నీటిపారుదల ఎక్కువ; చిన్న కమతాల నుండి గరిష్ఠ ఉత్పత్తి.","వాణిజ్య వ్యవసాయం: HYV విత్తనాలు, ఎరువులు, పురుగుమందులు; ఒకే పంట ఒక ప్రాంతంలో వాణిజ్యం, మరో ప్రాంతంలో జీవనాధారం (వరి – పంజాబ్ vs ఒడిశా).","తోటల పెంపకం: ఒకే పంట పెద్ద విస్తీర్ణంలో; మూలధనం, శ్రమ, పరిశ్రమతో అనుసంధానం – తేయాకు, కాఫీ, రబ్బరు, చెరకు, అరటి.","రబీ: అక్టోబర్–డిసెంబర్ విత్తు, ఏప్రిల్–జూన్ కోత – గోధుమ, బార్లీ, బఠాణి, శనగ, ఆవాలు (పంజాబ్, హర్యానా, హిమాచల్, J&K, ఉత్తరాఖండ్, UP).","ఖరీఫ్: రుతుపవనాలతో విత్తు, సెప్టెంబర్–అక్టోబర్ కోత – వరి, మొక్కజొన్న, జొన్న, సజ్జ, కంది, పెసర, మినుము, పత్తి, జనపనార, వేరుశనగ, సోయాబీన్.","జైద్: రబీ–ఖరీఫ్ మధ్య వేసవి – పుచ్చ, కర్బూజ, దోస, కూరగాయలు, పశుగ్రాసం; చెరకు దాదాపు ఏడాది పంట.","వరి: భారత్ ప్రపంచంలో రెండో పెద్ద ఉత్పత్తిదారు (చైనా తర్వాత); 25°C పైన ఉష్ణోగ్రత, అధిక తేమ, 100 సెం.మీ. పైగా వర్షం; తక్కువ వర్షం ప్రాంతాల్లో నీటిపారుదలతో.","గోధుమ: రెండో ప్రధాన ఆహార పంట (ఉత్తర, వాయువ్య భారతం); చల్లని పెరుగుదల కాలం, పక్వ దశలో ఎండ; 50–75 సెం.మీ. వర్షం; గంగా–సట్లెజ్ మైదానాలు, దక్కన్ నల్లరేగడి.","పప్పు ధాన్యాలు: కంది (అర్హర్), మినుము, పెసర, మసూర్, బఠాణి, శనగ; కంది తప్ప మిగతావి గాలి నుండి నత్రజని స్థిరీకరించి నేల సారం పెంచుతాయి – పంట మార్పిడిలో.","జనపనార – “బంగారు నార”: వరద మైదానాల్లో ఏటా నవీకరించబడే సారవంతమైన నేలలు; పశ్చిమ బెంగాల్, బీహార్, అస్సాం, ఒడిశా, మేఘాలయ.","సంస్కరణలు: జమీందారీ రద్దు, కమతాల ఏకీకరణ, హరిత విప్లవం, శ్వేత విప్లవం (ఆపరేషన్ ఫ్లడ్), పంట బీమా, గ్రామీణ బ్యాంకులు, సహకార సంఘాలు, KCC, PAIS, కనీస మద్దతు ధర, వాతావరణ బులెటిన్లు.","భూదాన్ ఉద్యమం: వినోబా భావే – 1951 పోచంపల్లి (ఆంధ్రప్రదేశ్)లో శ్రీ రామచంద్రారెడ్డి 80 ఎకరాలు దానం; “రక్తరహిత విప్లవం”; గ్రామదాన్ – గ్రామం మొత్తం భూమి దానం."],"w":[["జీవనాధార వ్యవసాయం","Subsistence farming"],["పోడు / నరికి–కాల్చు సాగు","Slash and burn / Shifting agriculture"],["సాంద్ర వ్యవసాయం","Intensive farming"],["వాణిజ్య వ్యవసాయం","Commercial farming"],["తోటల పెంపకం","Plantation agriculture"],["రబీ","Rabi (winter crop)"],["ఖరీఫ్","Kharif (monsoon crop)"],["జైద్","Zaid (summer season)"],["అధిక దిగుబడి వంగడాలు","High Yielding Varieties (HYV)"],["ముతక ధాన్యాలు / తృణధాన్యాలు","Coarse grains / Millets"],["పప్పు ధాన్యాలు","Pulses"],["ఉద్యాన పంటలు","Horticulture"],["బంగారు నార","Golden fibre (Jute)"],["హరిత విప్లవం","Green Revolution"],["శ్వేత విప్లవం","White Revolution (Operation Flood)"],["భూదానం","Bhoodan"]],"gr":{"t":"పంటలు – పరిస్థితులు – ప్రాంతాలు","p":["వరి: 25°C+, 100 సెం.మీ.+ వర్షం | ఉత్తర–ఈశాన్య మైదానాలు, తీర ప్రాంతాలు, డెల్టాలు; పంజాబ్, హర్యానా, పశ్చిమ UP, రాజస్థాన్‌లో కాలువలు–బోర్లతో","గోధుమ: 50–75 సెం.మీ. | జొన్న: వర్షాధారం (మహారాష్ట్ర అగ్రస్థానం) | సజ్జ: ఇసుక, లోతు తక్కువ నల్లరేగడి (రాజస్థాన్) | రాగి: పొడి ప్రాంతాలు, ఎర్ర–నల్ల–ఇసుక నేలలు (కర్ణాటక)","మొక్కజొన్న: 21–27°C, పాత ఒండ్రు | చెరకు: 21–27°C, 75–100 సెం.మీ. | తేయాకు: ఉష్ణ–ఉపఉష్ణ మండలం, హ్యూమస్ నేల, ఏడాదంతా తరచు వర్షం, బాగా నీరు పారే నేల | పత్తి: నల్లరేగడి, అధిక ఉష్ణం, తేలికపాటి వర్షం, 210 మంచు లేని రోజులు, ఎండ","ఖరీఫ్ వరి పంటలు (ఆంధ్ర, బెంగాల్...): ఆస్, అమన్, బోరో","భూదాన్: 1951, పోచంపల్లి (ఆంధ్రప్రదేశ్) – వినోబా భావే"]},"qa":[["పోడు (slash and burn) సాగు అంటే?","అడవిలో కొంత భాగం నరికి కాల్చి, బూడిదతో కలిసిన నేలలో సాగు చేసి, సారం తగ్గాక వేరే చోటుకు వెళ్ళడం."],["రబీ పంటలకు రెండు ఉదాహరణలు?","గోధుమ, శనగ (బార్లీ, బఠాణి, ఆవాలు)."],["ఖరీఫ్ పంటలకు రెండు ఉదాహరణలు?","వరి, మొక్కజొన్న (జొన్న, సజ్జ, పత్తి, వేరుశనగ)."],["జైద్ పంటలు ఏవి?","పుచ్చ, కర్బూజ, దోస, కూరగాయలు, పశుగ్రాసం."],["వరి సాగుకు కావలసిన పరిస్థితులు?","25°C పైన ఉష్ణోగ్రత, అధిక తేమ, 100 సెం.మీ. పైగా వర్షపాతం (లేదా నీటిపారుదల)."],["తోటల పెంపకం అంటే?","ఒకే పంటను పెద్ద విస్తీర్ణంలో మూలధనం, ఎక్కువ శ్రమతో పెంచే వాణిజ్య వ్యవసాయం – తేయాకు, కాఫీ, రబ్బరు."],["“బంగారు నార” అని దేనిని అంటారు?","జనపనార."],["పప్పు ధాన్యాలు నేల సారాన్ని ఎలా పెంచుతాయి?","అవి లెగ్యూమ్ పంటలు – గాలిలోని నత్రజనిని నేలలో స్థిరీకరిస్తాయి."],["భూదాన్ ఉద్యమ నాయకుడు?","ఆచార్య వినోబా భావే."],["హరిత విప్లవం దేనిపై ఆధారపడింది?","ప్యాకేజీ సాంకేతికత – HYV విత్తనాలు, రసాయన ఎరువులు, నీటిపారుదల, పురుగుమందులు."]],"act":"మీ ఊరిలో ఖరీఫ్, రబీ, జైద్ కాలాల్లో పండే పంటల జాబితా తయారు చేయండి. భారత పటంలో గోధుమ పండే ప్రాంతాలు (పంజాబ్, హర్యానా, UP, MP, రాజస్థాన్, బీహార్) గుర్తించండి.","kn":"భూదాన్ ఉద్యమం మన తెలుగు నేల పోచంపల్లి నుండే ప్రారంభమైంది (1951)! పోచంపల్లి ఇక్కత్ చీరలు కూడా ప్రపంచ ప్రసిద్ధం. నెల్లూరు జిల్లా “మొలగొలుకులు” సన్న బియ్యానికి, నిమ్మకాయలకు (గూడూరు) పేరు.","qz":[["ఒకే పంటను పెద్ద విస్తీర్ణంలో పండించే వ్యవసాయం?","తోటల పెంపకం","పోడు సాగు","ఉద్యాన సాగు","సాంద్ర వ్యవసాయం"],["రబీ పంట?","శనగ (Gram)","వరి","సజ్జ","పత్తి"],["లెగ్యూమ్ (నత్రజని స్థిరీకరించే) పంట?","పప్పు ధాన్యాలు","జొన్న","తృణధాన్యాలు","నువ్వులు"],["ఈశాన్య రాష్ట్రాల్లో పోడు సాగు పేరు?","ఝూమింగ్","పామ్లౌ","దీపా","మిల్పా"],["మణిపూర్‌లో పోడు సాగు పేరు?","పామ్లౌ","ఝూమింగ్","దీపా","రోకా"],["వరి ఉత్పత్తిలో భారత్ స్థానం?","రెండో స్థానం (చైనా తర్వాత)","మొదటి స్థానం","మూడో స్థానం","ఐదో స్థానం"],["గోధుమకు కావలసిన వార్షిక వర్షపాతం?","50–75 సెం.మీ.","100 సెం.మీ. పైగా","200 సెం.మీ.","25 సెం.మీ. లోపు"],["జైద్ కాలం పంట?","పుచ్చకాయ","గోధుమ","వరి","పత్తి"],["“బంగారు నార”?","జనపనార","పత్తి","కొబ్బరి పీచు","పట్టు"],["పత్తి పెరుగుదలకు కావలసిన మంచు లేని రోజులు?","210","100","365","50"],["భూదాన్ ఉద్యమ నాయకుడు?","వినోబా భావే","గాంధీజీ","నెహ్రూ","రామచంద్రారెడ్డి"],["భూదాన్ ఉద్యమం ప్రారంభమైన ప్రదేశం?","పోచంపల్లి (ఆంధ్రప్రదేశ్)","వార్ధా","సబర్మతి","బార్డోలీ"],["శ్వేత విప్లవానికి మరో పేరు?","ఆపరేషన్ ఫ్లడ్","హరిత విప్లవం","నీలి విప్లవం","పసుపు విప్లవం"],["ఖరీఫ్ కాలం ప్రారంభం?","రుతుపవనాల ప్రారంభంతో","శీతాకాలంలో","వేసవిలో","వసంతంలో"],["ఒకే రాష్ట్రంలో 3 వరి పంటలు – ఆస్, అమన్, బోరో – ఎక్కడ?","అస్సాం, ప.బెంగాల్, ఒడిశా","పంజాబ్","రాజస్థాన్","హిమాచల్"],["రైతులకు రుణాల కోసం ప్రవేశపెట్టిన కార్డు?","కిసాన్ క్రెడిట్ కార్డ్ (KCC)","ఆధార్ కార్డ్","రేషన్ కార్డ్","జాబ్ కార్డ్"]],"wb":{"mis":"పప్పు ధాన్యాలన్నీ నత్రజని స్థిరీకరిస్తాయి – కంది (అర్హర్) తప్ప అని పుస్తకం చెబుతుంది. వరి వాణిజ్య పంట అని అన్నిచోట్లా అనలేం – పంజాబ్‌లో వాణిజ్యం, ఒడిశాలో జీవనాధారం. గోధుమ రబీ పంట, ఖరీఫ్ కాదు.","qz":[],"pg":"64–87","f":"books/10/Class10_Social_Geography_Textbook.pdf","p":70,"lb":"పాఠ్యపుస్తకం","ws":["ఆలోచించండి – వ్యవసాయ ఆధారిత పరిశ్రమలు, వ్యవసాయ రకాలు (పుట 64)","ఆలోచించండి – రింఝా కుటుంబం, తోటలు, పంటలు (పుట 66)","ఆలోచించండి – ఖరీఫ్, రబీ పప్పు ధాన్యాలు (పుట 76)","చర్చించండి – రైతు పోర్టల్ (farmer.gov.in) ప్రయోజనాలు (పుట 82)","అభ్యాసాలు – Exercises (పుట 84)","కృత్యం – పదబంధం (puzzle) జవాబులు (పుట 86)"]},"tg":[["ఆలోచించండి – వ్యవసాయ ఆధారిత పరిశ్రమలు, వ్యవసాయ రకాలు (పుట 64)",["వ్యవసాయ ముడిసరుకుతో పరిశ్రమలు: పత్తి వస్త్ర, జనపనార, చక్కెర, వంటనూనె, తేయాకు, కాఫీ, రబ్బరు, పట్టు, ఆహార శుద్ధి (పండ్ల రసాలు, బిస్కట్లు), బియ్యం మిల్లులు, పాల ఉత్పత్తులు.","వ్యవసాయ రకాలు: ప్రాచీన జీవనాధార, సాంద్ర జీవనాధార, వాణిజ్య వ్యవసాయం, తోటల పెంపకం, మిశ్రమ వ్యవసాయం, సేంద్రియ వ్యవసాయం, పోడు సాగు, మెట్ల (టెర్రస్) సాగు."]],["ఆలోచించండి – రింఝా కుటుంబం, తోటలు, పంటలు (పుట 66)",["రింఝా కుటుంబం చేసేది ప్రాచీన జీవనాధార వ్యవసాయం – “నరికి–కాల్చు” పోడు (ఝూమింగ్) సాగు. ఇందులో పండే పంటలు: మెట్ట వరి, మొక్కజొన్న, జొన్న, సజ్జ, కూరగాయలు, దుంపలు (టాపియోకా, కంద), పప్పు ధాన్యాలు.","తోటల పెంపకం చేసే రాష్ట్రాలు: తేయాకు – అస్సాం, పశ్చిమ బెంగాల్ (డార్జిలింగ్, జల్‌పాయిగురి), తమిళనాడు, కేరళ; కాఫీ – కర్ణాటక, కేరళ, తమిళనాడు; రబ్బరు – కేరళ, తమిళనాడు, కర్ణాటక, అండమాన్–నికోబార్, మేఘాలయ.","ఒక ప్రాంతంలో వాణిజ్య, మరో ప్రాంతంలో జీవనాధార పంటలు: వరి (పంజాబ్ – వాణిజ్యం, ఒడిశా – జీవనాధారం), గోధుమ (పంజాబ్ vs బీహార్), మొక్కజొన్న, సజ్జ, కూరగాయలు, పప్పులు."]],["ఆలోచించండి – ఖరీఫ్, రబీ పప్పు ధాన్యాలు (పుట 76)",["ఖరీఫ్ పప్పులు: కంది (అర్హర్/తుర్), మినుము (ఉరద్), పెసర (మూంగ్). రబీ పప్పులు: శనగ (గ్రామ్), మసూర్, బఠాణి. (పెసర, మినుము రబీలోనూ కొన్ని ప్రాంతాల్లో పండిస్తారు.)"]],["చర్చించండి – రైతు పోర్టల్ (farmer.gov.in) ప్రయోజనాలు (పుట 82)",["ప్రభుత్వ రైతు పోర్టల్‌లో వాతావరణ సూచనలు, మార్కెట్ ధరలు (మండీ ధరలు), విత్తనాలు–ఎరువుల సమాచారం, పంటల సాగు పద్ధతులు, పురుగుల నివారణ, పంట బీమా, కిసాన్ క్రెడిట్ కార్డ్, ప్రభుత్వ పథకాలు, మట్టి పరీక్ష (Soil Health Card), శిక్షణ వివరాలు ఉంటాయి. రైతులు సరైన సమయంలో సరైన నిర్ణయాలు తీసుకుని, దళారుల మోసం తగ్గించుకుని, ఎక్కువ దిగుబడి, ఆదాయం పొందవచ్చు."]],["అభ్యాసాలు – Exercises (పుట 84)",["1) (i) (b) తోటల పెంపకం (Plantation Agriculture) (ii) (b) శనగ (Gram) (iii) (a) పప్పు ధాన్యాలు (Pulses)","2) (i) తేయాకు – ఉష్ణ, ఉపఉష్ణ మండల వాతావరణం; హ్యూమస్, సేంద్రియ పదార్థాలు గల లోతైన సారవంతమైన, బాగా నీరు పారే నేల; ఏడాది పొడవునా వెచ్చని, తేమతో కూడిన మంచు లేని వాతావరణం; ఏడాదంతా తరచు జల్లులు (లేత ఆకుల నిరంతర పెరుగుదలకు); ఎక్కువ, నైపుణ్యం గల శ్రామికులు.","(ii) వరి – ప్రధాన ఆహార పంట; ఉత్తర, ఈశాన్య మైదానాలు, తీర ప్రాంతాలు, డెల్టా ప్రాంతాలు (ప.బెంగాల్, ఆంధ్రప్రదేశ్, ఒడిశా, తమిళనాడు, కేరళ, అస్సాం, బీహార్, UP); కాలువలు, బోర్ల సహాయంతో పంజాబ్, హర్యానా, పశ్చిమ UP, రాజస్థాన్‌లో కూడా. (గోధుమ – గంగా–సట్లెజ్ మైదానాలు, దక్కన్ నల్లరేగడి ప్రాంతం.)","(iii) సంస్థాగత సంస్కరణలు: జమీందారీ రద్దు, కమతాల ఏకీకరణ, సహకార సంఘాలు, కరువు–వరద–తుఫాను–అగ్ని–వ్యాధులకు పంట బీమా, గ్రామీణ బ్యాంకులు, సహకార సంఘాలు, బ్యాంకుల ద్వారా తక్కువ వడ్డీ రుణాలు, కిసాన్ క్రెడిట్ కార్డ్ (KCC), వ్యక్తిగత ప్రమాద బీమా పథకం (PAIS), రేడియో–టీవీలో వాతావరణ బులెటిన్లు, వ్యవసాయ కార్యక్రమాలు, ముఖ్య పంటలకు కనీస మద్దతు ధర.","3) (i) ప్రభుత్వ చర్యలు: 1960–70ల్లో హరిత విప్లవం (HYV విత్తనాలు, ఎరువులు, నీటిపారుదల), శ్వేత విప్లవం (ఆపరేషన్ ఫ్లడ్ – పాల ఉత్పత్తి); భూ సంస్కరణలు – జమీందారీ రద్దు, కమతాల ఏకీకరణ; పంట బీమా; గ్రామీణ బ్యాంకులు, సహకార రుణాలు, KCC, PAIS; కనీస మద్దతు ధరలు, ప్రభుత్వ సేకరణ; వాతావరణ సమాచారం, వ్యవసాయ విస్తరణ కార్యక్రమాలు (రేడియో, టీవీ, రైతు పోర్టల్); సాగునీటి ప్రాజెక్టులు, విద్యుత్; వ్యవసాయ పరిశోధన సంస్థలు, విశ్వవిద్యాలయాలు, పశువైద్య సేవలు, ఉద్యాన అభివృద్ధి.","(ii) వరి పెరుగుదలకు: ఖరీఫ్ పంట; 25°C పైన అధిక ఉష్ణోగ్రత; అధిక తేమ; 100 సెం.మీ. పైగా వార్షిక వర్షపాతం (తక్కువ వర్షపాత ప్రాంతాల్లో నీటిపారుదల); ఒండ్రు, బంకమట్టి నేలలు (నీరు నిలిచేవి); చదునైన భూమి; ఎక్కువ శ్రమ. ప్రాంతాలు – ఉత్తర, ఈశాన్య మైదానాలు, తీర ప్రాంతాలు, డెల్టాలు; కాలువలు, బోర్లతో పంజాబ్, హర్యానా, పశ్చిమ UP, రాజస్థాన్.","ప్రాజెక్ట్: (1) రైతులకు అక్షరాస్యత అవసరం – ఆధునిక సాంకేతికత, విత్తన–ఎరువుల లేబుళ్లు, పురుగుమందుల సురక్షిత వాడకం, మార్కెట్ ధరలు, ప్రభుత్వ పథకాలు, బ్యాంకు రుణాలు, బీమా పత్రాలు, ఆన్‌లైన్ పోర్టల్‌లు అర్థం చేసుకోవడానికి; దళారుల మోసం నుండి రక్షణ. (2) భారత పటంలో గోధుమ ప్రాంతాలు: పంజాబ్, హర్యానా, ఉత్తరప్రదేశ్, మధ్యప్రదేశ్, బీహార్, రాజస్థాన్ (గంగా–సట్లెజ్ మైదానాలు, దక్కన్ నల్లరేగడి ప్రాంతం)."]],["కృత్యం – పదబంధం (puzzle) జవాబులు (పుట 86)",["1. రెండు ప్రధాన ఆహార పంటలు – RICE (వరి), WHEAT (గోధుమ)","2. వేసవి (రుతుపవన) పంట కాలం – KHARIF","3. పప్పు ధాన్యాల్లో ఉండేది – PROTEIN (మాంసకృత్తులు)","4. ముతక ధాన్యం – JOWAR (జొన్న)","5. రెండు ముఖ్య పానీయ పంటలు – TEA, COFFEE","6. నల్లరేగడి నేలల్లో పండే నార – COTTON (పత్తి)"]]]},{"id":"gs5","no":10,"t":"ఖనిజ, శక్తి వనరులు (Minerals and Energy Resources)","m":[10],"ty":"భూగోళం – అధ్యాయం 5","by":"సాంఘిక శాస్త్రం – భూగోళం 10వ తరగతి (పుటలు 88–119)","th":"ఖనిజాల లభ్యత, ఇనుప–ఇనుమేతర–అలోహ ఖనిజాలు, మైనింగ్ ప్రమాదాలు, ఖనిజ సంరక్షణ, సాంప్రదాయ–సాంప్రదాయేతర శక్తి వనరులు, శక్తి సంరక్షణ","sum":"ఖనిజం – నిర్దిష్ట అంతర్గత నిర్మాణం గల సహజసిద్ధ, సజాతీయ పదార్థం; భూవిజ్ఞాన శాస్త్రవేత్తల ప్రకారం శిలలు ఖనిజాల సమ్మేళనాలు; మన దైనందిన జీవితంలో ప్రతి వస్తువులో ఖనిజాలు. లభ్యత రూపాలు: (1) అగ్ని, రూపాంతర శిలల్లో పగుళ్ళు, సందుల్లో ఈనెలు (veins), లోడ్‌లు (lodes) – తగరం, రాగి, జింక్, సీసం; (2) అవక్షేప శిలల పొరల్లో (beds, layers) – బొగ్గు, ఇనుము, జిప్సం, పొటాష్, సోడియం లవణం (బాష్పీభవనంతో); (3) శిలల శైథిల్యం తర్వాత మిగిలే అవశేషాలు – బాక్సైట్; (4) లోయలు, కొండల అడుగున ఇసుకలో ప్లేసర్ నిక్షేపాలు – బంగారం, వెండి, తగరం, ప్లాటినం; (5) సముద్ర జలాలు, సముద్రగర్భం – లవణం, మెగ్నీషియం, బ్రోమిన్, మాంగనీస్ నాడ్యూల్స్. మేఘాలయ జోవాయ్, చిరపుంజీలో “ర్యాట్ హోల్” బొగ్గు తవ్వకం. ఇనుప ఖనిజాలు – మాగ్నటైట్ (అత్యుత్తమం, 70% ఇనుము, అయస్కాంత గుణం – విద్యుత్ పరిశ్రమకు), హెమటైట్ (ప్రధాన పారిశ్రామిక ఖనిజం, 50–60%); ప్రధాన బెల్టులు – ఒడిశా–జార్ఖండ్ (బాదంపహార్ – మయూర్‌భంజ్, కెందుఝర్; గువా, నోవాముండి – సింగ్‌భూమ్), దుర్గ్–బస్తర్–చంద్రపూర్ (ఛత్తీస్‌గఢ్–మహారాష్ట్ర; బైలదిల్లా కొండలు – ఎద్దు మూపురం ఆకారం – 14 నిక్షేపాలు, అత్యుత్తమ హెమటైట్, విశాఖపట్నం ఓడరేవు ద్వారా జపాన్, దక్షిణ కొరియాకు ఎగుమతి), బళ్ళారి–చిత్రదుర్గ–చిక్కమగళూరు–తుమకూరు (కర్ణాటక; కుద్రేముఖ్ – గుర్రపు ముఖం, 100% ఎగుమతి యూనిట్, పైప్‌లైన్ ద్వారా మంగళూరుకు స్లర్రీ), మహారాష్ట్ర–గోవా. మాంగనీస్ – ఉక్కు, ఫెర్రో మాంగనీస్ (1 టన్ను ఉక్కుకు 10 కిలోలు), బ్లీచింగ్ పౌడర్, పురుగుమందులు, పెయింట్లు. ఇనుమేతర – రాగి (బాలాఘాట్ MP, ఖేత్రి రాజస్థాన్, సింగ్‌భూమ్ జార్ఖండ్ – విద్యుత్ తీగలు, ఎలక్ట్రానిక్స్), బాక్సైట్ (అల్యూమినియం – అమర్‌కంటక్ పీఠభూమి, మైకల్ కొండలు, బిలాస్‌పూర్–కట్ని; ఒడిశా అగ్రస్థానం – కొరాపుట్ పంచపట్మాలి). అలోహ – అభ్రకం (మైకా – కోడర్మా–గయా–హజారీబాగ్ జార్ఖండ్ అగ్రస్థానం, అజ్మీర్, నెల్లూరు మైకా బెల్ట్ – విద్యుత్, ఎలక్ట్రానిక్స్ పరిశ్రమకు అనివార్యం). శిలా ఖనిజాలు – సున్నపురాయి (సిమెంట్, ఇనుము కరిగించడం). మైనింగ్ ప్రమాదాలు – ధూళి, విష వాయువులు, ఊపిరితిత్తుల వ్యాధులు, గనుల పైకప్పు కూలడం, వరదలు, అగ్ని; నీటి కాలుష్యం, భూక్షయం. ఖనిజాల సంరక్షణ – పునరుద్ధరణ చాలా నెమ్మది (లక్షల ఏళ్లు); ప్రణాళికాబద్ధ, సుస్థిర వినియోగం, మెరుగైన సాంకేతికత, పునర్వినియోగం (రీసైక్లింగ్), ప్రత్యామ్నాయాలు. శక్తి వనరులు: సాంప్రదాయ – వంటచెరకు, పిడకలు, బొగ్గు, పెట్రోలియం, సహజ వాయువు, విద్యుత్ (జల, థర్మల్); సాంప్రదాయేతర – సౌర, పవన, అలల, భూతాప, బయోగ్యాస్, అణుశక్తి. బొగ్గు – పీట్, లిగ్నైట్ (నైవేలి, తమిళనాడు), బిటుమినస్, ఆంత్రసైట్ (అత్యుత్తమ కఠిన బొగ్గు); గోండ్వానా (200 మిలియన్ ఏళ్లు – దామోదర్ లోయ: ఝరియా, రాణిగంజ్, బొకారో; గోదావరి, మహానది, సోన్, వార్ధా లోయలు), టెర్షియరీ (55 మిలియన్ ఏళ్లు – మేఘాలయ, అస్సాం, అరుణాచల్, నాగాలాండ్). పెట్రోలియం – ముంబై హై, గుజరాత్ (అంక్లేశ్వర్), అస్సాం (పురాతనం – దిగ్బోయ్, నహర్‌కటియా, మోరాన్–హుగ్రిజన్); సహజ వాయువు – కృష్ణా–గోదావరి బేసిన్, HVJ పైప్‌లైన్ (1700 కి.మీ.). సౌర (భుజ్ దగ్గర మాధాపూర్), పవన (నాగర్‌కోయిల్, జైసల్మేర్), అలల (ఖంబాత్, కచ్ఛ్ సింధుశాఖలు, సుందర్‌బన్స్), భూతాప (మణికరణ్ – హిమాచల్, పుగా లోయ – లద్దాఖ్), గోబర్ గ్యాస్ ప్లాంట్లు. శక్తి సంరక్షణ – ప్రజా రవాణా, అనవసర విద్యుత్ ఆపడం, పొదుపు పరికరాలు, సాంప్రదాయేతర వనరులు.","pts":["ఖనిజం: నిర్దిష్ట అంతర్గత నిర్మాణం గల సహజసిద్ధ, సజాతీయ పదార్థం; శిలలు ఖనిజాల సమ్మేళనాలు.","అగ్ని, రూపాంతర శిలల్లో – ఈనెలు, లోడ్‌లు (తగరం, రాగి, జింక్, సీసం); అవక్షేప శిలల్లో – పొరలు (బొగ్గు, ఇనుము, జిప్సం, పొటాష్, ఉప్పు).","శిలల శైథిల్యం (decomposition) తర్వాత మిగిలే అవశేషంగా ఏర్పడేది బాక్సైట్; ప్లేసర్ నిక్షేపాలు – బంగారం, వెండి, తగరం, ప్లాటినం.","ర్యాట్ హోల్ మైనింగ్: మేఘాలయ జోవాయ్, చిరపుంజీలో కుటుంబ సభ్యులు పొడవైన ఇరుకు సొరంగాలు తవ్వి బొగ్గు తీయడం (ఈశాన్యంలో ఖనిజాలు వ్యక్తులు/సమాజాల సొంతం).","మాగ్నటైట్ – అత్యుత్తమ ఇనుప ఖనిజం (70% ఇనుము), అయస్కాంత గుణం; హెమటైట్ – అత్యంత ముఖ్యమైన పారిశ్రామిక ఇనుప ఖనిజం (50–60%).","ఇనుప ఖనిజ బెల్టులు: ఒడిశా–జార్ఖండ్, దుర్గ్–బస్తర్–చంద్రపూర్ (బైలదిల్లా), బళ్ళారి–చిత్రదుర్గ–చిక్కమగళూరు–తుమకూరు (కుద్రేముఖ్), మహారాష్ట్ర–గోవా.","బైలదిల్లా ఖనిజం విశాఖపట్నం ఓడరేవు ద్వారా జపాన్, దక్షిణ కొరియాకు ఎగుమతి; కుద్రేముఖ్ – 100% ఎగుమతి యూనిట్.","మాంగనీస్: ఉక్కు, ఫెర్రో మాంగనీస్ మిశ్రమ లోహం (1 టన్ను ఉక్కుకు 10 కిలోలు), బ్లీచింగ్ పౌడర్, పురుగుమందులు, పెయింట్లు.","రాగి: బాలాఘాట్ (MP), ఖేత్రి (రాజస్థాన్), సింగ్‌భూమ్ (జార్ఖండ్) – విద్యుత్ తీగలు, ఎలక్ట్రానిక్స్, రసాయన పరిశ్రమలు.","బాక్సైట్ (అల్యూమినియం): అమర్‌కంటక్ పీఠభూమి, మైకల్ కొండలు, బిలాస్‌పూర్–కట్ని; ఒడిశా అగ్రస్థానం (పంచపట్మాలి – కొరాపుట్).","అభ్రకం (మైకా): పలుచని పొరలుగా విడిపోయే ఖనిజం; విద్యుత్, ఎలక్ట్రానిక్ పరిశ్రమలకు అనివార్యం; కోడర్మా–గయా–హజారీబాగ్ (జార్ఖండ్) అగ్రస్థానం; అజ్మీర్, నెల్లూరు మైకా బెల్ట్.","బొగ్గు రకాలు: పీట్ < లిగ్నైట్ (నైవేలి) < బిటుమినస్ (వాణిజ్యంలో ఎక్కువ; మెటలర్జికల్ – ఇనుము కరిగించడం) < ఆంత్రసైట్ (అత్యుత్తమ కఠిన బొగ్గు).","గోండ్వానా బొగ్గు (200+ మిలియన్ ఏళ్లు): దామోదర్ లోయ – ఝరియా, రాణిగంజ్, బొకారో; టెర్షియరీ బొగ్గు (55 మిలియన్ ఏళ్లు): మేఘాలయ, అస్సాం, అరుణాచల్, నాగాలాండ్.","పెట్రోలియం: ముంబై హై, గుజరాత్ (అంక్లేశ్వర్), అస్సాం (దిగ్బోయ్ – పురాతన చమురు రాష్ట్రం); సహజ వాయువు – కృష్ణా–గోదావరి బేసిన్; HVJ (హజీరా–విజయ్‌పూర్–జగదీశ్‌పూర్) 1700 కి.మీ. పైప్‌లైన్.","సాంప్రదాయేతర శక్తి: సౌర (మాధాపూర్, భుజ్), పవన (నాగర్‌కోయిల్, జైసల్మేర్), అలల (ఖంబాత్, కచ్ఛ్, సుందర్‌బన్స్), భూతాప (మణికరణ్, పుగా లోయ), బయోగ్యాస్ (గోబర్ గ్యాస్), అణుశక్తి (యురేనియం, థోరియం)."],"w":[["ఖనిజం","Mineral"],["ఖనిజ ధాతువు","Ore"],["ఇనుప ఖనిజాలు","Ferrous minerals"],["ఇనుమేతర ఖనిజాలు","Non-ferrous minerals"],["అలోహ ఖనిజాలు","Non-metallic minerals"],["ఈనెలు, లోడ్‌లు","Veins and lodes"],["ప్లేసర్ నిక్షేపం","Placer deposit"],["అభ్రకం","Mica"],["బాక్సైట్","Bauxite"],["సాంప్రదాయ శక్తి వనరులు","Conventional sources of energy"],["సాంప్రదాయేతర శక్తి వనరులు","Non-conventional sources of energy"],["శిలాజ ఇంధనాలు","Fossil fuels"],["భూతాప శక్తి","Geothermal energy"],["అలల శక్తి","Tidal energy"],["బయోగ్యాస్","Biogas"],["అణు శక్తి","Nuclear energy"]],"gr":{"t":"ఖనిజాలు – ప్రదేశాలు","p":["ఇనుము: బాదంపహార్ (ఒడిశా), గువా–నోవాముండి (జార్ఖండ్), బైలదిల్లా (ఛత్తీస్‌గఢ్), కుద్రేముఖ్ (కర్ణాటక)","రాగి: బాలాఘాట్, ఖేత్రి, సింగ్‌భూమ్ | బాక్సైట్: అమర్‌కంటక్, మైకల్, పంచపట్మాలి | మైకా: కోడర్మా (జార్ఖండ్), నెల్లూరు","బొగ్గు: ఝరియా, రాణిగంజ్, బొకారో (దామోదర్ లోయ) | లిగ్నైట్: నైవేలి | చమురు: ముంబై హై, అంక్లేశ్వర్, దిగ్బోయ్ | వాయువు: KG బేసిన్","పవన: నాగర్‌కోయిల్, జైసల్మేర్ | సౌర: మాధాపూర్ (భుజ్) | భూతాప: మణికరణ్, పుగా | అలలు: ఖంబాత్, కచ్ఛ్, సుందర్‌బన్స్","బొగ్గు నాణ్యత: పీట్ < లిగ్నైట్ < బిటుమినస్ < ఆంత్రసైట్"]},"qa":[["ఖనిజం అంటే?","నిర్దిష్ట అంతర్గత నిర్మాణం గల సహజసిద్ధ, సజాతీయ పదార్థం."],["ఇనుప, ఇనుమేతర ఖనిజాల తేడా?","ఇనుప ఖనిజాల్లో ఇనుము ఉంటుంది (ఇనుము, మాంగనీస్, నికెల్, కోబాల్ట్); ఇనుమేతర ఖనిజాల్లో ఇనుము ఉండదు (రాగి, బాక్సైట్, సీసం, జింక్, బంగారం)."],["అత్యుత్తమ ఇనుప ఖనిజం?","మాగ్నటైట్ (70% వరకు ఇనుము)."],["కోడర్మా దేనికి ప్రసిద్ధి?","అభ్రకం (మైకా) – జార్ఖండ్."],["బాక్సైట్ ఎలా ఏర్పడుతుంది?","అల్యూమినియం సిలికేట్లు గల శిలలు శైథిల్యం చెంది మిగిలే అవశేషంగా."],["అత్యుత్తమ కఠిన బొగ్గు?","ఆంత్రసైట్."],["భారత్‌లో పురాతన చమురు ఉత్పత్తి రాష్ట్రం?","అస్సాం (దిగ్బోయ్)."],["ఖనిజాలను ఎందుకు సంరక్షించాలి?","అవి పరిమితం, పునరుద్ధరించలేనివి; ఏర్పడటానికి లక్షల ఏళ్లు పడుతుంది; నిరంతర వెలికితీతతో ఖర్చు పెరుగుతుంది, నాణ్యత తగ్గుతుంది."],["భారత్‌లో భూతాప శక్తి ప్రాజెక్టులు ఎక్కడ?","మణికరణ్ (హిమాచల్ ప్రదేశ్), పుగా లోయ (లద్దాఖ్)."],["సౌర శక్తికి భారత్‌లో ఉజ్వల భవిష్యత్తు ఎందుకు?","ఉష్ణమండల దేశం – ఏడాది పొడవునా సమృద్ధిగా సూర్యరశ్మి; గ్రామాల్లో వంటచెరకు, పిడకలపై ఆధారం తగ్గుతుంది."]],"act":"మీ ఇంట్లో లోహాలతో చేసిన 10 వస్తువులు జాబితా చేసి అవి ఏ ఖనిజాల నుండి వచ్చాయో రాయండి. మీ రాష్ట్రంలోని థర్మల్/జల విద్యుత్ కేంద్రాలను (ఉదా: దామోదరం సంజీవయ్య థర్మల్ – నెల్లూరు, శ్రీశైలం జల విద్యుత్) భారత పటంలో గుర్తించండి.","kn":"మన నెల్లూరు జిల్లా గూడూరు, సైదాపురం ప్రాంతం “నెల్లూరు మైకా బెల్ట్”గా ప్రసిద్ధి – ఒకప్పుడు దేశంలో ప్రధాన మైకా ఉత్పత్తి ప్రాంతం! కృష్ణపట్నం వద్ద థర్మల్ విద్యుత్ కేంద్రాలు ఉన్నాయి.","qz":[["శిలల శైథిల్యం తర్వాత అవశేషంగా ఏర్పడే ఖనిజం?","బాక్సైట్","బొగ్గు","బంగారం","జింక్"],["జార్ఖండ్‌లోని కోడర్మా దేనికి ప్రముఖ ఉత్పత్తిదారు?","అభ్రకం (మైకా)","బాక్సైట్","ఇనుప ఖనిజం","రాగి"],["ఖనిజాలు పొరలుగా నిక్షిప్తమయ్యే శిలలు?","అవక్షేప శిలలు","రూపాంతర శిలలు","అగ్ని శిలలు","ఏవీ కాదు"],["మోనజైట్ ఇసుకలో ఉండే ఖనిజం?","థోరియం","చమురు","యురేనియం","బొగ్గు"],["అత్యుత్తమ ఇనుప ఖనిజం (అయస్కాంత గుణం)?","మాగ్నటైట్","హెమటైట్","లిమోనైట్","సిడెరైట్"],["బైలదిల్లా కొండలు ఏ ఆకారంలో?","ఎద్దు మూపురం","గుర్రపు ముఖం","పులి","ఏనుగు"],["100% ఎగుమతి యూనిట్ అయిన ఇనుప గనులు?","కుద్రేముఖ్","బైలదిల్లా","బాదంపహార్","నోవాముండి"],["ఖేత్రి గనులు దేనికి ప్రసిద్ధి?","రాగి","బంగారం","మైకా","బొగ్గు"],["అత్యధిక బాక్సైట్ ఉత్పత్తి రాష్ట్రం (2016–17)?","ఒడిశా","జార్ఖండ్","గుజరాత్","మహారాష్ట్ర"],["అత్యుత్తమ నాణ్యత గల కఠిన బొగ్గు?","ఆంత్రసైట్","లిగ్నైట్","పీట్","బిటుమినస్"],["ఈశాన్య భారతంలోని బొగ్గు భూవైజ్ఞానిక యుగం?","టెర్షియరీ","గోండ్వానా","ఆర్కియన్","కేంబ్రియన్"],["భారత్‌లో పురాతన చమురు క్షేత్రం?","దిగ్బోయ్ (అస్సాం)","ముంబై హై","అంక్లేశ్వర్","KG బేసిన్"],["మణికరణ్, పుగా లోయలు దేనికి?","భూతాప శక్తి","పవన శక్తి","అలల శక్తి","సౌర శక్తి"],["పవన శక్తిని సమర్థంగా వాడే ప్రాంతాలు?","నాగర్‌కోయిల్, జైసల్మేర్","ముంబై, కోల్‌కతా","ఢిల్లీ, ఆగ్రా","షిల్లాంగ్, గౌహతి"],["ఈనెలు, లోడ్‌లలో ఏర్పడే ఖనిజం?","తగరం, రాగి, జింక్, సీసం","బొగ్గు","జిప్సం","బాక్సైట్"],["HVJ పైప్‌లైన్ దేనిని రవాణా చేస్తుంది?","సహజ వాయువు","ముడి చమురు","నీరు","బొగ్గు స్లర్రీ"]],"wb":{"mis":"బాక్సైట్ అవక్షేప శిలల్లో పొరలుగా కాదు – శిలల శైథిల్య అవశేషంగా ఏర్పడుతుంది. హెమటైట్ అత్యధికంగా వాడే ఖనిజం, కానీ అత్యుత్తమం మాగ్నటైట్. అణుశక్తి సాంప్రదాయేతర వనరుగా పుస్తకం వర్గీకరిస్తుంది.","qz":[],"pg":"88–119","f":"books/10/Class10_Social_Geography_Textbook.pdf","p":94,"lb":"పాఠ్యపుస్తకం","ws":["ఆలోచించండి – ఇంట్లో లోహ వస్తువులు, ఖనిజాలు (పుట 88)","లోతుగా ఆలోచించండి – ఖనిజాలు, ఇనుము–ఉక్కు పరిశ్రమ సంబంధం (పుట 94)","సేకరించండి – మీ రాష్ట్ర విద్యుత్ కేంద్రాలు (పుట 112)","అభ్యాసాలు – Exercises (పుట 116)","కృత్యం – ఖనిజాల గళ్ళ నుడికట్టు (crossword) (పుట 118)"]},"tg":[["ఆలోచించండి – ఇంట్లో లోహ వస్తువులు, ఖనిజాలు (పుట 88)",["ఇంట్లో లోహ వస్తువులు: స్టీలు పాత్రలు (ఇనుము, క్రోమియం, నికెల్), అల్యూమినియం గిన్నెలు (బాక్సైట్), రాగి చెంబు, విద్యుత్ తీగలు (రాగి), ఇత్తడి వస్తువులు (రాగి + జింక్), బంగారు–వెండి ఆభరణాలు, ఇనుప బీరువా, సైకిల్, తాళాలు, మేకులు. ఇవి భూపటలంలోని శిలల్లో ఉన్న ఖనిజ ధాతువుల నుండి శుద్ధి చేసి తీసిన లోహాలు. ఖనిజాలు ఎక్కడ దొరుకుతాయి: ఇనుము – ఒడిశా, ఛత్తీస్‌గఢ్, కర్ణాటక; బాక్సైట్ – ఒడిశా, MP; రాగి – రాజస్థాన్, జార్ఖండ్, MP; బంగారం – కర్ణాటక (కోలార్, హట్టి)."]],["లోతుగా ఆలోచించండి – ఖనిజాలు, ఇనుము–ఉక్కు పరిశ్రమ సంబంధం (పుట 94)",["అవును, సంబంధం ఉంది. ఇనుప ఖనిజం, మాంగనీస్, కోకింగ్ బొగ్గు ఎక్కువగా ఒడిశా–జార్ఖండ్–ఛత్తీస్‌గఢ్–పశ్చిమ బెంగాల్ (చోటా నాగపూర్ పీఠభూమి) ప్రాంతంలో ఒకే చోట ఉన్నాయి. అందుకే జంషెడ్‌పూర్, బొకారో, రూర్కెలా, భిలాయ్, దుర్గాపూర్ వంటి ఇనుము–ఉక్కు కర్మాగారాలు ఇక్కడే – ముడిసరుకులు దగ్గరగా ఉండటం వల్ల రవాణా ఖర్చు తగ్గుతుంది (భారీ, బరువు తగ్గే ముడిసరుకులు)."]],["సేకరించండి – మీ రాష్ట్ర విద్యుత్ కేంద్రాలు (పుట 112)",["ఆంధ్రప్రదేశ్ – థర్మల్: డా. నార్ల తాతారావు థర్మల్ (విజయవాడ), రాయలసీమ థర్మల్ (ముద్దనూరు, కడప), సింహాద్రి NTPC (విశాఖపట్నం), శ్రీ దామోదరం సంజీవయ్య థర్మల్ కేంద్రం (కృష్ణపట్నం, నెల్లూరు). జల విద్యుత్: శ్రీశైలం (కృష్ణా), నాగార్జునసాగర్ కుడి కాలువ, ఎగువ సీలేరు, దిగువ సీలేరు, మాచ్‌ఖండ్. సౌర: కర్నూలు అల్ట్రా మెగా సోలార్ పార్క్ (పాణ్యం), అనంతపురం (ఎన్‌పీ కుంట). భారత పటంలో గుర్తించండి."]],["అభ్యాసాలు – Exercises (పుట 116)",["1) (i) (b) బాక్సైట్ (ii) (b) అభ్రకం (mica) (iii) (a) అవక్షేప శిలలు (iv) (c) థోరియం","2) (i) (a) ఇనుప ఖనిజాల్లో ఇనుము ఉంటుంది – ఇనుప ధాతువు, మాంగనీస్, నికెల్, కోబాల్ట్ (లోహ ఖనిజ ఉత్పత్తిలో మూడొంతులు; లోహ పరిశ్రమలకు ఆధారం); ఇనుమేతర ఖనిజాల్లో ఇనుము ఉండదు – రాగి, బాక్సైట్, సీసం, జింక్, బంగారం. (b) సాంప్రదాయ శక్తి వనరులు – చాలా కాలంగా వాడుతున్న, ఎక్కువగా పునరుద్ధరించలేని, కాలుష్యకారక వనరులు: వంటచెరకు, పిడకలు, బొగ్గు, పెట్రోలియం, సహజ వాయువు, విద్యుత్. సాంప్రదాయేతర వనరులు – ఇటీవల వాడుకలోకి వచ్చిన, పునరుద్ధరించగల, కాలుష్యం లేని: సౌర, పవన, అలల, భూతాప, బయోగ్యాస్, అణుశక్తి.","2) (ii) ఖనిజం – నిర్దిష్ట అంతర్గత నిర్మాణం గల సహజసిద్ధ, సజాతీయ పదార్థం (భూవిజ్ఞాన శాస్త్రం ప్రకారం); రంగు, కాఠిన్యం, స్ఫటికాలు, మెరుపు, సాంద్రతతో గుర్తిస్తారు.","(iii) అగ్ని, రూపాంతర శిలల్లో కరిగిన/ఆవిరి రూపంలోని ఖనిజాలు పగుళ్ళు, సందులు, లోపాల ద్వారా పైకి చొచ్చుకుని గట్టిపడి ఈనెలు (veins – చిన్నవి), లోడ్‌లు (lodes – పెద్దవి)గా ఏర్పడతాయి – తగరం, రాగి, జింక్, సీసం.","(iv) ఖనిజాలు పరిమితం, పునరుద్ధరించలేనివి; అవి ఏర్పడటానికి లక్షల సంవత్సరాలు పడుతుంది – వినియోగ వేగంతో పోలిస్తే పునరుద్ధరణ అతి నెమ్మది; నిరంతర వెలికితీతతో లోతు పెరిగి ఖర్చు పెరుగుతుంది, నాణ్యత తగ్గుతుంది; భావితరాల కోసం, పరిశ్రమల కొనసాగింపు కోసం సంరక్షణ అవసరం (రీసైక్లింగ్, ప్రత్యామ్నాయాలు, మెరుగైన సాంకేతికత).","3) (i) భారత్‌లో బొగ్గు రెండు భూవైజ్ఞానిక యుగాల శిలల్లో ఉంది: (1) గోండ్వానా బొగ్గు (200 మిలియన్ ఏళ్లు పైగా) – ప్రధానంగా దామోదర్ లోయ (పశ్చిమ బెంగాల్–జార్ఖండ్): ఝరియా, రాణిగంజ్, బొకారో – మెటలర్జికల్ బొగ్గు; ఇంకా గోదావరి, మహానది, సోన్, వార్ధా నదీ లోయలు. (2) టెర్షియరీ బొగ్గు (55 మిలియన్ ఏళ్లు) – మేఘాలయ, అస్సాం, అరుణాచల్ ప్రదేశ్, నాగాలాండ్. లిగ్నైట్ – నైవేలి (తమిళనాడు). బొగ్గు భారీ వస్తువు – వాడేటప్పుడు బరువు తగ్గుతుంది కాబట్టి భారీ పరిశ్రమలు, థర్మల్ కేంద్రాలు బొగ్గు క్షేత్రాల దగ్గరే.","3) (ii) భారత్ ఉష్ణమండల దేశం – ఏడాది పొడవునా సమృద్ధిగా సూర్యరశ్మి; ఫోటోవోల్టాయిక్ సాంకేతికతతో సూర్యకాంతిని నేరుగా విద్యుత్తుగా మార్చవచ్చు; పునరుద్ధరించగల, కాలుష్యం లేని, ఉచిత వనరు; గ్రామీణ, దూర ప్రాంతాల్లో వికేంద్రీకృత విద్యుత్ అందించవచ్చు; వంటచెరకు, పిడకలపై ఆధారం తగ్గి అడవులు, పర్యావరణం కాపాడబడతాయి, పిడకలను ఎరువుగా వాడవచ్చు; శిలాజ ఇంధనాల దిగుమతి భారం తగ్గుతుంది; భుజ్ దగ్గర మాధాపూర్ సౌర ప్లాంట్ వంటి పెద్ద ప్రాజెక్టులు – కాబట్టి సౌర శక్తికి ఉజ్వల భవిష్యత్తు ఉంది."]],["కృత్యం – ఖనిజాల గళ్ళ నుడికట్టు (crossword) (పుట 118)",["Across: ప్లేసర్ నిక్షేపంలో దొరికేది – GOLD; బైలదిల్లాలో తవ్వే ఇనుప ఖనిజం – HEMATITE; విద్యుత్ పరిశ్రమకు అనివార్యం – MICA; ఈశాన్య భారత బొగ్గు యుగం – TERTIARY; ఈనెలు, లోడ్‌లలో ఏర్పడేది – TIN.","Down: 1. ఒక ఇనుప ఖనిజం – MANGANESE; 2. సిమెంట్ పరిశ్రమ ముడిసరుకు – LIMESTONE; 3. అయస్కాంత గుణం గల అత్యుత్తమ ఇనుప ఖనిజం – MAGNETITE; 4. అత్యుత్తమ కఠిన బొగ్గు – ANTHRACITE; 5. అల్యూమినియం ధాతువు – BAUXITE; 6. ఖేత్రి గనులు – COPPER; 7. బాష్పీభవనంతో ఏర్పడేది – GYPSUM."]]]},{"id":"gs6","no":11,"t":"తయారీ పరిశ్రమలు (Manufacturing Industries)","m":[11],"ty":"భూగోళం – అధ్యాయం 6","by":"సాంఘిక శాస్త్రం – భూగోళం 10వ తరగతి (పుటలు 120–145)","th":"తయారీ ప్రాముఖ్యం, పరిశ్రమల స్థానం, పరిశ్రమల వర్గీకరణ, వ్యవసాయ ఆధారిత (వస్త్ర, జనపనార, చక్కెర), ఖనిజ ఆధారిత (ఇనుము–ఉక్కు, అల్యూమినియం, సిమెంట్), IT–ఎలక్ట్రానిక్స్, పారిశ్రామిక కాలుష్యం, నియంత్రణ","sum":"ముడిసరుకులను ఎక్కువ విలువైన ఉత్పత్తులుగా భారీ పరిమాణంలో మార్చడమే తయారీ (manufacturing) – ద్వితీయ కార్యకలాపం; ఒక దేశ ఆర్థిక బలాన్ని దాని తయారీ పరిశ్రమల అభివృద్ధితో కొలుస్తారు. తయారీ రంగం అభివృద్ధికి వెన్నెముక – వ్యవసాయ ఆధునీకరణకు తోడ్పాటు, వ్యవసాయం నుండి ఇతర ఉద్యోగాలు (వ్యవసాయంపై ఆధారం తగ్గింపు), పేదరికం–నిరుద్యోగ నిర్మూలన, ప్రాంతీయ అసమానతల తగ్గింపు, ఎగుమతులతో విదేశీ మారకద్రవ్యం, ముడిసరుకును విలువైన వస్తువుగా మార్చి ఆర్థిక సంపన్నత. పరిశ్రమలు–వ్యవసాయం పరస్పర ఆధారితం. పరిశ్రమల స్థానాన్ని నిర్ణయించేవి: ముడిసరుకు లభ్యత, శ్రమ, మూలధనం, విద్యుత్, మార్కెట్, ప్రభుత్వ విధానాలు; పట్టణీకరణ వల్ల సమీకరణ ఆర్థిక ప్రయోజనాలు (agglomeration economies). వర్గీకరణ: ముడిసరుకు ఆధారంగా – వ్యవసాయ ఆధారిత (పత్తి, ఉన్ని, జనపనార, పట్టు వస్త్రాలు, రబ్బరు, చక్కెర, తేయాకు, కాఫీ, వంటనూనె), ఖనిజ ఆధారిత (ఇనుము–ఉక్కు, సిమెంట్, అల్యూమినియం, యంత్ర పరికరాలు, పెట్రోకెమికల్స్); పాత్ర ఆధారంగా – ప్రాథమిక/కీలక పరిశ్రమలు (ఇనుము–ఉక్కు, రాగి, అల్యూమినియం కరిగించడం), వినియోగ పరిశ్రమలు (చక్కెర, టూత్‌పేస్ట్, కాగితం, కుట్టుమిషన్లు, ఫ్యాన్లు); మూలధనం ఆధారంగా – చిన్న తరహా (గరిష్ఠ పెట్టుబడి పరిమితి లోపు), భారీ తరహా; యాజమాన్యం ఆధారంగా – ప్రభుత్వ రంగం (BHEL, SAIL), ప్రైవేటు రంగం (TISCO, బజాజ్ ఆటో, డాబర్), ఉమ్మడి రంగం (OIL – ఆయిల్ ఇండియా), సహకార రంగం (మహారాష్ట్ర చక్కెర, కేరళ కొబ్బరి పరిశ్రమలు); ముడిసరుకు–ఉత్పత్తుల బరువు ఆధారంగా – భారీ పరిశ్రమలు (ఇనుము–ఉక్కు), తేలికపాటి పరిశ్రమలు (విద్యుత్ ఉపకరణాలు). వస్త్ర పరిశ్రమ – ముడిసరుకు నుండి అత్యధిక విలువ ఉత్పత్తుల వరకు స్వయం సమృద్ధమైన, పూర్తి విలువ గొలుసు గల ఏకైక పరిశ్రమ; పత్తి వస్త్రాలు – తొలి విజయవంతమైన మిల్లు ముంబై (1854); మహారాష్ట్ర, గుజరాత్ పత్తి ప్రాంతాలు; స్పిన్నింగ్ కేంద్రీకృతం, నేత వికేంద్రీకృతం. జనపనార – తొలి మిల్లు 1855 రిష్రా (కోల్‌కతా దగ్గర); హుగ్లీ నదీ తీరంలో; విభజన తర్వాత మూడొంతుల జనపనార ప్రాంతం బంగ్లాదేశ్‌కు; ముడి జనపనార, ఉత్పత్తుల్లో భారత్ అగ్రస్థానం; ప్లాస్టిక్ వ్యతిరేకత, జాతీయ జనపనార విధానం (2005). చక్కెర – ప్రపంచంలో రెండో స్థానం, గుర్–ఖండసారిలో మొదటి స్థానం; ముడిసరుకు బరువైనది, ఎక్కువ దూరం తీసుకెళ్తే సుక్రోజ్ తగ్గుతుంది – UP, బీహార్, మహారాష్ట్ర, కర్ణాటక, తమిళనాడు, AP, గుజరాత్; సహకార రంగానికి అనువైనది; దక్షిణ, పశ్చిమ రాష్ట్రాలకు తరలింపు (ఎక్కువ సుక్రోజ్, చల్లని వాతావరణం – ఎక్కువ కాలం గానుగ). ఇనుము–ఉక్కు – ప్రాథమిక పరిశ్రమ; భారీ పరిశ్రమ; ముడిసరుకులు – ఇనుప ఖనిజం, కోకింగ్ బొగ్గు, సున్నపురాయి (4:2:1), మాంగనీస్; చోటా నాగపూర్ పీఠభూమిలో కేంద్రీకరణ. అల్యూమినియం కరిగించడం – రెండో ముఖ్య లోహ పరిశ్రమ; తేలిక, తుప్పు పట్టదు, మంచి ఉష్ణ వాహకం; బాక్సైట్, చౌక–నిరంతర విద్యుత్ ముఖ్యం; ఒడిశా, ఝార్ఖండ్, పశ్చిమ బెంగాల్, ఛత్తీస్‌గఢ్, మహారాష్ట్ర, తమిళనాడు. సిమెంట్ – నిర్మాణానికి అవసరం; సున్నపురాయి, సిలికా, జిప్సం; తొలి ప్లాంట్ చెన్నై (1904); గుజరాత్ ప్లాంట్లు గల్ఫ్ మార్కెట్‌కు. IT–ఎలక్ట్రానిక్స్ – రేడియో, టీవీ, టెలిఫోన్, సెల్ ఫోన్, కంప్యూటర్లు; బెంగళూరు – భారత ఎలక్ట్రానిక్ రాజధాని; నోయిడా, ముంబై, చెన్నై, హైదరాబాద్, పుణె; ఉపాధి కల్పనలో ప్రధాన పాత్ర. పారిశ్రామిక కాలుష్యం – వాయు (సల్ఫర్ డయాక్సైడ్, కార్బన్ మోనాక్సైడ్, ధూళి; భోపాల్ గ్యాస్ దుర్ఘటన), జల (రంగులు, డిటర్జెంట్లు, ఆమ్లాలు, లవణాలు, సీసం, పాదరసం; కాగితం, పల్ప్, రసాయన, వస్త్ర, రంగుల, పెట్రోలియం రిఫైనరీలు, చర్మశుద్ధి, ఎలక్ట్రోప్లేటింగ్), ఉష్ణ (వేడి నీరు నదుల్లోకి), నేల, శబ్ద కాలుష్యం. నియంత్రణ – నీటి పునర్వినియోగం, వర్షపు నీటి సేకరణ, వ్యర్థ నీటి శుద్ధి (ప్రాథమిక – యాంత్రిక; ద్వితీయ – జీవ; తృతీయ – జీవ, రసాయన, భౌతిక), భూగర్భ జలాల అతి వినియోగ నియంత్రణ, ఎత్తైన చిమ్నీలు, ఎలక్ట్రోస్టాటిక్ ప్రెసిపిటేటర్లు, ఫ్యాబ్రిక్ ఫిల్టర్లు, స్క్రబ్బర్లు, బొగ్గు బదులు చమురు/వాయువు, శబ్దం తగ్గించే యంత్రాలు, ఇయర్ ప్లగ్‌లు; NTPC ఆదర్శం.","pts":["తయారీ: ముడిసరుకులను ఎక్కువ విలువ గల ఉత్పత్తులుగా భారీ పరిమాణంలో మార్చడం – ద్వితీయ రంగం.","ప్రాముఖ్యం: వ్యవసాయ ఆధునీకరణ, ఉద్యోగాలు, పేదరిక–నిరుద్యోగ నిర్మూలన, ప్రాంతీయ సమతుల్యత, ఎగుమతులు–విదేశీ మారకం, సంపద – అభివృద్ధికి వెన్నెముక.","స్థాన కారకాలు: ముడిసరుకు, శ్రమ, మూలధనం, విద్యుత్, మార్కెట్, ప్రభుత్వ విధానాలు, పట్టణాల సమీకరణ ప్రయోజనాలు.","ముడిసరుకు ఆధారంగా: వ్యవసాయ ఆధారిత (పత్తి, జనపనార, పట్టు, ఉన్ని, చక్కెర, తేయాకు, కాఫీ, వంటనూనె), ఖనిజ ఆధారిత (ఇనుము–ఉక్కు, సిమెంట్, అల్యూమినియం, యంత్ర పరికరాలు).","పాత్ర ఆధారంగా: ప్రాథమిక/కీలక పరిశ్రమలు – ఇతర పరిశ్రమలకు ముడిసరుకు (ఇనుము–ఉక్కు, రాగి, అల్యూమినియం కరిగించడం); వినియోగ పరిశ్రమలు – నేరుగా వినియోగదారులకు (చక్కెర, టూత్‌పేస్ట్, కాగితం, ఫ్యాన్లు).","యాజమాన్యం ఆధారంగా: ప్రభుత్వ (BHEL, SAIL), ప్రైవేటు (TISCO, బజాజ్ ఆటో, డాబర్), ఉమ్మడి (ఆయిల్ ఇండియా లిమిటెడ్), సహకార (మహారాష్ట్ర చక్కెర, కేరళ కొబ్బరి).","వస్త్ర పరిశ్రమ: ముడిసరుకు నుండి అత్యధిక విలువ ఉత్పత్తుల వరకు స్వయం సమృద్ధమైన, పూర్తి విలువ గొలుసు గల ఏకైక భారత పరిశ్రమ.","పత్తి వస్త్రాలు: తొలి విజయవంతమైన మిల్లు ముంబై (1854); నూలు వడకడం మహారాష్ట్ర, గుజరాత్, తమిళనాడులో కేంద్రీకృతం; నేత వికేంద్రీకృతం (చేనేత, పవర్ లూమ్).","జనపనార: తొలి మిల్లు 1855 రిష్రా; ఎక్కువ మిల్లులు హుగ్లీ నదీ తీరంలో; ముడి జనపనార, ఉత్పత్తుల్లో భారత్ అగ్రస్థానం, బంగ్లాదేశ్ తర్వాత రెండో ఎగుమతిదారు.","చక్కెర: ప్రపంచంలో రెండో స్థానం, గుర్–ఖండసారిలో మొదటి స్థానం; చెరకు బరువైనది, రవాణాలో సుక్రోజ్ తగ్గుతుంది – మిల్లులు పొలాలకు దగ్గరగా; సహకార రంగానికి అనువైనది.","ఇనుము–ఉక్కు: ప్రాథమిక, భారీ పరిశ్రమ; ఇనుప ఖనిజం, కోకింగ్ బొగ్గు, సున్నపురాయి (సుమారు 4:2:1), మాంగనీస్; ఉక్కు వినియోగం దేశాభివృద్ధికి సూచిక.","అల్యూమినియం కరిగించడం: రెండో ముఖ్యమైన లోహ పరిశ్రమ; ముడిసరుకు బాక్సైట్; చౌక, నిరంతర విద్యుత్ అవసరం.","సిమెంట్: సున్నపురాయి, సిలికా, జిప్సం, బొగ్గు/విద్యుత్; తొలి ప్లాంట్ చెన్నై 1904; గుజరాత్ ప్లాంట్లు గల్ఫ్ మార్కెట్ దగ్గర.","IT–ఎలక్ట్రానిక్స్: బెంగళూరు – భారత ఎలక్ట్రానిక్ రాజధాని; నోయిడా, ముంబై, చెన్నై, హైదరాబాద్, పుణె; అత్యధిక ఉపాధి కల్పన.","కాలుష్యం: వాయు, జల, ఉష్ణ, నేల, శబ్ద; నియంత్రణ – నీటి పునర్వినియోగం, వ్యర్థ శుద్ధి (ప్రాథమిక, ద్వితీయ, తృతీయ), ఎలక్ట్రోస్టాటిక్ ప్రెసిపిటేటర్లు, స్క్రబ్బర్లు, ఫిల్టర్లు, ఎత్తైన చిమ్నీలు."],"w":[["తయారీ","Manufacturing"],["వ్యవసాయ ఆధారిత పరిశ్రమలు","Agro-based industries"],["ఖనిజ ఆధారిత పరిశ్రమలు","Mineral-based industries"],["ప్రాథమిక / కీలక పరిశ్రమలు","Basic / Key industries"],["వినియోగ పరిశ్రమలు","Consumer industries"],["ప్రభుత్వ రంగం","Public sector"],["ఉమ్మడి రంగం","Joint sector"],["సహకార రంగం","Cooperative sector"],["భారీ పరిశ్రమలు","Heavy industries"],["తేలికపాటి పరిశ్రమలు","Light industries"],["సమీకరణ ఆర్థిక ప్రయోజనాలు","Agglomeration economies"],["విలువ గొలుసు","Value chain"],["కరిగించడం","Smelting"],["ఉష్ణ కాలుష్యం","Thermal pollution"],["ఎలక్ట్రోస్టాటిక్ ప్రెసిపిటేటర్","Electrostatic precipitator"],["పారిశ్రామిక కాలుష్యం","Industrial pollution"]],"gr":{"t":"ముఖ్య వాస్తవాలు","p":["1854 – తొలి విజయవంతమైన పత్తి మిల్లు (ముంబై) | 1855 – తొలి జనపనార మిల్లు (రిష్రా) | 1904 – తొలి సిమెంట్ ప్లాంట్ (చెన్నై)","ఇనుము–ఉక్కు ముడిసరుకులు: ఇనుప ఖనిజం : కోకింగ్ బొగ్గు : సున్నపురాయి ≈ 4 : 2 : 1","చక్కెర: ప్రపంచంలో 2వ స్థానం; గుర్, ఖండసారిలో 1వ స్థానం | జనపనార: ఉత్పత్తిలో 1వ, ఎగుమతిలో 2వ (బంగ్లాదేశ్ తర్వాత)","బెంగళూరు – భారత ఎలక్ట్రానిక్ రాజధాని","వ్యర్థ నీటి శుద్ధి: ప్రాథమిక – యాంత్రిక (వడపోత, తేర్చడం) | ద్వితీయ – జీవ ప్రక్రియ | తృతీయ – జీవ, రసాయన, భౌతిక (పునర్వినియోగం)"]},"qa":[["తయారీ అంటే?","ముడిసరుకులను ఎక్కువ విలువైన ఉత్పత్తులుగా భారీ పరిమాణంలో మార్చే ప్రక్రియ."],["ప్రాథమిక (కీలక) పరిశ్రమలు అంటే? ఉదాహరణ?","తమ ఉత్పత్తులను ఇతర పరిశ్రమలకు ముడిసరుకుగా సరఫరా చేసే పరిశ్రమలు – ఇనుము–ఉక్కు."],["తయారీ రంగాన్ని అభివృద్ధికి వెన్నెముక అని ఎందుకు అంటారు?","వ్యవసాయ ఆధునీకరణ, ఉద్యోగాలు, ఎగుమతులు, ప్రాంతీయ సమతుల్యత, సంపద సృష్టికి తోడ్పడుతుంది."],["భారత్‌లో తొలి విజయవంతమైన పత్తి మిల్లు?","ముంబై, 1854."],["జనపనార మిల్లులు ఎక్కువగా ఎక్కడ?","పశ్చిమ బెంగాల్ హుగ్లీ నదీ తీరం."],["చక్కెర పరిశ్రమ సహకార రంగానికి ఎందుకు అనువైనది?","కాలానుగుణ పరిశ్రమ, ముడిసరుకు రైతుల నుండే; రైతులే సభ్యులుగా లాభాలు పంచుకోవచ్చు."],["అల్యూమినియం కరిగించడానికి ముఖ్యమైన రెండు అంశాలు?","బాక్సైట్ (ముడిసరుకు), చౌక–నిరంతర విద్యుత్ సరఫరా."],["భారత ఎలక్ట్రానిక్ రాజధాని?","బెంగళూరు."],["పరిశ్రమలు కలిగించే కాలుష్య రకాలు?","వాయు, జల, ఉష్ణ, నేల, శబ్ద కాలుష్యం."],["పరిశ్రమల వాయు కాలుష్యాన్ని తగ్గించే పరికరాలు?","ఎలక్ట్రోస్టాటిక్ ప్రెసిపిటేటర్లు, ఫ్యాబ్రిక్ ఫిల్టర్లు, స్క్రబ్బర్లు, జడత్వ వేరుపరిచేవి, ఎత్తైన చిమ్నీలు."]],"act":"మీ ప్రాంతంలోని ఒక వ్యవసాయ ఆధారిత (బియ్యం మిల్లు/చక్కెర మిల్లు) మరియు ఒక ఖనిజ ఆధారిత (మైకా/సిమెంట్/గ్రానైట్) పరిశ్రమను సందర్శించి – ముడిసరుకులు, రవాణా, ఉద్యోగులు, కాలుష్య నియంత్రణ వివరాలతో నివేదిక రాయండి.","kn":"నెల్లూరు జిల్లా కృష్ణపట్నం, శ్రీ సిటీ (తిరుపతి జిల్లా) వంటి పారిశ్రామిక ప్రాంతాలు మన గూడూరుకు దగ్గరలోనే! వస్త్ర పరిశ్రమ మాత్రమే పత్తి నుండి వస్త్రాల వరకు పూర్తిగా స్వదేశీ విలువ గొలుసు గల భారత పరిశ్రమ.","qz":[["బాక్సైట్‌ను ముడిసరుకుగా వాడే పరిశ్రమ?","అల్యూమినియం కరిగించడం","సిమెంట్","కాగితం","ఉక్కు"],["టెలిఫోన్లు, కంప్యూటర్లు తయారుచేసే పరిశ్రమ?","ఎలక్ట్రానిక్","ఉక్కు","అల్యూమినియం","సమాచార సాంకేతికత"],["భారత్‌లో తొలి విజయవంతమైన పత్తి మిల్లు?","ముంబై (1854)","అహ్మదాబాద్ (1860)","కోల్‌కతా (1855)","చెన్నై (1904)"],["తొలి జనపనార మిల్లు ఎక్కడ, ఎప్పుడు?","రిష్రా, 1855","ముంబై, 1854","కాన్పూర్, 1860","హౌరా, 1900"],["గుర్, ఖండసారి ఉత్పత్తిలో భారత్ స్థానం?","మొదటి","రెండో","మూడో","ఐదో"],["ఇనుము–ఉక్కు పరిశ్రమ ఏ రకం?","ప్రాథమిక (కీలక) పరిశ్రమ","వినియోగ పరిశ్రమ","తేలికపాటి పరిశ్రమ","కుటీర పరిశ్రమ"],["ఉమ్మడి రంగ పరిశ్రమకు ఉదాహరణ?","ఆయిల్ ఇండియా లిమిటెడ్ (OIL)","TISCO","BHEL","డాబర్"],["ప్రభుత్వ రంగ సంస్థ?","SAIL","బజాజ్ ఆటో","TISCO","డాబర్"],["భారత్‌లో తొలి సిమెంట్ ప్లాంట్?","చెన్నై (1904)","ముంబై","కోల్‌కతా","గుజరాత్"],["భారత ఎలక్ట్రానిక్ రాజధాని?","బెంగళూరు","హైదరాబాద్","పుణె","నోయిడా"],["పూర్తి విలువ గొలుసు గల స్వయం సమృద్ధ ఏకైక పరిశ్రమ?","వస్త్ర పరిశ్రమ","చక్కెర","ఉక్కు","సిమెంట్"],["జనపనార మిల్లులు ఎక్కువగా ఏ నది తీరంలో?","హుగ్లీ","గోదావరి","యమున","నర్మదా"],["వినియోగ పరిశ్రమకు ఉదాహరణ?","టూత్‌పేస్ట్","ఇనుము–ఉక్కు","రాగి కరిగించడం","అల్యూమినియం కరిగించడం"],["వేడి నీటిని నదుల్లోకి వదిలితే కలిగే కాలుష్యం?","ఉష్ణ కాలుష్యం","శబ్ద కాలుష్యం","నేల కాలుష్యం","వాయు కాలుష్యం"],["గాలిలోని ధూళి కణాలను తొలగించే పరికరం?","ఎలక్ట్రోస్టాటిక్ ప్రెసిపిటేటర్","ఇయర్ ప్లగ్","వాటర్ పంప్","జనరేటర్"],["చక్కెర మిల్లులు దక్షిణ, పశ్చిమ రాష్ట్రాలకు తరలడానికి కారణం?","చెరకులో ఎక్కువ సుక్రోజ్, ఎక్కువ కాలం గానుగ","ఎక్కువ జనాభా","బొగ్గు లభ్యత","ఓడరేవులు"]],"wb":{"mis":"IT పరిశ్రమ, ఎలక్ట్రానిక్ పరిశ్రమ ఒకటి కాదు – టెలిఫోన్లు, కంప్యూటర్లు తయారుచేసేది ఎలక్ట్రానిక్ పరిశ్రమ. ఉమ్మడి రంగం అంటే ప్రభుత్వం + ప్రైవేటు కలిసి నడిపేది – సహకార రంగం కాదు. పరిశ్రమల కాలుష్యం గాలికే పరిమితం కాదు – నీరు, నేల, శబ్దం, ఉష్ణం కూడా.","qz":[],"pg":"120–145","f":"books/10/Class10_Social_Geography_Textbook.pdf","p":126,"lb":"పాఠ్యపుస్తకం","ws":["ఆలోచించండి – చక్కెర పరిశ్రమ సహకార రంగం, ఖనిజ ఆధారిత పరిశ్రమలు (పుట 128)","కనుగొనండి – సిమెంట్ ప్లాంట్ల స్థానాలు (పుట 134)","అభ్యాసాలు – Exercises (పుట 140)"]},"tg":[["ఆలోచించండి – చక్కెర పరిశ్రమ సహకార రంగం, ఖనిజ ఆధారిత పరిశ్రమలు (పుట 128)",["చక్కెర పరిశ్రమ సహకార రంగానికి అనువైనది ఎందుకంటే: ముడిసరుకు చెరకు రైతుల నుండే వస్తుంది, బరువైనది, ఎక్కువ కాలం నిల్వ ఉండదు (సుక్రోజ్ తగ్గుతుంది) – రైతులే సభ్యులుగా దగ్గరలోనే మిల్లు నడిపితే సమయానికి గానుగ, న్యాయమైన ధర, లాభాల్లో వాటా దక్కుతాయి; కాలానుగుణ పరిశ్రమ, తక్కువ మూలధనంతో నడపవచ్చు (మహారాష్ట్ర సహకార చక్కెర కర్మాగారాలు ఉదాహరణ).","ఖనిజ ఆధారిత పరిశ్రమలు: ఇనుము–ఉక్కు, అల్యూమినియం కరిగించడం, రాగి కరిగించడం, సిమెంట్, గాజు, యంత్ర పరికరాలు, పెట్రోకెమికల్స్, ఎరువులు, మైకా ఉత్పత్తులు, ఇటుకలు, గ్రానైట్."]],["కనుగొనండి – సిమెంట్ ప్లాంట్ల స్థానాలు (పుట 134)",["సిమెంట్ ప్లాంట్లు సున్నపురాయి, బొగ్గు, విద్యుత్, రవాణా, మార్కెట్ దగ్గరగా ఉండటం ఆర్థికంగా లాభదాయకం. ఉదాహరణలు: ఆంధ్రప్రదేశ్ – కర్నూలు, నంద్యాల, గుంటూరు (పల్నాడు – మాచర్ల), కడప (ఎర్రగుంట్ల); తెలంగాణ – నల్గొండ (మట్టంపల్లి), మంచిర్యాల; మధ్యప్రదేశ్ – కట్ని, సత్నా; రాజస్థాన్ – చిత్తోర్‌గఢ్, సవాయ్ మాధోపూర్; ఛత్తీస్‌గఢ్ – దుర్గ్, రాయ్‌పూర్; కర్ణాటక – గుల్బర్గా; తమిళనాడు – అరియలూర్; గుజరాత్ – కచ్ఛ్ (గల్ఫ్ ఎగుమతి)."]],["అభ్యాసాలు – Exercises (పుట 140)",["1) (i) (a) అల్యూమినియం కరిగించడం (ii) (b) ఎలక్ట్రానిక్","2) (i) ముడిసరుకులను ఎక్కువ విలువైన ఉత్పత్తులుగా భారీ పరిమాణంలో మార్చడం తయారీ – ఉదా: కలప నుండి కాగితం, చెరకు నుండి చక్కెర, ఇనుప ఖనిజం నుండి ఉక్కు, బాక్సైట్ నుండి అల్యూమినియం.","(ii) తమ ఉత్పత్తులను ఇతర వస్తువుల తయారీకి ముడిసరుకుగా సరఫరా చేసే పరిశ్రమలు ప్రాథమిక/కీలక పరిశ్రమలు – ఉదా: ఇనుము–ఉక్కు పరిశ్రమ (భారీ, మధ్య, తేలికపాటి పరిశ్రమలన్నీ యంత్రాల కోసం దీనిపై ఆధారపడతాయి), రాగి, అల్యూమినియం కరిగించడం.","3) (i) పరిశ్రమల కాలుష్యం: వాయు కాలుష్యం – సల్ఫర్ డయాక్సైడ్, కార్బన్ మోనాక్సైడ్ వంటి అవాంఛిత వాయువులు, ధూళి, పొగ (రసాయన, కాగితం కర్మాగారాలు, ఇటుక బట్టీలు, రిఫైనరీలు, కరిగించే కర్మాగారాలు, శిలాజ ఇంధనాల దహనం) – మానవ ఆరోగ్యం, జంతువులు, మొక్కలు, భవనాలపై ప్రభావం; భోపాల్ గ్యాస్ దుర్ఘటన వంటి విష వాయువుల ప్రమాదాలు. జల కాలుష్యం – రంగులు, డిటర్జెంట్లు, ఆమ్లాలు, లవణాలు, సీసం, పాదరసం వంటి భారీ లోహాలు, పురుగుమందులు, ఎరువులు, ప్లాస్టిక్, రబ్బరు సహా సేంద్రియ, అసేంద్రియ వ్యర్థాలు నదుల్లోకి (కాగితం–పల్ప్, రసాయన, వస్త్ర, రంగుల, రిఫైనరీలు, చర్మశుద్ధి, ఎలక్ట్రోప్లేటింగ్). ఉష్ణ కాలుష్యం – కర్మాగారాలు, థర్మల్ కేంద్రాల వేడి నీరు చల్లబరచకుండా నదుల్లోకి – జలచరాలకు హాని; అణు కేంద్రాల వ్యర్థాలు. నేల కాలుష్యం – వ్యర్థాలు, గాజు, హానికర రసాయనాలు, ఫ్లై యాష్ డంపింగ్ – నేల నిరుపయోగం, భూగర్భ జలాలు కలుషితం. శబ్ద కాలుష్యం – యంత్రాలు, జనరేటర్లు, రంపాలు – చిరాకు, వినికిడి లోపం, గుండె వేగం, రక్తపోటు పెరుగుదల.","3) (ii) పర్యావరణ క్షీణత తగ్గించే చర్యలు: ప్రాసెసింగ్‌లో నీటిని తక్కువగా వాడటం, రెండు/మూడు దశల్లో పునర్వినియోగం; అవసరాలకు వర్షపు నీటి సేకరణ; వేడి నీరు, వ్యర్థ నీటిని నదులు, చెరువుల్లోకి వదిలే ముందు శుద్ధి చేయడం – ప్రాథమిక (యాంత్రిక – వడపోత, తేర్చడం), ద్వితీయ (జీవ ప్రక్రియ), తృతీయ (జీవ, రసాయన, భౌతిక – పునర్వినియోగానికి); నీటి వనరుల సమీపంలో పరిశ్రమలు భూగర్భ జలాలను అతిగా తోడకుండా చట్టపరమైన నియంత్రణ; వాయువుల్లోని ధూళి కణాలను తగ్గించడానికి ఎలక్ట్రోస్టాటిక్ ప్రెసిపిటేటర్లు, ఫ్యాబ్రిక్ ఫిల్టర్లు, స్క్రబ్బర్లు, జడత్వ వేరుపరిచే పరికరాలు; ఎత్తైన చిమ్నీలు; బొగ్గుకు బదులు చమురు, వాయువు వంటి శుభ్రమైన ఇంధనాలు; యంత్రాల శబ్దం తగ్గించడం, జనరేటర్లకు సైలెన్సర్లు, ఇయర్ ప్లగ్‌లు, శబ్ద నిరోధక గోడలు; పచ్చదనం (గ్రీన్ బెల్ట్); NTPC వంటి సంస్థల ఆదర్శ పద్ధతులు – ఆధునిక సాంకేతికత, బూడిద వినియోగం, పర్యావరణ పర్యవేక్షణ.","కృత్యం 1 (ఒక్క పదం): (i) యంత్రాలు నడిపేది – POWER; (ii) కర్మాగారంలో పనిచేసేవారు – WORKER; (iii) ఉత్పత్తి అమ్మే చోటు – MARKET; (iv) వస్తువులు అమ్మే వ్యక్తి – RETAILER; (v) తయారైన వస్తువు – PRODUCT; (vi) తయారు చేయడం – MANUFACTURE; (vii) నేల, నీరు, గాలి క్షీణత – POLLUTION.","కృత్యం 2 (పదబంధం): 1. AGRO-BASED (వ్యవసాయ ఆధారిత) 2. SUGARCANE 3. JUTE (బంగారు నార) 4. IRON AND STEEL 5. BHILAI.","ప్రాజెక్ట్: ఉదా: వ్యవసాయ ఆధారిత – గూడూరు ప్రాంత బియ్యం మిల్లు (ముడిసరుకు – వడ్లు; రవాణా – ట్రాక్టర్లు, లారీలు; విద్యుత్); ఖనిజ ఆధారిత – మైకా/క్వార్ట్జ్ ప్రాసెసింగ్ లేదా సిమెంట్ (ముడిసరుకు – ఖనిజం; రవాణా ఖర్చు). పర్యావరణ నిబంధనలు పాటిస్తున్నాయో (ధూళి నియంత్రణ, వ్యర్థ నీటి శుద్ధి, పచ్చదనం) పరిశీలించి రాయండి."]]]},{"id":"gs7","no":12,"t":"జాతీయ ఆర్థిక వ్యవస్థకు జీవనాడులు (Lifelines of National Economy)","m":[11],"ty":"భూగోళం – అధ్యాయం 7","by":"సాంఘిక శాస్త్రం – భూగోళం 10వ తరగతి (పుటలు 146–173)","th":"రవాణా – రోడ్లు, రైల్వేలు, పైప్‌లైన్లు, జల రవాణా, ఓడరేవులు, వాయు రవాణా; సమాచార వ్యవస్థ; అంతర్జాతీయ వాణిజ్యం; పర్యాటకం","sum":"వస్తువులు, సేవలు సరఫరా ప్రాంతాల నుండి డిమాండ్ ప్రాంతాలకు చేరడానికి రవాణా అవసరం; రవాణా, సమాచారం, వాణిజ్యం పరస్పర పూరకాలు – దేశ ఆర్థిక వ్యవస్థకు జీవనాడులు. రవాణా రకాలు – భూ (రోడ్లు, రైల్వేలు, పైప్‌లైన్లు), జల, వాయు. రోడ్లు – ప్రపంచంలో అతిపెద్ద రోడ్ నెట్‌వర్క్‌లలో ఒకటి; రైల్వేల కంటే ప్రయోజనాలు: నిర్మాణ ఖర్చు తక్కువ, ఎగుడుదిగుడు, కొండ ప్రాంతాలకూ, తక్కువ మంది–తక్కువ సరుకు తక్కువ దూరాలకు చౌక, ఇంటింటికీ సేవ, ఇతర రవాణాలకు అనుసంధానం (feeder). రోడ్ల వర్గీకరణ: స్వర్ణ చతుర్భుజి సూపర్ హైవేలు (ఢిల్లీ–కోల్‌కతా–చెన్నై–ముంబై–ఢిల్లీ, ఆరు లేన్లు), ఉత్తర–దక్షిణ కారిడార్ (శ్రీనగర్–కన్యాకుమారి), తూర్పు–పడమర కారిడార్ (సిల్చార్–పోర్‌బందర్) – NHAI; జాతీయ రహదారులు (CPWD, షేర్‌షా సూరి మార్గ్ – ఢిల్లీ–అమృత్‌సర్ NH-1), రాష్ట్ర రహదారులు (PWD), జిల్లా రోడ్లు (జిల్లా పరిషత్), ఇతర (గ్రామీణ) రోడ్లు (ప్రధానమంత్రి గ్రామ సడక్ యోజన), సరిహద్దు రోడ్లు (బోర్డర్ రోడ్స్ ఆర్గనైజేషన్, 1960 – ఉత్తర, ఈశాన్య సరిహద్దులు); నిర్మాణ పదార్థం ఆధారంగా మెటల్డ్, అన్‌మెటల్డ్. రైల్వేలు – సరుకు, ప్రయాణికుల ప్రధాన రవాణా; 17 జోన్లు; గేజ్‌లు – బ్రాడ్ (1.676 మీ.), మీటర్ (1.000 మీ.), నారో (0.762, 0.610 మీ.) – మొత్తం 67,956 కి.మీ.; ఉత్తర మైదానాల్లో దట్టమైన నెట్‌వర్క్, పర్వతాలు, ఎడారులు, అడవుల్లో తక్కువ; కొంకణ్ రైల్వే; సమస్యలు – టికెట్ లేని ప్రయాణం, చైన్ లాగడం, ప్రజా ఆస్తి నష్టం. పైప్‌లైన్లు – ముడిచమురు, పెట్రోలియం ఉత్పత్తులు, సహజ వాయువు, స్లర్రీ; ప్రారంభ ఖర్చు ఎక్కువ, నిర్వహణ ఖర్చు తక్కువ, ట్రాన్స్‌షిప్‌మెంట్ నష్టాలు–ఆలస్యం ఉండవు; మూడు నెట్‌వర్క్‌లు – ఎగువ అస్సాం–కాన్పూర్, సలాయా (గుజరాత్)–జలంధర్, HVJ గ్యాస్ పైప్‌లైన్ (1700 కి.మీ.). జల రవాణా – అత్యంత చౌక, బరువైన, పెద్ద సరుకులకు అనుకూలం, ఇంధన సమర్థం, పర్యావరణ హితం; జాతీయ జలమార్గాలు. ఓడరేవులు – 7,516.6 కి.మీ. తీరం; 12 ప్రధాన, 200 నోటిఫైడ్ ఇతర ఓడరేవులు; ప్రధాన ఓడరేవులు 95% విదేశీ వాణిజ్యం; కాండ్లా (కచ్ఛ్ – స్వాతంత్ర్యం తర్వాత తొలి ఓడరేవు, కరాచీ నష్టం తర్వాత; దీన్‌దయాళ్ పోర్ట్), ముంబై (అతిపెద్ద సహజ ఓడరేవు), జవహర్‌లాల్ నెహ్రూ పోర్ట్, మార్మగోవా (గోవా – ఇనుప ఖనిజ ఎగుమతి), న్యూ మంగళూరు (కుద్రేముఖ్ ఇనుము), కొచ్చి (సహజ ఓడరేవు, లగూన్ ముఖద్వారం), తూత్తుకుడి, చెన్నై (పురాతన కృత్రిమ ఓడరేవు, ముంబై తర్వాత రెండో పెద్దది), విశాఖపట్నం (అత్యంత లోతైన, భూపరివేష్టిత, బాగా రక్షిత ఓడరేవు; ఇనుప ఖనిజ ఎగుమతికి), పారాదీప్ (ఒడిశా – ఇనుప ఖనిజం), కోల్‌కతా (నదీ ఓడరేవు, పోటు ఓడరేవు – నిరంతర డ్రెడ్జింగ్), హల్దియా (కోల్‌కతాపై ఒత్తిడి తగ్గించడానికి). వాయు రవాణా – అత్యంత వేగవంతం, సౌకర్యవంతం, ప్రతిష్ఠాత్మకం; కఠిన భూభాగాలు (ఈశాన్యం), ఎడారులు, దీవులకు; ఎయిర్ ఇండియా, ప్రైవేటు సంస్థలు; పవన్ హన్స్ హెలికాప్టర్లు (ONGC, దుర్గమ ప్రాంతాలు). సమాచారం – వ్యక్తిగత (తపాలా – ప్రపంచంలో అతిపెద్ద తపాలా నెట్‌వర్క్; మొదటి తరగతి – కార్డులు, కవర్లు విమానంలో; రెండో తరగతి – పుస్తక ప్యాకెట్లు, పత్రికలు; ఆరు మెయిల్ ఛానళ్లు – రాజధాని, మెట్రో, గ్రీన్, బిజినెస్, బల్క్, పీరియాడికల్; STD, టెలికాం) మరియు సామూహిక (రేడియో, టీవీ, పత్రికలు, సినిమా – ప్రపంచంలోనే అత్యధిక సినిమాల నిర్మాణం). వాణిజ్యం – అంతర్గత (స్థానిక), అంతర్జాతీయ; ఎగుమతులు–దిగుమతుల తేడా = వాణిజ్య శేషం (అనుకూల/ప్రతికూల); IT ఎగుమతులు. పర్యాటకం – 1.5 కోట్ల మంది ప్రత్యక్ష ఉపాధి; జాతీయ ఐక్యత, హస్తకళలకు మద్దతు, విదేశీ మారకం; వారసత్వ, పర్యావరణ, సాహస, సాంస్కృతిక, వైద్య, వ్యాపార పర్యాటకం.","pts":["రవాణా, సమాచారం, వాణిజ్యం – దేశ, ఆర్థిక వ్యవస్థకు జీవనాడులు; ప్రపంచాన్ని “గ్రామం”గా మార్చాయి.","రోడ్ల ప్రయోజనాలు: తక్కువ నిర్మాణ ఖర్చు, ఎగుడుదిగుడు–కొండ ప్రాంతాల్లో వీలు, తక్కువ దూరం–తక్కువ సరుకుకు చౌక, ఇంటింటి సేవ, ఇతర రవాణాలకు అనుసంధానం.","స్వర్ణ చతుర్భుజి: ఢిల్లీ–కోల్‌కతా–చెన్నై–ముంబై–ఢిల్లీ (6 లేన్లు); ఉత్తర–దక్షిణ కారిడార్: శ్రీనగర్–కన్యాకుమారి; తూర్పు–పడమర కారిడార్: సిల్చార్–పోర్‌బందర్ – NHAI.","రోడ్ల రకాలు: జాతీయ రహదారులు (CPWD), రాష్ట్ర రహదారులు (PWD), జిల్లా రోడ్లు (జిల్లా పరిషత్), ఇతర/గ్రామీణ రోడ్లు (PMGSY), సరిహద్దు రోడ్లు (BRO, 1960).","సరిహద్దు రోడ్లు: వ్యూహాత్మక ప్రాంతాల్లో (ఉత్తర, ఈశాన్య సరిహద్దులు) రోడ్లు – రక్షణ, దుర్గమ ప్రాంతాల అభివృద్ధి, సైన్యం–సరుకుల రవాణా.","రైల్వేలు: 17 జోన్లు; బ్రాడ్ గేజ్ 1.676 మీ. (63,950 కి.మీ.), మీటర్ 1.000 మీ., నారో 0.762/0.610 మీ.; మొత్తం 67,956 కి.మీ.","రైల్వేలకు అనుకూలం: ఉత్తర మైదానాలు (చదునైన భూమి, దట్టమైన జనాభా, వ్యవసాయ వనరులు); కష్టం: హిమాలయాలు, రాజస్థాన్ ఎడారి, గుజరాత్ చిత్తడి నేలలు, అడవులు, సహ్యాద్రి (కనుమల ద్వారా).","పైప్‌లైన్లు: ఎగువ అస్సాం–కాన్పూర్ (గువాహటి, బరౌని, అలహాబాద్ మీదుగా); సలాయా–జలంధర్ (విరంగం, మథుర, ఢిల్లీ, సోనిపట్); HVJ (హజీరా–విజయ్‌పూర్–జగదీశ్‌పూర్) గ్యాస్ – 1700 కి.మీ.","జల రవాణా: అత్యంత చౌక; బరువైన, పెద్ద సరుకులకు; ఇంధన సమర్థం, పర్యావరణ హితం.","ఓడరేవులు: 12 ప్రధాన + 200 నోటిఫైడ్ ఇతర; ప్రధాన ఓడరేవుల ద్వారా 95% విదేశీ వాణిజ్యం; తీర పొడవు 7,516.6 కి.మీ.","కాండ్లా (కచ్ఛ్): స్వాతంత్ర్యం తర్వాత అభివృద్ధి చేసిన తొలి ఓడరేవు – కరాచీ పాకిస్తాన్‌కు వెళ్ళాక ముంబై ఒత్తిడి తగ్గించడానికి; పోటు ఓడరేవు.","విశాఖపట్నం: అత్యంత లోతైన, భూపరివేష్టిత, బాగా రక్షిత ఓడరేవు – మొదట ఇనుప ఖనిజ ఎగుమతికి; పారాదీప్ – ఇనుప ఖనిజ ఎగుమతి; కోల్‌కతా – నదీ (పోటు) ఓడరేవు.","వాయు రవాణా: అత్యంత వేగవంతం; దుర్గమ ప్రాంతాలు, ఈశాన్యం, దీవులకు; పవన్ హన్స్ హెలికాప్టర్లు – ONGC తీరం ఆవల కార్యకలాపాలు.","సమాచారం: భారత తపాలా నెట్‌వర్క్ ప్రపంచంలో అతిపెద్దది; ఆరు మెయిల్ ఛానళ్లు – రాజధాని, మెట్రో, గ్రీన్, బిజినెస్, బల్క్, పీరియాడికల్; సామూహిక మాధ్యమాలు – రేడియో, టీవీ, పత్రికలు, సినిమా.","వాణిజ్యం: స్థానిక, అంతర్రాష్ట్ర, అంతర్జాతీయ; ఎగుమతులు > దిగుమతులు = అనుకూల వాణిజ్య శేషం; పర్యాటకం – 1.5 కోట్ల మందికి ప్రత్యక్ష ఉపాధి."],"w":[["రవాణా","Transport"],["సమాచార వ్యవస్థ","Communication"],["స్వర్ణ చతుర్భుజి","Golden Quadrilateral"],["జాతీయ రహదారి","National Highway"],["సరిహద్దు రోడ్లు","Border roads"],["మెటల్డ్ రోడ్లు","Metalled roads"],["రైల్ గేజ్","Rail gauge"],["పైప్‌లైన్","Pipeline"],["ట్రాన్స్‌షిప్‌మెంట్","Trans-shipment"],["జలమార్గం","Waterway"],["ఓడరేవు","Port"],["భూపరివేష్టిత ఓడరేవు","Landlocked harbour"],["నదీ ఓడరేవు","Riverine port"],["వాణిజ్య శేషం","Balance of trade"],["సామూహిక మాధ్యమాలు","Mass communication"],["పర్యాటకం","Tourism"]],"gr":{"t":"ముఖ్య వాస్తవాలు","p":["ఉత్తర–దక్షిణ కారిడార్: శ్రీనగర్ (ఉత్తర చివర) – కన్యాకుమారి | తూర్పు–పడమర: సిల్చార్ – పోర్‌బందర్","షేర్‌షా సూరి మార్గ్ (ఢిల్లీ–అమృత్‌సర్) = NH-1 | BRO స్థాపన: 1960","రైల్వే గేజ్‌లు: బ్రాడ్ 1.676 మీ. | మీటర్ 1.000 మీ. | నారో 0.762, 0.610 మీ. | 17 జోన్లు | దక్షిణ రైల్వే ప్రధాన కార్యాలయం – చెన్నై","ఓడరేవులు (పడమర): కాండ్లా, ముంబై, JNPT, మార్మగోవా, న్యూ మంగళూరు, కొచ్చి | (తూర్పు): తూత్తుకుడి, చెన్నై, విశాఖపట్నం, పారాదీప్, కోల్‌కతా, హల్దియా","ప్రధాన ఓడరేవులు 95% విదేశీ వాణిజ్యం | తీరం 7,516.6 కి.మీ."]},"qa":[["రవాణా, సమాచారాన్ని జీవనాడులు అని ఎందుకు అంటారు?","వస్తువులు, సేవలు, ప్రజలు, సమాచారాన్ని దేశమంతా చేర్చి ఉత్పత్తి, వినియోగం, వాణిజ్యం, ఐక్యతకు తోడ్పడతాయి – శరీరానికి రక్తనాళాల వంటివి."],["స్వర్ణ చతుర్భుజి ఏ నగరాలను కలుపుతుంది?","ఢిల్లీ–కోల్‌కతా–చెన్నై–ముంబై–ఢిల్లీ."],["తూర్పు–పడమర కారిడార్ కలిపే రెండు చివర్లు?","సిల్చార్ (అస్సాం) – పోర్‌బందర్ (గుజరాత్)."],["సరిహద్దు రోడ్ల ప్రాముఖ్యత?","దేశ రక్షణ, సరిహద్దు ప్రాంతాల్లో సైన్యం–సరుకుల రవాణా, దుర్గమ ప్రాంతాల ఆర్థికాభివృద్ధి."],["బ్రాడ్ గేజ్ వెడల్పు?","1.676 మీటర్లు."],["ట్రాన్స్‌షిప్‌మెంట్ నష్టాలు, ఆలస్యం తగ్గించే రవాణా?","పైప్‌లైన్ రవాణా."],["అత్యంత లోతైన భూపరివేష్టిత ఓడరేవు?","విశాఖపట్నం."],["స్వాతంత్ర్యం తర్వాత అభివృద్ధి చేసిన తొలి ఓడరేవు?","కాండ్లా (కచ్ఛ్, గుజరాత్)."],["అంతర్జాతీయ, స్థానిక వాణిజ్యం తేడా?","అంతర్జాతీయ – రెండు లేదా ఎక్కువ దేశాల మధ్య (ఓడరేవులు, విమానాశ్రయాల ద్వారా); స్థానిక – నగరాలు, పట్టణాలు, గ్రామాల్లో దేశం లోపల."],["పర్యాటకం ప్రయోజనాలు?","ఉపాధి, విదేశీ మారకం, జాతీయ ఐక్యత, హస్తకళలు–సంస్కృతికి మద్దతు, అంతర్జాతీయ అవగాహన."]],"act":"భారత పటంలో స్వర్ణ చతుర్భుజి, NS–EW కారిడార్లు, 12 ప్రధాన ఓడరేవులు గుర్తించండి. మీ ఊరి నుండి తిరుపతి/చెన్నైకి ఏ రవాణా మార్గాలు ఉన్నాయో (NH-16, రైల్వే) చార్ట్ తయారు చేయండి.","kn":"మన గూడూరు జంక్షన్ చెన్నై–హౌరా, చెన్నై–ఢిల్లీ (విజయవాడ మీదుగా) రైలు మార్గంలో ముఖ్యమైన స్టేషన్; చెన్నై–కోల్‌కతా జాతీయ రహదారి (NH-16) కూడా గూడూరు మీదుగానే! విశాఖపట్నం భారత్‌లోని అత్యంత లోతైన భూపరివేష్టిత ఓడరేవు.","qz":[["తూర్పు–పడమర కారిడార్ కలిపే చివర్లు?","సిల్చార్, పోర్‌బందర్","ముంబై, నాగ్‌పూర్","ముంబై, కోల్‌కతా","నాగ్‌పూర్, సిలిగురి"],["ట్రాన్స్‌షిప్‌మెంట్ నష్టాలు, ఆలస్యాన్ని తగ్గించే రవాణా?","పైప్‌లైన్","రైల్వేలు","రోడ్లు","జలమార్గాలు"],["HVJ పైప్‌లైన్‌తో అనుసంధానం లేని రాష్ట్రం?","మహారాష్ట్ర","మధ్యప్రదేశ్","గుజరాత్","ఉత్తరప్రదేశ్"],["తూర్పు తీరంలో అత్యంత లోతైన, భూపరివేష్టిత, బాగా రక్షిత ఓడరేవు?","విశాఖపట్నం","చెన్నై","పారాదీప్","తూత్తుకుడి"],["భారత్‌లో అత్యంత ముఖ్యమైన రవాణా సాధనం?","రైల్వేలు","పైప్‌లైన్","రోడ్లు","వాయుమార్గాలు"],["రెండు లేదా ఎక్కువ దేశాల మధ్య వాణిజ్యం?","అంతర్జాతీయ వాణిజ్యం","అంతర్గత వాణిజ్యం","బాహ్య వాణిజ్యం","స్థానిక వాణిజ్యం"],["ఉత్తర–దక్షిణ కారిడార్ ఉత్తర చివర?","శ్రీనగర్","ఢిల్లీ","అమృత్‌సర్","సిల్చార్"],["దక్షిణ రైల్వే జోన్ ప్రధాన కార్యాలయం?","చెన్నై","సికింద్రాబాద్","బెంగళూరు","విశాఖపట్నం"],["1.676 మీ. వెడల్పు గల రైల్ గేజ్?","బ్రాడ్ గేజ్","మీటర్ గేజ్","నారో గేజ్","స్టాండర్డ్ గేజ్"],["నదీ (riverine) ఓడరేవు?","కోల్‌కతా","ముంబై","చెన్నై","కాండ్లా"],["స్వాతంత్ర్యం తర్వాత అభివృద్ధి చేసిన తొలి ఓడరేవు?","కాండ్లా","పారాదీప్","హల్దియా","JNPT"],["సరిహద్దు రోడ్స్ ఆర్గనైజేషన్ (BRO) స్థాపన?","1960","1947","1953","1972"],["ప్రధాన ఓడరేవుల ద్వారా జరిగే విదేశీ వాణిజ్యం శాతం?","95%","50%","75%","30%"],["ఢిల్లీ–అమృత్‌సర్ షేర్‌షా సూరి మార్గ్ ఏ జాతీయ రహదారి?","NH-1","NH-7","NH-16","NH-44"],["ONGC తీరం ఆవల కార్యకలాపాలకు హెలికాప్టర్ సేవలు?","పవన్ హన్స్","ఎయిర్ ఇండియా","ఇండిగో","BRO"],["అతిపెద్ద సహజ ఓడరేవు?","ముంబై","చెన్నై","విశాఖపట్నం","కోల్‌కతా"]],"wb":{"mis":"చెన్నై కృత్రిమ ఓడరేవు; విశాఖపట్నం అత్యంత లోతైన భూపరివేష్టిత ఓడరేవు – రెండూ తూర్పు తీరమే. అంతర్జాతీయ (international) వాణిజ్యం అనే పదమే రెండు దేశాల మధ్య వాణిజ్యానికి సరైనది. HVJ పైప్‌లైన్ మహారాష్ట్ర గుండా వెళ్ళదు.","qz":[],"pg":"146–173","f":"books/10/Class10_Social_Geography_Textbook.pdf","p":152,"lb":"పాఠ్యపుస్తకం","ws":["కనుగొనండి – రైల్వే జోన్లు, ప్రధాన కార్యాలయాలు (పుట 152)","ఆలోచించండి – రైళ్లు సమయానికి నడవడానికి మన సహాయం (పుట 154)","కృత్యం – బనిహాల్, బారాముల్లా (పుట 156)","ఆలోచించండి – ఈశాన్యంలో వాయు రవాణా (పుట 160)","చర్చించండి – మీ రాష్ట్రంలో పర్యాటకం (పుట 166)","అభ్యాసాలు – Exercises (పుట 168)","కృత్యం – పదాల వెతుకులాట (పుట 170)"]},"tg":[["కనుగొనండి – రైల్వే జోన్లు, ప్రధాన కార్యాలయాలు (పుట 152)",["ముఖ్య జోన్లు – ప్రధాన కార్యాలయం: ఉత్తర – న్యూఢిల్లీ; ఈశాన్య – గోరఖ్‌పూర్; ఈశాన్య సరిహద్దు – మాలిగావ్ (గువాహటి); తూర్పు – కోల్‌కతా; ఆగ్నేయ – కోల్‌కతా (గార్డెన్ రీచ్); దక్షిణ మధ్య – సికింద్రాబాద్; దక్షిణ – చెన్నై; మధ్య – ముంబై (CST); పశ్చిమ – ముంబై (చర్చిగేట్); నైరుతి – హుబ్బళ్లి; వాయవ్య – జైపూర్; పశ్చిమ మధ్య – జబల్‌పూర్; ఉత్తర మధ్య – ప్రయాగ్‌రాజ్; తూర్పు మధ్య – హాజీపూర్; తూర్పు తీర – భువనేశ్వర్; ఆగ్నేయ మధ్య – బిలాస్‌పూర్; మెట్రో – కోల్‌కతా; దక్షిణ తీర రైల్వే – విశాఖపట్నం (కొత్తగా ప్రకటించిన జోన్). పటంలో ప్రధాన కార్యాలయాలు గుర్తించండి."]],["ఆలోచించండి – రైళ్లు సమయానికి నడవడానికి మన సహాయం (పుట 154)",["చైన్ అనవసరంగా లాగకపోవడం; టికెట్‌తోనే ప్రయాణం; రైల్వే ఆస్తిని (సీట్లు, లైట్లు, పట్టాలు) నష్టపరచకపోవడం; పట్టాలపై అడ్డంకులు పెట్టకపోవడం, ఆందోళనల పేరుతో రైళ్లను ఆపకపోవడం; పరిశుభ్రత పాటించడం; అనుమానాస్పద విషయాలు అధికారులకు తెలపడం; ఎక్కేటప్పుడు, దిగేటప్పుడు క్రమశిక్షణ."]],["కృత్యం – బనిహాల్, బారాముల్లా (పుట 156)",["బనిహాల్ – జమ్మూ–కశ్మీర్‌లో పీర్ పంజాల్ పర్వత శ్రేణికి దక్షిణాన (రామ్‌బన్ జిల్లా), జమ్మూ–శ్రీనగర్ మార్గంలో; బారాముల్లా – కశ్మీర్ లోయ వాయవ్య భాగంలో జీలం నది ఒడ్డున, శ్రీనగర్‌కు వాయవ్యంగా. పటంలో ఈ రెండు పట్టణాలను గుర్తించి, మధ్య రైలు మార్గం (శ్రీనగర్ మీదుగా) గీయండి."]],["ఆలోచించండి – ఈశాన్యంలో వాయు రవాణా (పుట 160)",["ఈశాన్యంలో పెద్ద నదులు, కోతకు గురైన కొండ భూభాగం, దట్టమైన అడవులు, తరచు వరదలు, అంతర్జాతీయ సరిహద్దుల వల్ల రోడ్లు, రైల్వేల నిర్మాణం కష్టం, తరచు దెబ్బతింటాయి. వాయు రవాణా లేకపోతే ఆ ప్రాంతం దేశంలోని మిగతా భాగాల నుండి దాదాపు వేరుపడుతుంది – అత్యవసర సేవలు, వైద్యం, వ్యాపారం, పర్యాటకం, రక్షణ కష్టమవుతాయి. అందుకే అక్కడ వాయు రవాణా అత్యంత కీలకం."]],["చర్చించండి – మీ రాష్ట్రంలో పర్యాటకం (పుట 166)",["ఆంధ్రప్రదేశ్‌లో అభివృద్ధి చేయగల పర్యాటకం: ఆధ్యాత్మిక (తిరుమల, శ్రీశైలం, శ్రీకాళహస్తి, అమరావతి బౌద్ధ స్థూపం), సముద్ర తీర (విశాఖ RK బీచ్, మైపాడు – నెల్లూరు, సూర్యలంక), పర్యావరణ (అరకు లోయ, బొర్రా గుహలు, పులికాట్ సరస్సు – నేలపట్టు పక్షులు, పాపికొండలు), చారిత్రక (గండికోట, లేపాక్షి, చంద్రగిరి కోట), సాహస (గండికోట కాన్యన్, హార్సిలీ హిల్స్). ఆకర్షణ: సహజ సౌందర్యం, సంస్కృతి, ప్రసిద్ధ దేవాలయాలు. సుస్థిర పర్యాటకంతో ప్రయోజనాలు: స్థానికులకు ఉపాధి (గైడ్లు, హోటళ్లు, హస్తకళలు – కొండపల్లి బొమ్మలు, కలంకారీ), విదేశీ మారకం, మౌలిక సదుపాయాలు; పర్యావరణాన్ని, స్థానిక సంస్కృతిని కాపాడుతూ, వ్యర్థాలు నియంత్రిస్తూ, పర్యాటకుల సంఖ్యను పరిమితం చేస్తూ అభివృద్ధి."]],["అభ్యాసాలు – Exercises (పుట 168)",["1) (i) (b) సిల్చార్, పోర్‌బందర్ (ii) (c) పైప్‌లైన్ (iii) (b) మహారాష్ట్ర (iv) (d) విశాఖపట్నం (v) (b) రైల్వేలు (vi) (b) అంతర్జాతీయ వాణిజ్యం (International trade)","2) (i) రోడ్ల ప్రయోజనాలు: రైల్వేల కంటే నిర్మాణ ఖర్చు తక్కువ; ఎగుడుదిగుడు, కొండ ప్రాంతాల్లో కూడా నిర్మించవచ్చు; తక్కువ మంది, తక్కువ సరుకును తక్కువ దూరాలకు తీసుకెళ్ళడం చౌక; ఇంటింటికీ సేవ – లోడింగ్, అన్‌లోడింగ్ ఖర్చు తక్కువ; రైల్వే స్టేషన్లు, ఓడరేవులు, విమానాశ్రయాలకు అనుసంధానం (feeder).","(ii) రైల్వేలు ఉత్తర మైదానాల్లో అత్యంత అనుకూలం – విశాలమైన చదునైన భూమి, దట్టమైన జనాభా, సమృద్ధ వ్యవసాయ వనరులు; ఎక్కువ దూరాలకు భారీ సరుకు (బొగ్గు, ధాన్యం, సిమెంట్), ఎక్కువ మంది ప్రయాణికులను తక్కువ ఖర్చుతో తీసుకెళ్తాయి.","(iii) సరిహద్దు రోడ్లు (BRO, 1960) ఉత్తర, ఈశాన్య సరిహద్దుల్లోని వ్యూహాత్మక ప్రాంతాల్లో నిర్మిస్తారు – దేశ రక్షణ (సైన్యం, ఆయుధాల రవాణా), దుర్గమ ప్రాంతాలను అనుసంధానించడం, ఆ ప్రాంతాల ఆర్థికాభివృద్ధి; అధిక ఎత్తు ప్రాంతాలకు అన్ని కాలాల్లో రవాణా.","(iv) వ్యక్తులు, రాష్ట్రాలు, దేశాల మధ్య వస్తువుల మార్పిడి (కొనుగోలు–అమ్మకం) వాణిజ్యం. అంతర్జాతీయ వాణిజ్యం – రెండు లేదా ఎక్కువ దేశాల మధ్య, సముద్ర, వాయు, భూ మార్గాల ద్వారా; దేశ ఆర్థికాభివృద్ధికి సూచిక. స్థానిక వాణిజ్యం – దేశం లోపల నగరాలు, పట్టణాలు, గ్రామాల మధ్య.","3) (i) రవాణా, సమాచారం వస్తువులు, సేవలను సరఫరా ప్రాంతాల నుండి డిమాండ్ ప్రాంతాలకు, ముడిసరుకును కర్మాగారాలకు, ఉత్పత్తులను మార్కెట్లకు చేర్చుతాయి; వ్యవసాయ, పారిశ్రామికాభివృద్ధి, వాణిజ్యం వీటిపైనే ఆధారపడతాయి; ఉత్పత్తి, వినియోగం, పంపిణీ కలుపుతాయి; దూర ప్రాంతాలను, ప్రజలను అనుసంధానించి జాతీయ ఐక్యత, సాంస్కృతిక మార్పిడి పెంచుతాయి; ఉపాధి, పర్యాటకం, విపత్తుల సమయంలో సహాయం, రక్షణకు అవసరం; సమాచార వ్యవస్థ (తపాలా, ఫోన్, ఇంటర్నెట్, మీడియా) ప్రపంచాన్ని ఒక గ్రామంగా మార్చింది. అందుకే రవాణా, సమాచార వ్యవస్థలను దేశ, ఆర్థిక వ్యవస్థల జీవనాడులు అంటారు – శరీరంలో రక్తనాళాల్లా.","3) (ii) గత 15 ఏళ్లలో అంతర్జాతీయ వాణిజ్యం మారింది – వస్తువుల మార్పిడి స్థానంలో సమాచారం, జ్ఞానం, సేవల మార్పిడి పెరిగింది; భారత్ IT, సాఫ్ట్‌వేర్ సేవల ఎగుమతుల్లో పెద్ద విదేశీ మారకం సంపాదిస్తోంది; ప్రపంచీకరణ, సరళీకరణతో ఎగుమతులు, దిగుమతుల పరిమాణం, వైవిధ్యం పెరిగాయి; ఎగుమతులు – రత్నాలు–ఆభరణాలు, రసాయనాలు, ఇంజనీరింగ్ వస్తువులు, వ్యవసాయ ఉత్పత్తులు, పెట్రోలియం ఉత్పత్తులు, ఔషధాలు; దిగుమతులు – ముడిచమురు, ఎలక్ట్రానిక్స్, యంత్రాలు, బంగారం; ఈ-కామర్స్, డిజిటల్ చెల్లింపులు, కంటైనర్ ఓడరేవులు, విమాన సరుకు రవాణా వాణిజ్యాన్ని వేగవంతం చేశాయి.","క్విజ్: 1. శ్రీనగర్ 2. చెన్నై 3. బ్రాడ్ గేజ్ 4. కోల్‌కతా 5. మొఘల్‌సరాయ్ (పండిట్ దీన్‌దయాళ్ ఉపాధ్యాయ జంక్షన్) – ఉత్తర భారతంలో అత్యంత రద్దీ జంక్షన్లలో ఒకటి (కాన్పూర్, న్యూఢిల్లీ కూడా రద్దీ జంక్షన్లు)."]],["కృత్యం – పదాల వెతుకులాట (పుట 170)",["గ్రిడ్‌లో అడ్డంగా, నిలువుగా, వికర్ణంగా ప్రధాన నగరాలు, ఓడరేవుల పేర్లు వెతకండి – ఉదా: CHENNAI, MUMBAI, KOLKATA, DELHI, KANDLA, KOCHI, HALDIA, PARADIP, ఇతర రవాణా కేంద్రాలు. ప్రతి దాన్ని భారత పటంలో గుర్తించండి."]]]},{"id":"ec1","no":13,"t":"అభివృద్ధి (Development) – అర్థశాస్త్రం","m":[7],"ty":"Economics – Chapter 1","by":"సాంఘిక శాస్త్రం – అర్థశాస్త్రం 10వ తరగతి (పుటలు 6–35)","th":"వేర్వేరు వ్యక్తులు – వేర్వేరు అభివృద్ధి లక్ష్యాలు, తలసరి ఆదాయం, ప్రజా సౌకర్యాలు, మానవ అభివృద్ధి సూచిక, సుస్థిర అభివృద్ధి","sum":"అభివృద్ధి అంటే మనం ఎలా బతకాలని కోరుకుంటున్నామో, దేశం ఎలా ఉండాలో ఆలోచించడం. వేర్వేరు వ్యక్తులకు వారి జీవన పరిస్థితులను బట్టి వేర్వేరు అభివృద్ధి లక్ష్యాలు ఉంటాయి – భూమిలేని కూలీకి ఎక్కువ పని దినాలు, మంచి కూలి; ధనిక రైతుకు మంచి మద్దతు ధర. ఒకరికి అభివృద్ధి మరొకరికి నష్టం కావచ్చు (పెద్ద డ్యామ్ – విద్యుత్ కావాలనుకునే పారిశ్రామికవేత్తలు vs నిర్వాసిత గిరిజనులు). ప్రజలు ఆదాయంతో పాటు సమానత్వం, స్వేచ్ఛ, భద్రత, గౌరవం వంటి ఆదాయేతర లక్ష్యాలనూ కోరుకుంటారు. దేశాలను పోల్చడానికి ఆదాయం ముఖ్య ప్రమాణం; జనాభా వేర్వేరు కాబట్టి సగటు ఆదాయం = తలసరి ఆదాయం (మొత్తం ఆదాయం ÷ జనాభా) వాడతారు. ప్రపంచ బ్యాంకు ప్రపంచ అభివృద్ధి నివేదికలో తలసరి ఆదాయంతో దేశాలను వర్గీకరిస్తుంది; భారత్ దిగువ మధ్య ఆదాయ దేశం. సగటు ఆదాయం పంపిణీలోని అసమానతలను దాచేస్తుంది. హర్యానా తలసరి ఆదాయం కేరళ కంటే ఎక్కువైనా, శిశు మరణాల రేటు, అక్షరాస్యత, హాజరు నిష్పత్తిలో కేరళ ముందుంది – కారణం ఆరోగ్యం, విద్య, ప్రజా పంపిణీ వ్యవస్థ వంటి ప్రజా సౌకర్యాలు. జేబులోని డబ్బు కాలుష్యం లేని వాతావరణం, కల్తీ లేని మందులు కొనలేదు; సమిష్టిగా అందించడం చౌక. UNDP మానవ అభివృద్ధి నివేదిక ఆరోగ్యం (ఆయుర్దాయం), విద్య, తలసరి ఆదాయంతో దేశాలను పోలుస్తుంది (HDI); శ్రీలంక భారత్ కంటే ముందుంది. సుస్థిర అభివృద్ధి – భావితరాల కోసం వనరులను కాపాడుతూ అభివృద్ధి; భూగర్భ జలాల అతి వినియోగం, ముడిచమురు వంటి పునరుద్ధరించలేని వనరుల క్షీణత హెచ్చరికలు.","pts":["వేర్వేరు వ్యక్తులు → వేర్వేరు అభివృద్ధి లక్ష్యాలు; ఒకరి అభివృద్ధి మరొకరికి వినాశకరం కావచ్చు (సంఘర్షించే లక్ష్యాలు).","ఆదాయేతర లక్ష్యాలు: సమాన గౌరవం, స్వేచ్ఛ, భద్రత, ఇతరుల గౌరవం, వివక్ష లేకపోవడం, స్నేహం.","జాతీయ అభివృద్ధి: ఎక్కువ మందికి న్యాయమైన, మంచి మార్గం ఏది అని ఆలోచించడం.","తలసరి ఆదాయం = దేశ మొత్తం ఆదాయం ÷ మొత్తం జనాభా (సగటు ఆదాయం).","ప్రపంచ బ్యాంకు (World Development Report) – తలసరి ఆదాయం ఆధారంగా అధిక ఆదాయ / తక్కువ ఆదాయ దేశాలు; భారత్ – దిగువ మధ్య ఆదాయ దేశం.","సగటుల పరిమితి: ఆదాయ పంపిణీలోని అసమానతలను చూపదు (దేశం A, B రెండింటి సగటు ₹10,000).","శిశు మరణాల రేటు (IMR): ఒక సంవత్సరంలో పుట్టిన 1000 మంది పిల్లల్లో ఏడాది లోపు మరణించేవారు.","అక్షరాస్యత రేటు: 7 సంవత్సరాలు, పైబడిన జనాభాలో అక్షరాస్యుల శాతం. నికర హాజరు నిష్పత్తి: 14–15 ఏళ్ల పిల్లల్లో బడికి వెళ్ళేవారి శాతం.","కేరళ: తక్కువ తలసరి ఆదాయం ఉన్నా IMR 7, అక్షరాస్యత 94% – మంచి ప్రజా ఆరోగ్య, విద్యా సౌకర్యాలు, PDS.","ప్రజా సౌకర్యాలు (Public facilities): సమిష్టిగా అందించడం చౌక, సమర్థవంతం – పాఠశాలలు, ఆసుపత్రులు, రేషన్, భద్రత.","మానవ అభివృద్ధి సూచిక (HDI) – UNDP: ఆయుర్దాయం, సగటు పాఠశాల సంవత్సరాలు, తలసరి ఆదాయం (PPP $). 2021–22లో భారత్ ర్యాంక్ 132, శ్రీలంక 73.","సుస్థిరత: పునరుద్ధరించగల వనరులు (భూగర్భ జలం) కూడా అతిగా వాడితే క్షీణిస్తాయి; పునరుద్ధరించలేనివి (ముడిచమురు) కొన్నాళ్లకే అయిపోతాయి.","“భూమికి అందరి అవసరాలు తీర్చే వనరులున్నాయి, కానీ ఒక్కరి దురాశను తీర్చేంత లేవు” – మహాత్మా గాంధీ."],"w":[["అభివృద్ధి","Development"],["ఆకాంక్షలు","Aspirations"],["తలసరి ఆదాయం","Per capita income"],["సగటు ఆదాయం","Average income"],["శిశు మరణాల రేటు","Infant Mortality Rate (IMR)"],["అక్షరాస్యత రేటు","Literacy rate"],["నికర హాజరు నిష్పత్తి","Net Attendance Ratio"],["ఆయుర్దాయం","Life expectancy"],["మానవ అభివృద్ధి సూచిక","Human Development Index (HDI)"],["ప్రజా సౌకర్యాలు","Public facilities"],["ప్రజా పంపిణీ వ్యవస్థ","Public Distribution System (PDS)"],["సుస్థిర అభివృద్ధి","Sustainable development"],["పునరుద్ధరించగల వనరులు","Renewable resources"],["పునరుద్ధరించలేని వనరులు","Non-renewable resources"],["కొనుగోలు శక్తి సమానత","Purchasing Power Parity (PPP)"],["శరీర ద్రవ్యరాశి సూచిక","Body Mass Index (BMI)"]],"gr":{"t":"ముఖ్య సూత్రాలు & పట్టికలు","p":["తలసరి ఆదాయం = మొత్తం ఆదాయం ÷ జనాభా","BMI = బరువు (kg) ÷ ఎత్తు² (m²); 18.5 కంటే తక్కువ = పోషకాహార లోపం","పట్టిక 1.3 (2018–19 తలసరి ఆదాయం): హర్యానా ₹2,36,147, కేరళ ₹2,04,105, బీహార్ ₹40,982","పట్టిక 1.4: IMR – హర్యానా 30, కేరళ 7, బీహార్ 32; అక్షరాస్యత – 82%, 94%, 62%; హాజరు – 61, 83, 43","పట్టిక 1.6 (2019): శ్రీలంక – ఆదాయం $12,578, ఆయుర్దాయం 76.4, పాఠశాల సం. 10.8, HDI ర్యాంక్ 73; భారత్ – $6,590, 67.2, 6.7, 132","ముడిచమురు నిల్వలు (2017): ప్రపంచం 50 సంవత్సరాలకే సరిపోతాయి"]},"qa":[["అభివృద్ధి లక్ష్యాలు వ్యక్తికి వ్యక్తికి ఎందుకు వేరుగా ఉంటాయి?","ప్రతి ఒక్కరి జీవన పరిస్థితులు, అవసరాలు వేరు కాబట్టి; ప్రతి ఒక్కరు తమకు ముఖ్యమైనదే కోరుకుంటారు."],["తలసరి ఆదాయం అంటే ఏమిటి?","దేశ మొత్తం ఆదాయాన్ని మొత్తం జనాభాతో భాగించగా వచ్చేది – సగటు ఆదాయం."],["ప్రపంచ బ్యాంకు దేశాలను వర్గీకరించడానికి వాడే ప్రమాణం?","తలసరి ఆదాయం."],["సగటు ఆదాయం యొక్క ప్రధాన లోపం ఏమిటి?","అది ప్రజల మధ్య ఆదాయ పంపిణీని (అసమానతలను) చూపదు."],["శిశు మరణాల రేటు అంటే?","ఒక సంవత్సరంలో పుట్టిన ప్రతి 1000 మంది సజీవ శిశువుల్లో ఏడాది వయసు నిండకముందే మరణించే పిల్లల సంఖ్య."],["కేరళలో శిశు మరణాల రేటు తక్కువ ఎందుకు?","ప్రాథమిక ఆరోగ్య, విద్యా సౌకర్యాలు తగినంతగా ఉన్నాయి; ప్రజా పంపిణీ వ్యవస్థ బాగా పనిచేస్తుంది."],["HDI లో ఏ మూడు అంశాలు ఉంటాయి?","ఆరోగ్యం (ఆయుర్దాయం), విద్య (సగటు పాఠశాల సంవత్సరాలు), తలసరి ఆదాయం."],["సుస్థిర అభివృద్ధి అంటే?","భావితరాల అవసరాలకు భంగం కలగకుండా, వనరులను కాపాడుతూ ప్రస్తుత అవసరాలు తీర్చుకునే అభివృద్ధి."],["పునరుద్ధరించలేని వనరులకు ఉదాహరణ?","ముడిచమురు, బొగ్గు, సహజ వాయువు, ఖనిజాలు."],["డబ్బుతో కొనలేని వాటికి రెండు ఉదాహరణలు?","కాలుష్యం లేని వాతావరణం, కల్తీ లేని మందులు, అంటువ్యాధుల నుండి రక్షణ."]],"act":"మీ తరగతిలో ప్రతి విద్యార్థి బరువు (kg), ఎత్తు (m) కొలిచి BMI లెక్కించండి (ఎవరినీ ఎగతాళి చేయకుండా). మీ గ్రామం (TV పల్లి / గూడూరు) కోసం 5 అభివృద్ధి లక్ష్యాలు రాసి, రైతు, కూలీ, విద్యార్థిని, వ్యాపారి – వీరి లక్ష్యాలు ఎలా వేరుగా ఉంటాయో పట్టిక చేయండి.","kn":"HDI ని 1990లో పాకిస్తాన్ ఆర్థికవేత్త మహబూబ్ ఉల్ హక్, భారత నోబెల్ గ్రహీత అమర్త్యసేన్ రూపొందించారు. 2021–22 మానవ అభివృద్ధి నివేదికలో భారత్ ర్యాంక్ 132 – మన పొరుగు దేశం శ్రీలంక (73) మనకంటే చాలా ముందుంది!","qz":[["దేశ అభివృద్ధిని సాధారణంగా దేని ద్వారా నిర్ణయిస్తారు?","పైవన్నీ (తలసరి ఆదాయం, అక్షరాస్యత, ఆరోగ్యం)","తలసరి ఆదాయం మాత్రమే","అక్షరాస్యత మాత్రమే","ఆరోగ్య స్థితి మాత్రమే"],["మానవ అభివృద్ధిలో భారత్ కంటే మెరుగైన పొరుగు దేశం?","శ్రీలంక","పాకిస్తాన్","మయన్మార్","నేపాల్"],["4 కుటుంబాల సగటు ఆదాయం ₹5000; మూడు కుటుంబాల ఆదాయం ₹4000, ₹7000, ₹3000 అయితే నాల్గవది?","₹6000","₹7500","₹3000","₹2000"],["ప్రపంచ బ్యాంకు దేశాల వర్గీకరణకు ప్రధాన ప్రమాణం?","తలసరి ఆదాయం","అక్షరాస్యత","ఆయుర్దాయం","జనాభా"],["మానవ అభివృద్ధి నివేదికను ప్రచురించేది?","UNDP","ప్రపంచ బ్యాంకు","IMF","WTO"],["తలసరి ఆదాయం = ?","మొత్తం ఆదాయం ÷ మొత్తం జనాభా","మొత్తం జనాభా ÷ మొత్తం ఆదాయం","మొత్తం ఆదాయం × జనాభా","మొత్తం ఆదాయం − ఖర్చులు"],["2018లో అతి తక్కువ శిశు మరణాల రేటు గల రాష్ట్రం (పాఠం ప్రకారం)?","కేరళ","హర్యానా","బీహార్","పంజాబ్"],["అక్షరాస్యత రేటు ఏ వయసు వారిలో లెక్కిస్తారు?","7 సంవత్సరాలు, పైబడినవారు","5 సంవత్సరాలు, పైబడినవారు","10–14 సంవత్సరాలు","15–49 సంవత్సరాలు"],["నికర హాజరు నిష్పత్తి ఏ వయసు పిల్లలకు సంబంధించినది?","14 – 15 సంవత్సరాలు","6 – 10 సంవత్సరాలు","10 – 14 సంవత్సరాలు","16 – 18 సంవత్సరాలు"],["కిందివాటిలో పునరుద్ధరించగల వనరు?","భూగర్భ జలం","ముడిచమురు","బొగ్గు","సహజ వాయువు"],["ప్రపంచ ముడిచమురు నిల్వలు ప్రస్తుత వేగంలో ఎన్నేళ్లు సరిపోతాయి (2017 అంచనా)?","50 సంవత్సరాలు","100 సంవత్సరాలు","10 సంవత్సరాలు","200 సంవత్సరాలు"],["BMI 18.5 కంటే తక్కువ ఉంటే?","పోషకాహార లోపం (తక్కువ బరువు)","అధిక బరువు","సాధారణం","స్థూలకాయం"],["\"భూమికి అందరి అవసరాలు తీర్చే వనరులున్నాయి కానీ ఒక్కరి దురాశను కాదు\" – అన్నది?","మహాత్మా గాంధీ","అమర్త్యసేన్","నెహ్రూ","అంబేద్కర్"],["ఒకరి అభివృద్ధి మరొకరికి వినాశకరం కావడానికి ఉదాహరణ?","పెద్ద డ్యామ్ – గిరిజనుల నిర్వాసితం","గ్రామానికి పాఠశాల","రోడ్ల నిర్మాణం","ఆసుపత్రి ఏర్పాటు"],["హర్యానా తలసరి ఆదాయం ఎక్కువైనా కేరళ మానవ అభివృద్ధిలో ముందుండటానికి కారణం?","మంచి ప్రజా సౌకర్యాలు (ఆరోగ్యం, విద్య, PDS)","ఎక్కువ పరిశ్రమలు","ఎక్కువ జనాభా","ఎక్కువ వర్షపాతం"],["HDI ర్యాంక్ 2021–22 లో భారత్ ర్యాంక్?","132","73","161","100"]],"wb":{"mis":"“తలసరి ఆదాయం ఎక్కువైతే ఆ రాష్ట్రం అన్నివిధాలా అభివృద్ధి చెందినట్లే” అనుకోవడం తప్పు – హర్యానా vs కేరళ చూడండి. సగటు అసమానతలను దాచుతుంది. HDI ని ప్రపంచ బ్యాంకు కాదు, UNDP ప్రచురిస్తుంది.","qz":[],"pg":"6–35","f":"books/10/Class10_Social_Economics_Textbook.pdf","p":12,"lb":"పాఠ్యపుస్తకం","ws":["పట్టిక 1.1 – వేర్వేరు వ్యక్తుల అభివృద్ధి లక్ష్యాలు (పుట 8)","ఇవి చేయండి 1 (Let’s work these out) (పుట 12)","ఇవి చేయండి 2 – చర్చించండి (పుట 14)","ఇవి చేయండి 3 – సగటు ఆదాయం (పుట 18)","ఇవి చేయండి 4 – ప్రజా సౌకర్యాలు (పుట 24)","ఉదాహరణ 1 – భూగర్భ జలం (పుట 28)","ఉదాహరణ 2 – ముడిచమురు (పుట 30)","అభ్యాసాలు – Exercises (1–9) (పుట 32)","అభ్యాసాలు – Exercises (10–13), ప్రాజెక్ట్ (పుట 34)"]},"tg":[["పట్టిక 1.1 – వేర్వేరు వ్యక్తుల అభివృద్ధి లక్ష్యాలు (పుట 8)",["పంజాబ్ ధనిక రైతులు: పంటలకు అధిక మద్దతు ధర, చౌక కూలీలు, పిల్లలను విదేశాల్లో స్థిరపరచడం.","పట్టణ నిరుద్యోగ యువత: మంచి, స్థిరమైన ఉద్యోగం, నైపుణ్య శిక్షణ, గౌరవప్రదమైన జీతం.","ధనిక పట్టణ కుటుంబపు బాలుడు: ఉన్నత చదువులు (విదేశాల్లో), మంచి ఉద్యోగం / సొంత వ్యాపారం.","భూస్వామ్య కుటుంబపు గ్రామీణ మహిళ: తన పేరుతో భూమి, నిర్ణయాధికారం, పిల్లలకు మంచి విద్య, గౌరవం, స్వేచ్ఛ.","వర్షాధార రైతులు: సాగునీరు (బోరు/కాలువ), సకాలంలో వర్షం, చౌక రుణాలు, పంట బీమా, మంచి ధర.","నర్మదా లోయ ఆదివాసీ: తమ భూమి, అడవి నుండి నిర్వాసితులు కాకపోవడం, జీవనోపాధి రక్షణ, చిన్న చెక్‌డ్యామ్‌లు, బడి, ఆసుపత్రి."]],["ఇవి చేయండి 1 (Let’s work these out) (పుట 12)",["1) (b) జీవన పరిస్థితులు వేరుగా ఉండటం ముఖ్యమైన కారణం. మనుషుల అవసరాలు, ఆకాంక్షలు వారి పరిస్థితుల నుండే వస్తాయి – భూమిలేని కూలీకి ఎక్కువ పని దినాలు, మంచి కూలి కావాలి; ధనిక రైతుకు మంచి మద్దతు ధర కావాలి.","2) రెండూ ఒకటి కాదు. (a) వేర్వేరు లక్ష్యాలు – ఒకరి లక్ష్యం మరొకరికి నష్టం చేయకపోవచ్చు. (b) సంఘర్షించే లక్ష్యాలు – ఒకరి అభివృద్ధి మరొకరికి నష్టం: విద్యుత్ కోసం పారిశ్రామికవేత్తలు పెద్ద డ్యామ్ కోరితే గిరిజనులు నిర్వాసితులవుతారు; సోదరి స్వేచ్ఛ, ఇంటి పనిలో భాగం కోరితే సోదరుడికి నచ్చకపోవచ్చు.","3) స్నేహితులు, కుటుంబంతో గడిపే సమయం, ఉద్యోగ భద్రత, సురక్షిత పని వాతావరణం, సమాన గౌరవం, స్వేచ్ఛ, కాలుష్యం లేని పరిసరాలు, నేర్చుకునే అవకాశం.","4) వేర్వేరు వ్యక్తులకు వేర్వేరు అభివృద్ధి లక్ష్యాలుంటాయి; అవి కొన్నిసార్లు సంఘర్షిస్తాయి. అందరూ ఎక్కువ ఆదాయం కోరుకున్నా, ఆదాయంతో పాటు భద్రత, గౌరవం, స్వేచ్ఛ, సమానత్వం వంటి కొలవలేని అంశాలు కూడా జీవన నాణ్యతను నిర్ణయిస్తాయి."]],["ఇవి చేయండి 2 – చర్చించండి (పుట 14)",["1) (చిత్రంలోని పేద బస్తీ ప్రాంతం) అభివృద్ధి లక్ష్యాలు: సురక్షిత తాగునీరు, మురుగునీటి కాలువలు, పక్కా ఇళ్ళు, మరుగుదొడ్లు, పాఠశాల, ఆరోగ్య కేంద్రం, విద్యుత్, ఉపాధి.","2) (i) లాభపడినవారు: బహుళజాతి సంస్థ, స్థానిక కంపెనీ (విష వ్యర్థాలను చౌకగా వదిలించుకున్నారు). నష్టపోయినవారు: ఐవరీ కోస్ట్ అబిడ్జాన్ ప్రజలు – మరణాలు, వాంతులు, చర్మ వ్యాధులు. (ii) పర్యావరణ రక్షణ, ప్రజారోగ్యం, విష వ్యర్థాల దిగుమతిపై కఠిన చట్టాలు, వాటి అమలు.","3) మా గ్రామం (TV పల్లి) లక్ష్యాలు: మంచి రోడ్లు, డ్రైనేజీ, రక్షిత తాగునీరు, సాగునీరు, 24 గంటల విద్యుత్, ఉన్నత పాఠశాల/కళాశాల, ఆసుపత్రి, యువతకు ఉపాధి, బస్సు సౌకర్యం.","కృత్యం 1: ఉదాహరణ – పోలవరం / సర్దార్ సరోవర్ డ్యామ్: అనుకూలం – సాగునీరు, విద్యుత్, తాగునీరు; వ్యతిరేకం – గిరిజనుల నిర్వాసితం, అడవుల మునక. వార్తాపత్రికల నుండి రెండు వైపుల వాదనలు సేకరించండి."]],["ఇవి చేయండి 3 – సగటు ఆదాయం (పుట 18)",["పట్టిక 1.2: దేశం A సగటు = (9500 + 10500 + 9800 + 10000 + 10200) ÷ 5 = ₹10,000; దేశం B సగటు = (500 × 4 + 48000) ÷ 5 = ₹10,000. సగటు సమానమైనా, A లో ఆదాయ పంపిణీ సమంగా ఉంది కాబట్టి A మెరుగు.","1) తరగతి సగటు మార్కులు, బ్యాట్స్‌మన్ సగటు పరుగులు, ఒక ప్రాంత సగటు వర్షపాతం / ఉష్ణోగ్రత.","2) దేశాల జనాభా వేర్వేరు కాబట్టి మొత్తం ఆదాయం కాకుండా ఒక సగటు వ్యక్తి ఎంత సంపాదిస్తాడో తెలుసుకోవడానికి; ఎక్కువ ఆదాయం అంటే ప్రజలకు కావలసిన వస్తువులు ఎక్కువగా కొనగలరు.","3) ఆదాయం ప్రజల మధ్య ఎంత సమంగా పంపిణీ అయిందో (సమాన పంపిణీ) చూడాలి.","4) కాదు. ధనికుల ఆదాయం మాత్రమే పెరిగినా సగటు పెరుగుతుంది. ఉదా: దేశం B లో 5వ వ్యక్తి ఆదాయం ₹48,000 నుండి ₹98,000 అయితే సగటు ₹20,000 అవుతుంది, కానీ మిగతా నలుగురి ఆదాయం ₹500 గానే ఉంది.","5) ప్రపంచ అభివృద్ధి నివేదిక తక్కువ ఆదాయ దేశాలు (ఉదా.): అఫ్ఘానిస్తాన్, బురుండి, మధ్య ఆఫ్రికా రిపబ్లిక్, చాద్, కాంగో (DR), ఇథియోపియా, లైబీరియా, మడగాస్కర్, మలావి, మొజాంబిక్, నైజర్, సియెర్రా లియోన్, సోమాలియా, ఉగాండా, యెమెన్ – తాజా నివేదిక నుండి వాటి తలసరి ఆదాయం చూడండి.","6) భారత్ అభివృద్ధి చెందిన దేశం కావాలంటే: తలసరి ఆదాయం పెరగాలి, అది అందరికీ సమంగా అందాలి; అందరికీ నాణ్యమైన విద్య, ఆరోగ్యం, పోషకాహారం; యువతకు ఉపాధి; మహిళలకు సమాన అవకాశాలు, భద్రత; అవినీతి నిర్మూలన; పర్యావరణాన్ని కాపాడుతూ (సుస్థిరంగా) పరిశ్రమలు, వ్యవసాయం అభివృద్ధి కావాలి."]],["ఇవి చేయండి 4 – ప్రజా సౌకర్యాలు (పుట 24)",["1) లేదు. హర్యానా తలసరి ఆదాయంలో ముందున్నా, కేరళ అక్షరాస్యత (94% vs 82%), శిశు మరణాల రేటు (7 vs 30), హాజరు నిష్పత్తి (83 vs 61)లో ముందుంది.","2) వీధి దీపాలు, రోడ్లు, పోలీసు రక్షణ, రక్షిత మంచినీటి సరఫరా, ప్రజా రవాణా, చెత్త సేకరణ, పార్కులు, గ్రంథాలయం.","3) లేదు. ఖర్చుతో పాటు సరైన నిర్వహణ, నిజాయితీ గల అధికారులు, ఉపాధ్యాయులు/వైద్యుల హాజరు, ప్రజల అవగాహన–భాగస్వామ్యం, అందరికీ సమాన అందుబాటు కూడా ముఖ్యం.","4) తమిళనాడు ప్రజలు మెరుగు – 90% గ్రామీణ ప్రజలు రేషన్ దుకాణం వాడుతున్నారు కాబట్టి చౌకగా ఆహారధాన్యాలు అంది, పోషణ, ఆహార భద్రత బాగుంటాయి.","కృత్యం 2: (a) 76% (పురుషులు), 54% (స్త్రీలు); 10–14 ఏళ్ల పిల్లలు కూడా బడిలో లేరు. (b) 18% బాలికలు, 15% బాలురు బడికి వెళ్ళడం లేదు; 10–14 వయసులో నిరక్షరాస్యత స్త్రీలలో 13%, పురుషుల్లో 10%. (c) 10–14 సంవత్సరాల వయసు."]],["ఉదాహరణ 1 – భూగర్భ జలం (పుట 28)",["(a) బోరు బావులతో అధిక సాగు, ఉచిత విద్యుత్, వరి–చెరకు వంటి ఎక్కువ నీరు కావాల్సిన పంటలు, పట్టణాల పెరుగుదల, వర్షపు నీరు భూమిలో ఇంకకపోవడం.","(b) అవును – బిందు/తుంపర సేద్యం, వర్షపు నీటి సంరక్షణ, ఇంకుడు గుంతలు, చెక్‌డ్యామ్‌లు, పంటల మార్పిడి ద్వారా నీటిని అతిగా వాడకుండానే అభివృద్ధి సాధ్యం."]],["ఉదాహరణ 2 – ముడిచమురు (పుట 30)",["(a) అవును – రవాణా, పరిశ్రమలు, విద్యుత్, ఎరువులు, ప్లాస్టిక్ తయారీకి ముడిచమురు అవసరం. కానీ ప్రత్యామ్నాయ శక్తి వనరులు పెంచుకోవాలి.","(b) దిగుమతి ఖర్చు పెరగడం, విదేశీ మారకద్రవ్యం బయటకు పోవడం, ధరల పెరుగుదల (ద్రవ్యోల్బణం), ఇతర దేశాలపై ఆధారపడటం, యుద్ధాల సమయంలో సరఫరా ఆగిపోవడం."]],["అభ్యాసాలు – Exercises (1–9) (పుట 32)",["1) (iv) పైవన్నీ  2) (ii) శ్రీలంక  3) (iv) ₹6000 [5000 × 4 = 20000; 20000 − (4000 + 7000 + 3000) = 6000]","4) తలసరి ఆదాయం. పరిమితులు: ఆదాయ పంపిణీ (అసమానతలు) చూపదు; ఆరోగ్యం, విద్య, పర్యావరణం, భద్రత, స్వేచ్ఛ వంటి ఆదాయేతర అంశాలను లెక్కలోకి తీసుకోదు.","5) ప్రపంచ బ్యాంకు తలసరి ఆదాయం ఒక్కటే చూస్తుంది. UNDP ఆరోగ్యం (ఆయుర్దాయం), విద్య (పాఠశాల సంవత్సరాలు), తలసరి ఆదాయం – మూడింటినీ కలిపి మానవ అభివృద్ధి సూచిక (HDI) తయారు చేస్తుంది; ప్రజల శ్రేయస్సుకు ప్రాధాన్యం ఇస్తుంది.","6) జనాభా వేర్వేరు గల దేశాలు/ప్రాంతాలను పోల్చడానికి సగటులు వాడతాం. పరిమితి: అసమానతలను దాచుతాయి. ఉదా: ఒక తరగతి సగటు 60 మార్కులు అయినా కొందరు 95, కొందరు 20 తెచ్చుకోవచ్చు; దేశం B లో సగటు ₹10,000 అయినా నలుగురికి ₹500 మాత్రమే.","7) ఏకీభవించను. తలసరి ఆదాయం ఉపయోగకరమైన ప్రమాణమే కానీ సరిపోదు. దాంతో పాటు IMR, అక్షరాస్యత, ఆరోగ్యం, హాజరు వంటి సూచికలను కలిపి వాడాలి.","8) ప్రస్తుతం: బొగ్గు, ముడిచమురు, సహజ వాయువు, జల విద్యుత్, అణు విద్యుత్, వంటచెరకు, పిడకలు, సౌర, పవన విద్యుత్. 50 ఏళ్ల తర్వాత: సౌర, పవన, అలల, భూతాప, హైడ్రోజన్, జీవ ఇంధనాలు (బయోగ్యాస్), అణు శక్తి ఎక్కువగా వాడవచ్చు.","9) వనరులు పరిమితం; ఇప్పుడు అతిగా వాడితే భావితరాలకు మిగలవు (భూగర్భ జలం తగ్గడం, చమురు అయిపోవడం). పర్యావరణ క్షీణత దేశ సరిహద్దులు దాటి అందరినీ ప్రభావితం చేస్తుంది. కాబట్టి అభివృద్ధి కొనసాగాలంటే సుస్థిరత అవసరం."]],["అభ్యాసాలు – Exercises (10–13), ప్రాజెక్ట్ (పుట 34)",["10) గాంధీ మాట: భూమి వనరులు అందరి అవసరాలకు సరిపోతాయి, కానీ దురాశ (అతి వినియోగం, సంపద పోగు)కు సరిపోవు. అభివృద్ధి అంటే వనరులను అవసరం మేరకే, న్యాయంగా పంచుకుంటూ, భావితరాల కోసం కాపాడుతూ వాడటం – సుస్థిర అభివృద్ధి.","11) మా ప్రాంతం (గూడూరు, నెల్లూరు జిల్లా): రొయ్యల చెరువుల వల్ల భూమి–నీరు ఉప్పగా మారడం, నదుల్లో ఇసుక తవ్వకం, ప్లాస్టిక్ చెత్త, చెత్త కాల్చడం, వాహనాల పొగ, భూగర్భ జలాలు తగ్గడం, చెట్ల నరికివేత.","12) పట్టిక 1.6: తలసరి ఆదాయం – అగ్రం శ్రీలంక ($12,578), అట్టడుగు మయన్మార్ ($3,851); ఆయుర్దాయం – శ్రీలంక (76.4), మయన్మార్ (65.7); సగటు పాఠశాల సంవత్సరాలు – శ్రీలంక (10.8), పాకిస్తాన్ (4.5); HDI ర్యాంక్ – శ్రీలంక (73), పాకిస్తాన్ (161).","13) (i) పోషకాహార లోపం కేరళలో తక్కువ (పురుషులు 8.5%, స్త్రీలు 10%), మధ్యప్రదేశ్‌లో ఎక్కువ (28%, 28%); దేశమంతా పురుషులు 20%, స్త్రీలు 23%. (ii) దేశంలో ఆహారం ఉన్నా పేదరికం వల్ల కొనుగోలు శక్తి లేకపోవడం, ఆదాయ అసమానతలు, PDS సరిగా పనిచేయకపోవడం, అవగాహన లోపం, స్త్రీల పట్ల వివక్ష, అనారోగ్యం, పరిశుభ్రత లోపం కారణాలు.","ప్రాజెక్ట్: సర్పంచ్, వ్యవసాయ అధికారి, ఉపాధ్యాయుడు వంటి ముగ్గురిని మీ ప్రాంత అభివృద్ధిపై మాట్లాడమని ఆహ్వానించి, ప్రశ్నలు అడిగి, ఏకీభవించే / విభేదించే అంశాలతో గోడ పత్రిక తయారు చేయండి."]]]},{"id":"ec2","no":14,"t":"భారత ఆర్థిక వ్యవస్థలో రంగాలు (Sectors of the Indian Economy)","m":[8],"ty":"Economics – Chapter 2","by":"సాంఘిక శాస్త్రం – అర్థశాస్త్రం 10వ తరగతి (పుటలు 38–75)","th":"ప్రాథమిక, ద్వితీయ, తృతీయ రంగాలు; GDP; ప్రచ్ఛన్న నిరుద్యోగం; MGNREGA; వ్యవస్థీకృత–అవ్యవస్థీకృత; ప్రభుత్వ–ప్రైవేటు రంగాలు","sum":"ఆర్థిక కార్యకలాపాలను మూడు రంగాలుగా విభజిస్తారు (ప్రమాణం – కార్యకలాపం స్వభావం): ప్రాథమిక రంగం – సహజ వనరులను నేరుగా వాడి వస్తువుల ఉత్పత్తి (వ్యవసాయం, పాడి, చేపలు, అడవులు, గనులు) – వ్యవసాయ, అనుబంధ రంగం; ద్వితీయ రంగం – సహజ ఉత్పత్తులను తయారీ ద్వారా ఇతర రూపాల్లోకి మార్చడం (పత్తి → వస్త్రం, చెరకు → చక్కెర) – పారిశ్రామిక రంగం; తృతీయ రంగం – వస్తువులు కాకుండా సేవలు (రవాణా, నిల్వ, సమాచారం, బ్యాంకింగ్, వ్యాపారం, ఉపాధ్యాయులు, వైద్యులు, IT) – సేవా రంగం. మూడు రంగాలు పరస్పరం ఆధారపడతాయి. ఒక సంవత్సరంలో దేశంలో ఉత్పత్తి అయిన అంతిమ వస్తుసేవల విలువ = స్థూల దేశీయోత్పత్తి (GDP); మధ్యంతర వస్తువులను లెక్కిస్తే రెండుసార్లు లెక్కించినట్లవుతుంది. అభివృద్ధి చెందిన దేశాల్లో ప్రాథమిక → ద్వితీయ → తృతీయ రంగాల వైపు మార్పు జరిగింది. భారత్‌లో 1973–74 నుండి 2013–14 మధ్య ఉత్పత్తిలో తృతీయ రంగం అతి పెద్దదైంది (కారణాలు: ప్రాథమిక సేవలు, వ్యవసాయ–పరిశ్రమల అభివృద్ధి, ఆదాయాల పెరుగుదల, IT సేవలు); కానీ ఉపాధిలో ఇంకా ప్రాథమిక రంగమే పెద్దది (2017–18లో 44%) – ద్వితీయ, తృతీయ రంగాల్లో తగినన్ని ఉద్యోగాలు రాలేదు. వ్యవసాయంలో అవసరానికి మించి మనుషులు పనిచేయడం = ప్రచ్ఛన్న (కనిపించని) నిరుద్యోగం / అల్ప ఉద్యోగిత. ఉపాధి పెంచే మార్గాలు: సాగునీరు, గ్రామీణ రోడ్లు, నిల్వ, చౌక రుణాలు, గ్రామీణ పరిశ్రమలు (దాల్ మిల్, శీతల గిడ్డంగి), విద్య–ఆరోగ్యం, పర్యాటకం; MGNREGA 2005 – గ్రామీణ ప్రజలకు ఏడాదికి 100 రోజుల ఉపాధి హామీ (పని హక్కు). ఉపాధి పరిస్థితుల ఆధారంగా వ్యవస్థీకృత రంగం (నమోదు, నియమాలు, ఉద్యోగ భద్రత, వేతనంతో సెలవు, PF, పెన్షన్ – కాంతా) మరియు అవ్యవస్థీకృత రంగం (చిన్న, చెల్లాచెదురు యూనిట్లు, తక్కువ జీతం, భద్రత లేదు – కమల్). అవ్యవస్థీకృత కార్మికులకు రక్షణ అవసరం. యాజమాన్యం ఆధారంగా ప్రభుత్వ రంగం (రైల్వే, పోస్టాఫీసు – లాభం మాత్రమే లక్ష్యం కాదు) మరియు ప్రైవేటు రంగం (TISCO, RIL – లాభార్జనే లక్ష్యం).","pts":["ప్రాథమిక రంగం: సహజ వనరులను నేరుగా ఉపయోగించి ఉత్పత్తి – వ్యవసాయం, పాడి, చేపల వేట, అటవీ, గనులు.","ద్వితీయ రంగం: తయారీ ప్రక్రియ ద్వారా సహజ ఉత్పత్తులను ఇతర రూపాల్లోకి మార్చడం – పారిశ్రామిక రంగం.","తృతీయ రంగం: ఉత్పత్తికి తోడ్పడే సేవలు + ఆవశ్యక సేవలు – రవాణా, నిల్వ, సమాచారం, బ్యాంకింగ్, వ్యాపారం, విద్య, వైద్యం, IT.","అంతిమ వస్తువులు వినియోగదారుకు చేరేవి (బిస్కట్లు); మధ్యంతర వస్తువులు అంతిమ వస్తువుల తయారీలో వాడేవి (గోధుమ, పిండి).","GDP = ఒక సంవత్సరంలో దేశంలో ఉత్పత్తయిన అంతిమ వస్తుసేవల విలువ; భారత్‌లో కేంద్ర మంత్రిత్వ శాఖ లెక్కిస్తుంది.","1973–74లో ఉత్పత్తిలో అతిపెద్ద రంగం ప్రాథమిక రంగం; 2013–14లో తృతీయ రంగం.","ఉపాధి వాటా (గ్రాఫ్ 3): ప్రాథమిక 71% (1977–78) → 44% (2017–18); ద్వితీయ 11% → 25%; తృతీయ 18% → 31%.","పరిశ్రమల ఉత్పత్తి 9 రెట్లు పెరిగినా ఉపాధి 3 రెట్లే; సేవల ఉత్పత్తి 14 రెట్లు, ఉపాధి 5 రెట్లు.","ప్రచ్ఛన్న నిరుద్యోగం: అందరూ పనిచేస్తున్నట్లు కనిపించినా సామర్థ్యం కంటే తక్కువ పని (లక్ష్మి కుటుంబం – 5 మంది 2 హెక్టార్లలో).","MGNREGA 2005: పని కావాలనుకునే గ్రామీణులకు ఏడాదికి 100 రోజుల ఉపాధి హామీ; ఇవ్వలేకపోతే నిరుద్యోగ భృతి – “పని హక్కు”.","వ్యవస్థీకృత రంగం: ప్రభుత్వ నమోదు, Factories Act, Minimum Wages Act వంటి చట్టాలు; ఉద్యోగ భద్రత, నిర్ణీత పని గంటలు, ఓవర్‌టైమ్, PF, గ్రాట్యుటీ, పెన్షన్.","అవ్యవస్థీకృత రంగం: చిన్న, చెల్లాచెదురు యూనిట్లు; నియమాలు పాటించరు; తక్కువ, అక్రమ జీతాలు; సెలవులు, భద్రత లేవు.","గ్రామీణ అవ్యవస్థీకృత: భూమిలేని కూలీలు, చిన్న–సన్నకారు రైతులు, కౌలుదారులు, చేతివృత్తులవారు; సుమారు 80% గ్రామీణ కుటుంబాలు చిన్న–సన్నకారు రైతులు.","ప్రభుత్వ రంగం: ఆస్తులు ప్రభుత్వానివి (రైల్వే, పోస్టాఫీసు); ప్రైవేటు రంగం: వ్యక్తులు/కంపెనీలవి (TISCO, RIL) – లాభార్జన లక్ష్యం.","ప్రభుత్వం ఖర్చు చేసేవి: రోడ్లు, వంతెనలు, రైల్వేలు, ఓడరేవులు, విద్యుత్, డ్యామ్‌లు; చౌక విద్యుత్; విద్య, ఆరోగ్యం; కనీస మద్దతు ధరతో కొని రేషన్ ద్వారా చౌకగా అమ్మడం."],"w":[["ప్రాథమిక రంగం","Primary sector"],["ద్వితీయ రంగం","Secondary sector"],["తృతీయ / సేవా రంగం","Tertiary / Service sector"],["స్థూల దేశీయోత్పత్తి","Gross Domestic Product (GDP)"],["అంతిమ వస్తువులు","Final goods"],["మధ్యంతర వస్తువులు","Intermediate goods"],["ప్రచ్ఛన్న నిరుద్యోగం","Disguised unemployment"],["అల్ప ఉద్యోగిత","Underemployment"],["బహిరంగ నిరుద్యోగం","Open unemployment"],["వ్యవస్థీకృత రంగం","Organised sector"],["అవ్యవస్థీకృత రంగం","Unorganised sector"],["ప్రభుత్వ రంగం","Public sector"],["ప్రైవేటు రంగం","Private sector"],["పరస్పర ఆధారితం","Interdependent"],["భవిష్య నిధి","Provident fund"],["జాతీయ గ్రామీణ ఉపాధి హామీ చట్టం","MGNREGA 2005"]],"gr":{"t":"ముఖ్య గణాంకాలు & సూత్రాలు","p":["GDP = ప్రాథమిక + ద్వితీయ + తృతీయ రంగాల అంతిమ వస్తుసేవల విలువ","జోడించిన విలువ (value added): గోధుమ ₹20 → పిండి ₹25 (+5) → బిస్కట్లు ₹80 (+55); మొత్తం = ₹80 = అంతిమ వస్తువు విలువ","GDP వాటా: ప్రాథమిక ~40% (1973–74) → ~13% (2013–14); తృతీయ రంగం 2013–14లో 60–70%","ఉపాధి వాటా 2017–18: ప్రాథమిక 44%, ద్వితీయ 25%, తృతీయ 31%","పట్టిక 2.3 (మిలియన్లు): వ్యవస్థీకృత 82, అవ్యవస్థీకృత 393, మొత్తం 475 → అవ్యవస్థీకృతం ≈ 83%","రంగాల విభజన ప్రమాణాలు: కార్యకలాపం స్వభావం (ప్రా/ద్వి/తృ), ఉపాధి పరిస్థితులు (వ్యవస్థీకృత/అవ్యవస్థీకృత), యాజమాన్యం (ప్రభుత్వ/ప్రైవేటు)"]},"qa":[["ప్రాథమిక రంగాన్ని “ప్రాథమిక” అని ఎందుకు అంటారు?","మనం తర్వాత తయారుచేసే అన్ని వస్తువులకు ఇదే పునాది (ఆధారం) కాబట్టి."],["GDP అంటే ఏమిటి?","ఒక నిర్దిష్ట సంవత్సరంలో దేశంలో ఉత్పత్తి అయిన అంతిమ వస్తుసేవల మొత్తం విలువ."],["GDP లో అంతిమ వస్తువులనే ఎందుకు లెక్కిస్తారు?","అంతిమ వస్తువు విలువలో మధ్యంతర వస్తువుల విలువ ఇప్పటికే ఉంటుంది; వేరుగా లెక్కిస్తే ఒకే దాన్ని పలుమార్లు లెక్కించినట్లవుతుంది."],["ప్రచ్ఛన్న నిరుద్యోగం అంటే?","అవసరానికి మించి ఎక్కువ మంది ఒకే పనిలో ఉండటం – కొందరిని తొలగించినా ఉత్పత్తి తగ్గదు; అందరూ సామర్థ్యం కంటే తక్కువ పనిచేస్తారు."],["MGNREGA 2005 ఏమి హామీ ఇస్తుంది?","పని కావాలనుకునే గ్రామీణ ప్రజలకు ఏడాదికి 100 రోజుల ఉపాధి; ఇవ్వలేకపోతే నిరుద్యోగ భృతి."],["వ్యవస్థీకృత రంగ కార్మికులకు లభించే ప్రయోజనాలు?","ఉద్యోగ భద్రత, నిర్ణీత పని గంటలు, ఓవర్‌టైమ్ వేతనం, వేతనంతో సెలవు, PF, గ్రాట్యుటీ, వైద్య సౌకర్యం, పెన్షన్."],["ప్రభుత్వ, ప్రైవేటు రంగాల మధ్య భేదానికి ప్రమాణం?","ఆస్తుల యాజమాన్యం, సేవలు అందించే బాధ్యత ఎవరిది అనేది."],["భారత్‌లో తృతీయ రంగం ప్రాముఖ్యత పెరగడానికి కారణాలు?","ప్రాథమిక సేవల అవసరం, వ్యవసాయ–పరిశ్రమల అభివృద్ధి, ఆదాయాల పెరుగుదలతో సేవల డిమాండ్, IT సేవల వృద్ధి."],["ఉపాధిలో ప్రాథమిక రంగం నుండి మార్పు ఎందుకు జరగలేదు?","ద్వితీయ, తృతీయ రంగాల్లో తగినన్ని ఉద్యోగాలు సృష్టి కాలేదు."],["ప్రభుత్వ రంగం చేపట్టే రెండు కార్యకలాపాలు?","రోడ్లు, వంతెనలు, రైల్వేలు, విద్యుత్, డ్యామ్‌లు; విద్య, ఆరోగ్యం; రేషన్ ద్వారా చౌక ధాన్యం."]],"act":"మీ చుట్టూ ఉన్న 20 మంది పెద్దల వృత్తులను జాబితా చేసి – (1) ప్రాథమిక / ద్వితీయ / తృతీయ, (2) వ్యవస్థీకృత / అవ్యవస్థీకృత, (3) ప్రభుత్వ / ప్రైవేటు – మూడు రకాలుగా వర్గీకరించి పట్టిక చేయండి. ఒక కూలీ, ఒక ప్రభుత్వ ఉద్యోగిని కలిసి పని పరిస్థితులు పోల్చండి.","kn":"MGNREGA ప్రపంచంలోనే అతిపెద్ద ఉపాధి హామీ పథకాలలో ఒకటి – 2006 ఫిబ్రవరి 2న ఆంధ్రప్రదేశ్‌లోని అనంతపురం జిల్లా బండ్లపల్లి నుండి ప్రారంభమైంది!","qz":[["ప్రభుత్వ, ప్రైవేటు రంగాలుగా విభజనకు ఆధారం?","సంస్థల యాజమాన్యం","ఉపాధి పరిస్థితులు","కార్యకలాపం స్వభావం","కార్మికుల సంఖ్య"],["సహజ ప్రక్రియ ద్వారా వస్తువు ఉత్పత్తి ఏ రంగం?","ప్రాథమిక","ద్వితీయ","తృతీయ","సమాచార సాంకేతిక"],["GDP అనేది ఒక సంవత్సరంలో ఉత్పత్తి అయిన ____ విలువ.","అంతిమ వస్తుసేవల","అన్ని వస్తుసేవల","మధ్యంతర వస్తుసేవల","మధ్యంతర, అంతిమ వస్తుసేవల"],["2013–14లో GDP లో తృతీయ రంగం వాటా (గ్రాఫ్ ప్రకారం)?","60 – 70 శాతం","20 – 30 శాతం","30 – 40 శాతం","50 – 60 శాతం"],["అల్ప ఉద్యోగిత (underemployment) అంటే ప్రజలు?","సామర్థ్యం కంటే తక్కువ పని చేయడం","పని చేయడానికి ఇష్టపడకపోవడం","సోమరితనంతో పనిచేయడం","పనికి జీతం రాకపోవడం"],["పత్తి ____ ఉత్పత్తి, వస్త్రం ____ ఉత్పత్తి.","సహజ, తయారీ","తయారీ, సహజ","సహజ, సహజ","తయారీ, తయారీ"],["ప్రాథమిక, ద్వితీయ, తృతీయ రంగాల కార్యకలాపాలు?","పరస్పర ఆధారితాలు","స్వతంత్రాలు","సంబంధం లేనివి","వ్యతిరేకమైనవి"],["ఎక్కువ మంది కార్మికులకు ఉద్యోగ భద్రత ఉండే రంగం?","వ్యవస్థీకృత","అవ్యవస్థీకృత","ప్రాథమిక","ప్రైవేటు అవ్యవస్థీకృత"],["MGNREGA కింద ఏడాదికి హామీ ఇచ్చే పని దినాలు?","100","200","150","365"],["కిందివాటిలో తృతీయ రంగ వృత్తి?","కాల్ సెంటర్ ఉద్యోగి","కుమ్మరి","తేనెటీగల పెంపకందారు","బుట్టలు అల్లేవాడు"],["1973–74లో అతిపెద్ద ఉత్పత్తి రంగం?","ప్రాథమిక","ద్వితీయ","తృతీయ","ప్రభుత్వ"],["2017–18లో ఉపాధిలో అతిపెద్ద రంగం?","ప్రాథమిక","తృతీయ","ద్వితీయ","వ్యవస్థీకృత"],["కిందివాటిలో మధ్యంతర వస్తువు (బిస్కట్ తయారీలో)?","గోధుమ పిండి","బిస్కట్ ప్యాకెట్","టీవీ","కారు"],["అవ్యవస్థీకృత రంగ కార్యకలాపం?","కాంట్రాక్టర్ కింద రోజు కూలీ","పాఠశాలలో ఉపాధ్యాయుడు","ఆసుపత్రిలో వైద్యుడు","పెద్ద కర్మాగార కార్మికుడు"],["ప్రభుత్వ రంగ సంస్థకు ఉదాహరణ?","భారతీయ రైల్వే","రిలయన్స్ ఇండస్ట్రీస్","TISCO","జెట్ ఎయిర్‌వేస్"],["ఉపాధి పరిస్థితుల ఆధారంగా రంగాల విభజన?","వ్యవస్థీకృత, అవ్యవస్థీకృత","ప్రభుత్వ, ప్రైవేటు","ప్రాథమిక, ద్వితీయ","గ్రామీణ, పట్టణ"]],"wb":{"mis":"తృతీయ రంగం GDP లో పెద్దదైంది కాబట్టి ఎక్కువ మంది దానిలోనే పనిచేస్తున్నారనుకోవడం తప్పు – ఉపాధిలో ఇంకా ప్రాథమిక రంగమే పెద్దది. GDP లో మధ్యంతర వస్తువులు వేరుగా లెక్కించరు. “ప్రైవేటు = అవ్యవస్థీకృతం” కాదు – పెద్ద ప్రైవేటు కంపెనీలు వ్యవస్థీకృత రంగమే.","qz":[],"pg":"38–75","f":"books/10/Class10_Social_Economics_Textbook.pdf","p":44,"lb":"పాఠ్యపుస్తకం","ws":["ఇవి చేయండి 1 – రంగాలు (పుట 42)","ఇవి చేయండి 2 – రంగాల మార్పు, GDP (పుట 46)","ఇవి చేయండి 3 – గ్రాఫ్ 1 (పుట 48)","ఇవి చేయండి 4 – ప్రాథమిక రంగం, అల్ప ఉద్యోగిత (పుట 54)","ఇవి చేయండి 5 – ఉపాధి కల్పన, MGNREGA (పుట 58)","ఇవి చేయండి 6 – వ్యవస్థీకృత / అవ్యవస్థీకృత (పుట 62)","గుర్తుచేసుకుందాం – పట్టిక 2.4 (పుట 66)","అభ్యాసాలు – Exercises (1, 2) (పుట 70)","అభ్యాసాలు – Exercises (3–12) (పుట 72)","అభ్యాసాలు – Exercises (13–24) (పుట 74)"]},"tg":[["ఇవి చేయండి 1 – రంగాలు (పుట 42)",["1) పట్టిక: (1) చక్కెర మిల్లు – ద్వితీయ రంగం ప్రాథమిక రంగంపై ఆధారపడుతుంది. (2) కంపెనీలు పత్తి దిగుమతి చేస్తే – ప్రాథమిక రంగం (పత్తి రైతులు) ద్వితీయ రంగం (వస్త్ర పరిశ్రమ)పై ఆధారపడుతుంది. (3) ఎరువులు, పంపుసెట్ల ధర పెరిగితే – ప్రాథమిక రంగం ద్వితీయ రంగంపై ఆధారపడుతుంది. (4) రవాణా సమ్మె – ప్రాథమిక, ద్వితీయ రంగాలు తృతీయ రంగం (రవాణా)పై; పరిశ్రమ–సేవా కార్మికులు ఆహారం కోసం ప్రాథమిక రంగంపై ఆధారపడతారు.","2) ప్రాథమిక: చేపలు పట్టడం, ఇనుప ఖనిజం తవ్వడం, మామిడి తోట. ద్వితీయ: కలపతో కుర్చీలు, ఇనుముతో ఉక్కు, పాలతో వెన్న–జున్ను తయారీ. తృతీయ: బస్సు డ్రైవర్, బ్యాంకు ఉద్యోగి, ఉపాధ్యాయుడు, మొబైల్ రిపేర్.","3) ప్రాథమిక: తోటమాలి, పూల సాగుదారు, తేనెటీగల పెంపకందారు, మత్స్యకారులు. ద్వితీయ: అగ్గిపెట్టెల కర్మాగార కార్మికులు, దర్జీ, బుట్టలు అల్లేవారు, కుమ్మరి. తృతీయ: వడ్డీ వ్యాపారి, పాల విక్రేత, వ్యోమగామి, పూజారి, కాల్ సెంటర్ ఉద్యోగి, కొరియర్.","4) ప్రమాణం – వయసు / చదువుతున్న తరగతి స్థాయి. ఇది ఉపయోగకరమే – పాఠ్యప్రణాళిక, ఉపాధ్యాయుల నియామకం, తరగతుల నిర్వహణ సులభం. కానీ విద్యార్థుల ప్రతిభ, ఆసక్తులు దీనితో తెలియవు."]],["ఇవి చేయండి 2 – రంగాల మార్పు, GDP (పుట 46)",["1) ప్రారంభ దశలో ప్రాథమిక రంగం అత్యంత ముఖ్యం; కొత్త తయారీ పద్ధతులు, కర్మాగారాలతో ద్వితీయ రంగం ఉత్పత్తి–ఉపాధిలో ముఖ్యమైంది; గత 100 ఏళ్లలో ద్వితీయ నుండి తృతీయ రంగానికి మార్పు – ఇప్పుడు సేవా రంగమే ఉత్పత్తి, ఉపాధిలో అతిపెద్దది.","2) సరిచేసిన రూపం: వస్తుసేవలను లెక్కించడానికి వాటి సంఖ్యలను కాకుండా విలువలను కలుపుతాం. ఒక నిర్దిష్ట సంవత్సరంలో (ఐదేళ్లలో కాదు) ఉత్పత్తి అయినవే లెక్కిస్తాం. అన్నింటినీ కాకుండా అంతిమ వస్తుసేవలను మాత్రమే కలుపుతాం (మధ్యంతర వస్తువులను కలిపితే రెండుసార్లు లెక్కించినట్లవుతుంది).","3) ప్రతి దశలో జోడించిన విలువ: రైతు గోధుమ ₹20 (జోడించిన విలువ ₹20), మిల్లు పిండి ₹25 (₹5), బిస్కట్ కంపెనీ ₹80 (₹55). మొత్తం జోడించిన విలువ = 20 + 5 + 55 = ₹80 = అంతిమ వస్తువు విలువ."]],["ఇవి చేయండి 3 – గ్రాఫ్ 1 (పుట 48)",["1) 1973–74లో ప్రాథమిక రంగం.  2) 2013–14లో తృతీయ రంగం.  3) తృతీయ రంగం అత్యధికంగా పెరిగింది.","4) 2013–14లో GDP సుమారు ₹56 లక్షల కోట్లు (గ్రాఫ్‌లో ₹55,00,000 – ₹56,00,000 కోట్ల మధ్య).","పోలిక: 40 ఏళ్లలో మూడు రంగాల ఉత్పత్తి పెరిగింది, కానీ తృతీయ రంగం అత్యధికంగా పెరిగి ప్రాథమిక రంగం స్థానాన్ని ఆక్రమించింది."]],["ఇవి చేయండి 4 – ప్రాథమిక రంగం, అల్ప ఉద్యోగిత (పుట 54)",["1) పట్టిక 2.2: GDP వాటా – 1973–74 సుమారు 40%, 2013–14 సుమారు 13%; ఉపాధి వాటా – 1977–78: 71%, 2017–18: 44%. మార్పు: GDP లో ప్రాథమిక రంగ వాటా బాగా తగ్గింది, కానీ ఉపాధిలో అంతగా తగ్గలేదు – ఇప్పటికీ అతిపెద్ద ఉపాధి రంగం.","2) (iii) సామర్థ్యం కంటే తక్కువ పని చేస్తున్నప్పుడు.","3) అభివృద్ధి చెందిన దేశాల్లో ఉత్పత్తి, ఉపాధి రెండింటిలోనూ ప్రాథమిక → ద్వితీయ → తృతీయ మార్పు జరిగింది. భారత్‌లో ఉత్పత్తిలో తృతీయ రంగం పెద్దదైనా, ఉపాధి ఇంకా ప్రాథమిక రంగంలోనే. కార్మికులు వ్యవసాయం నుండి పరిశ్రమలు, సేవలకు మారాల్సింది – అది జరగలేదు.","4) అల్ప ఉద్యోగిత వల్ల శ్రమ వృథా, తక్కువ ఆదాయం, పేదరికం, తక్కువ ఉత్పాదకత; కుటుంబాల జీవన ప్రమాణం పెరగదు; దేశ అభివృద్ధి నెమ్మదిస్తుంది."]],["ఇవి చేయండి 5 – ఉపాధి కల్పన, MGNREGA (పుట 58)",["1) చట్టం ద్వారా పని కోరిన ప్రతి గ్రామీణ వ్యక్తికి ఏడాదికి 100 రోజుల పని హామీ; ప్రభుత్వం పని ఇవ్వలేకపోతే నిరుద్యోగ భృతి చెల్లించాలి – కాబట్టి ఇది “పని హక్కు”.","2) సర్పంచ్‌గా సూచనలు: చెరువుల పూడికతీత, చెక్‌డ్యామ్‌లు, కాలువలు, ఇంకుడు గుంతలు, గ్రామీణ రోడ్లు, మొక్కలు నాటడం, భూమి చదును, ఉద్యాన తోటలు, భూసార సంరక్షణ – ఇవి భూమి ఉత్పాదకతను, ఆదాయాన్ని పెంచుతాయి.","3) సాగునీరు ఉంటే రెండో పంట (రబీ) వేయవచ్చు – ఎక్కువ పని దినాలు, ఎక్కువ ఉత్పత్తి. మార్కెటింగ్, రోడ్లు, నిల్వ సౌకర్యాలు ఉంటే మంచి ధర వస్తుంది; రవాణా, వ్యాపారం, ఆగ్రో పరిశ్రమల్లో కొత్త ఉద్యోగాలు వస్తాయి.","4) పట్టణాల్లో: చిన్న తరహా పరిశ్రమలు, స్వయం ఉపాధికి బ్యాంకు రుణాలు, నైపుణ్య శిక్షణ, IT సేవలు, పర్యాటకం, నిర్మాణ రంగం, ఆసుపత్రులు–పాఠశాలలు, ప్రజా రవాణా విస్తరణ."]],["ఇవి చేయండి 6 – వ్యవస్థీకృత / అవ్యవస్థీకృత (పుట 62)",["1) అవ్యవస్థీకృత రంగం: (ii) సిమెంట్ బస్తా మోసే హమాలీ, (iii) పొలానికి నీరు పెట్టే రైతు, (v) కాంట్రాక్టర్ కింద రోజు కూలీ, (vii) ఇంట్లో చేనేత కార్మికురాలు.","2) పోలిక: వ్యవస్థీకృత ఉద్యోగి (ఉదా: ఉపాధ్యాయుడు) – నెల జీతం, నిర్ణీత గంటలు, సెలవులు, PF, పెన్షన్, భద్రత. అవ్యవస్థీకృత కార్మికుడు (ఉదా: షాపు కూలీ) – రోజు కూలి, ఎక్కువ గంటలు, సెలవుకు జీతం లేదు, ఏ క్షణమైనా తొలగించవచ్చు.","3) వ్యవస్థీకృత రంగం – ప్రభుత్వం వద్ద నమోదైన, చట్టాలు పాటించే, క్రమమైన ఉపాధి గల సంస్థలు. అవ్యవస్థీకృత రంగం – నమోదు కాని చిన్న, చెల్లాచెదురు యూనిట్లు; నియమాలు అమలుకావు; ఉపాధి అస్థిరం.","4) పట్టిక 2.3: ప్రాథమిక – వ్యవస్థీకృత 1, అవ్యవస్థీకృత 231, మొత్తం 232; ద్వితీయ – 41, 74, 115; తృతీయ – 40, 88, 128; మొత్తం – 82, 393, 475; శాతం – 17%, 83%, 100%.","వ్యవసాయంలో అవ్యవస్థీకృతం = 231 ÷ 232 ≈ 99.6%. అవును – వ్యవసాయం దాదాపు పూర్తిగా అవ్యవస్థీకృత కార్యకలాపం; రైతులు సొంతంగా పనిచేస్తారు, కూలీలను అవసరమైనప్పుడే పెట్టుకుంటారు. దేశంలో సుమారు 83% కార్మికులు అవ్యవస్థీకృత రంగంలో; వ్యవస్థీకృత రంగ ఉపాధి సుమారు 17% మందికే."]],["గుర్తుచేసుకుందాం – పట్టిక 2.4 (పుట 66)",["ప్రాథమిక/ద్వితీయ/తృతీయ: ప్రమాణం – కార్యకలాపం స్వభావం; ముఖ్య నిర్ధారణ – GDP లో తృతీయ రంగం పెద్దది, ఉపాధి ప్రాథమిక రంగంలో; సమస్య – అల్ప/ప్రచ్ఛన్న నిరుద్యోగం; పరిష్కారం – సాగునీరు, రుణాలు, గ్రామీణ పరిశ్రమలు, MGNREGA, విద్య–ఆరోగ్య–పర్యాటక ఉద్యోగాలు.","వ్యవస్థీకృత/అవ్యవస్థీకృత: ప్రమాణం – ఉపాధి పరిస్థితులు; ముఖ్య నిర్ధారణ – ఎక్కువ మంది అవ్యవస్థీకృత రంగంలో; సమస్య – తక్కువ జీతం, భద్రత లేకపోవడం, దోపిడీ; పరిష్కారం – చట్టాల అమలు, కనీస వేతనం, సామాజిక భద్రత, చిన్న పరిశ్రమలకు ప్రభుత్వ మద్దతు."]],["అభ్యాసాలు – Exercises (1, 2) (పుట 70)",["1) (i) has not (ii) తృతీయ (iii) వ్యవస్థీకృత (iv) పెద్ద (large) (v) సహజ, తయారీ (natural, manufactured) (vi) పరస్పర ఆధారితం (interdependent)","2) (a) (iii) సంస్థల యాజమాన్యం (b) (i) ప్రాథమిక (c) (ii) అన్ని అంతిమ వస్తుసేవలు (d) (iv) 60 – 70 శాతం (గ్రాఫ్ 2 ప్రకారం సుమారు 67%)"]],["అభ్యాసాలు – Exercises (3–12) (పుట 72)",["3) 1 – (d) కాలువల నిర్మాణం; 2 – (c) ప్రభుత్వం ధాన్యం సేకరణ; 3 – (e) తక్కువ వడ్డీకి బ్యాంకు రుణాలు; 4 – (a) ఆగ్రో మిల్లుల ఏర్పాటు; 5 – (b) సహకార మార్కెటింగ్ సంఘాలు.","4) (i) కుమ్మరి – వస్తువు తయారుచేస్తాడు (ద్వితీయ); మిగతావారు సేవలు అందిస్తారు. (ii) కూరగాయల విక్రేత – మిగతావారు వృత్తి విద్య అవసరమైన నిపుణులు. (iii) చెప్పులు కుట్టేవాడు – మిగతావారు ప్రభుత్వ ఉద్యోగులు. (iv) జెట్ ఎయిర్‌వేస్ – ప్రైవేటు సంస్థ; మిగతావి ప్రభుత్వ రంగం.","5) సూరత్: వ్యవస్థీకృత – కార్యాలయాలు/కర్మాగారాలు 15% + లైసెన్సు గల దుకాణాలు/క్లినిక్‌లు 20% = 35%; అవ్యవస్థీకృత – చిన్న వర్క్‌షాపులు 15% + వీధి, నిర్మాణ, ఇంటి పనివారు 50% = 65%. అవ్యవస్థీకృత రంగంలో 65% కార్మికులు.","6) అవును – ప్రతి రంగం ఉత్పత్తి, ఉపాధి ఎంత అని విశ్లేషించడానికి, అభివృద్ధి క్రమాన్ని పోల్చడానికి, సమస్యలు (అల్ప ఉద్యోగిత) గుర్తించి విధానాలు రూపొందించడానికి ఉపయోగపడుతుంది.","7) GDP రంగం ఎంత ఉత్పత్తి చేస్తుందో, ఉపాధి ఎంత మందికి జీవనోపాధి ఇస్తుందో చెబుతాయి. ఇంకా పరిశీలించాల్సినవి: ఉద్యోగ భద్రత, వేతనాలు, పని పరిస్థితులు, ఆదాయ అసమానతలు, పర్యావరణ ప్రభావం, మహిళల భాగస్వామ్యం, ప్రాంతీయ సమతుల్యత.","8) ఉదా: రైతు, కూలీ, దర్జీ, ఉపాధ్యాయుడు, డ్రైవర్, దుకాణదారు, నర్సు, మేస్త్రి, పాల వ్యాపారి – (కార్యకలాపం స్వభావం ప్రకారం) ప్రాథమిక/ద్వితీయ/తృతీయ; (ఉపాధి పరిస్థితులు) వ్యవస్థీకృత/అవ్యవస్థీకృత; (యాజమాన్యం) ప్రభుత్వ/ప్రైవేటు.","9) తృతీయ రంగం వస్తువులను ఉత్పత్తి చేయదు, సేవలు అందిస్తుంది; ఇతర రంగాల అభివృద్ధికి తోడ్పడుతుంది. ఉదా: పంటను లారీ రవాణా, గిడ్డంగి నిల్వ, బ్యాంకు రుణం, ఫోన్ సమాచారం; ఉపాధ్యాయుడు, వైద్యుడు, IT ఉద్యోగి.","10) పనిచేస్తున్నట్లు కనిపించినా సామర్థ్యం మేరకు పని లేకపోవడం. గ్రామీణ: 5 మంది కుటుంబ సభ్యులు 2 హెక్టార్ల చిన్న పొలంలో పనిచేయడం – ఇద్దరు వెళ్ళిపోయినా ఉత్పత్తి తగ్గదు. పట్టణ: పెయింటర్లు, ప్లంబర్లు, వీధి వ్యాపారులు రోజంతా తిరిగినా తక్కువ పని, తక్కువ సంపాదన.","11) బహిరంగ నిరుద్యోగం – పని చేయాలని ఉన్నా పని దొరకక స్పష్టంగా కనిపించే నిరుద్యోగం (ఉదా: పరిశ్రమ మూతపడి ఖాళీగా ఉన్న కార్మికుడు). ప్రచ్ఛన్న నిరుద్యోగం – పనిచేస్తున్నట్లు కనిపించినా అవసరానికి మించి ఉండటం; దాగి ఉంటుంది (ఎక్కువగా వ్యవసాయంలో).","12) ఏకీభవించను. తృతీయ రంగం GDP లో అతిపెద్ద వాటా (60% పైగా) ఇస్తోంది, వేగంగా పెరుగుతోంది; రవాణా, బ్యాంకింగ్, సమాచారం ద్వారా వ్యవసాయ–పరిశ్రమలకు తోడ్పడుతుంది; విద్య, ఆరోగ్యం, IT ఎగుమతుల ద్వారా అభివృద్ధికి ముఖ్యం. అయితే ఉపాధి అంతగా పెరగలేదు."]],["అభ్యాసాలు – Exercises (13–24) (పుట 74)",["13) (1) అత్యంత నైపుణ్యం, విద్య గల కొద్దిమంది (బ్యాంకు, IT, వైద్యులు); (2) చాలా ఎక్కువ మంది చిన్న దుకాణదారులు, మరమ్మతు చేసేవారు, రవాణా కార్మికులు – వేరే అవకాశాలు లేక అతి తక్కువ సంపాదనతో.","14) అవును. తక్కువ, అక్రమ వేతనాలు; ఓవర్‌టైమ్, వేతనంతో సెలవు, వైద్య సౌకర్యం లేవు; ఉద్యోగ భద్రత లేదు – కారణం లేకుండా తొలగిస్తారు; చట్టాలు అమలుకావు; SC/ST/BC కార్మికులు సామాజిక వివక్ష కూడా ఎదుర్కొంటారు.","15) వ్యవస్థీకృత రంగం, అవ్యవస్థీకృత రంగం.","16) వ్యవస్థీకృతం: నమోదు, నియామక పత్రం, నిర్ణీత గంటలు, ఓవర్‌టైమ్, సెలవులు, PF, గ్రాట్యుటీ, పెన్షన్, సురక్షిత వాతావరణం. అవ్యవస్థీకృతం: నమోదు లేదు, తక్కువ కూలి, ఎక్కువ గంటలు, సెలవులు–భద్రత లేవు, యజమాని ఇష్టానుసారం.","17) NREGA 2005 లక్ష్యం: గ్రామీణ ప్రాంతాల్లో పని కావాలనుకునే ప్రతి కుటుంబానికి ఏడాదికి 100 రోజుల ఉపాధి; నిరుద్యోగం, పేదరికం తగ్గించడం; భూమి ఉత్పాదకత పెంచే పనులు (నీటి సంరక్షణ, రోడ్లు); పని ఇవ్వలేకపోతే భృతి.","18) ప్రభుత్వ రంగం (ZPHS పాఠశాల, PHC, APSRTC, పోస్టాఫీసు) – సేవే లక్ష్యం, తక్కువ రుసుము, అందరికీ. ప్రైవేటు రంగం (ప్రైవేటు స్కూలు, ఆసుపత్రి, బస్సులు) – లాభమే లక్ష్యం, ఎక్కువ రుసుము.","19) ఉదా: ప్రభుత్వ – బాగా నిర్వహించేది: పోస్టాఫీసు / ఇండియన్ రైల్వే; సరిగా లేనిది: కొన్ని ప్రభుత్వ ఆసుపత్రులు. ప్రైవేటు – బాగా: పెద్ద బ్యాంకు/ఆసుపత్రి; సరిగా లేనిది: కొన్ని ప్రైవేటు బస్సు సర్వీసులు. (మీ ప్రాంత ఉదాహరణలు రాయండి)","20) రైల్వేలు, రోడ్లు, విద్యుత్, డ్యామ్‌లు (భారీ పెట్టుబడి – ప్రైవేటు రంగం చేయలేదు/ఎక్కువ ధర వసూలు చేస్తుంది), పాఠశాలలు–ఆసుపత్రులు (అందరికీ అందాలి), రేషన్ దుకాణాలు (రైతులకు మద్దతు, పేదలకు చౌక ధాన్యం).","21) మౌలిక సదుపాయాలు (రోడ్లు, విద్యుత్, రైల్వే) కల్పన, ఉపాధి సృష్టి, చిన్న పరిశ్రమలకు చౌక విద్యుత్, విద్య–ఆరోగ్యం ద్వారా మానవ వనరుల అభివృద్ధి, వెనుకబడిన ప్రాంతాల అభివృద్ధి, ఆహార భద్రత, ఆదాయ అసమానతల తగ్గింపు.","22) వేతనాలు: కనీస వేతన చట్టం అమలు, సమయానికి చెల్లింపు (ఉదా: నిర్మాణ కూలీలకు తక్కువ కూలి). భద్రత: హెల్మెట్, సురక్షిత పని పరిస్థితులు (బాణసంచా, నిర్మాణ పనుల్లో ప్రమాదాలు). ఆరోగ్యం: వైద్య సౌకర్యం, బీమా, సెలవులు (రసాయనాలతో పనిచేసేవారు).","23) పట్టిక – అహ్మదాబాద్ (1997–98): వ్యవస్థీకృత – కార్మికులు 4,00,000, ఆదాయం ₹32,000 మిలియన్లు; అవ్యవస్థీకృత – 11,00,000, ₹28,000 మిలియన్లు; మొత్తం – 15,00,000, ₹60,000 మిలియన్లు. 73% కార్మికులు అవ్యవస్థీకృత రంగంలో ఉన్నా ఆదాయంలో వాటా 47% మాత్రమే. ఉపాధి మార్గాలు: చిన్న పరిశ్రమలకు రుణాలు, నైపుణ్య శిక్షణ, వ్యవస్థీకృత రంగ విస్తరణ, కార్మిక చట్టాల అమలు.","24) (i) 2000: మొత్తం ₹2,34,000 కోట్లు – ప్రాథమిక 22.2%, ద్వితీయ 20.7%, తృతీయ 57.1%. 2013: మొత్తం ₹57,42,500 కోట్లు – ప్రాథమిక 13.9%, ద్వితీయ 18.7%, తృతీయ 67.4%. (ii) రెండు సంవత్సరాలకు స్టాక్డ్ బార్ గ్రాఫ్ గీయండి. (iii) తృతీయ రంగ వాటా పెరిగింది, ప్రాథమిక రంగ వాటా గణనీయంగా తగ్గింది, ద్వితీయ రంగ వాటా కొంచెం తగ్గింది."]]]},{"id":"ec3","no":15,"t":"ద్రవ్యం, పరపతి (Money and Credit)","m":[9],"ty":"Economics – Chapter 3","by":"సాంఘిక శాస్త్రం – అర్థశాస్త్రం 10వ తరగతి (పుటలు 78–107)","th":"వినిమయ మాధ్యమంగా ద్రవ్యం, ఆధునిక ద్రవ్య రూపాలు, బ్యాంకుల రుణ కార్యకలాపాలు, పరపతి షరతులు, అధికారిక–అనధికారిక రుణాలు, స్వయం సహాయక సంఘాలు","sum":"వస్తు మార్పిడి (barter) పద్ధతిలో రెండు వైపులా కోరికలు ఏకీభవించాలి (double coincidence of wants) – ఇది కష్టం. ద్రవ్యం వినిమయ మాధ్యమంగా పనిచేసి ఈ సమస్యను తొలగిస్తుంది. పూర్వం ధాన్యం, పశువులు, తర్వాత బంగారు, వెండి, రాగి నాణేలు ద్రవ్యంగా వాడారు. ఆధునిక ద్రవ్యం – కాగితం నోట్లు, నాణేలు (కరెన్సీ) మరియు బ్యాంకు డిపాజిట్లు. కేంద్ర ప్రభుత్వం తరఫున భారతీయ రిజర్వు బ్యాంకు (RBI) కరెన్సీ నోట్లు జారీ చేస్తుంది; చట్టబద్ధమైనవి కాబట్టి అందరూ అంగీకరిస్తారు. బ్యాంకులో డిపాజిట్ – అడిగినప్పుడు తీసుకునే వీలున్నందున డిమాండ్ డిపాజిట్లు; చెక్కు ద్వారా చెల్లింపులు చేయవచ్చు కాబట్టి అవి కూడా ద్రవ్యమే. బ్యాంకులు డిపాజిట్లలో సుమారు 15% నగదుగా ఉంచి మిగతాది రుణాలుగా ఇస్తాయి; డిపాజిట్లపై కంటే రుణాలపై ఎక్కువ వడ్డీ – తేడాయే బ్యాంకు ఆదాయం. పరపతి (రుణం) – భవిష్యత్తులో చెల్లిస్తామనే వాగ్దానంతో డబ్బు/వస్తువులు/సేవలు పొందడం. సలీం (చెప్పుల తయారీదారు) కు రుణం లాభం తెచ్చింది; స్వప్న (చిన్న రైతు) పంట నష్టంతో అప్పుల ఊబిలో (debt trap) చిక్కి భూమి అమ్ముకుంది. పరపతి షరతులు: వడ్డీ రేటు, హామీ (collateral – భూమి, ఇల్లు, వాహనం, పశువులు, డిపాజిట్లు), పత్రాలు, తిరిగి చెల్లించే విధానం. సోన్‌పూర్ గ్రామంలో శ్యామల్ (వ్యాపారి – నెలకు 3%), అరుణ్ (బ్యాంకు – ఏడాదికి 8.5%), రమ (భూస్వామి – నెలకు 5%). అధికారిక రుణాలు – బ్యాంకులు, సహకార సంఘాలు (RBI పర్యవేక్షణ); అనధికారిక – వడ్డీ వ్యాపారులు, వ్యాపారులు, యజమానులు, బంధువులు (పర్యవేక్షణ లేదు, అధిక వడ్డీ). పేదలు ఎక్కువగా అనధికారిక రుణాలపై, ధనికులు అధికారిక రుణాలపై ఆధారపడతారు. అందరికీ చౌక రుణం అందాలంటే అధికారిక రుణాలు విస్తరించాలి. స్వయం సహాయక సంఘాలు (SHG – 15–20 మంది మహిళలు, పొదుపు, చిన్న రుణాలు, హామీ లేకుండా బ్యాంకు రుణం); బంగ్లాదేశ్ గ్రామీణ బ్యాంకు – ప్రొ. మహమ్మద్ యూనుస్ (2006 నోబెల్ శాంతి బహుమతి).","pts":["వస్తు మార్పిడిలో “కోరికల ద్వంద్వ ఏకీభావం” తప్పనిసరి; ద్రవ్యం దీన్ని తొలగిస్తుంది – వినిమయ మాధ్యమం.","ద్రవ్య పరిణామం: ధాన్యం, పశువులు → లోహ నాణేలు → కాగితం నోట్లు → బ్యాంకు డిపాజిట్లు, చెక్కులు, డిజిటల్ చెల్లింపులు.","భారత్‌లో కేంద్ర ప్రభుత్వం తరఫున RBI కరెన్సీ నోట్లు జారీ చేస్తుంది; రూపాయి చట్టబద్ధ ద్రవ్యం (legal tender).","డిమాండ్ డిపాజిట్లు: అడిగినప్పుడు తీసుకోవచ్చు; చెక్కు ద్వారా చెల్లింపు – కాబట్టి ద్రవ్యంగా పరిగణిస్తారు.","చెక్కు: ఖాతాదారు బ్యాంకుకు, అందులో పేర్కొన్న వ్యక్తికి నిర్దిష్ట మొత్తం చెల్లించమని ఇచ్చే ఆదేశ పత్రం.","బ్యాంకులు డిపాజిట్లలో సుమారు 15% నగదుగా ఉంచుతాయి; మిగతాది రుణాలు. రుణాలపై వడ్డీ − డిపాజిట్లపై వడ్డీ = బ్యాంకు ఆదాయం.","పరపతి సానుకూలం: సలీం – వర్కింగ్ క్యాపిటల్ కోసం రుణం, లాభం. ప్రమాదం: స్వప్న – పంట నష్టం, అప్పుల ఊబి, భూమి అమ్మకం.","పరపతి షరతులు: వడ్డీ రేటు, హామీ (collateral), పత్రాలు, తిరిగి చెల్లించే పద్ధతి.","అధికారిక వనరులు: బ్యాంకులు, సహకార సంఘాలు – RBI పర్యవేక్షణ, తక్కువ వడ్డీ. అనధికారిక: వడ్డీ వ్యాపారి, వ్యాపారి, యజమాని, బంధువులు – పర్యవేక్షణ లేదు, అధిక వడ్డీ, వేధింపులు.","RBI పర్యవేక్షణ: బ్యాంకుల నగదు నిల్వ, చిన్న రైతులు–చిన్న పరిశ్రమలకు రుణాలు, ఎవరికి ఎంత వడ్డీకి ఇచ్చారో సమాచారం.","పట్టణ పేద కుటుంబాల రుణాల్లో 85% అనధికారిక; ధనిక కుటుంబాలవి 90% అధికారిక.","SHG: 15–20 మంది (ఎక్కువగా మహిళలు), నెలకు ₹25–100 పొదుపు; 1–2 ఏళ్ల తర్వాత సంఘం పేరుతో హామీ లేకుండా బ్యాంకు రుణం; నిర్ణయాలు సభ్యులవే.","గ్రామీణ బ్యాంకు (బంగ్లాదేశ్): 1970ల్లో ప్రారంభం; 2018లో 81,600 గ్రామాల్లో 90 లక్షల మంది సభ్యులు – దాదాపు అందరూ పేద మహిళలు."],"w":[["వస్తు మార్పిడి","Barter system"],["కోరికల ద్వంద్వ ఏకీభావం","Double coincidence of wants"],["వినిమయ మాధ్యమం","Medium of exchange"],["కరెన్సీ","Currency"],["డిమాండ్ డిపాజిట్లు","Demand deposits"],["చెక్కు","Cheque"],["పరపతి / రుణం","Credit / Loan"],["హామీ / తాకట్టు","Collateral"],["వడ్డీ రేటు","Interest rate"],["అసలు","Principal"],["పరపతి షరతులు","Terms of credit"],["అప్పుల ఊబి","Debt trap"],["అధికారిక రుణ వనరులు","Formal sources of credit"],["అనధికారిక రుణ వనరులు","Informal sources of credit"],["స్వయం సహాయక సంఘం","Self Help Group (SHG)"],["భారతీయ రిజర్వు బ్యాంకు","Reserve Bank of India (RBI)"]],"gr":{"t":"ముఖ్య గణాంకాలు & పోలికలు","p":["వడ్డీ: నెలకు 5% = ఏడాదికి 60%; నెలకు 3% = ఏడాదికి 36%; బ్యాంకు 8.5% (ఏడాదికి)","సోన్‌పూర్: శ్యామల్ (1.5 ఎకరాలు) – వ్యాపారి 3%/నెల + పంట అతనికే అమ్మాలి; అరుణ్ (7 ఎకరాలు) – బ్యాంకు 8.5%/ఏడాది, 3 ఏళ్లలో; రమ (కూలీ) – భూస్వామి 5%/నెల, అతని పొలంలో పనిచేసి తీర్చాలి","క్రిషక్ సహకార సంఘం: 2300 మంది రైతు సభ్యులు – డిపాజిట్లను హామీగా పెట్టి బ్యాంకు రుణం","పట్టణ రుణాలు: పేద కుటుంబాలు – 85% అనధికారిక; ధనిక కుటుంబాలు – 90% అధికారిక","బ్యాంకు: డిపాజిట్లు → (15% నగదు నిల్వ) → రుణాలు; రుణ వడ్డీ > డిపాజిట్ వడ్డీ"]},"qa":[["వస్తు మార్పిడి పద్ధతిలో ప్రధాన సమస్య?","కోరికల ద్వంద్వ ఏకీభావం – ఒకరు అమ్మాలనుకున్నదే మరొకరు కొనాలనుకోవాలి."],["భారత్‌లో కరెన్సీ నోట్లు ఎవరు జారీ చేస్తారు?","కేంద్ర ప్రభుత్వం తరఫున భారతీయ రిజర్వు బ్యాంకు (RBI)."],["డిమాండ్ డిపాజిట్లను ద్రవ్యంగా ఎందుకు పరిగణిస్తారు?","అడిగినప్పుడు తీసుకోవచ్చు; చెక్కుల ద్వారా నేరుగా చెల్లింపులు చేయవచ్చు – వినిమయ మాధ్యమంగా పనిచేస్తాయి."],["హామీ (collateral) అంటే?","రుణం తీర్చే వరకు రుణదాతకు హామీగా ఉంచే రుణగ్రహీత ఆస్తి – భూమి, ఇల్లు, వాహనం, పశువులు, డిపాజిట్లు."],["అప్పుల ఊబి (debt trap) అంటే?","తీసుకున్న రుణం తీర్చలేక, ఇంకా రుణాలు తీసుకుంటూ అప్పు పెరిగిపోయే పరిస్థితి."],["అధికారిక రుణ వనరులు ఏవి?","బ్యాంకులు, సహకార సంఘాలు."],["అనధికారిక రుణదాతలు ఎవరు?","వడ్డీ వ్యాపారులు, వ్యాపారులు, యజమానులు, బంధువులు, స్నేహితులు."],["SHG లో సాధారణంగా ఎంత మంది సభ్యులు?","15 – 20 మంది (ఒకే ప్రాంతానికి చెందినవారు, ఎక్కువగా మహిళలు)."],["గ్రామీణ బ్యాంకు స్థాపకుడు ఎవరు?","ప్రొఫెసర్ మహమ్మద్ యూనుస్ (బంగ్లాదేశ్) – 2006 నోబెల్ శాంతి బహుమతి."],["బ్యాంకుల ఆదాయ ప్రధాన వనరు?","రుణగ్రహీతల నుండి వసూలు చేసే వడ్డీకి, డిపాజిటర్లకు ఇచ్చే వడ్డీకి మధ్య తేడా."]],"act":"మీ దగ్గరి బ్యాంకుకు వెళ్ళి డిపాజిట్ స్లిప్, చెక్కు నమూనా చూడండి; ₹10 నోటుపై “I promise to pay the bearer…” వాక్యం చదవండి. మీ గ్రామంలోని ఒక పొదుపు సంఘం (DWCRA/SHG) సభ్యురాలిని కలిసి వారి పొదుపు, రుణాలు, వడ్డీ వివరాలు అడిగి రాయండి.","kn":"ఆంధ్రప్రదేశ్ దేశంలోనే అత్యధిక స్వయం సహాయక (DWCRA) సంఘాలు గల రాష్ట్రాల్లో ఒకటి! భారత్‌లో UPI ద్వారా నెలకు 1,000 కోట్లకు పైగా డిజిటల్ లావాదేవీలు జరుగుతున్నాయి.","qz":[["కోరికల ద్వంద్వ ఏకీభావం ఏ పద్ధతి లక్షణం?","వస్తు మార్పిడి","ద్రవ్య వ్యవస్థ","బ్యాంకింగ్","చెక్కు పద్ధతి"],["భారత్‌లో కరెన్సీ నోట్లు జారీ చేసేది?","భారతీయ రిజర్వు బ్యాంకు","స్టేట్ బ్యాంక్ ఆఫ్ ఇండియా","ఆర్థిక మంత్రి","ప్రపంచ బ్యాంకు"],["బ్యాంకులు డిపాజిట్లలో సుమారు ఎంత శాతం నగదుగా ఉంచుతాయి?","15%","50%","5%","80%"],["సలీం, ప్రేమ్‌కు చెక్కు ఇచ్చిన తర్వాత?","సలీం బ్యాలెన్స్ తగ్గుతుంది, ప్రేమ్ బ్యాలెన్స్ పెరుగుతుంది","ఇద్దరి బ్యాలెన్స్ పెరుగుతుంది","సలీం బ్యాలెన్స్ పెరుగుతుంది, ప్రేమ్‌ది తగ్గుతుంది","ఇద్దరిదీ తగ్గుతుంది"],["రుణగ్రహీత హామీగా ఉంచే ఆస్తిని ఏమంటారు?","హామీ (Collateral)","అసలు","వడ్డీ","డిపాజిట్"],["అధికారిక రుణ వనరులో చేరనిది?","యజమానులు","బ్యాంకులు","సహకార సంఘాలు","గ్రామీణ బ్యాంకులు"],["SHG లో పొదుపు, రుణ నిర్ణయాలు తీసుకునేది?","సభ్యులు","బ్యాంకు","స్వచ్ఛంద సంస్థ","ప్రభుత్వం"],["పేద కుటుంబాల రుణ అవసరాలు ఎక్కువగా తీరేది?","అనధికారిక వనరుల నుండి","బ్యాంకుల నుండి","సహకార సంఘాల నుండి","RBI నుండి"],["అధిక రుణ వ్యయం (high cost of borrowing) దేన్ని పెంచుతుంది?","అప్పుల భారం","ఆదాయం","పొదుపు","లాభం"],["అరుణ్ బ్యాంకు రుణ వడ్డీ రేటు?","ఏడాదికి 8.5%","నెలకు 5%","నెలకు 3%","ఏడాదికి 60%"],["నెలకు 5% వడ్డీ అంటే ఏడాదికి?","60%","5%","12%","50%"],["గ్రామీణ బ్యాంకు ఏ దేశానికి చెందినది?","బంగ్లాదేశ్","భారత్","నేపాల్","శ్రీలంక"],["స్వప్న ఎందుకు అప్పుల ఊబిలో చిక్కింది?","పంట చీడపురుగులతో నాశనమై రుణం తీర్చలేక","వ్యాపారం విస్తరించి","బ్యాంకు రుణం తీసుకుని","భూమి కొని"],["బ్యాంకులు డిపాజిట్ల కంటే రుణాలపై వసూలు చేసే వడ్డీ?","ఎక్కువ","తక్కువ","సమానం","సున్నా"],["అనధికారిక రుణదాతలను పర్యవేక్షించేది?","ఏ సంస్థా లేదు","RBI","బ్యాంకులు","పంచాయతీ"],["ఆధునిక ద్రవ్య రూపాలు?","కరెన్సీ, బ్యాంకు డిపాజిట్లు","ధాన్యం, పశువులు","బంగారు నాణేలు మాత్రమే","వస్తు మార్పిడి"]],"wb":{"mis":"“రుణం ఎప్పుడూ మంచిదే” లేదా “ఎప్పుడూ చెడ్డదే” అనడం తప్పు – ప్రమాదం, మద్దతుపై ఆధారపడుతుంది (సలీం vs స్వప్న). నెలవారీ వడ్డీని ఏడాది వడ్డీతో పోల్చేటప్పుడు 12తో గుణించాలి. సహకార సంఘాలు అధికారిక వనరే; యజమానులు అనధికారికం.","qz":[],"pg":"78–107","f":"books/10/Class10_Social_Economics_Textbook.pdf","p":84,"lb":"పాఠ్యపుస్తకం","ws":["ఇవి చేయండి 1 – ద్రవ్యం (పుట 80)","ఇవి చేయండి 2 – చెక్కు, డిపాజిట్లు (పుట 84)","ఇవి చేయండి 3 – సలీం, స్వప్న (పుట 88)","ఇవి చేయండి 4 – పరపతి షరతులు (పుట 90)","ఇవి చేయండి 5 – సోన్‌పూర్ గ్రామం (పుట 94)","ఇవి చేయండి 6 – అధికారిక / అనధికారిక రుణాలు (పుట 100)","అభ్యాసాలు – Exercises (1–7) (పుట 104)","అభ్యాసాలు – Exercises (8–13), కృత్యం (పుట 106)"]},"tg":[["ఇవి చేయండి 1 – ద్రవ్యం (పుట 80)",["1) ద్రవ్యం వినిమయ మాధ్యమం: మనం వస్తువు అమ్మి డబ్బు తీసుకుని, ఆ డబ్బుతో కావలసింది ఎవరి దగ్గరైనా కొనవచ్చు. “కోరికల ద్వంద్వ ఏకీభావం” అవసరం లేదు – చెప్పుల తయారీదారు గోధుమ కావాలనుకుంటే చెప్పులు కావాలనుకునే గోధుమ రైతునే వెతకనక్కర్లేదు.","2) వస్తు మార్పిడి ఉదాహరణలు: పొలం కూలీలకు ధాన్యం రూపంలో కూలి; వడ్లకు బదులు కూరగాయలు/చేపలు; పాత వార్తాపత్రికలు, సామాన్లకు బదులు స్టీలు గిన్నెలు; వడ్రంగి, కమ్మరికి పంటలో భాగం (ఆయం)."]],["ఇవి చేయండి 2 – చెక్కు, డిపాజిట్లు (పుట 84)",["1) సలీం తన చెక్కుపై తేదీ రాసి, “Pay” దగ్గర “Self” అని, ₹20,000 అంకెల్లో, అక్షరాల్లో (Twenty thousand rupees only) రాసి, సంతకం చేసి బ్యాంకులో ఇస్తే నగదు ఇస్తారు.","2) (ii) సలీం బ్యాలెన్స్ తగ్గుతుంది, ప్రేమ్ బ్యాలెన్స్ పెరుగుతుంది.","3) డిమాండ్ డిపాజిట్లను అడిగినప్పుడు తీసుకోవచ్చు; చెక్కుల ద్వారా నేరుగా చెల్లింపులు జరపవచ్చు; అందరూ అంగీకరిస్తారు – కాబట్టి అవి వినిమయ మాధ్యమమైన ద్రవ్యమే."]],["ఇవి చేయండి 3 – సలీం, స్వప్న (పుట 88)",["1) పట్టిక: సలీం – రుణం ఎందుకు: ముడిసరుకు (తోలు) కొనడానికి, అదనపు కార్మికుల వేతనాలకు (వర్కింగ్ క్యాపిటల్); ప్రమాదం: తక్కువ – పెద్ద వ్యాపారి నుండి ఖచ్చితమైన ఆర్డర్; ఫలితం: సమయానికి ఉత్పత్తి, మంచి లాభం, రుణం తీర్చాడు. స్వప్న – రుణం ఎందుకు: వేరుశనగ సాగు ఖర్చులకు; ప్రమాదం: ఎక్కువ – పంట చీడపురుగులు, వాతావరణం, వడ్డీ వ్యాపారి అధిక వడ్డీ; ఫలితం: పంట నష్టం, అప్పు పెరిగి భూమిలో కొంత భాగం అమ్ముకుంది (అప్పుల ఊబి).","2) సలీంకు ఆర్డర్లు కొనసాగితే 6 ఏళ్లలో లాభాలు పెరిగి, వ్యాపారం విస్తరిస్తాడు, యంత్రాలు కొంటాడు, ఎక్కువ మందికి ఉపాధి ఇస్తాడు – అతని పరిస్థితి చాలా మెరుగవుతుంది.","3) కారణాలు: చీడపురుగులు – ఖరీదైన పురుగుమందులు పనిచేయలేదు; వడ్డీ వ్యాపారి నుండి అధిక వడ్డీకి రుణం; వర్షం, వాతావరణంపై ఆధారపడటం; పంట బీమా, ప్రభుత్వ మద్దతు లేకపోవడం."]],["ఇవి చేయండి 4 – పరపతి షరతులు (పుట 90)",["1) రుణగ్రహీత రుణం తీర్చలేకపోతే హామీగా పెట్టిన ఆస్తిని అమ్మి డబ్బు రాబట్టుకోవడానికి (భద్రత కోసం) రుణదాతలు హామీ అడుగుతారు.","2) అవును. పేదల వద్ద భూమి, ఇల్లు వంటి హామీ ఆస్తులు, పత్రాలు ఉండవు; కాబట్టి బ్యాంకులు రుణాలు ఇవ్వవు. వారు అధిక వడ్డీకి వడ్డీ వ్యాపారులపై ఆధారపడాల్సి వస్తుంది.","3) తక్కువ (low) వడ్డీ రేటు, సులభమైన (easy) తిరిగి చెల్లించే షరతులు, తక్కువ (less) హామీ, పత్రాల అవసరం."]],["ఇవి చేయండి 5 – సోన్‌పూర్ గ్రామం (పుట 94)",["1) రుణ వనరులు: గ్రామ వడ్డీ వ్యాపారి, వ్యవసాయ వ్యాపారి, బ్యాంకు, మధ్యతరహా భూస్వామి (యజమాని), (సమీపంలో) క్రిషక్ సహకార సంఘం.","2) రుణ ఉపయోగాలు: సాగు ఖర్చులు (విత్తనాలు, ఎరువులు, పురుగుమందులు), శీతల గిడ్డంగి రసీదుపై కొత్త రుణం, రోజువారీ ఇంటి ఖర్చులు, అనారోగ్యం, కుటుంబ వేడుకలు, వ్యవసాయ పనిముట్లు, చేపల పెంపకం, ఇళ్ళ నిర్మాణం.","3) చిన్న రైతు శ్యామల్: వ్యాపారి నుండి నెలకు 3% (ఏడాదికి 36%); పంటను అతనికే తక్కువ ధరకు అమ్మాలి. మధ్యతరహా రైతు అరుణ్: బ్యాంకు నుండి ఏడాదికి 8.5%, మూడేళ్లలో ఎప్పుడైనా తీర్చవచ్చు. భూమిలేని కూలీ రమ: భూస్వామి నుండి నెలకు 5% (ఏడాదికి 60%); అతని పొలంలో పనిచేసి తీర్చాలి.","4) అరుణ్‌కు చౌక బ్యాంకు రుణం (8.5%), పంటను ధర పెరిగాక అమ్ముకునే స్వేచ్ఛ (శీతల గిడ్డంగి) ఉన్నాయి. శ్యామల్ అధిక వడ్డీ కట్టి, పంటను కోత సమయంలో తక్కువ ధరకు వ్యాపారికే అమ్మాలి – కాబట్టి అరుణ్ ఆదాయం ఎక్కువ.","5) లేదు. భూమి వంటి హామీ ఆస్తులున్న అరుణ్ వంటి కొద్దిమందికే బ్యాంకు నుండి చౌక రుణం లభిస్తుంది.","6) (i) పెరుగుతుంది (will rise). (ii) బ్యాంకులు అందరూ ఇవ్వలేని హామీని అడుగుతాయి.","7) మీ ప్రాంతంలో రైతు, కూలీ, దుకాణదారు, ఉద్యోగిని అడిగి – ఎవరి నుండి, ఎంత వడ్డీకి, ఏ హామీతో, ఎలా తిరిగి చెల్లిస్తారో రాయండి; తేడాలు గమనించండి."]],["ఇవి చేయండి 6 – అధికారిక / అనధికారిక రుణాలు (పుట 100)",["1) అధికారిక (బ్యాంకులు, సహకార సంఘాలు): RBI పర్యవేక్షణ, తక్కువ వడ్డీ, హామీ–పత్రాలు అవసరం, రికార్డులు ఉంటాయి. అనధికారిక (వడ్డీ వ్యాపారి, వ్యాపారి, యజమాని, బంధువులు): పర్యవేక్షణ లేదు, అధిక వడ్డీ, హామీ లేకపోయినా ఇస్తారు, రికార్డులు ఉండవు, అన్యాయమైన పద్ధతుల్లో వసూలు.","2) చౌక రుణాలు ఉంటే రైతులు, చిన్న వ్యాపారులు ఎక్కువ సంపాదిస్తారు; కొత్త వ్యాపారాలు ప్రారంభిస్తారు; అప్పుల ఊబి తప్పుతుంది; దేశ అభివృద్ధి వేగవంతమవుతుంది.","3) అవును, ఉండాలి – అధిక వడ్డీ, వేధింపులు అరికట్టడానికి. కానీ కష్టం – అనధికారిక రుణదాతలు లక్షల సంఖ్యలో, గ్రామాల్లో చెల్లాచెదురుగా, నమోదు లేకుండా, రాతపూర్వక రికార్డులు లేకుండా రుణాలిస్తారు.","4) ధనికుల వద్ద హామీ ఆస్తులు, పత్రాలు, బ్యాంకులతో సంబంధాలు ఉంటాయి; బ్యాంకులు వారికి రుణం ఇవ్వడానికి ఇష్టపడతాయి. పేదలకు ఇవి లేక, బ్యాంకులు దగ్గరగా లేక వడ్డీ వ్యాపారులపై ఆధారపడతారు."]],["అభ్యాసాలు – Exercises (1–7) (పుట 104)",["1) అధిక ప్రమాదం ఉన్నప్పుడు (పంట నష్టం, వ్యాపార నష్టం) రుణం తీర్చలేక, వడ్డీ పెరిగి, కొత్త రుణాలు తీసుకుని అప్పుల ఊబిలో చిక్కుతారు; హామీ ఆస్తులు (భూమి) కోల్పోతారు – స్వప్న ఉదాహరణ.","2) ద్రవ్యం మధ్యవర్తిగా పనిచేస్తుంది. ఉదా: కుమ్మరి బియ్యం కావాలనుకుంటే, కుండలు కావాలనుకునే రైతును వెతకక్కర్లేదు – కుండలు ఎవరికైనా అమ్మి, ఆ డబ్బుతో ఎవరి దగ్గరైనా బియ్యం కొంటాడు.","3) బ్యాంకులు మిగులు డబ్బున్నవారి నుండి డిపాజిట్లు తీసుకుని వడ్డీ ఇస్తాయి; ఆ డబ్బులో ఎక్కువ భాగాన్ని అవసరమైనవారికి రుణాలుగా ఇచ్చి ఎక్కువ వడ్డీ వసూలు చేస్తాయి – ఇలా మధ్యవర్తిగా పనిచేస్తాయి.","4) ₹10 నోటుపై “I promise to pay the bearer the sum of ten rupees” అని RBI గవర్నర్ సంతకంతో ఉంటుంది. అంటే కేంద్ర ప్రభుత్వం తరఫున RBI ఈ నోటు విలువకు హామీ ఇస్తుంది – అది చట్టబద్ధ ద్రవ్యం, ఎవరూ తిరస్కరించలేరు.","5) అనధికారిక రుణాలపై అధిక వడ్డీ, దోపిడీ, అప్పుల ఊబి తప్పించడానికి; అందరికీ – ముఖ్యంగా పేదలకు – చౌక రుణాలు అందితే ఆదాయం పెరిగి అభివృద్ధి సాధ్యమవుతుంది; కాబట్టి బ్యాంకులు, సహకార సంఘాలు గ్రామాల్లో విస్తరించాలి.","6) పేదలను (ముఖ్యంగా మహిళలను) 15–20 మంది సంఘాలుగా చేసి క్రమంగా పొదుపు చేయించడం; సంఘం నుండే తక్కువ వడ్డీకి చిన్న రుణాలు; తర్వాత సంఘం పేరుతో హామీ లేకుండా బ్యాంకు రుణం – స్వయం ఉపాధి; మహిళల ఆర్థిక స్వావలంబన, సామాజిక సమస్యలపై చర్చకు వేదిక.","7) హామీ ఆస్తులు, సరైన పత్రాలు లేకపోవడం; ఇంతకు ముందు రుణాలు తీర్చకపోవడం; ఆదాయం అస్థిరంగా ఉండటం (ప్రమాదం ఎక్కువ); చిన్న రుణాలపై నిర్వహణ ఖర్చు ఎక్కువ."]],["అభ్యాసాలు – Exercises (8–13), కృత్యం (పుట 106)",["8) RBI బ్యాంకులు కనీస నగదు నిల్వ ఉంచుతున్నాయో లేదో చూస్తుంది; లాభదాయక వ్యాపారాలకే కాకుండా చిన్న రైతులు, చిన్న పరిశ్రమలు, చిన్న రుణగ్రహీతలకు కూడా రుణాలు ఇచ్చేలా చూస్తుంది; ఎవరికి, ఎంత, ఏ వడ్డీకి ఇచ్చారో సమాచారం తీసుకుంటుంది. ఇది డిపాజిటర్ల డబ్బు భద్రత, న్యాయమైన రుణ పంపిణీ కోసం అవసరం.","9) చౌక రుణాలు ఉత్పత్తి పెంచుతాయి, వ్యాపారాలు ప్రారంభించడానికి, సాగుకు, పరిశ్రమలకు తోడ్పడతాయి, ఆదాయం–ఉపాధి పెంచుతాయి – అభివృద్ధికి కీలకం. కానీ అధిక వడ్డీ, అధిక ప్రమాద రుణాలు అప్పుల ఊబికి దారితీస్తాయి.","10) మానవ్ వడ్డీ రేటు, హామీ అవసరం, పత్రాలు, తిరిగి చెల్లించే కాలం–పద్ధతి పోల్చుకుంటాడు. హామీ, పత్రాలు ఉంటే తక్కువ వడ్డీకి బ్యాంకు మేలు; లేకపోతే వడ్డీ వ్యాపారి – కానీ అధిక వడ్డీ ప్రమాదం.","11) (a) చిన్న రైతుల వద్ద హామీ, పత్రాలు లేవు; పంట నష్టం ప్రమాదం; తిరిగి చెల్లించే సామర్థ్యంపై సందేహం. (b) వడ్డీ వ్యాపారులు, వ్యాపారులు, భూస్వాములు, బంధువులు, SHGలు, సహకార సంఘాలు. (c) ఉదా: శ్యామల్ – నెలకు 3% వడ్డీ + పంటను తక్కువ ధరకు వ్యాపారికే అమ్మాలి; రమ – 5%/నెల, యజమాని పొలంలో తక్కువ కూలికి పనిచేయాలి. (d) సహకార సంఘాలు, SHGలు, గ్రామీణ బ్యాంకుల విస్తరణ, ప్రభుత్వ వ్యవసాయ రుణ పథకాలు (కిసాన్ క్రెడిట్ కార్డు), వడ్డీ రాయితీలు.","12) (i) పేద (poor) (ii) అధిక (High) (iii) భారతీయ రిజర్వు బ్యాంకు (iv) డిపాజిట్లు (v) హామీ (Collateral)","13) (i) (b) సభ్యులు (ii) (c) యజమానులు","కృత్యం – రుణం ఎందుకు: నిర్మాణ కూలీ – అనారోగ్యం/ఇంటి ఖర్చులు; కంప్యూటర్ తెలిసిన పట్టభద్రుడు – సొంత వ్యాపారం/ఉన్నత చదువు; ప్రభుత్వ ఉద్యోగి – ఇల్లు, వాహనం; ఢిల్లీలో వలస కూలీ – ఇంటికి డబ్బు, అత్యవసరాలు; ఇంటి పనిమనిషి – పిల్లల చదువు, అనారోగ్యం; చిన్న వ్యాపారి – సరుకు కొనడానికి; ఆటో డ్రైవర్ – ఆటో కొనడానికి/మరమ్మతు; ఫ్యాక్టరీ మూతపడిన కార్మికుడు – రోజువారీ ఖర్చులు, కొత్త పని. బ్యాంకు రుణం దొరికేవారు: ప్రభుత్వ ఉద్యోగి, పట్టభద్రుడు, చిన్న వ్యాపారి, ఆటో డ్రైవర్ (హామీ/క్రమ ఆదాయం ఉంది). దొరకనివారు: నిర్మాణ కూలీ, వలస కూలీ, పనిమనిషి, ఉద్యోగం పోయిన కార్మికుడు. ప్రమాణం – హామీ, క్రమమైన ఆదాయం, పత్రాలు."]]]},{"id":"ec4","no":16,"t":"ప్రపంచీకరణ, భారత ఆర్థిక వ్యవస్థ (Globalisation and the Indian Economy)","m":[10],"ty":"Economics – Chapter 4","by":"సాంఘిక శాస్త్రం – అర్థశాస్త్రం 10వ తరగతి (పుటలు 110–147)","th":"బహుళజాతి సంస్థలు, విదేశీ వాణిజ్యం, విదేశీ పెట్టుబడి, సాంకేతికత, సరళీకరణ, WTO, ప్రపంచీకరణ ప్రభావం, న్యాయమైన ప్రపంచీకరణ","sum":"ఒకటి కంటే ఎక్కువ దేశాల్లో ఉత్పత్తిని తమ యాజమాన్యంలో లేదా నియంత్రణలో ఉంచుకునే సంస్థ బహుళజాతి సంస్థ (MNC). చౌక శ్రమ, ముడిసరుకులు, మార్కెట్లకు దగ్గరగా, ప్రభుత్వ విధానాలు అనుకూలంగా ఉన్నచోట అవి ఉత్పత్తి కేంద్రాలు పెడతాయి. విదేశీ పెట్టుబడి – MNC లు భూమి, భవనాలు, యంత్రాలు వంటి ఆస్తుల కొనుగోలుకు పెట్టే పెట్టుబడి. MNC లు స్థానిక కంపెనీలతో భాగస్వామ్యం, స్థానిక కంపెనీలను కొనడం (కార్గిల్ – పరఖ్ ఫుడ్స్), చిన్న ఉత్పత్తిదారులకు ఆర్డర్లు ఇవ్వడం (వస్త్రాలు, పాదరక్షలు, క్రీడా వస్తువులు) ద్వారా ఉత్పత్తిని విస్తరిస్తాయి – ఇది వేర్వేరు ప్రాంతాల ఉత్పత్తిని అనుసంధానం చేస్తుంది. విదేశీ వాణిజ్యం దేశాల మార్కెట్లను ఏకీకృతం చేస్తుంది (చైనా బొమ్మలు). ఫోర్డ్ మోటార్స్ 1995లో చెన్నై వద్ద ₹1700 కోట్లతో కర్మాగారం పెట్టింది. ప్రపంచీకరణ = వాణిజ్యం, పెట్టుబడులు, సాంకేతికత, ప్రజల రాకపోకల ద్వారా దేశాల మధ్య వేగవంతమైన ఏకీకరణ. దీనికి తోడ్పడిన అంశాలు: రవాణా, సమాచార సాంకేతికత (IT, ఇంటర్నెట్, ఇ-బ్యాంకింగ్) అభివృద్ధి; విదేశీ వాణిజ్య–పెట్టుబడుల సరళీకరణ. స్వాతంత్ర్యం తర్వాత దేశీయ ఉత్పత్తిదారుల రక్షణకు దిగుమతులపై పన్నులు, కోటాలు వంటి వాణిజ్య అవరోధాలు పెట్టారు; 1991 నుండి వాటిని చాలావరకు తొలగించారు – సరళీకరణ. ప్రపంచ వాణిజ్య సంస్థ (WTO) – అభివృద్ధి చెందిన దేశాల చొరవతో, అంతర్జాతీయ వాణిజ్య సరళీకరణ లక్ష్యం; కానీ అభివృద్ధి చెందిన దేశాలు తమ రైతులకు భారీ రాయితీలు ఇస్తూనే ఉన్నాయి (అన్యాయం). ప్రభావం: వినియోగదారులకు ఎక్కువ ఎంపిక, నాణ్యత, తక్కువ ధరలు; MNC పెట్టుబడులు, కొత్త ఉద్యోగాలు; టాటా మోటార్స్, ఇన్ఫోసిస్, రాన్‌బాక్సీ వంటి భారత కంపెనీలు MNC లుగా ఎదిగాయి; IT సేవలు. కానీ చిన్న ఉత్పత్తిదారులు (హోసూరులో కెపాసిటర్లు తయారుచేసే రవి) పోటీకి నిలవలేకపోయారు; కార్మికులకు ఉద్యోగ భద్రత తగ్గింది (“సరళమైన” కార్మిక చట్టాలు, తాత్కాలిక ఉద్యోగాలు). ప్రత్యేక ఆర్థిక మండళ్లు (SEZ) – ప్రపంచ స్థాయి సౌకర్యాలు, 5 ఏళ్లు పన్ను మినహాయింపు. న్యాయమైన ప్రపంచీకరణ – అందరికీ అవకాశాలు, లాభాలు; ప్రభుత్వం కార్మిక చట్టాల అమలు, చిన్న ఉత్పత్తిదారులకు మద్దతు, WTO లో న్యాయమైన నియమాల కోసం పోరాడాలి.","pts":["MNC: ఒకటి కంటే ఎక్కువ దేశాల్లో ఉత్పత్తిని యాజమాన్యం/నియంత్రణలో ఉంచుకునే సంస్థ (ఫోర్డ్, కోకా-కోలా, నైక్, హోండా).","విదేశీ పెట్టుబడి: MNC లు భూమి, భవనాలు, యంత్రాలు, ఇతర పరికరాల కొనుగోలుకు ఖర్చు చేసే డబ్బు.","MNC లు ఉత్పత్తి నెలకొల్పే మార్గాలు: సొంత కర్మాగారాలు, స్థానిక కంపెనీలతో సంయుక్త ఉత్పత్తి, స్థానిక కంపెనీలను కొనడం (అత్యంత సాధారణం), చిన్న ఉత్పత్తిదారులకు ఆర్డర్లు.","కార్గిల్ ఫుడ్స్ (అమెరికా) పరఖ్ ఫుడ్స్‌ను కొని భారత్‌లో అతిపెద్ద వంటనూనె ఉత్పత్తిదారుగా మారింది (రోజుకు 50 లక్షల ప్యాకెట్లు).","విదేశీ వాణిజ్యం: ఉత్పత్తిదారులకు దేశీయ మార్కెట్ దాటి అవకాశం; కొనుగోలుదారులకు ఎక్కువ ఎంపిక → మార్కెట్ల ఏకీకరణ (చైనా బొమ్మలు).","ప్రపంచీకరణ: వాణిజ్యం, పెట్టుబడులు, సాంకేతికత, ప్రజల రాకపోకల ద్వారా దేశాల వేగవంతమైన అనుసంధానం.","తోడ్పడిన అంశాలు: సాంకేతికత (రవాణా – కంటైనర్లు, విమానాలు; IT – ఇంటర్నెట్, ఈమెయిల్, ఇ-బ్యాంకింగ్), విదేశీ వాణిజ్య–పెట్టుబడుల సరళీకరణ, WTO వంటి అంతర్జాతీయ సంస్థలు.","వాణిజ్య అవరోధాలు: దిగుమతి పన్నులు, కోటాలు (దిగుమతుల సంఖ్యపై పరిమితి).","సరళీకరణ: ప్రభుత్వ అవరోధాలు, ఆంక్షలను తొలగించడం – భారత్‌లో 1991 నుండి.","WTO: అంతర్జాతీయ వాణిజ్య నియమాలు; సుమారు 160 దేశాలు సభ్యులు; అభివృద్ధి చెందిన దేశాలు తమ అవరోధాలు, రాయితీలు కొనసాగిస్తున్నాయి.","లాభాలు: వినియోగదారులకు ఎంపిక, నాణ్యత, తక్కువ ధరలు; కొత్త ఉద్యోగాలు; భారత MNC లు (టాటా మోటార్స్, ఇన్ఫోసిస్, రాన్‌బాక్సీ, ఏషియన్ పెయింట్స్, సుందరం ఫాస్టెనర్స్); IT, కాల్ సెంటర్ సేవల ఎగుమతి.","నష్టాలు: చిన్న ఉత్పత్తిదారులు మూతపడటం (బ్యాటరీలు, కెపాసిటర్లు, ప్లాస్టిక్, బొమ్మలు, టైర్లు, పాల ఉత్పత్తులు, వంటనూనెలు); కార్మికులకు తాత్కాలిక ఉద్యోగాలు, తక్కువ వేతనాలు, ఎక్కువ గంటలు.","SEZ: విద్యుత్, నీరు, రోడ్లు, రవాణా, నిల్వ వంటి ప్రపంచ స్థాయి సౌకర్యాలు; మొదటి 5 ఏళ్లు పన్ను లేదు.","న్యాయమైన ప్రపంచీకరణ: కార్మిక చట్టాల అమలు, చిన్న ఉత్పత్తిదారులకు మద్దతు, అవసరమైతే వాణిజ్య అవరోధాలు, WTO లో న్యాయమైన నియమాల కోసం అభివృద్ధి చెందుతున్న దేశాల ఐక్యత."],"w":[["బహుళజాతి సంస్థ","Multinational Corporation (MNC)"],["విదేశీ పెట్టుబడి","Foreign investment"],["విదేశీ వాణిజ్యం","Foreign trade"],["ప్రపంచీకరణ","Globalisation"],["సరళీకరణ","Liberalisation"],["వాణిజ్య అవరోధం","Trade barrier"],["దిగుమతి పన్ను","Import tax / tariff"],["కోటా","Quota"],["ప్రపంచ వాణిజ్య సంస్థ","World Trade Organisation (WTO)"],["ప్రత్యేక ఆర్థిక మండలి","Special Economic Zone (SEZ)"],["మార్కెట్ల ఏకీకరణ","Integration of markets"],["ఉత్పత్తి అనుసంధానం","Interlinking of production"],["సమాచార సాంకేతికత","Information technology (IT)"],["సరళమైన కార్మిక చట్టాలు","Flexible labour laws"],["రాయితీ","Subsidy"],["న్యాయమైన ప్రపంచీకరణ","Fair globalisation"]],"gr":{"t":"ముఖ్య వాస్తవాలు","p":["ఫోర్డ్ మోటార్స్: 26 దేశాల్లో ఉత్పత్తి; 1995లో మహీంద్రా & మహీంద్రాతో కలిసి చెన్నై వద్ద ₹1700 కోట్ల కర్మాగారం; 2017లో 88,000 కార్లు భారత్‌లో అమ్మకం, 1,81,000 ఎగుమతి","ప్రపంచీకరణ మార్గాలు: వస్తువులు ↔ సేవలు ↔ పెట్టుబడులు ↔ సాంకేతికత ↔ ప్రజలు","1991 – భారత్‌లో సరళీకరణ ప్రారంభం; 2001 – WTO ఒప్పందం ప్రకారం కెపాసిటర్ల దిగుమతులపై ఆంక్షల తొలగింపు (రవి కథ)","అమెరికా రైతులకు భారీ రాయితీలు → తక్కువ ధరలకు పంటలు ఎగుమతి → పేద దేశాల రైతులకు నష్టం","SEZ – 5 ఏళ్లు పన్ను మినహాయింపు"]},"qa":[["బహుళజాతి సంస్థ (MNC) అంటే?","ఒకటి కంటే ఎక్కువ దేశాల్లో ఉత్పత్తిని తన యాజమాన్యంలో లేదా నియంత్రణలో ఉంచుకునే సంస్థ."],["విదేశీ పెట్టుబడి అంటే?","MNC లు ఇతర దేశాల్లో భూమి, భవనాలు, యంత్రాలు, పరికరాలు వంటి ఆస్తులు కొనడానికి పెట్టే పెట్టుబడి."],["ప్రపంచీకరణ అంటే?","వాణిజ్యం, పెట్టుబడులు, సాంకేతికత, ప్రజల రాకపోకల ద్వారా దేశాల మధ్య వేగంగా పెరుగుతున్న అనుసంధానం, ఏకీకరణ."],["సరళీకరణ అంటే?","ప్రభుత్వం విదేశీ వాణిజ్యం, పెట్టుబడులపై పెట్టిన అవరోధాలు, ఆంక్షలను తొలగించడం."],["వాణిజ్య అవరోధాలకు ఉదాహరణలు?","దిగుమతులపై పన్నులు, కోటాలు (దిగుమతుల సంఖ్యపై పరిమితి)."],["WTO లక్ష్యం ఏమిటి?","అంతర్జాతీయ వాణిజ్యాన్ని సరళీకరించడం; అందరు సభ్య దేశాలు పాటించాల్సిన వాణిజ్య నియమాలు రూపొందించడం."],["ప్రపంచీకరణకు తోడ్పడిన ప్రధాన అంశం?","సాంకేతికతలో వేగవంతమైన అభివృద్ధి – రవాణా, సమాచార సాంకేతికత (IT)."],["SEZ లకు ఇచ్చే ప్రోత్సాహకం?","ప్రపంచ స్థాయి సౌకర్యాలు, మొదటి ఐదేళ్లు పన్ను మినహాయింపు."],["ప్రపంచీకరణ వల్ల ఏర్పడిన రెండు భారత MNC లు?","టాటా మోటార్స్, ఇన్ఫోసిస్ (రాన్‌బాక్సీ, ఏషియన్ పెయింట్స్, సుందరం ఫాస్టెనర్స్)."],["ప్రపంచీకరణ వల్ల ఎక్కువగా దెబ్బతిన్నవారు?","చిన్న ఉత్పత్తిదారులు, అవ్యవస్థీకృత కార్మికులు."]],"act":"మీ ఇంట్లో వాడే 10 బ్రాండ్ వస్తువులు (సబ్బు, టూత్‌పేస్ట్, ఫోన్, బిస్కట్లు) జాబితా చేసి – ఏవి MNC లవి, ఏవి భారత కంపెనీలవి, ఏ దేశంలో తయారయ్యాయో ప్యాకెట్‌పై చూసి పట్టిక చేయండి.","kn":"శ్రీ సిటీ (తిరుపతి జిల్లా, తడ – మన గూడూరుకు దగ్గరలో) ఆంధ్రప్రదేశ్‌లోని పెద్ద SEZ / పారిశ్రామిక నగరం – అక్కడ అనేక దేశాల MNC కర్మాగారాలు ఉన్నాయి!","qz":[["గత రెండు దశాబ్దాల ప్రపంచీకరణలో వేగంగా పెరిగిన రాకపోకలు?","వస్తువులు, సేవలు, పెట్టుబడులు","వస్తువులు, సేవలు, ప్రజలు","వస్తువులు, పెట్టుబడులు, ప్రజలు","ప్రజలు మాత్రమే"],["MNC లు పెట్టుబడి పెట్టే అత్యంత సాధారణ మార్గం?","స్థానిక కంపెనీలను కొనడం","కొత్త కర్మాగారాలు పెట్టడం","స్థానిక కంపెనీలతో భాగస్వామ్యం","ప్రభుత్వానికి రుణం"],["ప్రపంచీకరణ వల్ల జీవన పరిస్థితులు మెరుగైనది?","పైవేవీ కాదు (అందరికీ సమానంగా కాదు)","అందరు ప్రజలకు","అభివృద్ధి చెందిన దేశాల ప్రజలకు మాత్రమే","అభివృద్ధి చెందుతున్న దేశాల కార్మికులకు"],["ప్రపంచీకరణ దేశాలను అనుసంధానం చేసి ఉత్పత్తిదారుల మధ్య?","ఎక్కువ పోటీ","తక్కువ పోటీ","పోటీలో మార్పు లేదు","పోటీ ఉండదు"],["దిగుమతుల సంఖ్యపై పరిమితిని ఏమంటారు?","కోటా","సుంకం","రాయితీ","సరళీకరణ"],["భారత్‌లో సరళీకరణ ప్రారంభమైన సంవత్సరం?","1991","1947","2001","1995"],["WTO ఏ దేశాల చొరవతో ప్రారంభమైంది?","అభివృద్ధి చెందిన దేశాలు","అభివృద్ధి చెందుతున్న దేశాలు","ఆఫ్రికా దేశాలు","భారత్, చైనా"],["ఫోర్డ్ మోటార్స్ భారత్‌లో కర్మాగారం పెట్టిన ప్రదేశం?","చెన్నై","పుణె","గుర్గావ్","హోసూరు"],["కార్గిల్ ఫుడ్స్ కొన్న భారత కంపెనీ?","పరఖ్ ఫుడ్స్","అమూల్","ఇన్ఫోసిస్","టాటా మోటార్స్"],["MNC గా ఎదిగిన భారత కంపెనీ?","ఇన్ఫోసిస్","కార్గిల్","ఫోర్డ్","నైక్"],["ప్రపంచీకరణను ఎక్కువగా ప్రోత్సహించిన అంశం?","సాంకేతికతలో అభివృద్ధి","జనాభా పెరుగుదల","యుద్ధాలు","వ్యవసాయం"],["SEZ లలో పన్ను మినహాయింపు కాలం?","మొదటి 5 ఏళ్లు","10 ఏళ్లు","1 సంవత్సరం","శాశ్వతంగా"],["కాల్ సెంటర్ల విస్తరణకు తోడ్పడింది?","సమాచార సాంకేతికత (IT)","దిగుమతి పన్నులు","కోటాలు","వ్యవసాయ రాయితీలు"],["రవి కెపాసిటర్ల కంపెనీ ఎక్కడ ఉంది?","హోసూరు (తమిళనాడు)","చెన్నై","బెంగళూరు","హైదరాబాద్"],["వాణిజ్య అవరోధాలను తొలగించడాన్ని ఏమంటారు?","సరళీకరణ","ప్రైవేటీకరణ","జాతీయీకరణ","రక్షణ విధానం"],["“మార్కెట్ల ఏకీకరణ”కు ప్రధాన కారణం?","విదేశీ వాణిజ్యం","వస్తు మార్పిడి","కోటాలు","స్థానిక ఉత్పత్తి మాత్రమే"]],"wb":{"mis":"విదేశీ వాణిజ్యం (వస్తువుల కొనుగోలు–అమ్మకం) మరియు విదేశీ పెట్టుబడి (ఆస్తుల కొనుగోలు) ఒకటి కాదు. ప్రపంచీకరణ అందరికీ సమానంగా లాభం ఇవ్వలేదు – నైపుణ్యం, సంపద గలవారికే ఎక్కువ. సరళీకరణ అంటే ప్రైవేటీకరణ కాదు.","qz":[],"pg":"110–147","f":"books/10/Class10_Social_Economics_Textbook.pdf","p":116,"lb":"పాఠ్యపుస్తకం","ws":["ఇది చేయండి – వస్త్ర పరిశ్రమలో ఉత్పత్తి విస్తరణ (పుట 114)","ఇవి చేయండి 1 – ఫోర్డ్ మోటార్స్ (పుట 118)","ఇవి చేయండి 2 – వాణిజ్యం, పెట్టుబడి (పుట 122)","ఇవి చేయండి 3 – ప్రపంచీకరణ (పుట 124)","ఇవి చేయండి 4 – IT, ప్రపంచీకరణ (పుట 126)","ఇవి చేయండి 5 – సరళీకరణ, కోటాలు (పుట 128)","ఇవి చేయండి 6 – WTO (పుట 132)","ఇవి చేయండి 7 – ప్రపంచీకరణ ప్రభావం (పుట 134)","ఇవి చేయండి 8 – రవి చిన్న పరిశ్రమ (పుట 136)","ఇవి చేయండి 9 – వస్త్ర పరిశ్రమ కార్మికులు (పుట 140)","అభ్యాసాలు – Exercises (1–12) (పుట 144)","అభ్యాసాలు – Exercise 13, ప్రాజెక్ట్ (పుట 146)"]},"tg":[["ఇది చేయండి – వస్త్ర పరిశ్రమలో ఉత్పత్తి విస్తరణ (పుట 114)",["కంపెనీ కొరియా నుండి పత్తి నారను తెప్పిస్తుంది, తైవాన్‌లో రంగు వేయించి నేయిస్తుంది, జపాన్ నుండి జిప్పులు, బటన్లు కొంటుంది, హాంకాంగ్‌లో డిజైన్ చేయిస్తుంది, థాయ్‌లాండ్‌లో కుట్టించి “Made in Thailand” ట్యాగ్‌తో ప్రపంచమంతా అమ్ముతుంది – ఇలా ఉత్పత్తి అనేక దేశాల్లో విస్తరించి ఉంటుంది."]],["ఇవి చేయండి 1 – ఫోర్డ్ మోటార్స్ (పుట 118)",["1) అవును. ఫోర్డ్ 26 దేశాల్లో ఉత్పత్తిని నియంత్రిస్తుంది; భారత్‌లోనూ కర్మాగారం ఉంది – కాబట్టి MNC.","2) MNC లు ఇతర దేశాల్లో భూమి, భవనాలు, యంత్రాలు వంటి ఆస్తులు కొనడానికి పెట్టే పెట్టుబడే విదేశీ పెట్టుబడి. ఫోర్డ్ భారత్‌లో ₹1700 కోట్లు పెట్టుబడి పెట్టింది.","3) భారత్‌లో పెద్ద జనాభా – కార్లు కొనేవారు ఎక్కువ (పెద్ద మార్కెట్); చౌక శ్రమ, ముడిసరుకులు, విడిభాగాల సరఫరాదారులు – ఉత్పత్తి ఖర్చు తక్కువ. రెండూ కలిసి ఎక్కువ లాభం.","4) (a) భారత్‌లో కార్మికులు, వనరుల ఖర్చు తక్కువ; (b) విడిభాగాలు సరఫరా చేసే స్థానిక తయారీదారులు ఇక్కడే ఉన్నారు – రవాణా ఖర్చు, సమయం ఆదా; (c) భారత్, చైనాలో పెద్ద సంఖ్యలో కొనుగోలుదారులు దగ్గరగా ఉన్నారు.","5) భారత్‌లో తయారైన కార్లు ఇక్కడ అమ్ముతారు, దక్షిణాఫ్రికా, మెక్సికో, బ్రెజిల్, అమెరికాకు ఎగుమతి చేస్తారు; విడిభాగాలను ప్రపంచంలోని ఫోర్డ్ కర్మాగారాలకు పంపుతారు; స్థానిక విడిభాగాల తయారీదారులూ దీనిలో భాగం – ఇలా వేర్వేరు దేశాల ఉత్పత్తి అనుసంధానమవుతుంది.","6) సాధారణ కంపెనీ ఒకే దేశంలో ఉత్పత్తి చేసి అమ్ముతుంది (లేదా ఎగుమతి చేస్తుంది). MNC అనేక దేశాల్లో ఉత్పత్తిని యాజమాన్యం/నియంత్రణలో ఉంచుకుని, చౌకగా ఉన్నచోట ఉత్పత్తి చేసి ప్రపంచమంతా అమ్ముతుంది.","7) అమెరికా, జపాన్, యూరప్ దేశాలు ధనిక దేశాలు – భారీ పెట్టుబడి, ఆధునిక సాంకేతికత, పరిశోధన, పెద్ద కంపెనీలు అక్కడే ఉన్నాయి; ముందుగా పారిశ్రామికీకరణ జరిగింది."]],["ఇవి చేయండి 2 – వాణిజ్యం, పెట్టుబడి (పుట 122)",["1) గతంలో దేశాలను కలిపిన ప్రధాన మార్గం విదేశీ వాణిజ్యం. ఇప్పుడు వాణిజ్యంతో పాటు MNC ల విదేశీ పెట్టుబడులు, ఉత్పత్తి విస్తరణ, సాంకేతికత, సేవల ద్వారా కూడా దేశాలు అనుసంధానమవుతున్నాయి.","2) విదేశీ వాణిజ్యం – ఇతర దేశాలతో వస్తువుల కొనుగోలు, అమ్మకం (ఎగుమతి–దిగుమతి). విదేశీ పెట్టుబడి – MNC లు ఇతర దేశాల్లో భూమి, భవనాలు, యంత్రాలు వంటి ఆస్తులు కొనడం.","3) (a) చైనా ఉక్కు కంపెనీలు – భారత ఉక్కుతో పోటీ పెరిగి, ధరలు తగ్గించుకోవాలి, నష్టపోవచ్చు. (b) భారత ఉక్కు కంపెనీలు – కొత్త మార్కెట్, ఎగుమతులు పెరిగి లాభం, ఉత్పత్తి విస్తరణ. (c) చైనాలో ఉక్కు కొనే పరిశ్రమలు – ఎక్కువ ఎంపిక, తక్కువ ధరకు ఉక్కు, ఉత్పత్తి ఖర్చు తగ్గుతుంది."]],["ఇవి చేయండి 3 – ప్రపంచీకరణ (పుట 124)",["1) MNC లు చౌకగా ఉన్న దేశాల్లో పెట్టుబడి పెట్టి, ఉత్పత్తిని అనేక దేశాలకు విస్తరిస్తాయి; విదేశీ వాణిజ్యంలో పెద్ద భాగం వాటిదే; సాంకేతికతను తీసుకెళ్తాయి – దేశాల మధ్య ఉత్పత్తి, మార్కెట్లను ఏకీకృతం చేస్తాయి.","2) వస్తువుల వాణిజ్యం, సేవల వాణిజ్యం, పెట్టుబడులు, సాంకేతికత బదిలీ, ప్రజల రాకపోకలు (ఉద్యోగాలు, చదువు కోసం వలసలు).","3) (b) ఉత్పత్తిదారుల మధ్య ఎక్కువ పోటీ."]],["ఇవి చేయండి 4 – IT, ప్రపంచీకరణ (పుట 126)",["1) సాంకేతికత పదాలు: ఇంటర్నెట్ ద్వారా పంపడం, టెలికమ్యూనికేషన్ సౌకర్యాలు, కంప్యూటర్‌లో డిజైన్, విమానంలో (by air) పంపడం, ఇంటర్నెట్ ద్వారా వెంటనే డబ్బు బదిలీ (ఇ-బ్యాంకింగ్).","2) IT (టెలికాం, కంప్యూటర్లు, ఇంటర్నెట్) ద్వారా ప్రపంచంలో ఎక్కడి నుండైనా వెంటనే సమాచారం, ఆదేశాలు, డబ్బు పంపవచ్చు; సేవల ఉత్పత్తి (కాల్ సెంటర్లు, డిజైనింగ్) దేశాల మధ్య విస్తరించింది. IT విస్తరణ లేకుండా ప్రపంచీకరణ ఇంత వేగంగా సాధ్యమయ్యేది కాదు."]],["ఇవి చేయండి 5 – సరళీకరణ, కోటాలు (పుట 128)",["1) ప్రభుత్వం విదేశీ వాణిజ్యంపై పెట్టిన అవరోధాలు, ఆంక్షలు (పన్నులు, కోటాలు) తొలగించి వస్తువుల దిగుమతి–ఎగుమతిని స్వేచ్ఛగా అనుమతించడం.","2) ప్రభుత్వం ఉదాహరణకు “ఏడాదికి 1 లక్ష చైనా బొమ్మలు మాత్రమే దిగుమతి” అని కోటా పెడితే, మార్కెట్‌లో చైనా బొమ్మలు పరిమితంగా ఉంటాయి; భారత బొమ్మల తయారీదారులకు రక్షణ లభిస్తుంది. దేశీయ పరిశ్రమ నిలదొక్కుకునే వరకు తాత్కాలికంగా వాడవచ్చు; కానీ ఎప్పటికీ వాడితే వినియోగదారులకు ఎంపిక తగ్గి, దేశీయ ఉత్పత్తిదారులు నాణ్యత మెరుగుపరచుకోరు."]],["ఇవి చేయండి 6 – WTO (పుట 132)",["1) WTO అభివృద్ధి చెందిన దేశాల చొరవతో ప్రారంభమైంది. దాని లక్ష్యం అంతర్జాతీయ వాణిజ్యాన్ని సరళీకరించడం. WTO అన్ని దేశాలకు అంతర్జాతీయ వాణిజ్య నియమాలను రూపొందిస్తుంది, వాటిని పాటిస్తున్నారో లేదో చూస్తుంది. ఆచరణలో దేశాల మధ్య వాణిజ్యం న్యాయంగా లేదు. భారత్ వంటి అభివృద్ధి చెందుతున్న దేశాలు వాణిజ్య అవరోధాలను తొలగించాయి, కానీ అభివృద్ధి చెందిన దేశాలు చాలా సందర్భాల్లో తమ ఉత్పత్తిదారులకు రక్షణ కొనసాగిస్తున్నాయి.","2) అభివృద్ధి చెందిన దేశాలు తమ రైతులకు భారీ రాయితీలు తగ్గించాలి; WTO నియమాలు అన్ని దేశాలకూ ఒకేలా అమలవ్వాలి; అభివృద్ధి చెందుతున్న దేశాలు ఐక్యంగా న్యాయమైన నియమాల కోసం పోరాడాలి; పేద దేశాల చిన్న ఉత్పత్తిదారులకు కొంత రక్షణ అనుమతించాలి.","3) పర్యావరణ హితమైన వస్తువుల (సౌర విద్యుత్, సేంద్రియ సాగు) ఉత్పత్తికి మద్దతు న్యాయమే – సమాజానికి మేలు. కానీ అమెరికా రైతులకు భారీ రాయితీలు ఇచ్చి తక్కువ ధరకు పంటలు ఎగుమతి చేయడం అన్యాయం – పేద దేశాల రైతులు నష్టపోతారు."]],["ఇవి చేయండి 7 – ప్రపంచీకరణ ప్రభావం (పుట 134)",["1) ఎక్కువ ఎంపిక, మంచి నాణ్యత, తక్కువ ధరలు (మొబైల్ ఫోన్లు, టీవీలు, కార్లు); కొత్త ఉద్యోగాలు; ముడిసరుకులు సరఫరా చేసే స్థానిక కంపెనీలు అభివృద్ధి.","2) అవును – ఎక్కువ పెట్టుబడి, ఉద్యోగాలు, ఆధునిక సాంకేతికత, ఎగుమతుల ద్వారా విదేశీ మారకద్రవ్యం, దేశ ప్రతిష్ఠ పెరుగుతాయి; ప్రజలకు ఆదాయం పెరుగుతుంది.","3) విదేశీ పెట్టుబడి వల్ల కొత్త పరిశ్రమలు, ఉద్యోగాలు, ఆధునిక సాంకేతికత, మూలధనం, ఎగుమతులు, ఆర్థిక వృద్ధి – అందుకే ప్రభుత్వాలు ఆకర్షిస్తాయి.","4) SEZ ల వ్యతిరేకులు: భూములు కోల్పోయే రైతులు, కూలీలు (జీవనోపాధి నష్టం), పర్యావరణవేత్తలు (వ్యవసాయ భూమి, అడవుల నాశనం), కార్మిక సంఘాలు (కార్మిక చట్టాల సడలింపు), ఆర్థికవేత్తలు (పన్ను మినహాయింపుల వల్ల ప్రభుత్వ ఆదాయ నష్టం)."]],["ఇవి చేయండి 8 – రవి చిన్న పరిశ్రమ (పుట 136)",["1) 2001లో WTO ఒప్పందం ప్రకారం కెపాసిటర్ల దిగుమతులపై ఆంక్షలు తొలగాయి. MNC బ్రాండ్ల పోటీతో భారత టీవీ కంపెనీలు MNC లకు కూర్పు (assembling) పనులకే మారాయి; కెపాసిటర్లు కొన్నా సగం ధరకే వచ్చే దిగుమతులను ఇష్టపడ్డాయి. ఫలితంగా రవి 2000 సంవత్సరంలో కంటే సగం కంటే తక్కువ ఉత్పత్తి చేస్తున్నాడు; 20 మంది కార్మికులకు బదులు 7 మందే ఉన్నారు; అతని స్నేహితుల యూనిట్లు (హైదరాబాద్, చెన్నై) మూతపడ్డాయి.","2) ఆపకూడదు. ప్రభుత్వం తాత్కాలిక మద్దతు, సాంకేతికత, చౌక రుణాలు ఇస్తే, రవి వంటి వారు నాణ్యత పెంచి, ఖర్చు తగ్గించుకుని పోటీ పడవచ్చు; లేకపోతే ఉపాధి నష్టం.","3) (a) మంచి రోడ్లు, విద్యుత్, నీరు, ముడిసరుకులు, మార్కెటింగ్, సమాచారం ఉంటే ఉత్పత్తి ఖర్చు తగ్గి, సమయానికి సరఫరా చేయగలరు; (b) ఆధునిక సాంకేతికత నాణ్యత, ఉత్పాదకత పెంచుతుంది; (c) సకాలంలో చౌక రుణాలు పెట్టుబడికి తోడ్పడతాయి.","MNC లు ఈ మౌలిక సదుపాయాల్లో పెద్దగా పెట్టుబడి పెట్టవు – అవి లాభం కోసమే పనిచేస్తాయి; ప్రజా సౌకర్యాల్లో త్వరిత లాభం ఉండదు. కాబట్టి ప్రభుత్వ పాత్ర ముఖ్యం – రోడ్లు, విద్యుత్, రుణాలు అందించడం దాని బాధ్యత.","ఇతర చర్యలు: చిన్న పరిశ్రమలకు పన్ను రాయితీలు, నైపుణ్య శిక్షణ, పారిశ్రామిక క్లస్టర్లు, ప్రభుత్వ కొనుగోళ్లలో ప్రాధాన్యం, అవసరమైతే తాత్కాలిక దిగుమతి సుంకాలు."]],["ఇవి చేయండి 9 – వస్త్ర పరిశ్రమ కార్మికులు (పుట 140)",["1) కార్మికులు – శాశ్వత ఉద్యోగాలు పోయి తాత్కాలిక ఉద్యోగాలు, తక్కువ వేతనాలు, ఎక్కువ గంటలు, రాత్రి షిఫ్టులు; భారత ఎగుమతిదారులు – MNC ఆర్డర్ల కోసం ఖర్చులు తగ్గించుకోవాలి, లాభాలు తగ్గాయి; విదేశీ MNC లు – చౌకగా ఉత్పత్తులు కొని ఎక్కువ లాభాలు పొందాయి.","2) (a) ప్రభుత్వం: కార్మిక చట్టాల అమలు, కనీస వేతనం, సామాజిక భద్రత; (b) ఎగుమతి కర్మాగార యజమానులు: న్యాయమైన వేతనం, నిర్ణీత గంటలు, సురక్షిత పని పరిస్థితులు; (c) MNC లు: సరఫరాదారులకు న్యాయమైన ధర, కార్మిక ప్రమాణాల పర్యవేక్షణ; (d) కార్మికులు: సంఘాలుగా ఏర్పడి హక్కుల కోసం పోరాడటం, నైపుణ్యాలు పెంచుకోవడం.","3) యజమానుల దృష్టి: పోటీ తీవ్రంగా ఉంది, డిమాండ్ బట్టి కార్మికులను నియమించుకునే/తొలగించే స్వేచ్ఛ కావాలి – ఖర్చు తగ్గి, ఆర్డర్లు వస్తాయి. కార్మికుల దృష్టి: ఉద్యోగ భద్రత, న్యాయమైన వేతనం, సెలవులు, ఆరోగ్య–సామాజిక భద్రత కావాలి; సరళ చట్టాలు దోపిడీకి దారితీస్తాయి."]],["అభ్యాసాలు – Exercises (1–12) (పుట 144)",["1) ప్రపంచీకరణ అంటే దేశాలు వాణిజ్యం, పెట్టుబడులు, సాంకేతికత, సేవలు, ప్రజల రాకపోకల ద్వారా ఒకదానితో ఒకటి వేగంగా అనుసంధానమై, ఒకే ప్రపంచ మార్కెట్‌లా మారడం. ఉదా: మన ఫోన్ విడిభాగాలు అనేక దేశాల్లో తయారై, భారత్‌లో కూర్పు జరగడం.","2) స్వాతంత్ర్యం తర్వాత దేశీయ ఉత్పత్తిదారులను (కొత్త పరిశ్రమలను) విదేశీ పోటీ నుండి రక్షించడానికి అవరోధాలు పెట్టారు. 1991 నాటికి భారత పరిశ్రమలు బలపడ్డాయని, ప్రపంచ పోటీ వల్ల నాణ్యత మెరుగవుతుందని భావించి, అంతర్జాతీయ సంస్థల మద్దతుతో వాటిని తొలగించారు.","3) డిమాండ్‌ను బట్టి కార్మికులను తాత్కాలికంగా నియమించుకుని, అవసరం లేనప్పుడు తొలగించవచ్చు; ఏడాదంతా జీతాలు, ప్రయోజనాలు ఇవ్వనక్కర్లేదు – శ్రమ ఖర్చు తగ్గి పోటీ సామర్థ్యం పెరుగుతుంది.","4) సొంత కర్మాగారాలు నెలకొల్పడం; స్థానిక కంపెనీలతో సంయుక్త ఉత్పత్తి; స్థానిక కంపెనీలను కొనడం (కార్గిల్ – పరఖ్); చిన్న ఉత్పత్తిదారులకు ఆర్డర్లు ఇచ్చి తమ బ్రాండ్‌తో అమ్మడం (వస్త్రాలు, పాదరక్షలు, క్రీడా వస్తువులు).","5) తమ ఉత్పత్తులు అమ్ముకోవడానికి, పెట్టుబడులు పెట్టడానికి పెద్ద మార్కెట్లు, చౌక శ్రమ, వనరులు కావాలి కాబట్టి. బదులుగా అభివృద్ధి చెందుతున్న దేశాలు అడగాల్సినవి: అభివృద్ధి చెందిన దేశాలూ తమ అవరోధాలు, వ్యవసాయ రాయితీలు తొలగించాలి; సాంకేతికత బదిలీ; న్యాయమైన WTO నియమాలు; కార్మికుల రాకపోకలకు స్వేచ్ఛ.","6) ప్రపంచీకరణ అందరికీ సమానంగా లాభం ఇవ్వలేదు. నైపుణ్యం, విద్య, సంపద గలవారు, పెద్ద కంపెనీలు, IT ఉద్యోగులు, ధనిక వినియోగదారులు లాభపడ్డారు. చిన్న ఉత్పత్తిదారులు (బొమ్మలు, బ్యాటరీలు, కెపాసిటర్లు), అవ్యవస్థీకృత కార్మికులు, చిన్న రైతులు నష్టపోయారు.","7) వాణిజ్య–పెట్టుబడి అవరోధాలు తొలగడంతో వస్తువులు సులభంగా దిగుమతి–ఎగుమతి అవుతున్నాయి; MNC లు ఫ్యాక్టరీలు, కార్యాలయాలు పెట్టగలుగుతున్నాయి – దీనితో దేశాల మధ్య ఉత్పత్తి, మార్కెట్ల ఏకీకరణ వేగవంతమైంది.","8) విదేశీ వాణిజ్యం వల్ల ఒక దేశ వస్తువులు ఇతర దేశ మార్కెట్లకు చేరి, ధరలు సమీపిస్తాయి. ఉదా: దక్షిణ కొరియా/చైనా మొబైల్ ఫోన్లు భారత మార్కెట్‌లో భారత ఫోన్లతో పోటీపడటం; ఆంధ్ర రొయ్యలు అమెరికా మార్కెట్లలో అమ్ముడవడం – రెండు దేశాల మార్కెట్లు అనుసంధానమవుతాయి.","9) 20 ఏళ్ల తర్వాత: ఇంకా ఎక్కువ ఆన్‌లైన్ వాణిజ్యం, కృత్రిమ మేధ (AI), రోబోటిక్స్, ఇంటి నుండే ప్రపంచ ఉద్యోగాలు, ప్రపంచ బ్రాండ్లు, ఎక్కువ ప్రయాణాలు; కానీ అసమానతలు, ఉద్యోగ భద్రత, పర్యావరణ సమస్యలు పెరగవచ్చు – కారణం సాంకేతికత, ఇంటర్నెట్ వేగంగా విస్తరిస్తుండటం.","10) ఇద్దరిలోనూ కొంత నిజం ఉంది. ప్రపంచీకరణ వినియోగదారులకు ఎంపిక, కొన్ని రంగాల్లో (IT, ఆటోమొబైల్) ఉద్యోగాలు, భారత MNC లను ఇచ్చింది; కానీ చిన్న ఉత్పత్తిదారులు, కార్మికులు నష్టపోయారు. కాబట్టి ప్రభుత్వం న్యాయమైన ప్రపంచీకరణ కోసం చిన్న ఉత్పత్తిదారులకు మద్దతు, కార్మిక చట్టాల అమలు చేయాలి.","11) ప్రపంచీకరణ; విదేశీ వాణిజ్యం (foreign trade); భారత్‌లో పెద్ద మార్కెట్, చౌక శ్రమ, నైపుణ్యం గల కార్మికులు, సరళీకరణ విధానాలు ఉన్నాయి కాబట్టి; దిగుమతులు (imports), విదేశీ పెట్టుబడులు; పోటీ (competition).","12) (i) – (b) వస్త్రాలు, పాదరక్షలు, క్రీడా వస్తువులు; (ii) – (e) వాణిజ్య అవరోధాలు; (iii) – (d) టాటా మోటార్స్, ఇన్ఫోసిస్, రాన్‌బాక్సీ; (iv) – (c) కాల్ సెంటర్లు; (v) – (a) ఆటోమొబైల్స్."]],["అభ్యాసాలు – Exercise 13, ప్రాజెక్ట్ (పుట 146)",["13) (i) (b) వస్తువులు, సేవలు, పెట్టుబడులు (ii) (b) స్థానిక కంపెనీలను కొనడం (iii) (d) పైవేవీ కాదు (అందరికీ సమానంగా మెరుగుపడలేదు)","ప్రాజెక్ట్ I: సబ్బులు (HUL – లక్స్, లైఫ్‌బాయ్), టూత్‌పేస్ట్ (కోల్‌గేట్), పానీయాలు (కోకా-కోలా, పెప్సీ), ఫోన్లు (సామ్‌సంగ్, యాపిల్) – MNC లవి; అమూల్, పతంజలి, టాటా – భారత కంపెనీలవి.","ప్రాజెక్ట్ II: ఉదా: ఆంధ్రప్రదేశ్ రొయ్యల/ఆక్వా పరిశ్రమ – ఉత్పత్తిదారులు, ఎగుమతి (అమెరికా, యూరప్), MNC లు, పోటీ, పని పరిస్థితులు, 15 ఏళ్ల మార్పులు, సమస్యలు – చిత్రాలు, ఇంటర్వ్యూలతో నివేదిక."]]]},{"id":"ec5","no":17,"t":"వినియోగదారుల హక్కులు (Consumer Rights)","m":[11],"ty":"Economics – Chapter 5","by":"సాంఘిక శాస్త్రం – అర్థశాస్త్రం 10వ తరగతి (పుటలు 150–179)","th":"మార్కెట్‌లో వినియోగదారుల దోపిడీ, వినియోగదారుల ఉద్యమం, COPRA 1986, వినియోగదారుల హక్కులు, వినియోగదారుల కమిషన్లు, ISI–Agmark–Hallmark","sum":"మార్కెట్‌లో వినియోగదారులు తక్కువ తూకం, కొలతలు, కల్తీ, నాసిరకం వస్తువులు, MRP కంటే ఎక్కువ ధర, తప్పుడు సమాచారం, అమ్మిన తర్వాత సేవ లేకపోవడం వంటి దోపిడీకి గురవుతారు. ఉత్పత్తిదారులు పెద్ద కంపెనీలు, శక్తిమంతులు; వినియోగదారులు చెల్లాచెదురుగా, బలహీనంగా ఉంటారు – కాబట్టి నియమాలు, నిబంధనలు అవసరం. ఆహార కొరత, నిల్వ (హోర్డింగ్), బ్లాక్ మార్కెటింగ్, ఆహారం–వంటనూనెల కల్తీ నుండి 1960ల్లో భారత్‌లో వినియోగదారుల ఉద్యమం వ్యవస్థీకృత రూపం దాల్చింది; 1970ల వరకు వ్యాసాలు, ప్రదర్శనలు; తర్వాత వినియోగదారుల సంఘాలు పెరిగాయి. దీని ఫలితంగా 1986లో వినియోగదారుల రక్షణ చట్టం (COPRA) వచ్చింది – డిసెంబర్ 24 జాతీయ వినియోగదారుల దినోత్సవం. 1985లో ఐక్యరాజ్యసమితి వినియోగదారుల రక్షణ మార్గదర్శకాలు; కన్స్యూమర్స్ ఇంటర్నేషనల్ – 100+ దేశాల్లో 200+ సంస్థల సమాఖ్య. వినియోగదారుల హక్కులు: భద్రత హక్కు (రెజి మాథ్యూ కేసు – తప్పు మత్తుమందు), సమాచార హక్కు (పదార్థాలు, ధర, బ్యాచ్ నంబర్, తయారీ–గడువు తేదీ, చిరునామా; RTI చట్టం 2005 – ప్రభుత్వ శాఖల సమాచారం), ఎంపిక హక్కు (అభిరామి – కోచింగ్ ఫీజు వాపసు; షరతులతో బలవంతపు కొనుగోలు తప్పు), పరిహారం పొందే హక్కు (redressal – ప్రకాష్ మనీ ఆర్డర్ కేసు), ప్రాతినిధ్య హక్కు, వినియోగదారుల విద్య హక్కు. COPRA కింద మూడంచెల న్యాయ వ్యవస్థ: జిల్లా వినియోగదారుల వివాద పరిష్కార కమిషన్ (₹1 కోటి వరకు), రాష్ట్ర కమిషన్ (₹1–10 కోట్లు), జాతీయ కమిషన్ (₹10 కోట్లకు మించి); లాయర్ లేకుండానే, ఆన్‌లైన్‌లోనూ ఫిర్యాదు చేయవచ్చు. ప్రమాణ ముద్రలు: ISI (BIS), Agmark (వ్యవసాయ ఉత్పత్తులు), Hallmark (బంగారు ఆభరణాలు), +F (ఆహార బలవర్థకం). LPG సిలిండర్లు, ఆహార రంగులు, సిమెంట్, ప్యాకేజ్డ్ తాగునీరు వంటి వాటికి ధృవీకరణ తప్పనిసరి. వినియోగదారుల చైతన్యం, చురుకైన భాగస్వామ్యం ద్వారానే ఉద్యమం విజయవంతమవుతుంది.","pts":["దోపిడీ రూపాలు: తక్కువ తూకం/కొలత, కల్తీ, నాసిరకం వస్తువులు, MRP కంటే ఎక్కువ ధర, తప్పుడు ప్రకటనలు, అమ్మిన తర్వాత సేవ లేకపోవడం, నకిలీ వస్తువులు.","కారణాలు: ఉత్పత్తిదారులు బలవంతులు, వినియోగదారులు అసంఘటితం; పరిమిత సమాచారం, పోటీ లేకపోవడం, అవగాహన లోపం, నియమాల అమలు బలహీనం.","వినియోగదారుల ఉద్యమం: 1960ల్లో వ్యవస్థీకృత రూపం (ఆహార కొరత, నిల్వ, బ్లాక్ మార్కెట్, కల్తీ); ఫలితం – COPRA 1986.","డిసెంబర్ 24 – జాతీయ వినియోగదారుల దినోత్సవం (1986లో పార్లమెంటు COPRA ను ఆమోదించిన రోజు).","భద్రత హక్కు: ప్రాణాలకు, ఆస్తికి హాని చేసే వస్తుసేవల నుండి రక్షణ (ప్రెషర్ కుక్కర్ సేఫ్టీ వాల్వ్, విద్యుత్ ఉపకరణాలు).","సమాచార హక్కు: పదార్థాలు, ధర (MRP), బ్యాచ్ నంబర్, తయారీ–గడువు తేదీ, తయారీదారు చిరునామా, వాడే విధానం, దుష్ప్రభావాలు.","RTI చట్టం (అక్టోబర్ 2005): ప్రభుత్వ శాఖల పనితీరుపై పౌరులకు సమాచారం పొందే హక్కు (అమృత ఉద్యోగ ఫలితం కేసు).","ఎంపిక హక్కు: వస్తువు/సేవ ఎంచుకునే స్వేచ్ఛ; బలవంతంగా వేరే వస్తువు కొనిపించడం తప్పు (గ్యాస్ కనెక్షన్‌తో స్టవ్).","పరిహారం హక్కు (redressal): అన్యాయమైన వ్యాపార పద్ధతులు, దోపిడీపై ఫిర్యాదు చేసి నష్టపరిహారం పొందడం.","ప్రాతినిధ్య హక్కు: వినియోగదారుల కమిషన్లలో తమ వాదన వినిపించడం; వినియోగదారుల సంఘాలు ప్రాతినిధ్యం వహిస్తాయి.","మూడంచెల కమిషన్లు: జిల్లా (₹1 కోటి వరకు), రాష్ట్ర (₹1–10 కోట్లు), జాతీయ (₹10 కోట్లకు పైన); అప్పీలు పై స్థాయికి.","ప్రమాణ ముద్రలు: ISI – BIS (విద్యుత్ ఉపకరణాలు, LPG, సిమెంట్); Agmark – వ్యవసాయ ఉత్పత్తులు (నూనెలు, తృణధాన్యాలు, తేనె); Hallmark – బంగారు ఆభరణాలు (BIS); +F – బలవర్థక ఆహారం.","వినియోగదారుల బాధ్యతలు: బిల్లు తీసుకోవడం, ప్రమాణ ముద్రలు, గడువు తేదీ చూడటం, వారంటీ కార్డు, అవసరమైతే ఫిర్యాదు చేయడం, సంఘాలుగా ఏర్పడటం.","కన్స్యూమర్స్ ఇంటర్నేషనల్: 100+ దేశాల 200+ వినియోగదారుల సంస్థల సమాఖ్య; 1985 – UN వినియోగదారుల రక్షణ మార్గదర్శకాలు."],"w":[["వినియోగదారుడు","Consumer"],["దోపిడీ","Exploitation"],["కల్తీ","Adulteration"],["నిల్వ చేయడం","Hoarding"],["నల్లబజారు","Black marketing"],["గరిష్ఠ చిల్లర ధర","Maximum Retail Price (MRP)"],["వినియోగదారుల రక్షణ చట్టం","Consumer Protection Act, 1986 (COPRA)"],["భద్రత హక్కు","Right to safety"],["సమాచార హక్కు","Right to information"],["ఎంపిక హక్కు","Right to choose"],["పరిహారం కోరే హక్కు","Right to seek redressal"],["ప్రాతినిధ్య హక్కు","Right to represent"],["వినియోగదారుల వివాద పరిష్కార కమిషన్","Consumer Disputes Redressal Commission"],["వినియోగదారుల రక్షణ మండలి","Consumer protection council / forum"],["ప్రమాణీకరణ","Standardisation"],["భారతీయ ప్రమాణాల సంస్థ","Bureau of Indian Standards (BIS)"]],"gr":{"t":"ముఖ్య తేదీలు & వాస్తవాలు","p":["1960లు – వ్యవస్థీకృత వినియోగదారుల ఉద్యమం; 1985 – UN మార్గదర్శకాలు; 1986 – COPRA (డిసెంబర్ 24); 2005 అక్టోబర్ – RTI చట్టం","కమిషన్లు: జిల్లా ≤ ₹1 కోటి | రాష్ట్ర ₹1–10 కోట్లు | జాతీయ > ₹10 కోట్లు","దేశంలో 2000+ వినియోగదారుల సంఘాలు – వాటిలో 50–60 మాత్రమే బాగా వ్యవస్థీకృతమైనవి","ధృవీకరణ తప్పనిసరి: LPG సిలిండర్లు, ఆహార రంగులు–సంకలితాలు, సిమెంట్, ప్యాకేజ్డ్ తాగునీరు","కేసులు: రెజి మాథ్యూ (భద్రత), అభిరామి (ఎంపిక/పరిహారం), అమృత (RTI), ప్రకాష్ (మనీ ఆర్డర్ – పరిహారం)"]},"qa":[["వినియోగదారుల రక్షణ చట్టం ఎప్పుడు వచ్చింది?","1986లో (డిసెంబర్ 24)."],["జాతీయ వినియోగదారుల దినోత్సవం ఎప్పుడు?","డిసెంబర్ 24."],["వినియోగదారుల ఉద్యమం పుట్టడానికి కారణాలు?","ఆహార కొరత, నిల్వ, నల్లబజారు, ఆహారం–వంటనూనెల కల్తీ, అన్యాయ వ్యాపార పద్ధతులు."],["ISI ముద్రను ఇచ్చే సంస్థ?","భారతీయ ప్రమాణాల సంస్థ (BIS)."],["Agmark ఏ వస్తువులకు?","వ్యవసాయ ఉత్పత్తులు – వంటనూనెలు, తృణధాన్యాలు, తేనె, పప్పులు."],["Hallmark ఏ వస్తువులకు?","బంగారు, వెండి ఆభరణాలు."],["జిల్లా వినియోగదారుల కమిషన్ పరిష్కరించే కేసుల పరిమితి?","₹1 కోటి వరకు."],["RTI చట్టం ఏమి నిర్ధారిస్తుంది?","ప్రభుత్వ శాఖల పనితీరుపై పౌరులకు అన్ని సమాచారం పొందే హక్కు."],["ఆరు వినియోగదారుల హక్కులు?","భద్రత, సమాచారం, ఎంపిక, పరిహారం, ప్రాతినిధ్యం, వినియోగదారుల విద్య."],["ప్యాకెట్‌పై ఉండాల్సిన సమాచారం?","పదార్థాలు, MRP, బ్యాచ్ నంబర్, తయారీ–గడువు తేదీ, తయారీదారు చిరునామా, బరువు."]],"act":"మీ ఇంట్లోని 5 ప్యాకెట్ వస్తువులపై MRP, తయారీ–గడువు తేదీ, బ్యాచ్ నంబర్, ISI/Agmark/FSSAI ముద్రలు, కస్టమర్ కేర్ నంబర్ ఉన్నాయో పట్టిక చేయండి. “జాగ్రత్తగల వినియోగదారుడే సురక్షిత వినియోగదారుడు” అనే నినాదంతో పోస్టర్ గీయండి.","kn":"జాతీయ వినియోగదారుల హెల్ప్‌లైన్ 1915 (టోల్ ఫ్రీ) – ఫోన్ లేదా “e-Daakhil” వెబ్‌సైట్ ద్వారా ఇంటి నుండే ఫిర్యాదు చేయవచ్చు! మార్చి 15 ప్రపంచ వినియోగదారుల హక్కుల దినోత్సవం.","qz":[["భారత్‌లో వినియోగదారుల రక్షణ చట్టం (COPRA) వచ్చిన సంవత్సరం?","1986","1947","2005","1991"],["జాతీయ వినియోగదారుల దినోత్సవం?","డిసెంబర్ 24","మార్చి 15","అక్టోబర్ 2","జనవరి 26"],["ఉత్పత్తి పదార్థాల వివరాలు పొందడం ఏ హక్కు?","సమాచార హక్కు","భద్రత హక్కు","ఎంపిక హక్కు","ప్రాతినిధ్య హక్కు"],["Agmark ధృవీకరణ దేనికి?","వంటనూనెలు, తృణధాన్యాలు","బంగారు ఆభరణాలు","విద్యుత్ ఉపకరణాలు","మందులు"],["స్కూటర్ ఇంజన్ లోపంతో ప్రమాదం – ఏ హక్కు?","భద్రత హక్కు","సమాచార హక్కు","ఎంపిక హక్కు","విద్య హక్కు"],["వస్తువులు, సేవలకు ప్రమాణాలు రూపొందించే సంస్థ?","భారతీయ ప్రమాణాల సంస్థ (BIS)","Agmark","కన్స్యూమర్స్ ఇంటర్నేషనల్","RBI"],["జిల్లా వినియోగదారుల కమిషన్ పరిష్కరించే క్లెయిమ్‌లు?","₹1 కోటి వరకు","₹10 కోట్ల వరకు","₹10 కోట్లకు పైగా","₹1 లక్ష వరకు"],["Hallmark ఏ వస్తువుల ప్రమాణీకరణకు?","ఆభరణాలు","వంటనూనెలు","సిమెంట్","LPG సిలిండర్లు"],["RTI చట్టం వచ్చిన సంవత్సరం?","2005","1986","2019","1995"],["వినియోగదారుల సంస్థల ప్రపంచ స్థాయి సమాఖ్య?","కన్స్యూమర్స్ ఇంటర్నేషనల్","WTO","UNDP","BIS"],["భారత్‌లో వ్యవస్థీకృత వినియోగదారుల ఉద్యమం ప్రారంభమైన దశాబ్దం?","1960లు","1940లు","1980లు","2000లు"],["ఆహారంలో ముఖ్య పోషకాలు కలపడాన్ని ఏమంటారు?","ఆహార బలవర్థకం (Food fortification)","కల్తీ","ప్రమాణీకరణ","నిల్వ"],["కేసు కొట్టివేస్తే జిల్లా కమిషన్ తర్వాత అప్పీలు ఎక్కడ?","రాష్ట్ర కమిషన్","సుప్రీం కోర్టు నేరుగా","పోలీసు స్టేషన్","పంచాయతీ"],["రెజి మాథ్యూ కేసు ఏ హక్కుకు ఉదాహరణ?","భద్రత హక్కు","ఎంపిక హక్కు","సమాచార హక్కు","ప్రాతినిధ్య హక్కు"],["కిందివాటిలో ధృవీకరణ తప్పనిసరి అయిన వస్తువు?","LPG సిలిండర్","పుస్తకం","బట్టలు","చెప్పులు"],["COPRA ఏమిటి?","వస్తువులు, సేవలు రెండింటికీ వర్తిస్తుంది","వస్తువులకు మాత్రమే","సేవలకు మాత్రమే","ప్రభుత్వ సేవలకు మాత్రమే"]],"wb":{"mis":"COPRA వస్తువులకే కాదు, సేవలకూ (వైద్యం, బ్యాంకు, టెలిఫోన్, కోచింగ్) వర్తిస్తుంది. ఫిర్యాదుకు ఎప్పుడూ జిల్లా కమిషన్ కాదు – క్లెయిమ్ విలువను బట్టి జిల్లా/రాష్ట్ర/జాతీయ. చిన్న నష్టమైనా ఫిర్యాదు చేయవచ్చు; లాయర్ తప్పనిసరి కాదు.","qz":[],"pg":"150–179","f":"books/10/Class10_Social_Economics_Textbook.pdf","p":156,"lb":"పాఠ్యపుస్తకం","ws":["ఇవి చేయండి 1 – మార్కెట్‌లో దోపిడీ (పుట 154)","ఇవి చేయండి 2 – వినియోగదారుల సంఘాలు (పుట 156)","ఇవి చేయండి 3 – భద్రతా నియమాలు (పుట 158)","ఇవి చేయండి 4 – MRP, సమాచారం, RTI (పుట 162)","ఇది చేయండి – ప్రకటనలు (పుట 164)","ఇది చేయండి – అరిత కేసు (సరైన క్రమం) (పుట 168)","ఇవి చేయండి 5 – హక్కులు, ప్రమాణాలు (పుట 172)","అభ్యాసాలు – Exercises (1–12) (పుట 174)","అభ్యాసాలు – Exercise 13, ప్రాజెక్ట్‌లు (పుట 176)"]},"tg":[["ఇవి చేయండి 1 – మార్కెట్‌లో దోపిడీ (పుట 154)",["1) తక్కువ తూకం, కొలతలు; కల్తీ (నూనె, పాలు, నెయ్యి); నాసిరకం, లోపభూయిష్ట వస్తువులు; MRP కంటే ఎక్కువ ధర; గడువు ముగిసిన వస్తువులు; తప్పుడు ప్రకటనలు, అసంపూర్ణ సమాచారం; అమ్మిన తర్వాత సేవ లేకపోవడం; నకిలీ బ్రాండ్లు; బిల్లు ఇవ్వకపోవడం.","2) ఉదా: కూరగాయల వ్యాపారి తూకపు రాయి కింద అయస్కాంతం / తక్కువ బరువు; చల్లటి పానీయానికి “కూలింగ్ చార్జ్” పేరుతో MRP కంటే ఎక్కువ వసూలు; కొత్త ఫోన్ వారంటీలో రిపేర్ చేయకపోవడం.","3) ప్రభుత్వం: వినియోగదారుల రక్షణ చట్టాలు చేసి కఠినంగా అమలు చేయడం, తూనికలు–కొలతల తనిఖీలు, ఆహార కల్తీ నియంత్రణ, ప్రమాణాల ధృవీకరణ (ISI, Agmark), వినియోగదారుల కమిషన్లు, అవగాహన ప్రచారం (“జాగో గ్రాహక్ జాగో”)."]],["ఇవి చేయండి 2 – వినియోగదారుల సంఘాలు (పుట 156)",["1) వార్తాపత్రికల్లో వ్యాసాలు, ప్రదర్శనలు, ర్యాలీలు; రేషన్ దుకాణాలు, బస్సుల్లో రద్దీపై పర్యవేక్షణ; ఫిర్యాదులు నమోదు చేసి కోర్టుల్లో కేసులు వేయడం; వినియోగదారులకు మార్గదర్శనం; చట్టం కోసం ప్రభుత్వంపై ఒత్తిడి.","2) నియమాల అమలు బలహీనంగా ఉండటం, అవినీతి, తనిఖీ అధికారులు తక్కువ, వినియోగదారులకు అవగాహన లేకపోవడం, ఫిర్యాదు ప్రక్రియ ఖర్చుతో–ఆలస్యంతో కూడుకోవడం, వ్యాపారుల లాభాపేక్ష."]],["ఇవి చేయండి 3 – భద్రతా నియమాలు (పుట 158)",["(a) LPG సిలిండర్ – ISI ముద్ర, లీకేజీ పరీక్ష, సరైన బరువు, సేఫ్టీ క్యాప్, గడువు (test date) తేదీ. (b) సినిమా థియేటర్ – అగ్నిమాపక పరికరాలు, అత్యవసర ద్వారాలు, సరైన విద్యుత్ వైరింగ్, వెంటిలేషన్. (c) సర్కస్ – సేఫ్టీ నెట్లు, జంతువుల నియంత్రణ, బలమైన గుడారం, ప్రథమ చికిత్స. (d) మందులు – గడువు తేదీ, మోతాదు, దుష్ప్రభావాల సమాచారం, ప్రిస్క్రిప్షన్ నిబంధన, సరైన నిల్వ. (e) వంటనూనె – కల్తీ లేకపోవడం, Agmark/FSSAI ముద్ర, సీల్డ్ ప్యాక్. (f) పెళ్లి పందిరి – అగ్ని నిరోధక వస్త్రం, అగ్నిమాపక పరికరాలు, సురక్షిత విద్యుత్, బలమైన నిర్మాణం. (g) ఎత్తైన భవనం – నిర్మాణ భద్రత, అగ్నిమాపక వ్యవస్థ, అత్యవసర మెట్లు, లిఫ్ట్ నిర్వహణ, భూకంప నిరోధకత.","2) ఉదా: నాసిరకం ప్రెషర్ కుక్కర్ పేలి గాయం; కొత్త ఇస్త్రీ పెట్టె వల్ల విద్యుత్ షాక్; కల్తీ నూనెతో అనారోగ్యం – ఇలాంటి సందర్భాల్లో బాధ్యత ఉత్పత్తిదారుదే."]],["ఇవి చేయండి 4 – MRP, సమాచారం, RTI (పుట 162)",["1) MRP కంటే ఎక్కువ: దుకాణదారుని మోసం, “కూలింగ్ చార్జ్”, కొరత ఉన్నప్పుడు. తక్కువ: పోటీ, తగ్గింపు అమ్మకాలు, గడువు దగ్గరపడటం, పెద్ద దుకాణాల ఆఫర్లు. అవును – MRP కంటే ఎక్కువ వసూలు చట్టవిరుద్ధం; వినియోగదారుల సంఘాలు ఫిర్యాదు చేయాలి, అవగాహన కల్పించాలి.","2) ఉపయోగాలు: పదార్థాలు (అలర్జీ ఉన్నవారికి), గడువు తేదీ (భద్రత), MRP (మోసం నివారణ), బరువు, తయారీదారు చిరునామా (ఫిర్యాదుకు). ఇంకా ఉండాల్సినవి: దుష్ప్రభావాలు, కస్టమర్ కేర్ నంబర్, పోషక విలువలు తెలుగులో కూడా, నిల్వ విధానం.","3) ఏకీభవిస్తాను. RTI ద్వారా రోడ్లు, నీరు, ఆసుపత్రులకు ఎంత నిధులు మంజూరు చేశారు, ఎంత ఖర్చు చేశారు, పని ఎందుకు ఆగిందో అధికారులను ప్రశ్నించి సమాచారం పొందవచ్చు – అధికారుల జవాబుదారీతనం పెరుగుతుంది."]],["ఇది చేయండి – ప్రకటనలు (పుట 164)",["నిజంగా ప్రయోజనం: “ప్రతి 500 గ్రా. ప్యాక్‌లో 15 గ్రా. ఎక్కువ” (ధర అదే అయితే), “₹2000 బూట్లు కొంటే ₹500 బూట్లు ఉచితం” (అవసరమైతే). మిగతావి (స్క్రాచ్ అండ్ విన్, బంగారు నాణెం, సంవత్సరాంతపు బహుమతి, చాక్లెట్) ఎక్కువగా ఆకర్షణ వలలు – అనవసర కొనుగోళ్లకు దారితీస్తాయి; ధర, నాణ్యత పోల్చి కొనాలి."]],["ఇది చేయండి – అరిత కేసు (సరైన క్రమం) (పుట 168)",["(g) గోడ గడియారం కొన్నది → (c) లోపం గల వస్తువు అని గుర్తించింది → (e) డీలర్, బ్రాంచ్ ఆఫీసుకు ఫిర్యాదు – ఫలితం లేదు → (a) జిల్లా కమిషన్‌లో కేసు వేసింది → (b) నిపుణుడిని (లాయర్) నియమించుకుంది → (d) కమిషన్ విచారణలకు హాజరైంది → (f) బిల్లు, వారంటీ చూపమన్నారు → (h) కొత్త గడియారం ఇవ్వాలని డీలర్‌కు ఆదేశం."]],["ఇవి చేయండి 5 – హక్కులు, ప్రమాణాలు (పుట 172)",["1) పోస్టర్: ఉదా: “బంగారం కొంటున్నారా? Hallmark చూడండి – బిల్లు తీసుకోండి – బరువు సరిచూడండి”.","2) మీ జిల్లా వినియోగదారుల వివాద పరిష్కార కమిషన్ – జిల్లా కేంద్రం (SPSR నెల్లూరు) లో ఉంది; e-Daakhil పోర్టల్ ద్వారా ఆన్‌లైన్‌లోనూ ఫిర్యాదు చేయవచ్చు.","3) వినియోగదారుల రక్షణ మండలి (consumer protection council/forum) – స్వచ్ఛంద సంస్థ; అవగాహన కల్పిస్తుంది, కేసు ఎలా వేయాలో మార్గదర్శనం చేసి ప్రాతినిధ్యం వహిస్తుంది. వినియోగదారుల వివాద పరిష్కార కమిషన్ – ప్రభుత్వం ఏర్పాటు చేసిన పాక్షిక న్యాయ (quasi-judicial) సంస్థ; కేసులు విచారించి తీర్పు, పరిహారం ఇస్తుంది.","4) (a) లత – భద్రత హక్కు (v) (b) జాన్ – పరిహారం హక్కు (iii) (c) గడువు ముగిసిన మందు – పరిహారం హక్కు (iii) [భద్రత కూడా] (d) ఇక్బాల్ – సమాచార హక్కు (ii) (e) కేబుల్ ఆపరేటర్ – ఎంపిక హక్కు (i) (f) లోపం గల కెమెరా – పరిహారం హక్కు (iii)","5) చాలా వస్తువులకు ISI/Agmark ధృవీకరణ స్వచ్ఛందం (తప్పనిసరి కాదు); ఆరోగ్యం, భద్రతకు సంబంధించిన కొన్నింటికే (LPG, ఆహార రంగులు, సిమెంట్, ప్యాకేజ్డ్ నీరు) తప్పనిసరి. ధృవీకరణకు ఖర్చు, ప్రక్రియ ఉండటం, వినియోగదారుల్లో అవగాహన లేకపోవడం కూడా కారణం.","6) Hallmark – భారతీయ ప్రమాణాల సంస్థ (BIS); ISO – అంతర్జాతీయ ప్రమాణీకరణ సంస్థ (International Organization for Standardization, జెనీవా)."]],["అభ్యాసాలు – Exercises (1–12) (పుట 174)",["1) ఉత్పత్తిదారులు శక్తిమంతులు, వినియోగదారులు బలహీనులు కాబట్టి దోపిడీ నివారణకు నియమాలు అవసరం. ఉదా: తక్కువ తూకం, కల్తీ నూనె, MRP కంటే ఎక్కువ ధర, నాసిరకం ప్రెషర్ కుక్కర్, గడువు ముగిసిన మందులు, వడ్డీ వ్యాపారుల అధిక వడ్డీ.","2) ఆహార కొరత, నిల్వ, నల్లబజారు, ఆహారం–వంటనూనెల కల్తీ వల్ల 1960ల్లో ఉద్యమం వ్యవస్థీకృతమైంది. 1970ల వరకు వ్యాసాలు, ప్రదర్శనలు; రేషన్ దుకాణాల అక్రమాలు, బస్సుల రద్దీపై సంఘాలు. ఒత్తిడి ఫలితంగా 1986లో COPRA; తర్వాత వినియోగదారుల కమిషన్లు, 2000+ సంఘాలు; RTI 2005.","3) ఉదా 1: గడువు తేదీ చూడకుండా మందు కొంటే ఆరోగ్యానికి ప్రమాదం – చైతన్యం ఉంటే తప్పించుకోవచ్చు. ఉదా 2: బిల్లు, వారంటీ కార్డు తీసుకోకపోతే లోపం గల వస్తువుకు పరిహారం పొందలేం. కాబట్టి వినియోగదారుల చైతన్యం అవసరం.","4) పరిమిత సమాచారం, పరిమిత సరఫరా, పరిమిత పోటీ (గుత్తాధిపత్యం), తక్కువ అక్షరాస్యత–అవగాహన, వినియోగదారులు అసంఘటితంగా ఉండటం, తప్పుడు ప్రకటనలు, నియమాల అమలు బలహీనం.","5) వినియోగదారులను అన్యాయమైన వ్యాపార పద్ధతుల నుండి రక్షించడం, వారి హక్కులను చట్టబద్ధం చేయడం, సులభంగా, తక్కువ ఖర్చుతో, త్వరగా న్యాయం (పరిహారం) అందించడానికి మూడంచెల కమిషన్లు ఏర్పాటు చేయడం.","6) బిల్లు అడగడం; ISI, Agmark, Hallmark ముద్రలు, MRP, గడువు తేదీ చూడటం; వారంటీ కార్డు తీసుకోవడం; నాణ్యత, ధర పోల్చడం; అవసరమైనంతే కొనడం; మోసం జరిగితే ఫిర్యాదు చేయడం; పరిసరాలను శుభ్రంగా ఉంచడం.","7) తేనె – Agmark (వ్యవసాయ ఉత్పత్తి నాణ్యత); బిస్కట్ ప్యాకెట్ – ISI / FSSAI ముద్ర (ఆహార భద్రత, నాణ్యత ప్రమాణాలు). ఇవి నాణ్యతకు హామీ ఇస్తాయి.","8) COPRA 1986 చట్టం; మూడంచెల వినియోగదారుల వివాద పరిష్కార కమిషన్లు; RTI చట్టం 2005; ప్రమాణాల సంస్థలు (BIS, Agmark); తూనికలు–కొలతల చట్టాలు; ఆహార కల్తీ నిరోధక చట్టాలు; వినియోగదారుల సంఘాలకు ఆర్థిక సహాయం; డిసెంబర్ 24 జాతీయ వినియోగదారుల దినోత్సవం.","9) భద్రత హక్కు – ప్రాణానికి హాని చేసే వస్తువుల నుండి రక్షణ. సమాచార హక్కు – వస్తువు పదార్థాలు, ధర, గడువు తెలుసుకోవడం. ఎంపిక హక్కు – ఇష్టమైనది ఎంచుకునే స్వేచ్ఛ. పరిహారం హక్కు – నష్టపోతే ఫిర్యాదు చేసి పరిహారం పొందడం. ప్రాతినిధ్య హక్కు – కమిషన్లలో వాదన వినిపించడం. వినియోగదారుల విద్య హక్కు – హక్కులు, చట్టాలపై అవగాహన పొందడం.","10) వినియోగదారుల సంఘాలు/ఫోరమ్‌లు ఏర్పాటు చేయడం, ర్యాలీలు, ధర్నాలు, ప్రచారాలు, కాలనీల సంక్షేమ సంఘాల ద్వారా ఒకరి తరఫున మరొకరు కేసులు వేయడం, ఉమ్మడి ఫిర్యాదులు (class action suit), సోషల్ మీడియా.","11) పురోగతి: 2000+ సంఘాలు, మూడంచెల కమిషన్లు, RTI, అవగాహన ప్రచారాలు, ఆన్‌లైన్ ఫిర్యాదులు. లోపాలు: 50–60 సంఘాలే బాగా పనిచేస్తాయి; పరిష్కార ప్రక్రియ క్లిష్టం, ఖర్చుతో, ఆలస్యంతో కూడుకున్నది; లాయర్లు కావాల్సి రావడం; బిల్లులు తీసుకోకపోవడం; అవగాహన నెమ్మదిగా పెరుగుతోంది; చట్టాల అమలు బలహీనం.","12) (i) – (e) సమాచార హక్కు; (ii) – (c) వంటనూనెలు, తృణధాన్యాల ధృవీకరణ; (iii) – (a) భద్రత హక్కు; (iv) – (b) వినియోగదారుల కేసుల పరిష్కారం; (v) – (g) ప్రధాన ఆహారానికి పోషకాలు కలపడం; (vi) – (f) ప్రపంచ స్థాయి వినియోగదారుల సంస్థల సమాఖ్య; (vii) – (d) ప్రమాణాలు రూపొందించే సంస్థ."]],["అభ్యాసాలు – Exercise 13, ప్రాజెక్ట్‌లు (పుట 176)",["13) (i) తప్పు (వస్తువులు, సేవలు రెండింటికీ) (ii) ఒప్పు (iii) తప్పు (క్లెయిమ్ విలువను బట్టి జిల్లా/రాష్ట్ర/జాతీయ కమిషన్) (iv) తప్పు (చిన్న నష్టమైనా వెళ్ళవచ్చు) (v) ఒప్పు (vi) తప్పు (క్లిష్టం, ఆలస్యం) (vii) ఒప్పు","ప్రాజెక్ట్ 2 – లేఖ: జిల్లా వినియోగదారుల వివాద పరిష్కార కమిషన్ అధ్యక్షులకు, SPSR నెల్లూరు. విషయం: లోపం గల కలర్ టీవీపై ఫిర్యాదు. అయ్యా, నేను శ్రీమతి కృష్ణ, (తేదీ)న (దుకాణం పేరు) నుండి 6 నెలల వారంటీతో ₹____ కి కలర్ టీవీ కొన్నాను (బిల్లు, వారంటీ కార్డు జతచేశాను). 3 నెలలకే అది పనిచేయడం మానేసింది. డీలర్ పంపిన ఇంజనీర్ సరిచేసినా సమస్య కొనసాగుతోంది; నా ఫిర్యాదులకు జవాబు లేదు. కాబట్టి టీవీని మార్చి కొత్తది ఇప్పించాలని లేదా డబ్బు వాపసుతో పాటు నష్టపరిహారం ఇప్పించాలని ప్రార్థిస్తున్నాను. ఇట్లు, శ్రీమతి కృష్ణ (చిరునామా, ఫోన్).","ప్రాజెక్ట్ 4 – నినాదం: “లేవండి, మేల్కోండి, మీ హక్కులు సాధించే వరకు ఆగకండి!”","ప్రాజెక్ట్ 6 – సర్వే ప్రశ్నావళి (బిల్లు అడుగుతారా? భద్రపరుస్తారా? ఫిర్యాదు చేశారా?) పంచి, “ఎల్లప్పుడూ / కొన్నిసార్లు / ఎప్పుడూ కాదు” జవాబుల శాతం లెక్కించి నివేదిక రాయండి."]]]},{"id":"cv1","no":18,"t":"అధికార విభజన (Power-sharing)","m":[7],"ty":"పౌరశాస్త్రం – అధ్యాయం 1","by":"సాంఘిక శాస్త్రం – ప్రజాస్వామ్య రాజకీయాలు-II, 10వ తరగతి (పుటలు 4–27)","th":"బెల్జియం, శ్రీలంక ఉదాహరణలు, మెజారిటీవాదం, బెల్జియం నమూనా, అధికార విభజన ఎందుకు కావాలి (వివేకపూర్వక, నైతిక కారణాలు), అధికార విభజన రూపాలు","sum":"ప్రజాస్వామ్యంలో అధికారం అంతా ఒకే అంగం లేదా ఒకే వర్గం చేతిలో ఉండకూడదు. ఈ పాఠం బెల్జియం, శ్రీలంక అనే రెండు ప్రజాస్వామ్య దేశాల కథలతో మొదలవుతుంది. బెల్జియంలో 59% డచ్ (ఫ్లెమిష్ ప్రాంతం), 40% ఫ్రెంచ్ (వలోనియా), 1% జర్మన్ మాట్లాడేవారు; రాజధాని బ్రస్సెల్స్‌లో 80% ఫ్రెంచ్, 20% డచ్. ధనిక ఫ్రెంచ్ మైనారిటీపై డచ్ ప్రజల అసంతృప్తితో 1950–60లలో ఉద్రిక్తతలు వచ్చాయి. బెల్జియం నాయకులు 1970–1993 మధ్య రాజ్యాంగాన్ని నాలుగుసార్లు సవరించి అందరూ కలిసి జీవించే వినూత్న ఏర్పాటు చేశారు – కేంద్రంలో డచ్, ఫ్రెంచ్ మంత్రులు సమానం; రాష్ట్ర ప్రభుత్వాలకు అధికారాలు; బ్రస్సెల్స్‌లో ప్రత్యేక ప్రభుత్వం (సమాన ప్రాతినిధ్యం); భాషా సమాజాల “సమాజ ప్రభుత్వం” (community government). ఫలితంగా దేశం విడిపోలేదు; బ్రస్సెల్స్ యూరోపియన్ యూనియన్ ప్రధాన కార్యాలయం అయింది. శ్రీలంక (1948 స్వాతంత్ర్యం)లో 74% సింహళీయులు, 18% తమిళులు (శ్రీలంక తమిళులు 13%, భారత తమిళులు). సింహళ ఆధిపత్యం కోసం మెజారిటీవాద చర్యలు – 1956 సింహళం ఒక్కటే అధికార భాష, ఉద్యోగాలు–విశ్వవిద్యాలయాల్లో సింహళీయులకు ప్రాధాన్యం, బౌద్ధమతానికి రక్షణ. తమిళులలో పరాయితనం పెరిగి, 1980ల నాటికి స్వతంత్ర తమిళ ఈలం డిమాండ్, అంతర్యుద్ధం (2009లో ముగిసింది). పాఠం: మెజారిటీ నిరంకుశత్వం దేశ ఐక్యతను దెబ్బతీస్తుంది. అధికార విభజనకు రెండు కారణాలు – వివేకపూర్వక (prudential: ఘర్షణలు తగ్గించి రాజకీయ స్థిరత్వం), నైతిక (moral: అధికార విభజనే ప్రజాస్వామ్య స్ఫూర్తి). రూపాలు – (1) క్షితిజ సమాంతర (శాసన, కార్యనిర్వాహక, న్యాయ శాఖల మధ్య – నియంత్రణ, సమతుల్యత), (2) నిలువు/సమాఖ్య (కేంద్రం, రాష్ట్రాలు, స్థానిక ప్రభుత్వాలు), (3) సామాజిక వర్గాల మధ్య (సమాజ ప్రభుత్వం, రిజర్వ్‌డ్ నియోజకవర్గాలు), (4) రాజకీయ పార్టీలు, ఒత్తిడి వర్గాలు, ఉద్యమాల మధ్య (సంకీర్ణ ప్రభుత్వం).","pts":["బెల్జియం: ఐరోపాలో చిన్న దేశం (హర్యానా కంటే చిన్నది); సరిహద్దులు – ఫ్రాన్స్, నెదర్లాండ్స్, జర్మనీ, లక్సెంబర్గ్; జనాభా కోటికి కొంచెం ఎక్కువ.","బెల్జియం భాషలు: డచ్ 59% (ఫ్లెమిష్ ప్రాంతం), ఫ్రెంచ్ 40% (వలోనియా), జర్మన్ 1%; బ్రస్సెల్స్‌లో 80% ఫ్రెంచ్, 20% డచ్.","బ్రస్సెల్స్ ప్రత్యేక సమస్య: డచ్ ప్రజలు దేశంలో మెజారిటీ, కానీ రాజధానిలో మైనారిటీ.","శ్రీలంక: సింహళీయులు 74%, తమిళులు 18% (శ్రీలంక తమిళులు 13% – ఉత్తర, తూర్పు ప్రాంతాలు; మిగిలినవారు భారత తమిళులు); క్రైస్తవులు సుమారు 7%.","మెజారిటీవాదం (Majoritarianism): మైనారిటీల కోరికలు, అవసరాలను పట్టించుకోకుండా మెజారిటీ సమాజం తనకు నచ్చినట్లు దేశాన్ని పాలించాలనే నమ్మకం.","శ్రీలంక మెజారిటీవాద చర్యలు: 1956 చట్టం – సింహళం ఒక్కటే అధికార భాష; విశ్వవిద్యాలయ ప్రవేశాలు, ప్రభుత్వ ఉద్యోగాల్లో సింహళీయులకు ప్రాధాన్యం; బౌద్ధమతాన్ని ప్రభుత్వం రక్షించి పోషించాలని రాజ్యాంగం.","ఫలితం: తమిళులలో పరాయితనం → తమిళ అధికార భాష, ప్రాంతీయ స్వయంప్రతిపత్తి, సమాన అవకాశాల కోసం పోరాటం → 1980ల నాటికి స్వతంత్ర తమిళ ఈలం డిమాండ్ → అంతర్యుద్ధం (2009లో ముగిసింది).","బెల్జియం నమూనా (1970–1993, నాలుగు రాజ్యాంగ సవరణలు): ① కేంద్రంలో డచ్, ఫ్రెంచ్ మంత్రుల సంఖ్య సమానం; కొన్ని చట్టాలకు ప్రతి భాషా వర్గం మెజారిటీ మద్దతు కావాలి.","బెల్జియం నమూనా: ② కేంద్ర అధికారాలు చాలా రాష్ట్ర ప్రభుత్వాలకు – అవి కేంద్రానికి లోబడి ఉండవు. ③ బ్రస్సెల్స్‌కు ప్రత్యేక ప్రభుత్వం – రెండు వర్గాలకు సమాన ప్రాతినిధ్యం.","బెల్జియం నమూనా: ④ సమాజ ప్రభుత్వం (Community Government) – ఒక భాషా సమాజం (డచ్/ఫ్రెంచ్/జర్మన్) వారు ఎక్కడ ఉన్నా ఎన్నుకుంటారు; సాంస్కృతిక, విద్యా, భాషా విషయాలపై అధికారం.","ఫలితం: బెల్జియంలో అంతర్యుద్ధం, దేశ విభజన తప్పాయి; యూరోపియన్ యూనియన్ ప్రధాన కార్యాలయం బ్రస్సెల్స్.","వివేకపూర్వక కారణం (Prudential): అధికార విభజన సామాజిక వర్గాల మధ్య ఘర్షణలను తగ్గిస్తుంది → రాజకీయ స్థిరత్వం; మెజారిటీ నిరంకుశత్వం మైనారిటీకే కాదు మెజారిటీకీ నష్టం.","నైతిక కారణం (Moral): అధికార విభజనే ప్రజాస్వామ్య స్ఫూర్తి; ఎలా పాలించబడాలో ప్రజలను సంప్రదించాలి; పాల్గొనడం ద్వారా పౌరులకు వ్యవస్థలో భాగస్వామ్యం → చట్టబద్ధమైన (legitimate) ప్రభుత్వం.","రూపం 1 – క్షితిజ సమాంతర విభజన (Horizontal): ఒకే స్థాయిలోని శాసన, కార్యనిర్వాహక, న్యాయ శాఖల మధ్య; నియంత్రణ–సమతుల్యత (checks and balances).","రూపం 2 – నిలువు విభజన (Vertical / సమాఖ్య): కేంద్ర (యూనియన్), రాష్ట్ర ప్రభుత్వాలు, ఇంకా కింద మున్సిపాలిటీ, పంచాయతీ; అధికారాలను రాజ్యాంగం నిర్దేశిస్తుంది.","రూపం 3 – సామాజిక వర్గాల మధ్య: మత, భాషా వర్గాలు – బెల్జియం సమాజ ప్రభుత్వం; భారత్‌లో రిజర్వ్‌డ్ నియోజకవర్గాలు (బలహీన వర్గాలు, మహిళల ప్రాతినిధ్యం).","రూపం 4 – రాజకీయ పార్టీలు, ఒత్తిడి వర్గాలు, ఉద్యమాల మధ్య: పార్టీల పోటీ, సంకీర్ణ (coalition) ప్రభుత్వాలు; వ్యాపారులు, రైతులు, కార్మికుల వంటి ప్రయోజన వర్గాల ప్రభావం."],"w":[["అధికార విభజన","Power-sharing"],["జాతి సంబంధ (ఒకే సంస్కృతి, ఉమ్మడి వంశం అనే నమ్మకం)","Ethnic"],["మెజారిటీవాదం","Majoritarianism"],["అంతర్యుద్ధం","Civil war"],["పరాయితనం (దూరమైన భావన)","Alienation"],["స్వయంప్రతిపత్తి","Autonomy"],["సమాజ ప్రభుత్వం","Community government"],["వివేకపూర్వక (లాభనష్టాల జాగ్రత్త లెక్క)","Prudential"],["నైతిక","Moral"],["చట్టబద్ధమైన ప్రభుత్వం","Legitimate government"],["క్షితిజ సమాంతర విభజన","Horizontal distribution"],["నిలువు విభజన","Vertical division"],["నియంత్రణ–సమతుల్యత","Checks and balances"],["సంకీర్ణ ప్రభుత్వం","Coalition government"],["ఒత్తిడి వర్గాలు","Pressure groups"],["సమాఖ్య ప్రభుత్వం","Federal government"],["ఏకపక్షంగా","Unilaterally"]],"gr":{"t":"బెల్జియం vs శ్రీలంక","p":["అంశం | బెల్జియం | శ్రీలంక","మెజారిటీ వర్గం | డచ్ 59% | సింహళీయులు 74%","మైనారిటీ వర్గం | ఫ్రెంచ్ 40%, జర్మన్ 1% | తమిళులు 18%","ప్రభుత్వ మార్గం | వసతి కల్పన (Accommodation) | మెజారిటీవాదం","ముఖ్య చర్యలు | మంత్రులు సమానం, రాష్ట్రాలకు అధికారాలు, బ్రస్సెల్స్ ప్రభుత్వం, సమాజ ప్రభుత్వం | 1956 సింహళం ఏకైక అధికార భాష, ఉద్యోగాల్లో ప్రాధాన్యం, బౌద్ధమత రక్షణ","ఫలితం | ఐక్యత, శాంతి; EU ప్రధాన కార్యాలయం | అంతర్యుద్ధం (2009 వరకు), వేలాది మరణాలు"]},"qa":[["బెల్జియంలో అత్యధిక జనాభా మాట్లాడే భాష?","డచ్ (59%, ఫ్లెమిష్ ప్రాంతం)."],["బ్రస్సెల్స్ ఎందుకు ప్రత్యేక సమస్యగా మారింది?","డచ్ మాట్లాడేవారు దేశంలో మెజారిటీ అయినా రాజధానిలో మైనారిటీ (20%); అక్కడ ఫ్రెంచ్ వారు 80%."],["మెజారిటీవాదం అంటే ఏమిటి?","మైనారిటీల కోరికలు, అవసరాలను పట్టించుకోకుండా మెజారిటీ సమాజం తనకు నచ్చినట్లు దేశాన్ని పాలించాలనే నమ్మకం."],["శ్రీలంకలో 1956 చట్టం ఏమిటి?","సింహళాన్ని ఒక్కటే అధికార భాషగా గుర్తించింది – తమిళాన్ని విస్మరించింది."],["సమాజ ప్రభుత్వం (Community Government) అంటే?","బెల్జియంలో ఒక భాషా సమాజం (డచ్/ఫ్రెంచ్/జర్మన్) ప్రజలు ఎక్కడ నివసించినా ఎన్నుకునే ప్రభుత్వం; సాంస్కృతిక, విద్యా, భాషా అంశాలపై అధికారం."],["అధికార విభజనకు వివేకపూర్వక కారణం?","సామాజిక వర్గాల మధ్య ఘర్షణ అవకాశాలు తగ్గి, రాజకీయ స్థిరత్వం వస్తుంది."],["అధికార విభజనకు నైతిక కారణం?","అధికార విభజనే ప్రజాస్వామ్య స్ఫూర్తి – పాలనతో ప్రభావితమయ్యే ప్రజలకు అధికారంలో భాగం ఉండాలి."],["నియంత్రణ–సమతుల్యత వ్యవస్థ అంటే?","శాసన, కార్యనిర్వాహక, న్యాయ శాఖల్లో ఏదీ అపరిమిత అధికారం వాడకుండా ఒకదాన్ని మరొకటి నియంత్రించడం."],["నిలువు అధికార విభజనకు ఉదాహరణ?","భారత్‌లో కేంద్ర, రాష్ట్ర ప్రభుత్వాలు, పంచాయతీలు/మున్సిపాలిటీలు."],["సంకీర్ణ ప్రభుత్వం అంటే?","రెండు లేదా అంతకంటే ఎక్కువ పార్టీలు కూటమిగా ఏర్పడి కలిసి నడిపే ప్రభుత్వం."]],"act":"ఒక వారం పాటు వార్తాపత్రికలో ఘర్షణలు/యుద్ధాల వార్తలు కత్తిరించి సేకరించండి. మన రాష్ట్రం, భారత్, విదేశాలు అని వర్గీకరించి – ఏవి అధికార పంపిణీ వివాదాలో, ఏవి అధికార విభజనతో పరిష్కరించవచ్చో తరగతిలో చర్చించండి.","kn":"బెల్జియం నమూనా చాలా క్లిష్టమైనది – అక్కడి ప్రజలకే అర్థం కావడం కష్టమట! అయినా అది పనిచేసింది. ఐరోపా దేశాలు కలిసి యూరోపియన్ యూనియన్‌గా ఏర్పడినప్పుడు బ్రస్సెల్స్‌నే ప్రధాన కార్యాలయంగా ఎంచుకున్నాయి.","qz":[["బెల్జియంలో డచ్ మాట్లాడే జనాభా శాతం?","59%","40%","80%","74%"],["బెల్జియంలో ఫ్రెంచ్ మాట్లాడే ప్రాంతం?","వలోనియా","ఫ్లెమిష్","బ్రస్సెల్స్ మాత్రమే","లక్సెంబర్గ్"],["బ్రస్సెల్స్‌లో ఫ్రెంచ్ మాట్లాడేవారి శాతం?","80%","20%","59%","40%"],["శ్రీలంకకు స్వాతంత్ర్యం వచ్చిన సంవత్సరం?","1948","1947","1956","1980"],["శ్రీలంకలో సింహళాన్ని ఏకైక అధికార భాషగా చేసిన చట్టం సంవత్సరం?","1956","1948","1970","1993"],["శ్రీలంక అంతర్యుద్ధం ముగిసిన సంవత్సరం?","2009","1983","1993","2005"],["బెల్జియం రాజ్యాంగాన్ని 1970–1993 మధ్య ఎన్నిసార్లు సవరించారు?","నాలుగు","రెండు","మూడు","ఆరు"],["భాషా సమాజం ప్రజలు ఎక్కడ ఉన్నా ఎన్నుకునే బెల్జియం ప్రభుత్వం?","సమాజ ప్రభుత్వం","రాష్ట్ర ప్రభుత్వం","బ్రస్సెల్స్ ప్రభుత్వం","కేంద్ర ప్రభుత్వం"],["మైనారిటీల అవసరాలు పట్టించుకోకుండా మెజారిటీ పాలించాలనే నమ్మకం?","మెజారిటీవాదం","సమాఖ్యవాదం","లౌకికవాదం","సంకీర్ణం"],["ఘర్షణలు తగ్గించి స్థిరత్వం తెస్తుందనేది అధికార విభజనకు ఏ కారణం?","వివేకపూర్వక","నైతిక","చారిత్రక","ఆర్థిక"],["శాసన, కార్యనిర్వాహక, న్యాయ శాఖల మధ్య అధికార విభజన?","క్షితిజ సమాంతర విభజన","నిలువు విభజన","సామాజిక విభజన","పార్టీల విభజన"],["కేంద్రం, రాష్ట్రాల మధ్య అధికార విభజన?","నిలువు (సమాఖ్య) విభజన","క్షితిజ సమాంతర విభజన","సంకీర్ణం","నియంత్రణ–సమతుల్యత"],["యూరోపియన్ యూనియన్ ప్రధాన కార్యాలయం?","బ్రస్సెల్స్","పారిస్","బెర్లిన్","కొలంబో"],["లెబనాన్ నిబంధనల ప్రకారం అధ్యక్షుడు ఏ వర్గం వారు?","మెరోనైట్ కాథలిక్ క్రైస్తవులు","సున్నీ ముస్లింలు","షియా ముస్లింలు","ఆర్థోడాక్స్ క్రైస్తవులు"],["జర్మనీలో 2005 తర్వాత ఏర్పడిన “గ్రాండ్ కోయలిషన్” ఏ అధికార విభజన రూపం?","రాజకీయ పార్టీల మధ్య","సామాజిక వర్గాల మధ్య","ప్రభుత్వ అంగాల మధ్య","ప్రభుత్వ స్థాయిల మధ్య"]],"wb":{"mis":"“అధికారం పంచితే దేశం బలహీనమవుతుంది” అనేది తప్పు భావన – బెల్జియం అధికారం పంచి ఐక్యంగా నిలిచింది; శ్రీలంక పంచకపోవడంతో అంతర్యుద్ధం వచ్చింది. బెల్జియంలో రాష్ట్ర ప్రభుత్వాలు కేంద్రానికి లోబడి ఉండవు.","pg":"4–27","f":"books/10/Class10_Social_Civics_Textbook.pdf","p":6,"lb":"పాఠ్యపుస్తకం","ws":["పటాలు చూడండి – వర్గాల కేంద్రీకరణ (పుట 6)","ఆలోచించండి – బొమ్మల్లోని ప్రశ్నలు (పుట 10)","కృత్యం – వార్తాపత్రిక క్లిప్పింగులు (పుట 12)","ఆలోచించండి – అనెట్, సెల్వి (పుట 14)","ఖలీల్ సందిగ్ధం – విక్రమ్ జవాబు (నమూనా) (పుట 16)","కార్టూన్ – “Reigning the Reins” (రష్యా, 2005) (పుట 18)","ఆలోచించండి – క్లాస్ మానిటర్ (పుట 20)","అభ్యాసాలు – ఉదాహరణలు: ఏ రకం అధికార విభజన? (పుట 22)","అభ్యాసాలు – ప్రశ్నలు 1–4 (పుట 22)","అభ్యాసాలు – ప్రశ్నలు 5–7 (పుట 24)","అభ్యాసాలు – ప్రశ్నలు 8–9 (పుట 26)"]},"tg":[["పటాలు చూడండి – వర్గాల కేంద్రీకరణ (పుట 6)",["1) బెల్జియం: డచ్ మాట్లాడేవారు ఉత్తరాన ఫ్లెమిష్ ప్రాంతంలో; ఫ్రెంచ్ మాట్లాడేవారు దక్షిణాన వలోనియాలో; జర్మన్ మాట్లాడేవారు తూర్పు అంచున చిన్న ప్రాంతంలో కేంద్రీకృతమై ఉన్నారు.","2) బ్రస్సెల్స్ రాజధాని ప్రాంతంలో రెండు వర్గాలూ (ఎక్కువగా ఫ్రెంచ్) కలిసి ఉన్నారు.","3) శ్రీలంక: సింహళీయులు దేశంలో ఎక్కువ భాగం (దక్షిణ, మధ్య, పశ్చిమ); శ్రీలంక తమిళులు ఉత్తర, తూర్పు ప్రాంతాల్లో; భారత తమిళులు మధ్య కొండ ప్రాంతాల (తేయాకు తోటలు)లో; ముస్లింలు తూర్పు తీరం వెంట."]],["ఆలోచించండి – బొమ్మల్లోని ప్రశ్నలు (పుట 10)",["“మెజారిటీ పాలిస్తే తప్పేమిటి?” – 1) మెజారిటీ మైనారిటీ కోరికలను విస్మరిస్తే వారిలో పరాయితనం పెరుగుతుంది.","2) శ్రీలంకలో అదే జరిగి అంతర్యుద్ధానికి దారితీసింది.","3) ప్రజాస్వామ్యం అంటే మెజారిటీ పాలనే కాదు – మైనారిటీ హక్కుల రక్షణ కూడా.","“ఏ మంత్రి ఏ వర్గం నుండి రావాలో చెప్పడం ఎలాంటి పరిష్కారం?” – 1) బెల్జియం వంటి తీవ్రంగా విభజిత సమాజంలో ఏ వర్గం ఒంటరిగా నిర్ణయాలు తీసుకోకుండా ఇది కాపాడుతుంది.","2) భారత్‌లో ఈ నిబంధన లేకపోయినా రిజర్వేషన్లు, సమాఖ్య వ్యవస్థ వంటి వేరే ఏర్పాట్లు ఉన్నాయి.","3) ప్రతి దేశం తన పరిస్థితులకు తగిన అధికార విభజన ఎంచుకుంటుంది."]],["కృత్యం – వార్తాపత్రిక క్లిప్పింగులు (పుట 12)",["1) ఘర్షణ వార్తలను మూడు వర్గాలుగా విభజించండి: మన రాష్ట్రం, భారత్, భారత్ బయట. (విద్యార్థుల సొంత సేకరణ)","2) ప్రతి ఘర్షణకు కారణం రాయండి – నీరు, భూమి, భాష, మతం, జాతి, సరిహద్దు, అధికారం వంటివి.","3) భాష, ప్రాంతం, జాతి, సమాజాల మధ్య అధికారంలో వాటా కోసం వచ్చినవి = అధికార విభజన వివాదాలు.","4) ఇలాంటి వాటిని స్వయంప్రతిపత్తి, సమాన ప్రాతినిధ్యం, అధికారాల వికేంద్రీకరణ, సంకీర్ణ ఏర్పాట్లతో పరిష్కరించవచ్చు (ఉదా: బెల్జియం నమూనా).","“అధికారం పంచితే మరింత శక్తిమంతులం అవుతామా?” – అవును; పంచడం వల్ల అన్ని వర్గాలు దేశాన్ని తమదిగా భావించి ఐక్యత, స్థిరత్వం పెరుగుతాయి – బెల్జియం ఉదాహరణ."]],["ఆలోచించండి – అనెట్, సెల్వి (పుట 14)",["1) అనెట్ (బెల్జియం) తల్లిదండ్రులు విజయం సాధించే అవకాశం ఎక్కువ.","2) బెల్జియంలో విద్య, భాష, సంస్కృతి అంశాలు “సమాజ ప్రభుత్వం” చేతిలో ఉన్నాయి – ఫ్రెంచ్ సమాజ ప్రభుత్వాన్ని ఆశ్రయించవచ్చు.","3) బెల్జియం వ్యవస్థ అన్ని భాషా వర్గాల ప్రయోజనాలను గౌరవించే వసతి కల్పన విధానం.","4) శ్రీలంకలో మెజారిటీవాద విధానాలు (సింహళ ఏకైక అధికార భాష) ఉన్నాయి; తమిళుల ప్రాంతాలకు స్వయంప్రతిపత్తి నిరాకరించారు – కాబట్టి సెల్వి కోరిక నెరవేరే అవకాశం తక్కువ."]],["ఖలీల్ సందిగ్ధం – విక్రమ్ జవాబు (నమూనా) (పుట 16)",["1) పాత నిబంధనలను వెంటనే రద్దు చేయను – అంతర్యుద్ధం తర్వాత శాంతికి అవే హామీ; హఠాత్తుగా మార్చితే మళ్ళీ హింస రావచ్చు.","2) కానీ శాశ్వతంగా అలాగే ఉంచను – అవి ఖలీల్ వంటి ఏ మతాన్నీ పాటించని, ప్రతిభ ఉన్న పౌరులకు సమాన అవకాశం ఇవ్వవు; జనాభా మారినా పదవులు మారవు.","3) మధ్యే మార్గం: అన్ని వర్గాలతో చర్చించి, కొంత కాలంలో దశలవారీగా మార్పు – ఉదా: ఉన్నత పదవులు వర్గాల మధ్య రొటేషన్, ఏ వర్గానికీ చెందనివారికి కూడా పోటీ అవకాశం, మైనారిటీల హక్కుల రక్షణకు రాజ్యాంగ హామీలు.","4) లక్ష్యం: శాంతి + సమానత్వం రెండూ ఉండే అధికార విభజన. (ఇది నమూనా జవాబు – విద్యార్థులు తమ కారణాలతో వేరే జవాబు కూడా రాయవచ్చు.)"]],["కార్టూన్ – “Reigning the Reins” (రష్యా, 2005) (పుట 18)",["1) కార్టూన్ భావం: అధికారం ఒకే వ్యక్తి (అధ్యక్షుడు) చేతిలో కేంద్రీకృతమైతే ప్రజాస్వామ్యం బలహీనమై, నియంత్రణలో పడుతుంది.","2) ప్రజాస్వామ్యం, అధికార కేంద్రీకరణ ఒకదానికొకటి విరుద్ధం – నిజమైన ప్రజాస్వామ్యానికి అధికార విభజన అవసరం.","3) ఇతర ఉదాహరణలు: సైనిక పాలనలు (పాకిస్తాన్‌లో జనరల్ ముషారఫ్), భారత్‌లో అత్యవసర పరిస్థితి (1975–77) కాలంలో హక్కుల రద్దు, ఒకే పార్టీ పాలన ఉన్న దేశాలు."]],["ఆలోచించండి – క్లాస్ మానిటర్ (పుట 20)",["1) ప్రతి నెలా మానిటర్ మారడం – బాధ్యత, అవకాశం అందరికీ రావడం; అధికారం ఒక్కరి చేతిలో ఉండిపోదు.","2) కానీ ఒకే సమయంలో అధికారాన్ని పలువురు పంచుకోవడం కాదు – ఇది అధికార “మార్పిడి/రొటేషన్” మాత్రమే.","3) ఒకేసారి ఇద్దరు/ముగ్గురు మానిటర్లు వేర్వేరు పనులు (క్రమశిక్షణ, హాజరు, పరిశుభ్రత) చూస్తే అది అధికార విభజనకు దగ్గరగా ఉంటుంది."]],["అభ్యాసాలు – ఉదాహరణలు: ఏ రకం అధికార విభజన? (పుట 22)",["1) బాంబే హైకోర్టు మహారాష్ట్ర ప్రభుత్వాన్ని ఆదేశించడం → క్షితిజ సమాంతర విభజన – న్యాయ శాఖ, కార్యనిర్వాహక శాఖ మధ్య (నియంత్రణ–సమతుల్యత).","2) కెనడా అంటారియో ప్రభుత్వం – ఆదివాసీ సమాజంతో భూ ఒప్పందం → సామాజిక వర్గాల మధ్య – ప్రభుత్వం, ఆదివాసీ (స్థానిక) సమాజం మధ్య.","3) రష్యాలో రెండు పార్టీలు కలిసి కూటమి → రాజకీయ పార్టీల మధ్య – Union of Right Forces, Liberal Yabloko Movement మధ్య.","4) నైజీరియా రాష్ట్రాల ఆర్థిక మంత్రులు సమాఖ్య ప్రభుత్వాన్ని ఆదాయ వివరాలు అడగడం → నిలువు (సమాఖ్య) విభజన – కేంద్ర (సమాఖ్య), రాష్ట్ర ప్రభుత్వాల మధ్య."]],["అభ్యాసాలు – ప్రశ్నలు 1–4 (పుట 22)",["1) అధికార విభజన రూపాలు:","(i) ప్రభుత్వ అంగాల మధ్య (క్షితిజ సమాంతర) – శాసన, కార్యనిర్వాహక, న్యాయ శాఖలు; ఉదా: భారత్‌లో సుప్రీంకోర్టు చట్టాలను సమీక్షించడం.","(ii) వివిధ స్థాయి ప్రభుత్వాల మధ్య (నిలువు) – ఉదా: భారత్‌లో కేంద్రం, రాష్ట్రాలు, పంచాయతీలు.","(iii) సామాజిక వర్గాల మధ్య – ఉదా: బెల్జియం సమాజ ప్రభుత్వం, భారత్‌లో SC/ST రిజర్వ్‌డ్ నియోజకవర్గాలు.","(iv) రాజకీయ పార్టీలు, ఒత్తిడి వర్గాల మధ్య – ఉదా: భారత్‌లో సంకీర్ణ ప్రభుత్వాలు (NDA, UPA).","2) వివేకపూర్వక కారణం: సామాజిక వర్గాల మధ్య ఘర్షణ తగ్గి స్థిరత్వం వస్తుంది – ఉదా: భారత్‌లో భాషా ప్రాతిపదికన రాష్ట్రాలు ఏర్పాటు చేయడం వల్ల భాషా ఘర్షణలు తగ్గి దేశ ఐక్యత బలపడింది.","నైతిక కారణం: పాలనతో ప్రభావితమయ్యే ప్రజలకు అధికారంలో భాగం ఉండాలి – ఉదా: పంచాయతీరాజ్ వ్యవస్థ గ్రామ ప్రజలు తమ పాలనలో నేరుగా పాల్గొనేలా చేస్తుంది.","3) ఔసెఫ్ అభిప్రాయంతో ఏకీభవిస్తాను.","కారణాలు: (i) అధికార విభజన ప్రజాస్వామ్య స్ఫూర్తి – సమాజం చిన్నదైనా, విభజనలు లేకపోయినా ప్రజలను సంప్రదించాలి.","(ii) ప్రతి ప్రజాస్వామ్యంలో శాసన, కార్యనిర్వాహక, న్యాయ శాఖల మధ్య విభజన తప్పనిసరి – లేకపోతే నిరంకుశత్వం వస్తుంది.","(iii) థామ్మన్, మథాయి అభిప్రాయాలు అధికార విభజనకు వివేకపూర్వక కారణాన్ని మాత్రమే చూస్తాయి; నైతిక కారణాన్ని విస్మరిస్తాయి.","4) ఈ నిషేధం బెల్జియం అధికార విభజన స్ఫూర్తికి అనుగుణంగా లేదు.","కారణాలు: (i) బెల్జియం నమూనా అన్ని భాషా వర్గాల ఉనికి, సంస్కృతిని గౌరవించడంపై నిలుస్తుంది.","(ii) ఫ్రెంచ్ మాట్లాడటంపై నిషేధం ఒక వర్గంపై మరో వర్గం ఇష్టాన్ని రుద్దడమే – ఇది శ్రీలంక మెజారిటీవాదం లాంటిది.","(iii) ఇలాంటి చర్యలు వర్గాల మధ్య ఉద్రిక్తత పెంచి ఐక్యతను దెబ్బతీస్తాయి; కలుపుకోవడం (integration) నిర్బంధంతో కాదు, గౌరవంతో రావాలి."]],["అభ్యాసాలు – ప్రశ్నలు 5–7 (పుట 24)",["5) పంచాయతీరాజ్ గద్యంలో వివేకపూర్వక కారణం: “పంచాయతీలకు అధికారం ఇవ్వడం అవినీతిని తగ్గించి పరిపాలనా సామర్థ్యాన్ని పెంచుతుంది” – ప్రజలు ప్రణాళిక, అమలులో పాల్గొంటే అవినీతి దళారులు తొలగిపోతారు. (“ప్రజల చేతికి అధికారం” అనేది నైతిక కారణం.)","6) జవాబు: (a) A, B, D, F.","అనుకూల వాదనలు: A – ఘర్షణ తగ్గిస్తుంది; B – ఏకపక్ష నిర్ణయాల అవకాశం తగ్గిస్తుంది; D – వైవిధ్యాలకు చోటిస్తుంది; F – ప్రజల భాగస్వామ్యం పెంచుతుంది.","C, E, G వ్యతిరేక వాదనలు.","7) జవాబు: (d) B, C, D.","A తప్పు – బెల్జియంలో డచ్ మెజారిటీ ఆధిపత్యం రుద్దలేదు; అందరూ కలిసి జీవించే ఏర్పాటు చేశారు."]],["అభ్యాసాలు – ప్రశ్నలు 8–9 (పుట 26)",["8) జవాబు: (c) – 1-B (ప్రభుత్వ అంగాల మధ్య → అధికారాల విభజన), 2-D (వివిధ స్థాయిల మధ్య → సమాఖ్య ప్రభుత్వం), 3-A (సామాజిక వర్గాల మధ్య → సమాజ ప్రభుత్వం), 4-C (పార్టీల మధ్య → సంకీర్ణ ప్రభుత్వం).","9) జవాబు: (b) A, B రెండూ నిజం – అధికార విభజన ప్రజాస్వామ్యానికి మంచిది; సామాజిక వర్గాల మధ్య ఘర్షణ అవకాశాలను తగ్గిస్తుంది."]]]},{"id":"cv2","no":19,"t":"సమాఖ్య వ్యవస్థ (Federalism)","m":[8],"ty":"పౌరశాస్త్రం – అధ్యాయం 2","by":"సాంఘిక శాస్త్రం – ప్రజాస్వామ్య రాజకీయాలు-II, 10వ తరగతి (పుటలు 28–59)","th":"సమాఖ్య వ్యవస్థ అంటే ఏమిటి, లక్షణాలు, కలిసివచ్చే–కలిపి ఉంచే సమాఖ్యలు, భారత్ సమాఖ్య (మూడు జాబితాలు), భాషా రాష్ట్రాలు, భాషా విధానం, కేంద్ర–రాష్ట్ర సంబంధాలు, వికేంద్రీకరణ, 1992 సవరణ, స్థానిక ప్రభుత్వాలు","sum":"సమాఖ్య వ్యవస్థ (Federalism) అంటే అధికారం కేంద్ర అధికార సంస్థకు, దేశంలోని వివిధ అంగ విభాగాలకు (రాష్ట్రాలకు) మధ్య విభజించబడిన ప్రభుత్వ వ్యవస్థ. ఏకకేంద్ర (unitary) వ్యవస్థలో ఒకే స్థాయి ప్రభుత్వం ఉంటుంది, కింది స్థాయిలు దానికి లోబడి ఉంటాయి; సమాఖ్యలో కేంద్ర ప్రభుత్వం రాష్ట్రాన్ని ఏదైనా చేయమని ఆదేశించలేదు. 1993లో బెల్జియం ఏకకేంద్రం నుండి సమాఖ్యకు మారింది; శ్రీలంక ఇప్పటికీ ఏకకేంద్రమే. ప్రపంచంలోని 193 దేశాల్లో 25 మాత్రమే సమాఖ్యలు, కానీ ప్రపంచ జనాభాలో 40% వాటిలోనే. సమాఖ్య లక్షణాలు: రెండు/అంతకంటే ఎక్కువ స్థాయిల ప్రభుత్వాలు; ఒకే పౌరులపై ప్రతి స్థాయికి తన పరిధి (jurisdiction); అధికారాలు రాజ్యాంగంలో; ప్రాథమిక నిబంధనలు ఒక స్థాయి ఒంటరిగా మార్చలేదు; న్యాయస్థానాలు వివాదాలు పరిష్కరిస్తాయి; ఆర్థిక స్వయంప్రతిపత్తికి ఆదాయ వనరులు; ఐక్యత కాపాడుతూ వైవిధ్యాన్ని గౌరవించడం. సమాఖ్యలు రెండు విధాలుగా ఏర్పడతాయి – “కలిసివచ్చే” (coming together: అమెరికా, స్విట్జర్లాండ్, ఆస్ట్రేలియా – రాష్ట్రాలు సమానం, బలమైనవి), “కలిపి ఉంచే” (holding together: భారత్, స్పెయిన్, బెల్జియం – కేంద్రం బలమైనది, రాష్ట్రాల అధికారాలు అసమానం). భారత రాజ్యాంగం భారత్‌ను “రాష్ట్రాల యూనియన్” అంటుంది; సమాఖ్య అనే పదం వాడకపోయినా సమాఖ్య సూత్రాలపై నిలుస్తుంది. మొదట రెండు స్థాయిలు, తర్వాత పంచాయతీలు–మున్సిపాలిటీలు మూడో స్థాయి. శాసన అధికారాలు మూడు జాబితాలు – యూనియన్ (రక్షణ, విదేశాంగ, బ్యాంకింగ్, సమాచార రంగం, కరెన్సీ), రాష్ట్ర (పోలీసు, వాణిజ్యం, వ్యవసాయం, నీటిపారుదల), ఉమ్మడి (విద్య, అడవులు, కార్మిక సంఘాలు, వివాహం, దత్తత, వారసత్వం – విభేదిస్తే కేంద్ర చట్టమే చెల్లుతుంది); మిగిలిన అంశాలు (residuary) కేంద్రానికి. అస్సాం, నాగాలాండ్, అరుణాచల్, మిజోరం వంటి రాష్ట్రాలకు ప్రత్యేక హోదా; ఢిల్లీ, చండీగఢ్, లక్షద్వీప్ వంటి కేంద్రపాలిత ప్రాంతాలకు తక్కువ అధికారాలు. ఈ విభజన మార్చాలంటే పార్లమెంటు రెండు సభల్లో 2/3 మెజారిటీ + కనీసం సగం రాష్ట్రాల శాసనసభల ఆమోదం. సమాఖ్య ఆచరణలో – భాషా రాష్ట్రాలు (1947 తర్వాత), భాషా విధానం (జాతీయ భాష లేదు; హిందీ అధికార భాష – 40% మాతృభాష; 22 షెడ్యూల్డ్ భాషలు; హిందీయేతర రాష్ట్రాలు, ముఖ్యంగా తమిళనాడు వ్యతిరేకించగా ఇంగ్లీషు కూడా కొనసాగింది), కేంద్ర–రాష్ట్ర సంబంధాలు (1990 తర్వాత ప్రాంతీయ పార్టీలు, సంకీర్ణ ప్రభుత్వాలు; రాష్ట్ర ప్రభుత్వాలను ఏకపక్షంగా రద్దు చేయడం కష్టం చేసిన సుప్రీంకోర్టు తీర్పు). 2011 జనగణన – 1300కు పైగా మాతృభాషలు, 121 ప్రధాన భాషలు. వికేంద్రీకరణ: 1992 రాజ్యాంగ సవరణ – స్థానిక సంస్థలకు క్రమం తప్పక ఎన్నికలు, SC/ST/OBCలకు రిజర్వేషన్లు, మహిళలకు కనీసం 1/3 స్థానాలు, రాష్ట్ర ఎన్నికల సంఘం, అధికారాలు–ఆదాయం పంచుకోవడం. గ్రామ పంచాయతీ (సర్పంచ్, గ్రామ సభ) → పంచాయతీ సమితి/మండలం → జిల్లా పరిషత్; పట్టణాల్లో మున్సిపాలిటీ (చైర్‌పర్సన్), నగరాల్లో మున్సిపల్ కార్పొరేషన్ (మేయర్). దేశంలో సుమారు 36 లక్షల మంది ఎన్నికైన స్థానిక ప్రతినిధులు – ప్రపంచంలోనే అతిపెద్ద ప్రజాస్వామ్య ప్రయోగం.","pts":["సమాఖ్య వ్యవస్థ: అధికారం కేంద్ర అధికార సంస్థకు, దేశంలోని అంగ విభాగాలకు (రాష్ట్రాలు/ప్రావిన్సులు) మధ్య విభజించబడిన ప్రభుత్వ వ్యవస్థ.","ఏకకేంద్ర వ్యవస్థ (Unitary): ఒకే స్థాయి ప్రభుత్వం, లేదా కింది స్థాయిలు కేంద్రానికి లోబడి ఉంటాయి – కేంద్రం వాటికి ఆదేశాలు ఇవ్వగలదు (ఉదా: శ్రీలంక).","ప్రపంచంలో 193 దేశాల్లో 25 మాత్రమే సమాఖ్యలు; కానీ వాటిలో ప్రపంచ జనాభాలో 40% మంది నివసిస్తారు; పెద్ద దేశాలు ఎక్కువగా సమాఖ్యలు.","సమాఖ్య లక్షణాలు (1–4): రెండు లేదా ఎక్కువ స్థాయిల ప్రభుత్వాలు; ఒకే పౌరులను పాలించినా శాసనం, పన్నులు, పరిపాలనలో ప్రతి స్థాయికి తన పరిధి; పరిధులు రాజ్యాంగంలో పేర్కొనబడతాయి; ప్రాథమిక నిబంధనలు ఒక స్థాయి ఒంటరిగా మార్చలేదు.","సమాఖ్య లక్షణాలు (5–7): రాజ్యాంగ వ్యాఖ్యానం, వివాదాల పరిష్కారం న్యాయస్థానాలది; ప్రతి స్థాయికి ప్రత్యేక ఆదాయ వనరులు; లక్ష్యం – దేశ ఐక్యత కాపాడటం + ప్రాంతీయ వైవిధ్యానికి చోటు.","సమాఖ్యకు ముఖ్యం: పరస్పర నమ్మకం, కలిసి జీవించాలనే అంగీకారం.","కలిసివచ్చే సమాఖ్యలు (Coming together): స్వతంత్ర రాష్ట్రాలు భద్రత కోసం కలిసి పెద్ద దేశంగా – అమెరికా, స్విట్జర్లాండ్, ఆస్ట్రేలియా; రాష్ట్రాలకు సమాన అధికారాలు, బలమైనవి.","కలిపి ఉంచే సమాఖ్యలు (Holding together): పెద్ద దేశం తన అధికారాన్ని రాష్ట్రాలతో పంచుకోవడం – భారత్, స్పెయిన్, బెల్జియం; కేంద్రం బలమైనది, రాష్ట్రాల అధికారాలు అసమానం.","భారత్: రాజ్యాంగం “రాష్ట్రాల యూనియన్” అని ప్రకటించింది; మొదట రెండు స్థాయిలు (యూనియన్, రాష్ట్రాలు), తర్వాత పంచాయతీలు, మున్సిపాలిటీలు మూడో స్థాయి.","యూనియన్ జాబితా: జాతీయ ప్రాముఖ్యత – రక్షణ, విదేశీ వ్యవహారాలు, బ్యాంకింగ్, సమాచార వ్యవస్థ, కరెన్సీ; కేంద్రం మాత్రమే చట్టాలు చేస్తుంది.","రాష్ట్ర జాబితా: రాష్ట్ర, స్థానిక ప్రాముఖ్యత – పోలీసు, వాణిజ్యం, వ్యాపారం, వ్యవసాయం, నీటిపారుదల; రాష్ట్రాలు మాత్రమే చట్టాలు చేస్తాయి.","ఉమ్మడి జాబితా: విద్య, అడవులు, కార్మిక సంఘాలు, వివాహం, దత్తత, వారసత్వం – ఇద్దరూ చట్టాలు చేయవచ్చు; విభేదిస్తే కేంద్ర చట్టమే చెల్లుతుంది.","అవశిష్ట అధికారాలు (Residuary): ఏ జాబితాలోనూ లేని అంశాలు (ఉదా: కంప్యూటర్ సాఫ్ట్‌వేర్) – కేంద్రానికి.","ప్రత్యేక హోదా: అస్సాం, నాగాలాండ్, అరుణాచల్ ప్రదేశ్, మిజోరం వంటి రాష్ట్రాలు (చరిత్ర, సంస్కృతి కారణంగా – ఆర్టికల్ 371); కేంద్రపాలిత ప్రాంతాలు (చండీగఢ్, లక్షద్వీప్, ఢిల్లీ) – కేంద్రానికి ప్రత్యేక అధికారాలు.","అధికార విభజన మార్చాలంటే: పార్లమెంటు రెండు సభల్లో 2/3 మెజారిటీ + కనీసం సగం రాష్ట్రాల శాసనసభల ఆమోదం; వివాదాలు హైకోర్టులు, సుప్రీంకోర్టు తేలుస్తాయి.","భాషా రాష్ట్రాలు: భాష ఆధారంగా రాష్ట్రాల పునర్వ్యవస్థీకరణ (రాష్ట్రాల పునర్వ్యవస్థీకరణ కమిషన్ – 1 నవంబర్ 1956 అమలు) – భయాలకు విరుద్ధంగా దేశం మరింత ఐక్యమైంది, పరిపాలన సులభమైంది; సంస్కృతి, జాతి, భౌగోళికత ఆధారంగా కూడా (నాగాలాండ్, ఉత్తరాఖండ్, జార్ఖండ్).","భాషా విధానం: జాతీయ భాష లేదు; హిందీ అధికార భాష (40% మాతృభాష); హిందీ కాకుండా 22 షెడ్యూల్డ్ భాషలు; కేంద్ర పరీక్షలు వీటిలో రాయవచ్చు; రాష్ట్రాలకు సొంత అధికార భాషలు; 1965 తర్వాత కూడా ఇంగ్లీషు కొనసాగింపు (తమిళనాడు ఉద్యమం).","కేంద్ర–రాష్ట్ర సంబంధాలు: 1990 వరకు ఒకే పార్టీ పాలనతో కేంద్రం ప్రత్యర్థి రాష్ట్ర ప్రభుత్వాలను తరచూ రద్దు చేసేది; 1990 తర్వాత ప్రాంతీయ పార్టీల ఎదుగుదల, సంకీర్ణ ప్రభుత్వాలు → రాష్ట్రాల స్వయంప్రతిపత్తికి గౌరవం; సుప్రీంకోర్టు తీర్పుతో ఏకపక్ష రద్దు కష్టం.","వికేంద్రీకరణ: కేంద్ర, రాష్ట్ర ప్రభుత్వాల నుండి అధికారాన్ని స్థానిక ప్రభుత్వాలకు ఇవ్వడం – స్థానిక సమస్యలకు స్థానిక పరిష్కారం, ప్రజల ప్రత్యక్ష భాగస్వామ్యం.","1992 రాజ్యాంగ సవరణ: క్రమం తప్పక స్థానిక ఎన్నికలు; SC, ST, OBCలకు స్థానాలు, అధ్యక్ష పదవుల్లో రిజర్వేషన్; మహిళలకు కనీసం 1/3 స్థానాలు; ప్రతి రాష్ట్రంలో రాష్ట్ర ఎన్నికల సంఘం; రాష్ట్రాలు అధికారాలు, ఆదాయం పంచాలి.","గ్రామీణ స్థానిక ప్రభుత్వం (పంచాయతీరాజ్): గ్రామ పంచాయతీ (సర్పంచ్, వార్డు సభ్యులు/పంచ్‌లు) – గ్రామ సభ (గ్రామ ఓటర్లందరూ; ఏటా కనీసం 2–3 సార్లు సమావేశం) పర్యవేక్షణలో → పంచాయతీ సమితి/బ్లాక్/మండలం → జిల్లా పరిషత్ (చైర్‌పర్సన్).","పట్టణ స్థానిక ప్రభుత్వం: పట్టణాల్లో మున్సిపాలిటీ (మున్సిపల్ చైర్‌పర్సన్), పెద్ద నగరాల్లో మున్సిపల్ కార్పొరేషన్ (మేయర్).","సుమారు 36 లక్షల మంది ఎన్నికైన స్థానిక ప్రతినిధులు – ప్రపంచంలోనే అతిపెద్ద ప్రజాస్వామ్య ప్రయోగం; సమస్యలు: గ్రామ సభలు క్రమంగా జరగకపోవడం, తగిన అధికారాలు–నిధులు లేకపోవడం.","పోర్టో అలెగ్రే (బ్రెజిల్): సుమారు 13 లక్షల ప్రజలు నగర బడ్జెట్ తయారీలో నేరుగా పాల్గొంటారు – భాగస్వామ్య ప్రజాస్వామ్యానికి ఉదాహరణ."],"w":[["సమాఖ్య వ్యవస్థ","Federalism"],["ఏకకేంద్ర ప్రభుత్వం","Unitary government"],["పరిధి (అధికార క్షేత్రం)","Jurisdiction"],["కలిసివచ్చే సమాఖ్య","Coming together federation"],["కలిపి ఉంచే సమాఖ్య","Holding together federation"],["యూనియన్ జాబితా","Union List"],["రాష్ట్ర జాబితా","State List"],["ఉమ్మడి జాబితా","Concurrent List"],["అవశిష్ట అంశాలు","Residuary subjects"],["కేంద్రపాలిత ప్రాంతాలు","Union Territories"],["సంకీర్ణ ప్రభుత్వం","Coalition government"],["వికేంద్రీకరణ","Decentralisation"],["షెడ్యూల్డ్ భాషలు","Scheduled Languages"],["గ్రామ సభ","Gram Sabha"],["జిల్లా పరిషత్","Zilla Parishad"],["మేయర్ (కార్పొరేషన్ అధిపతి)","Mayor"],["ప్రత్యేక హోదా","Special status"],["రాష్ట్ర ఎన్నికల సంఘం","State Election Commission"]],"gr":{"t":"మూడు జాబితాలు (భారత రాజ్యాంగం)","p":["జాబితా | ఎవరు చట్టం చేస్తారు | ఉదాహరణలు","యూనియన్ జాబితా | కేంద్రం మాత్రమే | రక్షణ, విదేశీ వ్యవహారాలు, బ్యాంకింగ్, సమాచారం, కరెన్సీ","రాష్ట్ర జాబితా | రాష్ట్రాలు మాత్రమే | పోలీసు, వాణిజ్యం, వ్యాపారం, వ్యవసాయం, నీటిపారుదల","ఉమ్మడి జాబితా | ఇద్దరూ (విభేదిస్తే కేంద్ర చట్టం) | విద్య, అడవులు, కార్మిక సంఘాలు, వివాహం, దత్తత, వారసత్వం","అవశిష్ట అంశాలు | కేంద్రం | కంప్యూటర్ సాఫ్ట్‌వేర్ వంటి కొత్త అంశాలు"]},"qa":[["సమాఖ్య వ్యవస్థ అంటే ఏమిటి?","అధికారం కేంద్ర అధికార సంస్థకు, దేశంలోని వివిధ అంగ విభాగాలకు మధ్య విభజించబడిన ప్రభుత్వ వ్యవస్థ."],["ఏకకేంద్ర, సమాఖ్య ప్రభుత్వాల మధ్య ముఖ్య తేడా?","ఏకకేంద్రంలో కేంద్రం కింది స్థాయి ప్రభుత్వాలకు ఆదేశాలు ఇవ్వగలదు; సమాఖ్యలో రాష్ట్రాలకు రాజ్యాంగబద్ధ అధికారాలు ఉంటాయి – కేంద్రం వాటిని ఆదేశించలేదు."],["“కలిసివచ్చే” సమాఖ్యలకు ఉదాహరణలు?","అమెరికా, స్విట్జర్లాండ్, ఆస్ట్రేలియా."],["“కలిపి ఉంచే” సమాఖ్యలకు ఉదాహరణలు?","భారత్, స్పెయిన్, బెల్జియం."],["అవశిష్ట అధికారాలు ఎవరికి?","కేంద్ర (యూనియన్) ప్రభుత్వానికి."],["ఉమ్మడి జాబితా అంశాలపై కేంద్ర, రాష్ట్ర చట్టాలు విభేదిస్తే?","కేంద్ర ప్రభుత్వ చట్టమే చెల్లుతుంది."],["అధికార విభజనను మార్చడానికి కావలసినది?","పార్లమెంటు రెండు సభల్లో కనీసం 2/3 మెజారిటీ + కనీసం సగం రాష్ట్రాల శాసనసభల ఆమోదం."],["భారత్‌లో షెడ్యూల్డ్ భాషలు ఎన్ని?","హిందీ కాకుండా 22 భాషలు (ఎనిమిదవ షెడ్యూల్)."],["1992 సవరణ ప్రకారం మహిళలకు రిజర్వేషన్?","స్థానిక సంస్థల్లో కనీసం మూడింట ఒక వంతు (1/3) స్థానాలు."],["మున్సిపల్ కార్పొరేషన్ అధిపతిని ఏమంటారు?","మేయర్."]],"act":"మీ గ్రామ పంచాయతీ / పట్టణ మున్సిపాలిటీ వివరాలు సేకరించండి: వార్డు సభ్యుడు, సర్పంచ్ (లేదా కౌన్సిలర్, చైర్‌పర్సన్), మండల పరిషత్ అధ్యక్షుడు, జిల్లా పరిషత్ చైర్‌పర్సన్ పేర్లు; చివరి గ్రామ సభ ఎప్పుడు జరిగింది, ఎంతమంది పాల్గొన్నారు – ఒక చార్ట్ తయారుచేయండి.","kn":"భాష ఆధారంగా ఏర్పడిన మొదటి రాష్ట్రం ఆంధ్ర రాష్ట్రం (1953) – పొట్టి శ్రీరాములు గారి నిరాహార దీక్ష, బలిదానం తర్వాత. మన నెల్లూరు జిల్లా ఆయన పేరుతోనే “శ్రీ పొట్టి శ్రీరాములు నెల్లూరు జిల్లా”!","qz":[["సమాఖ్య వ్యవస్థలు ఉన్న దేశాల సంఖ్య (193లో)?","25","40","100","193"],["సమాఖ్య దేశాల్లో నివసిస్తున్న ప్రపంచ జనాభా శాతం?","40%","25%","60%","10%"],["బెల్జియం ఏకకేంద్రం నుండి సమాఖ్యకు మారిన సంవత్సరం?","1993","1970","1956","2009"],["“కలిసివచ్చే” సమాఖ్యకు ఉదాహరణ?","అమెరికా","భారత్","స్పెయిన్","బెల్జియం"],["“కలిపి ఉంచే” సమాఖ్యకు ఉదాహరణ?","భారత్","అమెరికా","స్విట్జర్లాండ్","ఆస్ట్రేలియా"],["యూనియన్ జాబితాలోని అంశం?","రక్షణ","పోలీసు","వ్యవసాయం","విద్య"],["రాష్ట్ర జాబితాలోని అంశం?","పోలీసు","బ్యాంకింగ్","కరెన్సీ","విదేశీ వ్యవహారాలు"],["ఉమ్మడి జాబితాలోని అంశం?","విద్య","రక్షణ","నీటిపారుదల","కరెన్సీ"],["కంప్యూటర్ సాఫ్ట్‌వేర్ వంటి అవశిష్ట అంశాలపై చట్టం చేసేది?","కేంద్ర ప్రభుత్వం","రాష్ట్ర ప్రభుత్వం","స్థానిక ప్రభుత్వం","సుప్రీంకోర్టు"],["కేంద్రపాలిత ప్రాంతానికి ఉదాహరణ?","చండీగఢ్","నాగాలాండ్","గోవా","సిక్కిం"],["హిందీని మాతృభాషగా మాట్లాడేవారు సుమారు?","40%","70%","22%","11%"],["భారత్‌లో హిందీ కాకుండా షెడ్యూల్డ్ భాషలు?","22","14","121","18"],["స్థానిక ప్రభుత్వాలను బలోపేతం చేసిన రాజ్యాంగ సవరణ సంవత్సరం?","1992","1956","1990","1947"],["స్థానిక సంస్థల్లో మహిళలకు కనీస రిజర్వేషన్?","మూడింట ఒక వంతు","సగం","నాలుగో వంతు","పదో వంతు"],["పంచాయతీ, మున్సిపల్ ఎన్నికలు నిర్వహించేది?","రాష్ట్ర ఎన్నికల సంఘం","భారత ఎన్నికల సంఘం","జిల్లా కలెక్టర్","గ్రామ సభ"],["గ్రామ పంచాయతీని పర్యవేక్షించే గ్రామ ఓటర్లందరి సభ?","గ్రామ సభ","జిల్లా పరిషత్","పంచాయతీ సమితి","శాసనసభ"]],"wb":{"mis":"భారత రాజ్యాంగంలో “సమాఖ్య” అనే పదం లేకపోయినా భారత్ సమాఖ్యనే. సమాఖ్య పెద్ద దేశాలకే అనేది తప్పు – చిన్న బెల్జియం కూడా సమాఖ్య అయింది. రాష్ట్రాలు కేంద్రానికి లోబడినవి కావు – రాజ్యాంగం ఇచ్చిన సొంత అధికారాలు ఉన్నాయి.","pg":"28–59","f":"books/10/Class10_Social_Civics_Textbook.pdf","p":30,"lb":"పాఠ్యపుస్తకం","ws":["ఆలోచించండి – పటం, బొమ్మ (పుట 30)","ఆలోచించండి – బెల్జియం ఎందుకు సమాఖ్య? (పుట 32)","నేపాల్ సంభాషణ – మీ స్పందన (పుట 34)","కృత్యం – ఆకాశవాణి వార్తలు, ఆలోచించండి (పుట 36)","ఆలోచించండి – మూడు సందర్భాలు (పుట 38)","కృత్యం – రాష్ట్రాల మార్పులు (పుట 40)","ఆలోచించండి – “హిందీయే ఎందుకు?” (పుట 42)","కార్టూన్లు – కేంద్ర–రాష్ట్ర సంబంధాలు; ప్రాంతీయవాదం (పుట 44)","కృత్యం – భాషల పట్టిక (పుట 46)","Let us revise – రామచంద్ర గుహ వ్యాసం (చిన్న నోట్) (పుట 48)","ఆలోచించండి – “మూడంచెల రైలు బోగీ” (పుట 50)","వార్తాపత్రిక క్లిప్పింగులు; కలెక్టర్ ప్రశ్న (పుట 52)","కృత్యం – మీ స్థానిక ప్రభుత్వం (పుట 54)","అభ్యాసాలు – ప్రశ్నలు 1–5 (పుట 56)","అభ్యాసాలు – ప్రశ్నలు 6–9 (పుట 56)","అభ్యాసాలు – ప్రశ్నలు 10–12 (పుట 58)"]},"tg":[["ఆలోచించండి – పటం, బొమ్మ (పుట 30)",["“భారత ప్రభుత్వాన్ని యూనియన్, ఫెడరల్ లేదా సెంట్రల్ – ఏమంటారు?” – రాజ్యాంగం భారత్‌ను “రాష్ట్రాల యూనియన్” అంటుంది; కాబట్టి అధికారిక పేరు యూనియన్ ప్రభుత్వం; సాధారణంగా కేంద్ర ప్రభుత్వం అంటాం; సమాఖ్య వ్యవస్థలో దాన్ని సమాఖ్య (ఫెడరల్) ప్రభుత్వం అని కూడా అంటారు.","పటంలో మినహాయింపు: పెద్ద దేశాలు ఎక్కువగా సమాఖ్యలు; కానీ చైనా చాలా పెద్ద దేశమైనా సమాఖ్య కాదు – ఏకకేంద్ర వ్యవస్థ. (పటంలో గుర్తించినవి: భారత్, అమెరికా, రష్యా, బ్రెజిల్, కెనడా, ఆస్ట్రేలియా, దక్షిణాఫ్రికా వంటి సమాఖ్యలు.)"]],["ఆలోచించండి – బెల్జియం ఎందుకు సమాఖ్య? (పుట 32)",["1) సమాఖ్య పెద్ద దేశాలకే కాదు – వైవిధ్యాన్ని గౌరవిస్తూ ఐక్యత కాపాడటమే దాని ఉద్దేశం.","2) బెల్జియంలో డచ్, ఫ్రెంచ్, జర్మన్ భాషా వర్గాలు వేర్వేరు ప్రాంతాల్లో కేంద్రీకృతమై ఉన్నాయి.","3) ప్రాంతాలకు రాజ్యాంగబద్ధ అధికారాలు ఇవ్వడం ద్వారా ఘర్షణ తగ్గించి దేశ విభజన తప్పించడానికే బెల్జియం 1993లో సమాఖ్యగా మారింది."]],["నేపాల్ సంభాషణ – మీ స్పందన (పుట 34)",["సరిత (“చిన్న దేశం – సమాఖ్య అక్కర్లేదు”) – తప్పు అవగాహన: 1) సమాఖ్య దేశ పరిమాణం మీద కాదు, వైవిధ్యం మీద ఆధారపడుతుంది.","2) చిన్న బెల్జియం కూడా సమాఖ్యే.","3) నేపాల్‌లో కొండ, తరాయ్ ప్రాంతాలు, అనేక భాషలు, జాతులు ఉన్నాయి.","బాబూలాల్ (“తరాయ్ ప్రాంతానికి సొంత రాష్ట్ర ప్రభుత్వంతో ఎక్కువ స్వయంప్రతిపత్తి”) – సరైన అవగాహన: సమాఖ్య ప్రాంతాలకు స్వయంప్రతిపత్తి ఇచ్చి ప్రాంతీయ వైవిధ్యాన్ని గౌరవిస్తుంది.","రామ్ గణేష్ (“రాజు అధికారాలు ఎన్నికైన ప్రతినిధులకు”) – తప్పు అవగాహన: 1) అది రాచరికం నుండి ప్రజాస్వామ్యానికి మార్పు మాత్రమే.","2) సమాఖ్య అంటే వేర్వేరు స్థాయిల ప్రభుత్వాల మధ్య అధికార విభజన.","“రాజ్యాంగ నిర్మాతలకు సమాఖ్య తెలియదా?” – తెలుసు; “రాష్ట్రాల యూనియన్” అనే పదం వాడారు – రాష్ట్రాలు ఒప్పందంతో కలిసినవి కావు, అందువల్ల విడిపోయే హక్కు లేదు అని స్పష్టం చేయడానికి; అయినా వ్యవస్థ సమాఖ్య సూత్రాలపైనే ఉంది."]],["కృత్యం – ఆకాశవాణి వార్తలు, ఆలోచించండి (పుట 36)",["1) ఒక వారం జాతీయ, ప్రాంతీయ వార్తల నుండి మూడు వర్గాలుగా జాబితా (విద్యార్థుల సొంత పని). నమూనా:","కేంద్రం మాత్రమే – రక్షణ ఒప్పందం, రిజర్వ్ బ్యాంకు వడ్డీ రేటు, రైల్వే బడ్జెట్, విదేశీ పర్యటన.","రాష్ట్రం మాత్రమే – రాష్ట్ర పోలీసు నియామకాలు, సాగునీటి ప్రాజెక్టు, రాష్ట్ర వ్యవసాయ పథకం.","కేంద్ర–రాష్ట్ర సంబంధాలు – GST పరిహారం, కేంద్ర నిధుల విడుదల, నదీ జలాల వివాదం, విపత్తు సహాయం.","“వ్యవసాయం, వాణిజ్యం రాష్ట్ర అంశాలైతే కేంద్రంలో ఆ మంత్రులెందుకు?” – 1) జాతీయ విధానాలు (కనీస మద్దతు ధర, ఎగుమతి–దిగుమతి, అంతర్రాష్ట్ర, విదేశీ వాణిజ్యం) కేంద్రానివే.","2) పరిశోధన, పెద్ద పథకాలు, రాష్ట్రాలకు నిధులు, సమన్వయం కోసం కేంద్ర మంత్రిత్వ శాఖలు అవసరం."]],["ఆలోచించండి – మూడు సందర్భాలు (పుట 38)",["1) పోఖ్రాన్ అణుపరీక్షలు: రాజస్థాన్ ప్రభుత్వం అడ్డుకోలేదు – రక్షణ యూనియన్ జాబితా అంశం; కేంద్రానిదే అధికారం.","2) సిక్కిం కొత్త పాఠ్యపుస్తకాలు: విద్య ఉమ్మడి జాబితాలో ఉంది – రాష్ట్రం కేంద్ర అనుమతి తీసుకోనవసరం లేదు; కానీ ఆ అంశంపై కేంద్ర చట్టం/జాతీయ విధానం ఉంటే దానికి విరుద్ధంగా ఉండకూడదు (విభేదిస్తే కేంద్ర చట్టమే చెల్లుతుంది).","3) నక్సలైట్లపై పోలీసు విధానం: పోలీసు రాష్ట్ర జాబితా అంశం – ప్రధానమంత్రి ముఖ్యమంత్రులందరూ పాటించాల్సిన ఆదేశం ఇవ్వలేరు; సమన్వయం కోసం చర్చలు, సలహాలు మాత్రమే."]],["కృత్యం – రాష్ట్రాల మార్పులు (పుట 40)",["1) మా ఊరు (TV పల్లి, గూడూరు, SPSR నెల్లూరు): 1947లో మద్రాసు రాష్ట్రంలో → 1953 ఆంధ్ర రాష్ట్రం → 1956 ఆంధ్రప్రదేశ్ → 2014 విభజన తర్వాత కూడా ఆంధ్రప్రదేశ్‌లోనే.","2) 1947 తర్వాత పేర్లు మారిన రాష్ట్రాలు: మద్రాసు → తమిళనాడు, మైసూరు → కర్ణాటక, యునైటెడ్ ప్రావిన్సెస్ → ఉత్తర్‌ప్రదేశ్ (ఒరిస్సా → ఒడిశా కూడా).","3) పెద్ద రాష్ట్రాల నుండి ఏర్పడినవి: ఛత్తీస్‌గఢ్ (మధ్యప్రదేశ్ నుండి, 2000), జార్ఖండ్ (బీహార్, 2000), ఉత్తరాఖండ్ (ఉత్తర్‌ప్రదేశ్, 2000); తెలంగాణ (ఆంధ్రప్రదేశ్, 2014), నాగాలాండ్ (అస్సాం, 1963), హర్యానా (పంజాబ్, 1966)."]],["ఆలోచించండి – “హిందీయే ఎందుకు?” (పుట 42)",["1) హిందీ ఎక్కువ మంది (సుమారు 40%) మాతృభాష కాబట్టి అధికార భాషగా ఎంచారు; అయినా జాతీయ భాష హోదా ఏ భాషకూ ఇవ్వలేదు.","2) బంగ్లా, తెలుగు వంటి భాషలను కాపాడటానికి 22 షెడ్యూల్డ్ భాషలు, రాష్ట్రాలకు సొంత అధికార భాషలు, కేంద్ర పరీక్షలు ఏ షెడ్యూల్డ్ భాషలోనైనా రాసే అవకాశం ఉన్నాయి.","3) హిందీని బలవంతంగా రుద్దకుండా, ఇంగ్లీషును కూడా కొనసాగించడం వల్ల శ్రీలంక వంటి పరిస్థితి రాలేదు."]],["కార్టూన్లు – కేంద్ర–రాష్ట్ర సంబంధాలు; ప్రాంతీయవాదం (పుట 44)",["“రాష్ట్రాలు బిచ్చపాత్రతో కేంద్రం వద్దకు వెళ్లాలా?” – వెళ్లకూడదు: 1) సమాఖ్యలో రాష్ట్రాలు కేంద్రానికి లోబడినవి కావు.","2) రాజ్యాంగం వాటికి సొంత అధికారాలు, ఆదాయ వనరులు ఇచ్చింది.","3) పన్నుల ఆదాయంలో న్యాయమైన వాటా వాటి హక్కు – దయ కాదు.","“సంకీర్ణ నాయకుడు భాగస్వాములను ఎలా సంతృప్తిపరచాలి?” – 1) ఉమ్మడి కనీస కార్యక్రమం తయారుచేయడం.","2) మంత్రిపదవుల్లో న్యాయమైన వాటా.","3) ముఖ్య నిర్ణయాలకు ముందు సంప్రదింపులు, సమన్వయ కమిటీ.","4) ప్రాంతీయ పార్టీల రాష్ట్రాల ప్రయోజనాలను గౌరవించడం.","“ప్రాంతీయవాదం ప్రజాస్వామ్యానికి మంచిదా?” – ప్రాంతీయ పార్టీలు, ప్రాంతీయ ఆకాంక్షలు ప్రజాస్వామ్యంలో భాగమే; అవి రాష్ట్రాల స్వయంప్రతిపత్తిని, అధికార విభజనను బలపరిచాయి. కానీ దేశ ఐక్యతను దెబ్బతీసే వేర్పాటువాదం కాకూడదు."]],["కృత్యం – భాషల పట్టిక (పుట 46)",["1) పట్టికలోని శాతాలతో బార్ గ్రాఫ్/పై చార్ట్ (విద్యార్థుల సొంత పని) – హిందీ అతిపెద్ద భాగం; తర్వాత బెంగాలీ, మరాఠీ, తెలుగు, తమిళం…","2) భారత పటంలో భాషా ప్రాంతాలు షేడ్ చేయండి – ఉదా: తెలుగు → ఆంధ్రప్రదేశ్, తెలంగాణ; తమిళం → తమిళనాడు; కన్నడ → కర్ణాటక; మలయాళం → కేరళ; బెంగాలీ → పశ్చిమ బెంగాల్.","3) షెడ్యూల్డ్ కాని భాషలకు ఉదాహరణలు: భిలి, గోండి, తుళు (విద్యార్థులు జనగణన పట్టిక చూసి సరిచూసుకోవచ్చు)."]],["Let us revise – రామచంద్ర గుహ వ్యాసం (చిన్న నోట్) (పుట 48)",["నా అభిప్రాయం: రచయిత వాదనకు అనుకూలం – భాషా రాష్ట్రాలు భారత ఐక్యతను బలపరిచాయి.","1) ఉదాహరణ – ఆంధ్రప్రదేశ్: తెలుగు మాట్లాడే ప్రజల ప్రత్యేక రాష్ట్ర డిమాండ్ (పొట్టి శ్రీరాములు దీక్ష) తో 1953లో ఆంధ్ర రాష్ట్రం – మొదటి భాషా రాష్ట్రం; 1956లో ఆంధ్రప్రదేశ్.","2) సొంత భాషలో పరిపాలన, విద్య, న్యాయం అందడంతో ప్రజలు ప్రభుత్వానికి దగ్గరయ్యారు.","3) “తెలుగువారిగానూ, భారతీయులుగానూ” ఉండటంలో విరోధం లేదని నిరూపితమైంది.","4) తెలుగు వంటి భాషల కోరికలను విస్మరించి ఉంటే శ్రీలంక లాగా ఘర్షణలు, విభజన భయం ఉండేవి.","5) నదీ జలాలు, సరిహద్దుల మీద రాష్ట్రాల మధ్య అప్పుడప్పుడు వివాదాలు వచ్చినా అవి చర్చలు, న్యాయస్థానాలతో పరిష్కారమవుతున్నాయి. (వ్యతిరేకంగా రాయాలనుకుంటే – భాషా భావోద్వేగాలు కొన్నిసార్లు రాష్ట్రాల మధ్య వివాదాలు పెంచుతాయని ఉదాహరణలతో రాయవచ్చు.)"]],["ఆలోచించండి – “మూడంచెల రైలు బోగీ” (పుట 50)",["భారత్‌లో మూడంచెల ప్రభుత్వం – కేంద్రం, రాష్ట్రాలు, స్థానిక ప్రభుత్వాలు (పంచాయతీలు/మున్సిపాలిటీలు). రైలు బోగీలో మూడు బెర్తుల్లా ప్రతి స్థాయికి తన స్థానం, తన పని ఉంటాయి; స్థానిక స్థాయి (కింది బెర్త్) ప్రజలకు అత్యంత దగ్గరగా ఉంటుంది."]],["వార్తాపత్రిక క్లిప్పింగులు; కలెక్టర్ ప్రశ్న (పుట 52)",["క్లిప్పింగులు చెప్పేది: 1) “10 లక్షలకు పైగా మహిళలు పంచాయతీలకు ఎన్నిక” – రిజర్వేషన్‌తో మహిళల భాగస్వామ్యం పెరిగింది.","2) “మహిళా ప్రధాన్‌లు మార్పు తెస్తున్నారు” – స్థానిక పాలనలో సానుకూల మార్పు.","3) “రూ.250 కే గ్రామంలో న్యాయం” – గ్రామ స్థాయిలో చౌక, వేగవంతమైన న్యాయం.","4) “పంచాయతీలకు నేరుగా నిధులను రాష్ట్రాలు వ్యతిరేకిస్తున్నాయి”, “పంచాయతీ పదవులు వేలం” – రాష్ట్రాలు అధికారాలు, నిధులు పూర్తిగా ఇవ్వకపోవడం, డబ్బుతో పదవులు వంటి సమస్యలు.","ముగింపు: వికేంద్రీకరణ ముందడుగు వేసింది కానీ ఇంకా పూర్తి కాలేదు.","“జిల్లా పరిషత్ చైర్‌పర్సన్ కాకుండా కలెక్టర్ ఎందుకు?” – 1) కలెక్టర్ రాష్ట్ర ప్రభుత్వం నియమించే అధికారి; జిల్లాలో రాష్ట్ర పాలన, శాంతిభద్రతలు, రెవెన్యూ బాధ్యత ఆయనది.","2) జిల్లా పరిషత్ స్థానిక అభివృద్ధి పనులే చూస్తుంది; రాష్ట్రాలు స్థానిక సంస్థలకు అన్ని అధికారాలు, నిధులు ఇంకా ఇవ్వలేదు.","3) అందుకే రాజకీయ అధిపతి (చైర్‌పర్సన్) ఉన్నా పరిపాలనలో అధికారుల పాత్ర ఎక్కువ."]],["కృత్యం – మీ స్థానిక ప్రభుత్వం (పుట 54)",["గ్రామంలో అయితే: వార్డు సభ్యుడు/పంచ్, సర్పంచ్, మండల పరిషత్ (పంచాయతీ సమితి) అధ్యక్షుడు, జిల్లా పరిషత్ చైర్‌పర్సన్ పేర్లు; చివరి గ్రామ సభ తేదీ, హాజరైన వారి సంఖ్య. పట్టణంలో అయితే: కౌన్సిలర్, మున్సిపల్ చైర్‌పర్సన్/మేయర్ పేర్లు, మున్సిపాలిటీ బడ్జెట్, ఎక్కువ ఖర్చు చేసిన అంశాలు. (విద్యార్థుల సొంత సేకరణ)"]],["అభ్యాసాలు – ప్రశ్నలు 1–5 (పుట 56)",["1) పటం: మణిపూర్ – ఈశాన్యం, మయన్మార్ సరిహద్దు; సిక్కిం – ఉత్తరాన, నేపాల్–భూటాన్ మధ్య; ఛత్తీస్‌గఢ్ – మధ్య భారత్ (మధ్యప్రదేశ్‌కు తూర్పు); గోవా – పశ్చిమ తీరం (మహారాష్ట్ర, కర్ణాటక మధ్య).","2) ప్రపంచ పటంలో సమాఖ్య దేశాలు: అమెరికా, కెనడా, ఆస్ట్రేలియా (ఇంకా బ్రెజిల్, రష్యా, జర్మనీ, స్విట్జర్లాండ్).","3) భారత్–బెల్జియం:","పోలిక – రెండూ “కలిపి ఉంచే” సమాఖ్యలు; రెండింట్లోనూ కేంద్రం, రాష్ట్రాల మధ్య రాజ్యాంగబద్ధ అధికార విభజన.","తేడా – బెల్జియంలో భాషా వర్గాలకు “సమాజ ప్రభుత్వం”, కేంద్ర మంత్రివర్గంలో డచ్–ఫ్రెంచ్ సమానత్వం ఉన్నాయి; భారత్‌లో అలాంటివి లేవు, కానీ మూడో స్థాయిగా పంచాయతీలు–మున్సిపాలిటీలు ఉన్నాయి; భారత్‌లో కేంద్రం మరింత బలమైనది.","4) సమాఖ్య vs ఏకకేంద్రం:","సమాఖ్య – అధికారం కేంద్రం, రాష్ట్రాల మధ్య రాజ్యాంగబద్ధంగా విభజించబడుతుంది; రాష్ట్రాలు తమ పరిధిలో స్వతంత్రం; కేంద్రం ఆదేశించలేదు. ఉదా: భారత్‌లో పోలీసు రాష్ట్ర అంశం – ప్రధాని ముఖ్యమంత్రికి ఆదేశం ఇవ్వలేరు.","ఏకకేంద్రం – ఒకే స్థాయి ప్రభుత్వం లేదా కింది స్థాయిలు కేంద్రానికి లోబడి; కేంద్రం వాటికి ఆదేశాలు ఇవ్వగలదు. ఉదా: శ్రీలంక.","5) 1992 సవరణకు ముందు–తర్వాత:","(i) ముందు ఎన్నికలు క్రమం తప్పకుండా జరగలేదు, రాష్ట్రాలు ఇష్టమొచ్చినట్లు రద్దు చేసేవి → తర్వాత క్రమం తప్పక ఎన్నికలు తప్పనిసరి, రాష్ట్ర ఎన్నికల సంఘం.","(ii) ముందు స్థానిక సంస్థలకు సొంత అధికారాలు, నిధులు చాలా తక్కువ → తర్వాత రాష్ట్రాలు అధికారాలు, ఆదాయం పంచాలి.","(iii) ముందు మహిళలు, బలహీన వర్గాలకు రిజర్వేషన్ లేదు → తర్వాత SC/ST/OBCలకు రిజర్వేషన్, మహిళలకు కనీసం 1/3."]],["అభ్యాసాలు – ప్రశ్నలు 6–9 (పుట 56)",["6) ఖాళీలు: అమెరికా “కలిసివచ్చే” (coming together) రకం సమాఖ్య – రాష్ట్రాలు సమాఖ్య ప్రభుత్వంతో పోలిస్తే “బలమైనవి/స్వతంత్రమైనవి”; భారత్ “కలిపి ఉంచే” (holding together) రకం సమాఖ్య; భారత్‌లో “కేంద్ర (యూనియన్)” ప్రభుత్వానికి ఎక్కువ అధికారాలు.","7) (నమూనా) సంగీత అభిప్రాయానికి మద్దతు – వసతి కల్పన విధానం జాతీయ ఐక్యతను బలపరిచింది.","వాదన: భాషలను గౌరవించి, హిందీని బలవంతంగా రుద్దకపోవడం వల్ల అన్ని భాషల ప్రజలు దేశాన్ని తమదిగా భావించారు.","ఉదాహరణ: తమిళనాడులో హిందీ వ్యతిరేక ఉద్యమం తర్వాత ఇంగ్లీషు కొనసాగించడం ఉద్రిక్తత తగ్గించింది; భాషా రాష్ట్రాలు (ఆంధ్రప్రదేశ్) ఐక్యత పెంచాయి – శ్రీలంకలో సింహళ ఏకైక భాష విధానం అంతర్యుద్ధానికి దారితీసింది.","8) జవాబు: (d) ప్రభుత్వ అధికారం వివిధ స్థాయిల ప్రభుత్వాల మధ్య విభజించబడటం.","9) యూనియన్ జాబితా – A. రక్షణ, E. బ్యాంకింగ్, G. సమాచార వ్యవస్థ (Communications).","రాష్ట్ర జాబితా – B. పోలీసు, C. వ్యవసాయం, H. వాణిజ్యం (Trade).","ఉమ్మడి జాబితా – D. విద్య, F. అడవులు, I. వివాహాలు."]],["అభ్యాసాలు – ప్రశ్నలు 10–12 (పుట 58)",["10) సరిగా జతపరచనిది: (d) స్థానిక ప్రభుత్వాలు – అవశిష్ట అధికారాలు. (అవశిష్ట అధికారాలు కేంద్రానివి.)","11) జవాబు: (c) – 1-A (భారత యూనియన్ – ప్రధానమంత్రి), 2-C (రాష్ట్రం – గవర్నర్), 3-D (మున్సిపల్ కార్పొరేషన్ – మేయర్), 4-B (గ్రామ పంచాయతీ – సర్పంచ్).","12) జవాబు: (c) A, B మాత్రమే.","C తప్పు – శ్రీలంకలో ప్రావిన్సులు ఉన్నా అది ఆచరణలో ఏకకేంద్రమే.","D తప్పు – స్థానిక సంస్థలకు అధికారాలు ఇవ్వడం సమాఖ్యను మరింత బలపరుస్తుంది."]]]},{"id":"cv3","no":20,"t":"లింగం, మతం, కులం (Gender, Religion and Caste)","m":[9],"ty":"పౌరశాస్త్రం – అధ్యాయం 3","by":"సాంఘిక శాస్త్రం – ప్రజాస్వామ్య రాజకీయాలు-II, 10వ తరగతి (పుటలు 60–93)","th":"లింగ విభజన, పితృస్వామ్యం, మహిళల రాజకీయ ప్రాతినిధ్యం, మతం–మతతత్వం, లౌకిక రాజ్యం, కుల అసమానతలు, రాజకీయాల్లో కులం, కులంలో రాజకీయాలు","sum":"సామాజిక విభజనలు రాజకీయాల్లో వ్యక్తమైనప్పుడు ప్రజాస్వామ్యం వాటిని ఎలా ఎదుర్కొంటుందో ఈ పాఠం లింగం, మతం, కులం అనే మూడు ఉదాహరణలతో చూపుతుంది. లింగ విభజన సహజమైనది కాదు – సమాజం ఆడ, మగ పిల్లలకు వేర్వేరు పాత్రలు అంటగట్టడం (sexual division of labour) వల్ల వచ్చింది; ఇంటి పనులు మహిళలవే అనే భావన; వారి పని కనిపించదు, జీతం రాదు (టైమ్ యూజ్ సర్వే: మహిళ రోజుకు సగటున 7½ గంటలకు పైగా, పురుషుడు 6½ గంటలు పనిచేస్తారు). మహిళా ఉద్యమాలు ఓటు హక్కు, విద్య, ఉద్యోగ అవకాశాలు, సమాన హక్కుల కోసం పోరాడాయి (స్త్రీవాదం – feminism). స్కాండినేవియన్ దేశాల్లో (స్వీడన్, నార్వే, ఫిన్లాండ్) ప్రజాజీవితంలో మహిళల భాగస్వామ్యం ఎక్కువ. భారత్ ఇంకా పితృస్వామ్య (patriarchal) సమాజం – మహిళల అక్షరాస్యత 54% vs పురుషులు 76%; ఉన్నత పదవుల్లో తక్కువ; సమాన వేతన చట్టం 1976 ఉన్నా తక్కువ జీతం; బాలల లింగ నిష్పత్తి 919 (2011); హింస, వేధింపులు. లోక్‌సభలో మహిళలు 2019లో మొదటిసారి 14.36%; శాసనసభల్లో 5% లోపు. పంచాయతీలు, మున్సిపాలిటీల్లో 1/3 రిజర్వేషన్ – 10 లక్షలకు పైగా మహిళా ప్రతినిధులు; 2023లో నారీ శక్తి వందన్ అధినియమ్ (మహిళా రిజర్వేషన్ చట్టం) – లోక్‌సభ, శాసనసభల్లో 1/3. మతం: గాంధీజీ – మతాన్ని రాజకీయాల నుండి వేరుచేయలేమని, అయితే అది నైతిక విలువల మతం అని చెప్పారు. మతపరమైన భిన్నత్వాలు రాజకీయాల్లో వ్యక్తమవడం తప్పు కాదు; కానీ ఒక మతాన్ని ఇతరుల కంటే గొప్పదిగా, మతాన్నే జాతీయతకు ఆధారంగా చూపి రాజ్యాధికారం ఒక మతానికి ఉపయోగించడం మతతత్వం (communalism). దాని రూపాలు – రోజువారీ మత దురభిమానాలు, మెజారిటీ ఆధిపత్యం/మైనారిటీ ప్రత్యేక రాజకీయ యూనిట్ కోరిక, మత ప్రాతిపదికన రాజకీయ సమీకరణ, మత హింస, అల్లర్లు, ఊచకోతలు. భారత్ లౌకిక రాజ్యం – అధికార మతం లేదు; మత స్వేచ్ఛ; మత ప్రాతిపదికన వివక్ష నిషేధం; మతాల్లో సమానత్వం కోసం రాజ్యం జోక్యం (అంటరానితనం నిషేధం). కులం: వంశపారంపర్య వృత్తి విభజనను ఆచారాలతో సమర్థించిన విపరీత రూపం – అంటరానితనం, బహిష్కరణ. ఫూలే, గాంధీజీ, అంబేద్కర్, పెరియార్ కృషి; పట్టణీకరణ, అక్షరాస్యత, వృత్తి చలనశీలత వల్ల కుల క్రమం బలహీనపడుతోంది; కానీ కులంలోనే వివాహాలు, అంటరానితనం, విద్య–ఆస్తి–పేదరికంలో అసమానతలు కొనసాగుతున్నాయి. 2011లో SC 16.6%, ST 8.6%; OBC సుమారు 41% (NSS 2004–05). రాజకీయాల్లో కులం – అభ్యర్థుల ఎంపిక, కుల భావాల ద్వారా మద్దతు, సార్వత్రిక వయోజన ఓటు హక్కుతో కొత్త చైతన్యం; కానీ ఏ నియోజకవర్గంలోనూ ఒక్క కులమే మెజారిటీ కాదు, ఏ పార్టీకీ ఒక కులం ఓట్లు అన్నీ రావు, ఓటర్లు ప్రభుత్వ పనితీరు, నాయకుల ప్రజాదరణ చూసి ఓటేస్తారు – కాబట్టి కులం ఒక్కటే ఫలితాలను నిర్ణయించదు. కులంలో రాజకీయాలు – కులాలు పెద్దవి కావడం, ఇతర కులాలతో కూటములు, “వెనుకబడిన/ముందు” వర్గాలు. కుల రాజకీయాలు దళితులు, OBCలకు అధికారంలో వాటా ఇచ్చాయి; కానీ కులం మీదే ఆధారపడితే పేదరికం, అభివృద్ధి, అవినీతి వంటి సమస్యలు పక్కకు పోతాయి, ఉద్రిక్తతలు, హింస రావచ్చు.","pts":["లింగ విభజన: జీవసంబంధమైనది కాదు – ఆడ, మగ పిల్లలకు సమాజం ఆశించే వేర్వేరు పాత్రలు, సామాజిక అంచనాల వల్ల వచ్చిన శ్రేణీకృత (hierarchical) విభజన.","లైంగిక శ్రమ విభజన: ఇంటి పనులు (వంట, శుభ్రత, పిల్లల పెంపకం) మహిళలవి, బయటి పనులు పురుషులవి అనే భావన; మహిళల ఇంటి పని కనిపించదు, జీతం లేదు, విలువ ఇవ్వరు.","టైమ్ యూజ్ సర్వే (1998–99): మహిళ రోజుకు 7½ గంటలకు పైగా, పురుషుడు 6½ గంటలు పని; పురుషుల పని ఆదాయం తెస్తుంది కాబట్టి కనిపిస్తుంది.","స్త్రీవాది (Feminist): స్త్రీ, పురుషులకు సమాన హక్కులు, అవకాశాలు ఉండాలని నమ్మే వ్యక్తి (స్త్రీ లేదా పురుషుడు); మహిళా ఉద్యమాలు ఓటు, విద్య, ఉద్యోగం, కుటుంబ సమానత్వం కోసం పోరాడాయి.","పితృస్వామ్యం (Patriarchy): “తండ్రి పాలన” – పురుషులకు ఎక్కువ విలువ, మహిళలపై అధికారం ఇచ్చే వ్యవస్థ.","భారత్‌లో మహిళల వెనుకబాటు: అక్షరాస్యత మహిళలు 54%, పురుషులు 76%; ఉన్నత విద్య, ఉన్నత పదవుల్లో తక్కువ; సమాన వేతన చట్టం 1976 ఉన్నా తక్కువ జీతాలు; బాలల లింగ నిష్పత్తి 919 (కొన్ని రాష్ట్రాల్లో 850, 800 కంటే తక్కువ); గృహ హింస, వేధింపులు.","మహిళల రాజకీయ ప్రాతినిధ్యం: లోక్‌సభలో 2019లో మొదటిసారి 14.36%; రాష్ట్ర శాసనసభల్లో 5% లోపు; ఈ విషయంలో భారత్ ప్రపంచంలో దిగువ దేశాల్లో ఒకటి.","పరిష్కారం: స్థానిక సంస్థల్లో 1/3 స్థానాలు మహిళలకు – 10 లక్షలకు పైగా మహిళా ప్రతినిధులు; 2023 నారీ శక్తి వందన్ అధినియమ్ – లోక్‌సభ, శాసనసభల్లో 1/3 స్థానాలు మహిళలకు.","మతం–రాజకీయాలు: గాంధీజీ – మతాన్ని రాజకీయాల నుండి వేరుచేయలేం (నైతిక విలువల మతం); మతపరమైన అభిప్రాయాలు రాజకీయాల్లో రావడం తప్పు కాదు; మత ప్రాతిపదికన వివక్ష, హింసను ఎదిరించాలి; కుటుంబ చట్టాలు మహిళలపై వివక్ష చూపకూడదు.","మతతత్వం (Communalism): ఒక మతం గొప్పది, ఒక మతానుచరులంతా ఒకే సమాజం, వారి ప్రయోజనాలు ఒకటే, ఇతర మతాల వారితో విరుద్ధం అనే నమ్మకం; రాజ్యాధికారంతో ఒక మత ఆధిపత్యం కోరడం.","మతతత్వ రూపాలు: (1) రోజువారీ నమ్మకాల్లో మత దురభిమానాలు, మూస భావనలు, (2) మెజారిటీ ఆధిపత్యం/మైనారిటీ ప్రత్యేక దేశం కోరిక, (3) మత చిహ్నాలు, నాయకులు, భయాలతో రాజకీయ సమీకరణ, (4) మత హింస, అల్లర్లు, ఊచకోతలు (విభజన సమయంలో).","లౌకిక రాజ్యం (భారత్): అధికార మతం లేదు (శ్రీలంకలో బౌద్ధం, పాకిస్తాన్‌లో ఇస్లాం, ఇంగ్లాండ్‌లో క్రైస్తవం లాగా కాదు); మత స్వేచ్ఛ – ఆచరించడం, ప్రచారం చేయడం లేదా ఏ మతమూ పాటించకపోవడం; మత ప్రాతిపదికన వివక్ష నిషేధం; మతాల్లో సమానత్వం కోసం రాజ్యం జోక్యం (అంటరానితనం నిషేధం).","కుల వ్యవస్థ: వంశపారంపర్య వృత్తి విభజనను ఆచారాలు సమర్థించడం; ఒకే కులంలో వివాహం, ఇతర కులాలతో భోజనం చేయకపోవడం; “అంటరాని” వర్గాల బహిష్కరణ.","సంస్కర్తలు: జ్యోతిబా ఫూలే, గాంధీజీ, డా. బి.ఆర్. అంబేద్కర్, పెరియార్ రామస్వామి నాయకర్ – కుల అసమానతలు లేని సమాజం కోసం కృషి.","మార్పులు: ఆర్థికాభివృద్ధి, పట్టణీకరణ, అక్షరాస్యత, విద్య, వృత్తి చలనశీలత, గ్రామాల్లో భూస్వాముల ప్రాబల్యం తగ్గడం → కుల క్రమం బలహీనపడుతోంది; రాజ్యాంగం కుల వివక్షను నిషేధించింది.","కొనసాగుతున్న అసమానతలు: ఎక్కువ మంది కులంలోనే వివాహం; అంటరానితనం పూర్తిగా పోలేదు; “ఉన్నత” కులాల వారే విద్య, ఆస్తిలో ముందు; పేదల్లో SC, ST, OBC ఎక్కువ.","జనాభా: 2011లో SC (దళితులు) 16.6%, ST (ఆదివాసీలు) 8.6%; OBC సుమారు 41% (NSS 2004–05) – మొత్తం సుమారు 2/3.","రాజకీయాల్లో కులం: పార్టీలు కుల సమీకరణాలు చూసి అభ్యర్థులను ఎంచుకోవడం; కుల భావాలతో మద్దతు కూడగట్టడం; సార్వత్రిక వయోజన ఓటు హక్కు, “ఒక వ్యక్తి–ఒక ఓటు”తో అణగారిన కులాల్లో చైతన్యం.","కులం ఒక్కటే ఎన్నికలను నిర్ణయించదు: ఏ నియోజకవర్గంలోనూ ఒక కులమే స్పష్టమైన మెజారిటీ కాదు; ఏ పార్టీకీ ఒక కులం ఓట్లన్నీ రావు (“ఓటు బ్యాంకు” = ఎక్కువ భాగం మాత్రమే); ఒకే కులం అభ్యర్థులు చాలామంది పోటీ చేస్తారు; అధికార పార్టీలు, సిట్టింగ్ సభ్యులు ఓడిపోతుంటారు; ప్రభుత్వ పనితీరు, నాయకుల ప్రజాదరణ ముఖ్యం.","కులంలో రాజకీయాలు: కులాలు పొరుగు ఉపకులాలను కలుపుకొని పెద్దవి కావడం; ఇతర కులాలతో కూటములు, చర్చలు; “వెనుకబడిన”, “ముందు” వంటి కొత్త కుల వర్గాలు.","కుల రాజకీయాలు – అనుకూలం: దళితులు, OBCలకు నిర్ణయాధికారంలో వాటా, గౌరవం, భూమి–వనరుల కోసం పోరాటం. ప్రతికూలం: పేదరికం, అభివృద్ధి, అవినీతి వంటి సమస్యలు పక్కకు; ఉద్రిక్తతలు, ఘర్షణలు, హింస."],"w":[["లింగ విభజన","Gender division"],["లైంగిక శ్రమ విభజన","Sexual division of labour"],["స్త్రీవాది","Feminist"],["పితృస్వామ్యం","Patriarchy"],["బాలల లింగ నిష్పత్తి","Child sex ratio"],["మతతత్వం","Communalism"],["లౌకికవాదం","Secularism"],["కుటుంబ చట్టాలు","Family laws"],["కుల క్రమం","Caste hierarchy"],["పట్టణీకరణ","Urbanisation"],["వృత్తి చలనశీలత","Occupational mobility"],["అంటరానితనం","Untouchability"],["ఓటు బ్యాంకు","Vote bank"],["సార్వత్రిక వయోజన ఓటు హక్కు","Universal adult franchise"],["షెడ్యూల్డ్ కులాలు (దళితులు)","Scheduled Castes"],["షెడ్యూల్డ్ తెగలు (ఆదివాసీలు)","Scheduled Tribes"],["కులతత్వం","Casteism"],["మత దురభిమానం","Religious prejudice"]],"gr":{"t":"మూడు సామాజిక విభజనలు – రాజకీయాల్లో","p":["విభజన | రాజకీయ వ్యక్తీకరణ | ఫలితం","లింగం | మహిళా ఉద్యమాలు, రిజర్వేషన్ డిమాండ్ | ఎక్కువగా అనుకూలం – మహిళలకు హక్కులు, ప్రాతినిధ్యం","మతం | మతతత్వ రాజకీయాలు | ఎక్కువగా ప్రతికూలం – హింస, విభజన; లౌకికవాదమే పరిష్కారం","కులం | కుల సమీకరణ, కూటములు | అనుకూలం (దళితులు, OBCలకు అధికారం) + ప్రతికూలం (అసలు సమస్యలు పక్కకు, హింస)"]},"qa":[["లింగ విభజన సహజమైనదా?","కాదు – సమాజం స్త్రీ, పురుషులకు అంటగట్టిన పాత్రలు, అంచనాల వల్ల వచ్చింది; జీవసంబంధమైనది కాదు."],["పితృస్వామ్యం అంటే?","పురుషులకు ఎక్కువ విలువ, మహిళలపై అధికారం ఇచ్చే వ్యవస్థ (తండ్రి పాలన)."],["2011 జనగణన ప్రకారం భారత బాలల లింగ నిష్పత్తి?","ప్రతి 1000 మంది బాలురకు 919 బాలికలు."],["సమాన వేతన చట్టం ఏ సంవత్సరం?","1976 – సమాన పనికి సమాన వేతనం."],["2019 లోక్‌సభలో మహిళల శాతం?","14.36% (మొదటిసారి)."],["మతతత్వం అంటే?","ఒక మతాన్ని ఇతరుల కంటే గొప్పదిగా భావించి, మతాన్నే సమాజానికి ప్రధాన ఆధారంగా చూస్తూ రాజ్యాధికారంతో ఒక మత ఆధిపత్యం కోరే రాజకీయాలు."],["భారత్‌ను లౌకిక రాజ్యంగా చేసే రెండు రాజ్యాంగ అంశాలు?","(1) అధికార మతం లేదు. (2) అందరికీ ఏ మతాన్నైనా ఆచరించే, ప్రచారం చేసే లేదా పాటించకపోయే స్వేచ్ఛ; మత ప్రాతిపదికన వివక్ష నిషేధం."],["2011లో SC, ST జనాభా శాతం?","SC 16.6%, ST 8.6%."],["“ఓటు బ్యాంకు” అంటే?","ఒక కులం/వర్గంలోని ఎక్కువ మంది ఓటర్లు ఒక పార్టీకే ఓటు వేయడం."],["భారత్‌కు మాత్రమే ప్రత్యేకమైన సామాజిక విభజన?","కులం."]],"act":"మీ ఇంట్లో ఒక వారం “టైమ్ యూజ్ సర్వే” చేయండి: ప్రతి పెద్ద సభ్యుడు ఆదాయ పని, ఇంటి పని, చదువు–వినోదం, విశ్రాంతి, నిద్రకు ఎంత సమయం గడుపుతారో రాసి రోజువారీ సగటు లెక్కించండి. మహిళలు ఎక్కువ పని చేస్తున్నారా? తరగతిలో పోల్చండి.","kn":"నారీ శక్తి వందన్ అధినియమ్ (2023) లోక్‌సభ, రాష్ట్ర శాసనసభల్లో మూడింట ఒక వంతు స్థానాలను మహిళలకు కేటాయించింది – దశాబ్దాలుగా పెండింగ్‌లో ఉన్న మహిళా రిజర్వేషన్ బిల్లు చివరకు చట్టమైంది.","qz":[["లింగ విభజన అంటే సాధారణంగా?","సమాజం స్త్రీ, పురుషులకు అంటగట్టిన అసమాన పాత్రలు","స్త్రీ, పురుషుల జీవసంబంధ తేడా","అసమాన బాలల లింగ నిష్పత్తి","మహిళలకు ఓటు హక్కు లేకపోవడం"],["స్త్రీ, పురుషులకు సమాన హక్కులు, అవకాశాలు కోరే వ్యక్తి?","స్త్రీవాది","మతతత్వవాది","కులతత్వవాది","లౌకికవాది"],["పురుషులకు ఎక్కువ విలువ, అధికారం ఇచ్చే వ్యవస్థ?","పితృస్వామ్యం","మాతృస్వామ్యం","లౌకికవాదం","సమాఖ్యవాదం"],["భారత్‌లో మహిళల అక్షరాస్యత (పుస్తకం ప్రకారం)?","54%","76%","90%","33%"],["2011 బాలల లింగ నిష్పత్తి (1000 బాలురకు)?","919","940","850","1000"],["సమాన వేతన చట్టం సంవత్సరం?","1976","1992","1956","2023"],["భారత్‌లో స్థానిక సంస్థల్లో మహిళలకు రిజర్వేషన్?","మూడింట ఒక వంతు","సగం","నాలుగో వంతు","ఐదో వంతు"],["మహిళలకు ప్రజాజీవితంలో భాగస్వామ్యం ఎక్కువ ఉన్న దేశాలు?","స్కాండినేవియన్ దేశాలు","అరబ్ దేశాలు","పసిఫిక్ దేశాలు","దక్షిణాసియా దేశాలు"],["ఒక మతం ఇతరుల కంటే గొప్పది అనే రాజకీయ నమ్మకం?","మతతత్వం","లౌకికవాదం","స్త్రీవాదం","సమాఖ్యవాదం"],["భారత రాజ్యాంగం గురించి తప్పైన వాక్యం?","ఒక మతానికి అధికార హోదా ఇస్తుంది","మత వివక్ష నిషేధిస్తుంది","మత స్వేచ్ఛ ఇస్తుంది","మతాల్లో సమానత్వం కాపాడుతుంది"],["భారత్‌కు ప్రత్యేకమైన సామాజిక విభజన?","కులం","లింగం","మతం","భాష"],["2011లో షెడ్యూల్డ్ కులాల జనాభా శాతం?","16.6%","8.6%","41%","25%"],["కుల అసమానతలు లేని సమాజం కోసం కృషి చేసినవారు?","జ్యోతిబా ఫూలే","మాజినీ","బిస్మార్క్","మెటర్నిక్"],["ఒక కులంలోని ఎక్కువ మంది ఒక పార్టీకే ఓటు వేయడం?","ఓటు బ్యాంకు","సంకీర్ణం","ఫిరాయింపు","రిజర్వేషన్"],["వివాహం, విడాకులు, దత్తత, వారసత్వానికి సంబంధించిన చట్టాలు?","కుటుంబ చట్టాలు","నేర చట్టాలు","కార్మిక చట్టాలు","పన్ను చట్టాలు"]],"wb":{"mis":"కుల రాజకీయాలు, మతతత్వం ఒకటే అనుకోవడం తప్పు – కుల రాజకీయాలకు అనుకూల కోణం (అణగారిన వర్గాలకు అధికారం) ఉంది. కులం ఒక్కటే ఎన్నికల ఫలితాన్ని నిర్ణయించదు. లౌకికవాదం అంటే మత వ్యతిరేకత కాదు – అన్ని మతాలకు సమాన దూరం, సమాన గౌరవం.","pg":"60–93","f":"books/10/Class10_Social_Civics_Textbook.pdf","p":62,"lb":"పాఠ్యపుస్తకం","ws":["ఆలోచించండి – ఇంటి పని రాజకీయమా? (పుట 62)","చర్చించండి – “ఆదర్శ మహిళ” భావనలు (పుట 64)","కృత్యం – టైమ్ యూజ్ సర్వే (పుట 66)","పటం, పోస్టర్ – బాలల లింగ నిష్పత్తి (పుట 68)","ఆలోచించండి – మహిళల ప్రాతినిధ్యం ఎందుకు తక్కువ? (పుట 70)","ఆలోచించండి – స్త్రీవాదం vs కులతత్వం, మతతత్వం (పుట 72)","ఆలోచించండి – “నేను మతవాదిని కాను…” (పుట 74)","ఆలోచించండి – మతంపై జోకులు (పుట 76)","మత, సామాజిక వైవిధ్యం – పై చార్ట్ పరిశీలన (పుట 80)","ఆలోచించండి – కులం గురించి చర్చిస్తే కులతత్వం పెరుగుతుందా? (పుట 82)","ఆలోచించండి – కులాలను “ఓటు బ్యాంకులు”గా చూడటం సరైనదా? (పుట 86)","అభ్యాసాలు – ప్రశ్నలు 1–3 (పుట 90)","అభ్యాసాలు – ప్రశ్నలు 4–6 (పుట 90)","అభ్యాసాలు – ప్రశ్నలు 7–11 (పుట 90)","అభ్యాసాలు – ప్రశ్న 12 (పుట 92)"]},"tg":[["ఆలోచించండి – ఇంటి పని రాజకీయమా? (పుట 62)",["1) అవును – ఇంటి పని ఎవరు చేయాలి, ఎవరికి అధికారం అనేది అధికార సంబంధం (power relation); రాజకీయ శాస్త్రం అధికారం, అసమానతలను చదువుతుంది.","2) ఇంటి పని మహిళలదే అనే లింగ విభజన వల్ల వారి పని కనిపించదు, వారు ప్రజాజీవితంలోకి రాలేకపోతున్నారు.","3) ఈ అసమానతలు రాజకీయంగా చర్చకు వచ్చినప్పుడే చట్టాలు, రిజర్వేషన్లు వంటి మార్పులు వస్తాయి."]],["చర్చించండి – “ఆదర్శ మహిళ” భావనలు (పుట 64)",["1) సమాజంలోని భావనలు: ఇంటి పని, వంట, పిల్లల పెంపకం మాత్రమే చేసేది; ఎదురు మాట్లాడనిది; త్యాగమే జీవితం – ఇవి మహిళలను ఇంటికే పరిమితం చేసే మూస భావనలు; పూర్తిగా ఏకీభవించను.","2) నా దృష్టిలో ఆదర్శ మహిళ: చదువుకున్న, స్వతంత్రంగా ఆలోచించి నిర్ణయాలు తీసుకునే, సొంత వృత్తి/ఆదాయం ఉండే, సమాజంలో, రాజకీయాల్లో చురుగ్గా పాల్గొనే వ్యక్తి.","3) ఇంటి బాధ్యతలు స్త్రీ, పురుషులు ఇద్దరూ పంచుకోవాలి. (విద్యార్థులు తమ సొంత అభిప్రాయం రాయవచ్చు.)"]],["కృత్యం – టైమ్ యూజ్ సర్వే (పుట 66)",["1) ఇంట్లో పెద్దలందరి రోజువారీ పనులను 5 వర్గాలుగా ఒక వారం గమనించి రాయండి: ఆదాయ పని, ఇంటి పని, చదువు–వినోదం, మాటలు, విశ్రాంతి–నిద్ర–స్వీయ సంరక్షణ.","2) ప్రతి వర్గానికి వారం మొత్తం సమయం ÷ 7 = రోజువారీ సగటు.","3) సాధారణంగా వచ్చే ఫలితం: మహిళలు ఆదాయ పని + ఇంటి పని కలిపి పురుషుల కంటే ఎక్కువ గంటలు పనిచేస్తారు; వారి విశ్రాంతి సమయం తక్కువ – పుస్తకంలోని సర్వే (మహిళ 7½ గం.+, పురుషుడు 6½ గం.) లాగానే.","“అమ్మ ‘నేను పనిచేయను, గృహిణిని’ అంటుంది…” – ఇంటి పని కూడా పనే; జీతం రాకపోవడం వల్ల దాన్ని పనిగా గుర్తించడం లేదు – ఇదే లింగ వివక్ష."]],["పటం, పోస్టర్ – బాలల లింగ నిష్పత్తి (పుట 68)",["1) ఆంధ్రప్రదేశ్ బాలల లింగ నిష్పత్తి (2011) సుమారు 939 – జాతీయ సగటు 919 కంటే ఎక్కువ (పటంలో రంగుతో సరిచూడండి).","2) పంజాబ్, హర్యానా వంటి రాష్ట్రాల్లో 850 కంటే తక్కువ – అక్కడ కొడుకుల పట్ల మక్కువ, లింగ నిర్ధారణ గర్భస్రావాలు ఎక్కువ; ఛత్తీస్‌గఢ్, కేరళ, ఈశాన్య రాష్ట్రాల్లో ఎక్కువ.","3) పటం, పోస్టర్ రెండూ ఒకే సమస్యను చూపుతాయి – పటం గణాంకాలతో (ఎక్కడ ఎంత), పోస్టర్ భావోద్వేగ సందేశంతో (ఆడపిల్లను కాపాడండి) – బాలికల సంఖ్య తగ్గడం సమాజానికి ప్రమాదం."]],["ఆలోచించండి – మహిళల ప్రాతినిధ్యం ఎందుకు తక్కువ? (పుట 70)",["1) పితృస్వామ్య సమాజం – రాజకీయాలు పురుషుల రంగం అనే భావన.","2) పార్టీలు మహిళలకు తక్కువ టికెట్లు ఇవ్వడం; ఎన్నికల ఖర్చు, హింస, భద్రత లోపం.","3) ఇంటి బాధ్యతల భారం, తక్కువ విద్య, ఆర్థిక స్వాతంత్ర్యం లేకపోవడం.","4) అమెరికాలు (29.5%), ఐరోపా (26.4%) కూడా సంతృప్తికర స్థాయికి రాలేదు – జనాభాలో సగం ఉన్న మహిళలకు సమాన (సుమారు 50%) ప్రాతినిధ్యం ఉండాలి; నార్డిక్ దేశాలు (42.3%) మాత్రమే దగ్గరగా ఉన్నాయి."]],["ఆలోచించండి – స్త్రీవాదం vs కులతత్వం, మతతత్వం (పుట 72)",["“రాజకీయంగా ప్రస్తావించకుండా మహిళలు ఈ విజయాలు సాధించేవారా?” – లేదు; ఉద్యమాలు, రాజకీయ డిమాండ్ల వల్లే ఓటు హక్కు, సమాన వేతన చట్టం, స్థానిక సంస్థల్లో 1/3 రిజర్వేషన్ వచ్చాయి.","“కులతత్వం, మతతత్వం చెడ్డవైతే స్త్రీవాదం ఎలా మంచిది?” – 1) స్త్రీవాదం సమానత్వాన్ని, అణచివేత నుండి విముక్తిని కోరుతుంది – ఎవరిపైనా ఆధిపత్యం కాదు.","2) మతతత్వం, కులతత్వం ఒక వర్గం గొప్పదని, ఇతరులపై ఆధిపత్యం కోరతాయి, ద్వేషం పెంచుతాయి.","3) కాబట్టి విభజనను ప్రస్తావించడం కాదు – ఆ ప్రస్తావన సమానత్వం కోసమా, ఆధిపత్యం కోసమా అనేదే ముఖ్యం."]],["ఆలోచించండి – “నేను మతవాదిని కాను…” (పుట 74)",["1) మతతత్వం మతాన్ని పాటించేవారికే కాదు – అందరికీ ప్రమాదం; మత హింస, అల్లర్లు అందరి ప్రాణాలు, ఆస్తులు, దేశ శాంతిని దెబ్బతీస్తాయి.","2) లౌకికవాదం భారత దేశపు పునాది; మత ప్రమేయం లేని వ్యక్తికీ మత స్వేచ్ఛ (ఏ మతమూ పాటించని హక్కు) దానివల్లే.","3) అందువల్ల పౌరులందరూ మతతత్వాన్ని ఎదిరించి, లౌకికవాదాన్ని కాపాడాలి."]],["ఆలోచించండి – మతంపై జోకులు (పుట 76)",["1) అవును, అది మతతత్వపు రోజువారీ రూపం – ఒక మతం వారిపై మూస భావనలు (stereotypes), దురభిమానాలు చూపడం, వారిని తక్కువగా చూడటం.","2) సరదా అనిపించినా ఇలాంటి జోకులు అపనమ్మకం, ద్వేషం పెంచి పెద్ద ఘర్షణలకు దారితీయవచ్చు.","3) అన్ని మతాల వారిని సమానంగా గౌరవించడమే సరైన ప్రవర్తన."]],["మత, సామాజిక వైవిధ్యం – పై చార్ట్ పరిశీలన (పుట 80)",["1) 1961 నుండి హిందువులు, జైనులు, క్రైస్తవుల శాతం కొంచెం తగ్గింది; ముస్లింలు, సిక్కులు, బౌద్ధుల శాతం కొంచెం పెరిగింది.","2) ముస్లింల శాతం ఇతరులను మించిపోతుందనేది తప్పు అభిప్రాయం – సచార్ కమిటీ అంచనా: రాబోయే 50 ఏళ్లలో 3–4% మాత్రమే పెరగవచ్చు.","3) 2011లో SC 16.6%, ST 8.6%; OBC సుమారు 41% – మొత్తం జనాభాలో సుమారు మూడింట రెండు వంతులు."]],["ఆలోచించండి – కులం గురించి చర్చిస్తే కులతత్వం పెరుగుతుందా? (పుట 82)",["1) లేదు – ఎక్కడ ఆధిపత్యం, అసమానత ఉంటాయో వాటిని చర్చించడం రాజకీయ శాస్త్రం పని.","2) మౌనంగా ఉంటే కుల వివక్ష పోదు; దాన్ని గుర్తించి, అర్థం చేసుకుని, చట్టాలు, విద్య, చైతన్యంతో ఎదుర్కోవాలి.","3) చర్చ ఉద్దేశం కుల గర్వం పెంచడం కాదు – సమానత్వం సాధించడం."]],["ఆలోచించండి – కులాలను “ఓటు బ్యాంకులు”గా చూడటం సరైనదా? (పుట 86)",["1) సరైనది కాదు – ఓటర్లు కేవలం కులం సభ్యులు కాదు; వారు తమ సమస్యలు, ప్రభుత్వ పనితీరు, నాయకుల ప్రజాదరణ చూసి ఓటేస్తారు.","2) ఒక కులం ఓట్లన్నీ ఒకే పార్టీకి రావు; ఓటు బ్యాంకు రాజకీయాలు అభివృద్ధి, పేదరికం, అవినీతి వంటి అసలు సమస్యలను పక్కకు నెడతాయి.","3) కుల ఉద్రిక్తతలు పెరిగి సమాజం విడిపోతుంది – ప్రజాస్వామ్యానికి హానికరం."]],["అభ్యాసాలు – ప్రశ్నలు 1–3 (పుట 90)",["1) మహిళలపై వివక్ష ఉన్న రంగాలు:","(i) విద్య – అక్షరాస్యత మహిళలు 54%, పురుషులు 76%; ఉన్నత విద్యలో బాలికలు తక్కువ (తల్లిదండ్రులు కొడుకుల చదువుకే ఖర్చు).","(ii) ఉద్యోగం – ఉన్నత జీతాల పదవుల్లో తక్కువ; ఇంటి పనికి జీతం, గుర్తింపు లేదు.","(iii) వేతనాలు – సమాన వేతన చట్టం (1976) ఉన్నా ఒకే పనికి తక్కువ జీతం.","(iv) లింగ నిష్పత్తి – కొడుకుల పట్ల మక్కువ, లింగ నిర్ధారణ గర్భస్రావాలు → బాలల లింగ నిష్పత్తి 919.","(v) భద్రత – గృహ హింస, వేధింపులు, దోపిడీ.","(vi) రాజకీయాలు – లోక్‌సభలో 14.36%, శాసనసభల్లో 5% లోపు.","2) మతతత్వ రాజకీయాల రూపాలు:","(i) రోజువారీ నమ్మకాల్లో మత దురభిమానాలు, మూస భావనలు, ఒక మతం గొప్పదనే భావం – ఉదా: ఇతర మతాల వారిపై హేళన చేసే జోకులు.","(ii) మెజారిటీ వర్గం ఆధిపత్యం కోరడం / మైనారిటీ ప్రత్యేక రాజకీయ విభాగం కోరడం – ఉదా: శ్రీలంకలో బౌద్ధ సింహళ ఆధిపత్యం.","(iii) మత చిహ్నాలు, మత నాయకులు, భావోద్వేగ విజ్ఞప్తులు, భయాలతో రాజకీయ సమీకరణ – ఉదా: ఎన్నికల్లో ఒక మతం ఓట్ల కోసం మరో మతంపై భయం సృష్టించడం.","(iv) మత హింస, అల్లర్లు, ఊచకోతలు – ఉదా: దేశ విభజన (1947) సమయంలో మత అల్లర్లు.","3) కుల అసమానతలు ఇంకా కొనసాగుతున్న విధానం:","(i) ఇప్పటికీ ఎక్కువ మంది తమ కులంలోనే వివాహం చేసుకుంటున్నారు.","(ii) రాజ్యాంగం నిషేధించినా అంటరానితనం పూర్తిగా పోలేదు.","(iii) చారిత్రకంగా విద్య అందిన “ఉన్నత” కులాలవారే ఆధునిక విద్య, మంచి ఉద్యోగాల్లో ముందున్నారు.","(iv) భూమి, ఆస్తి ఎక్కువగా ఉన్నత కులాల చేతిలో; పేదల్లో SC, ST, OBCలు ఎక్కువ – కులానికి, ఆర్థిక స్థితికి ఇంకా దగ్గరి సంబంధం."]],["అభ్యాసాలు – ప్రశ్నలు 4–6 (పుట 90)",["4) కులం ఒక్కటే ఎన్నికల ఫలితాన్ని నిర్ణయించదు – కారణాలు:","(i) దేశంలో ఏ పార్లమెంటు నియోజకవర్గంలోనూ ఒకే కులం స్పష్టమైన మెజారిటీ కాదు – ప్రతి అభ్యర్థి, పార్టీ అనేక కులాల నమ్మకం గెలవాలి.","(ii) ఏ పార్టీకీ ఒక కులం ఓట్లన్నీ రావు; ఒకే కులం నుండి చాలా మంది అభ్యర్థులు పోటీ చేస్తారు – అప్పుడు ఆ కుల ఓటర్లకు ఎంపిక ఉంటుంది.","(iii) అధికార పార్టీ, సిట్టింగ్ సభ్యులు తరచూ ఓడిపోతారు – కుల సమీకరణాలు మాత్రమే పనిచేస్తే ఇలా జరగదు; ప్రభుత్వ పనితీరు, నాయకుల ప్రజాదరణ నిర్ణయాత్మకం.","5) మహిళల ప్రాతినిధ్యం:","(i) లోక్‌సభలో మహిళా సభ్యులు 2019లో మొదటిసారి 14.36%కు చేరారు.","(ii) రాష్ట్ర శాసనసభల్లో 5% కంటే తక్కువ.","(iii) ఈ విషయంలో భారత్ ఆఫ్రికా, లాటిన్ అమెరికాలోని అనేక అభివృద్ధి చెందుతున్న దేశాల కంటే కూడా వెనుకబడి ఉంది.","(iv) స్థానిక సంస్థల్లో 1/3 రిజర్వేషన్‌తో 10 లక్షలకు పైగా మహిళా ప్రతినిధులు ఉన్నారు.","(v) 2023 నారీ శక్తి వందన్ అధినియమ్ లోక్‌సభ, శాసనసభల్లో 1/3 స్థానాలు మహిళలకు కేటాయించింది.","6) భారత్‌ను లౌకిక రాజ్యంగా చేసే రాజ్యాంగ అంశాలు:","(i) భారత రాజ్యానికి అధికార మతం లేదు – శ్రీలంకలో బౌద్ధం, పాకిస్తాన్‌లో ఇస్లాం, ఇంగ్లాండ్‌లో క్రైస్తవం లాగా ఏ మతానికీ ప్రత్యేక హోదా లేదు.","(ii) ప్రతి వ్యక్తికీ ఏ మతాన్నైనా నమ్మే, ఆచరించే, ప్రచారం చేసే లేదా ఏ మతాన్నీ పాటించని స్వేచ్ఛ.","(అదనంగా: మత ప్రాతిపదికన వివక్ష నిషేధం; మతాల్లో సమానత్వం కోసం రాజ్యం జోక్యం – అంటరానితనం నిషేధం.)"]],["అభ్యాసాలు – ప్రశ్నలు 7–11 (పుట 90)",["7) జవాబు: (b) సమాజం స్త్రీ, పురుషులకు అంటగట్టిన అసమాన పాత్రలు.","8) జవాబు: (d) పంచాయతీరాజ్ సంస్థలు.","గమనిక: పుస్తకం రాసిన సమయానికి రిజర్వేషన్ స్థానిక సంస్థల్లోనే అమలులో ఉంది; 2023 చట్టం లోక్‌సభ, శాసనసభల్లో 1/3 రిజర్వేషన్ నిర్ణయించినా అది జనగణన, నియోజకవర్గాల పునర్విభజన తర్వాతే అమలులోకి వస్తుంది. పరీక్షలో పుస్తకం జవాబు (d) రాయాలి.","9) జవాబు: (c) A, C.","(మతతత్వం – ఒక మతం గొప్పది; ఒక మతానుచరులంతా ఒకే సమాజం. B, D లౌకికవాద భావాలు.)","10) తప్పైన వాక్యం: (b) ఒక మతానికి అధికార హోదా ఇస్తుంది.","11) ఖాళీ: కులం (Caste) ఆధారంగా సామాజిక విభజనలు భారత్‌కు ప్రత్యేకం."]],["అభ్యాసాలు – ప్రశ్న 12 (పుట 92)",["12) జవాబు: (b) – 1-B (స్త్రీ, పురుషులకు సమాన హక్కులు కోరేవారు → స్త్రీవాది), 2-A (మతమే సమాజానికి ప్రధాన ఆధారం అనేవారు → మతతత్వవాది), 3-D (కులమే ప్రధాన ఆధారం అనేవారు → కులతత్వవాది), 4-C (మత విశ్వాసాల ఆధారంగా వివక్ష చూపనివారు → లౌకికవాది)."]]]},{"id":"cv4","no":21,"t":"రాజకీయ పార్టీలు (Political Parties)","m":[10],"ty":"పౌరశాస్త్రం – అధ్యాయం 4","by":"సాంఘిక శాస్త్రం – ప్రజాస్వామ్య రాజకీయాలు-II, 10వ తరగతి (పుటలు 94–127)","th":"రాజకీయ పార్టీ అంటే, భాగాలు, విధులు, అవసరం, పార్టీ వ్యవస్థలు (ఏకపార్టీ, ద్విపార్టీ, బహుళపార్టీ), ప్రజల భాగస్వామ్యం, జాతీయ–రాష్ట్ర పార్టీలు, సవాళ్లు, సంస్కరణలు","sum":"రాజకీయ పార్టీ అంటే ఎన్నికల్లో పోటీ చేసి ప్రభుత్వంలో అధికారం చేపట్టడానికి కలిసే ప్రజల సమూహం; సమాజ సమష్టి శ్రేయస్సు కోసం కొన్ని విధానాలు, కార్యక్రమాలపై వారు ఏకీభవిస్తారు. పార్టీ సమాజంలోని ఒక భాగం (partisanship) – ఏ వర్గం వైపో, ఎవరి ప్రయోజనాలు కాపాడుతుందో దాని ద్వారానే గుర్తింపు. పార్టీకి మూడు భాగాలు – నాయకులు, క్రియాశీల సభ్యులు, అనుచరులు. విధులు: ఎన్నికల్లో పోటీ (అభ్యర్థుల ఎంపిక), విధానాలు–కార్యక్రమాలు ప్రజల ముందు ఉంచడం, చట్టాల తయారీ, ప్రభుత్వాల ఏర్పాటు–నిర్వహణ, ఓడిన పార్టీలు ప్రతిపక్షంగా విమర్శ, ప్రజాభిప్రాయాన్ని రూపొందించడం, ప్రభుత్వ యంత్రాంగం–సంక్షేమ పథకాలు ప్రజలకు అందేలా చేయడం. పార్టీలు లేకపోతే అందరూ స్వతంత్ర అభ్యర్థులే – దేశవ్యాప్త విధానాలు, బాధ్యత ఉండవు; అందుకే పార్టీలు ప్రాతినిధ్య ప్రజాస్వామ్యానికి తప్పనిసరి. ఎన్నికల సంఘంలో 750కి పైగా పార్టీలు నమోదు. పార్టీ వ్యవస్థలు – ఏకపార్టీ (చైనా – ప్రజాస్వామికం కాదు), ద్విపార్టీ (అమెరికా, బ్రిటన్), బహుళపార్టీ (భారత్ – సంకీర్ణాలు, కూటములు: 2004లో NDA, UPA, వామపక్ష ఫ్రంట్). ఏ దేశమూ పార్టీ వ్యవస్థను ఎంచుకోదు – అది సమాజ స్వభావం, చరిత్ర, ఎన్నికల విధానంతో కాలక్రమంలో ఏర్పడుతుంది. భారత్‌లో పార్టీలపై నమ్మకం తక్కువ అయినా పార్టీ సభ్యత్వం, కార్యకలాపాల్లో భాగస్వామ్యం ఎక్కువ, పెరుగుతోంది. గుర్తింపు: రాష్ట్ర శాసనసభ ఎన్నికల్లో కనీసం 6% ఓట్లు + 2 స్థానాలు → రాష్ట్ర పార్టీ; లోక్‌సభ లేదా నాలుగు రాష్ట్రాల శాసనసభ ఎన్నికల్లో 6% ఓట్లు + లోక్‌సభలో 4 స్థానాలు → జాతీయ పార్టీ. 2023 ఎన్నికల సంఘం ప్రకటన ప్రకారం ఆరు జాతీయ పార్టీలు – ఆమ్ ఆద్మీ పార్టీ (2012), బహుజన్ సమాజ్ పార్టీ (1984, కాన్షీరామ్), భారతీయ జనతా పార్టీ (1980; సమగ్ర మానవతావాదం, అంత్యోదయ), CPI(M) (1964), భారత జాతీయ కాంగ్రెస్ (1885), నేషనల్ పీపుల్స్ పార్టీ (2013, పి.ఎ. సంగ్మా – ఈశాన్యం నుండి తొలి జాతీయ పార్టీ). మిగిలినవి రాష్ట్ర (ప్రాంతీయ) పార్టీలు – 1996 నుండి సంకీర్ణ ప్రభుత్వాల్లో భాగమై సమాఖ్యను బలపరిచాయి. సవాళ్లు: అంతర్గత ప్రజాస్వామ్య లోపం, వారసత్వ రాజకీయాలు, డబ్బు–కండబలం, ఓటర్లకు అర్థవంతమైన ఎంపిక లేకపోవడం. సంస్కరణలు: పార్టీ ఫిరాయింపు నిరోధక చట్టం, అభ్యర్థుల ఆస్తులు–నేర కేసుల అఫిడవిట్ (సుప్రీంకోర్టు), పార్టీ సంస్థాగత ఎన్నికలు, ఆదాయపన్ను రిటర్నులు (ఎన్నికల సంఘం); సూచనలు – పార్టీల అంతర్గత వ్యవహారాలపై చట్టం, మహిళలకు 1/3 టికెట్లు, ఎన్నికలకు ప్రభుత్వ నిధులు; ప్రజల ఒత్తిడి, ప్రజలు పార్టీల్లో చేరడం. “చెడు రాజకీయాలకు పరిష్కారం మరిన్ని, మంచి రాజకీయాలు.”","pts":["రాజకీయ పార్టీ: ఎన్నికల్లో పోటీ చేసి ప్రభుత్వంలో అధికారం చేపట్టడానికి కలిసే ప్రజల సమూహం; సమష్టి శ్రేయస్సు కోసం కొన్ని విధానాలు, కార్యక్రమాలపై ఏకీభవిస్తారు.","పక్షపాతం (Partisanship): పార్టీ సమాజంలో ఒక భాగం; ఏ వర్గం వైపో, ఎవరి ప్రయోజనాలు కాపాడుతుందో దాన్ని బట్టి గుర్తింపు; Partisan = ఒక పార్టీ/వర్గానికి గట్టిగా కట్టుబడిన వ్యక్తి.","పార్టీ మూడు భాగాలు: నాయకులు, క్రియాశీల సభ్యులు, అనుచరులు.","విధి 1 – ఎన్నికల్లో పోటీ: అభ్యర్థుల ఎంపిక (అమెరికాలో సభ్యులు, ఓటర్లు ఎంచుకుంటారు; భారత్‌లో అగ్ర నాయకులు).","విధి 2 – విభిన్న విధానాలు, కార్యక్రమాలు ప్రజల ముందు ఉంచడం; ప్రజలు ఎంచుకుంటారు; అధికార పార్టీ వాటినే అమలు చేస్తుంది.","విధి 3 – చట్టాల తయారీలో నిర్ణయాత్మక పాత్ర (శాసనసభ్యులు పార్టీ నాయకత్వాన్ని అనుసరిస్తారు).","విధి 4 – ప్రభుత్వాల ఏర్పాటు, నిర్వహణ; నాయకులను తయారుచేయడం, శిక్షణ, మంత్రులుగా నియమించడం.","విధి 5 – ఓడిన పార్టీలు ప్రతిపక్షంగా ప్రభుత్వ వైఫల్యాలు, తప్పుడు విధానాలను విమర్శించడం, ప్రజలను సమీకరించడం.","విధి 6 – ప్రజాభిప్రాయాన్ని రూపొందించడం: సమస్యలు లేవనెత్తడం, ఉద్యమాలు, లక్షలాది కార్యకర్తలు.","విధి 7 – ప్రభుత్వ యంత్రాంగం, సంక్షేమ పథకాలు ప్రజలకు అందేలా చేయడం – స్థానిక నాయకుడు సులభంగా అందుబాటులో ఉంటాడు.","పార్టీల అవసరం: పార్టీలు లేకపోతే అందరూ స్వతంత్ర అభ్యర్థులు – ప్రధాన విధాన మార్పులపై హామీ ఇవ్వలేరు; ప్రభుత్వ స్థిరత్వం, బాధ్యత ఉండవు; పంచాయతీ ఎన్నికలు పార్టీ రహితమైనా గ్రామం వర్గాలుగా విడిపోతుంది.","ఏకపార్టీ వ్యవస్థ: ఒకే పార్టీ పాలన – చైనాలో కమ్యూనిస్ట్ పార్టీ; స్వేచ్ఛాయుత పోటీ లేదు – ప్రజాస్వామికం కాదు.","ద్విపార్టీ వ్యవస్థ: అధికారం సాధారణంగా రెండు ప్రధాన పార్టీల మధ్య మారుతుంది – అమెరికా, బ్రిటన్.","బహుళపార్టీ వ్యవస్థ: రెండు కంటే ఎక్కువ పార్టీలకు సొంతంగా/కూటమిగా అధికారంలోకి వచ్చే అవకాశం – భారత్; కూటమి/ఫ్రంట్ (2004లో NDA, UPA, వామపక్ష ఫ్రంట్); అస్థిరంగా అనిపించినా వివిధ ప్రయోజనాలకు ప్రాతినిధ్యం.","పార్టీ వ్యవస్థను ఏ దేశమూ ఎంచుకోదు – సమాజ స్వభావం, సామాజిక–ప్రాంతీయ విభజనలు, రాజకీయ చరిత్ర, ఎన్నికల విధానంతో కాలక్రమంలో ఏర్పడుతుంది.","ప్రజల భాగస్వామ్యం: దక్షిణాసియాలో, ప్రపంచమంతా పార్టీలపై నమ్మకం తక్కువ; కానీ భారత్‌లో పార్టీ సభ్యత్వం కెనడా, జపాన్, స్పెయిన్, దక్షిణ కొరియా కంటే ఎక్కువ, 30 ఏళ్లుగా పెరుగుతోంది.","గుర్తింపు పొందిన పార్టీలు: ఎన్నికల సంఘం ప్రత్యేక ఎన్నికల చిహ్నం, ఇతర సౌకర్యాలు ఇస్తుంది; రాష్ట్ర పార్టీ = శాసనసభ ఎన్నికల్లో 6% ఓట్లు + 2 స్థానాలు; జాతీయ పార్టీ = లోక్‌సభ/నాలుగు రాష్ట్రాల ఎన్నికల్లో 6% ఓట్లు + లోక్‌సభలో 4 స్థానాలు.","ఆరు జాతీయ పార్టీలు (2023): AAP, BSP, BJP, CPI(M), INC, NPP.","AAP – 26 నవంబర్ 2012, అవినీతి వ్యతిరేక ఉద్యమం తర్వాత; జవాబుదారీతనం, పారదర్శకత, సుపరిపాలన. BSP – 1984, కాన్షీరామ్; బహుజన సమాజం (దళితులు, ఆదివాసీలు, OBCలు, మత మైనారిటీలు); సాహు మహరాజ్, ఫూలే, పెరియార్, అంబేద్కర్ స్ఫూర్తి; ప్రధాన బలం ఉత్తర్‌ప్రదేశ్.","BJP – 1980 (1951 భారతీయ జనసంఘ్ – శ్యామా ప్రసాద్ ముఖర్జీ); దీన్‌దయాళ్ ఉపాధ్యాయ సమగ్ర మానవతావాదం, అంత్యోదయ; సాంస్కృతిక జాతీయవాదం; 2019లో 303 స్థానాలు; NDA నాయకత్వం.","CPI(M) – 1964; మార్క్సిజం–లెనినిజం, సోషలిజం, లౌకికవాదం; పశ్చిమ బెంగాల్ (34 ఏళ్లు నిరంతర పాలన), కేరళ, త్రిపుర. INC – 1885, ప్రపంచంలోని పురాతన పార్టీల్లో ఒకటి; నెహ్రూ నాయకత్వం; మధ్యేవాద పార్టీ; 2004–2014 UPA ప్రభుత్వ నాయకత్వం (పుస్తకంలో “2004 to 2019” అని ఉంది – UPA ప్రభుత్వం 2014 వరకే); 2019లో 19.5% ఓట్లు, 52 స్థానాలు.","NPP – జూలై 2013, పి.ఎ. సంగ్మా; ఈశాన్య భారతం నుండి జాతీయ హోదా పొందిన తొలి పార్టీ; మేఘాలయలో ప్రభుత్వం.","రాష్ట్ర (ప్రాంతీయ) పార్టీలు: సమాజ్‌వాదీ పార్టీ, RJD, బిజూ జనతాదళ్, సిక్కిం డెమోక్రటిక్ ఫ్రంట్, మిజో నేషనల్ ఫ్రంట్, తెలంగాణ రాష్ట్ర సమితి, తెలుగుదేశం వంటివి; 1996 నుండి కేంద్ర సంకీర్ణాల్లో భాగం → సమాఖ్య, ప్రజాస్వామ్యం బలపడ్డాయి.","సవాలు 1 – అంతర్గత ప్రజాస్వామ్య లోపం: అధికారం ఒకరిద్దరు నాయకుల చేతిలో; సభ్యత్వ రిజిస్టర్లు, సమావేశాలు, అంతర్గత ఎన్నికలు లేవు; నాయకుడి పట్ల వ్యక్తిగత విధేయతే ముఖ్యం.","సవాలు 2 – వారసత్వ రాజకీయాలు: అగ్ర పదవులు ఒకే కుటుంబం చేతిలో; సామాన్య కార్యకర్త పైకి రాలేడు; అనుభవం, ప్రజాదరణ లేనివారు అధికారంలోకి.","సవాలు 3 – డబ్బు, కండబలం: ధనవంతులైన అభ్యర్థులు, నిధులిచ్చే కంపెనీల ప్రభావం, నేరచరితులకు మద్దతు.","సవాలు 4 – అర్థవంతమైన ఎంపిక లేకపోవడం: పార్టీల మధ్య సైద్ధాంతిక తేడాలు తగ్గడం (బ్రిటన్‌లో లేబర్–కన్జర్వేటివ్); నాయకులు పార్టీలు మారడం.","సంస్కరణలు (జరిగినవి): రాజ్యాంగ సవరణ – ఫిరాయింపు చేస్తే శాసనసభ్యత్వం పోతుంది; సుప్రీంకోర్టు – అభ్యర్థులు ఆస్తులు, నేర కేసుల అఫిడవిట్ ఇవ్వాలి; ఎన్నికల సంఘం – పార్టీలు సంస్థాగత ఎన్నికలు జరపాలి, ఆదాయపన్ను రిటర్నులు దాఖలు చేయాలి.","సంస్కరణ సూచనలు: పార్టీల అంతర్గత వ్యవహారాలపై చట్టం (సభ్యత్వ రిజిస్టర్, పార్టీ రాజ్యాంగం, స్వతంత్ర న్యాయ సంస్థ, బహిరంగ ఎన్నికలు); మహిళలకు 1/3 టికెట్లు, పార్టీ నిర్ణయ సంస్థల్లో కోటా; ఎన్నికలకు ప్రభుత్వ నిధులు (నగదు లేదా వస్తు రూపంలో).","ఇతర మార్గాలు: ప్రజలు, ఒత్తిడి వర్గాలు, ఉద్యమాలు, మీడియా పిటిషన్లు, ప్రచారం, ఆందోళనలతో ఒత్తిడి; సంస్కరణ కోరేవారు పార్టీల్లో చేరడం – “చెడు రాజకీయాలకు పరిష్కారం మరిన్ని, మంచి రాజకీయాలు”; అతి నియంత్రణ ప్రమాదకరం."],"w":[["రాజకీయ పార్టీ","Political party"],["పక్షపాతం","Partisanship"],["పక్షపాతి (ఒక పార్టీకి గట్టి మద్దతుదారు)","Partisan"],["అధికార పార్టీ","Ruling party"],["ప్రతిపక్షం","Opposition"],["ఏకపార్టీ వ్యవస్థ","One-party system"],["ద్విపార్టీ వ్యవస్థ","Two-party system"],["బహుళపార్టీ వ్యవస్థ","Multiparty system"],["కూటమి / ఫ్రంట్","Alliance / Front"],["గుర్తింపు పొందిన పార్టీ","Recognised party"],["జాతీయ పార్టీ","National party"],["రాష్ట్ర పార్టీ","State party"],["ఫిరాయింపు (పార్టీ మారడం)","Defection"],["అఫిడవిట్ (ప్రమాణ పత్రం)","Affidavit"],["వారసత్వ రాజకీయాలు","Dynastic succession"],["అంతర్గత ప్రజాస్వామ్యం","Internal democracy"],["ఎన్నికల చిహ్నం","Election symbol"],["సమగ్ర మానవతావాదం","Integral humanism"]],"gr":{"t":"ఆరు జాతీయ పార్టీలు (ఎన్నికల సంఘం, 2023)","p":["పార్టీ | స్థాపన | ముఖ్యాంశం","భారత జాతీయ కాంగ్రెస్ (INC) | 1885 | మధ్యేవాద, లౌకికవాదం, బలహీన వర్గాల సంక్షేమం","భారతీయ జనతా పార్టీ (BJP) | 1980 | సమగ్ర మానవతావాదం, అంత్యోదయ, సాంస్కృతిక జాతీయవాదం","CPI(M) | 1964 | మార్క్సిజం–లెనినిజం, సోషలిజం, లౌకికవాదం","బహుజన్ సమాజ్ పార్టీ (BSP) | 1984 | కాన్షీరామ్; బహుజన సమాజం (దళితులు, ఆదివాసీలు, OBC, మైనారిటీలు)","ఆమ్ ఆద్మీ పార్టీ (AAP) | 2012 | అవినీతి వ్యతిరేకత, పారదర్శకత, సుపరిపాలన","నేషనల్ పీపుల్స్ పార్టీ (NPP) | 2013 | పి.ఎ. సంగ్మా; ఈశాన్యం నుండి తొలి జాతీయ పార్టీ"]},"qa":[["రాజకీయ పార్టీ అంటే ఏమిటి?","ఎన్నికల్లో పోటీ చేసి ప్రభుత్వంలో అధికారం చేపట్టడానికి కలిసే ప్రజల సమూహం; సమష్టి శ్రేయస్సు కోసం కొన్ని విధానాలపై ఏకీభవిస్తారు."],["రాజకీయ పార్టీ మూడు భాగాలు?","నాయకులు, క్రియాశీల సభ్యులు, అనుచరులు."],["ఏకపార్టీ వ్యవస్థకు ఉదాహరణ?","చైనా (కమ్యూనిస్ట్ పార్టీ)."],["ద్విపార్టీ వ్యవస్థ ఉన్న దేశాలు?","అమెరికా, బ్రిటన్ (యునైటెడ్ కింగ్‌డమ్)."],["రాష్ట్ర పార్టీగా గుర్తింపు నిబంధన?","రాష్ట్ర శాసనసభ ఎన్నికల్లో కనీసం 6% ఓట్లు, కనీసం 2 స్థానాలు."],["జాతీయ పార్టీగా గుర్తింపు నిబంధన?","లోక్‌సభ లేదా నాలుగు రాష్ట్రాల శాసనసభ ఎన్నికల్లో కనీసం 6% ఓట్లు + లోక్‌సభలో కనీసం 4 స్థానాలు."],["BSP స్థాపకుడు?","కాన్షీరామ్ (1984)."],["BJP మార్గదర్శక తత్వం?","దీన్‌దయాళ్ ఉపాధ్యాయ సమగ్ర మానవతావాదం (Integral humanism), అంత్యోదయ."],["ఫిరాయింపు అంటే?","ఏ పార్టీ తరఫున ఎన్నికయ్యారో ఆ పార్టీని వదిలి మరో పార్టీలో చేరడం."],["అఫిడవిట్‌లో అభ్యర్థులు ఏమి తెలపాలి?","తమ ఆస్తుల వివరాలు, తమపై పెండింగ్‌లో ఉన్న నేర కేసులు."]],"act":"మీ ప్రాంతంలోని రాజకీయ పార్టీల ఎన్నికల చిహ్నాలు, వాటి నాయకుల పేర్లు సేకరించి చార్ట్ తయారుచేయండి. ఏ పార్టీ జాతీయ పార్టీ, ఏది రాష్ట్ర పార్టీ అని గుర్తించండి. పత్రికల్లో వచ్చే పార్టీల కార్యక్రమాల ఫోటోలను “పార్టీ విధుల” వారీగా అతికించండి.","kn":"భారత ఎన్నికల సంఘంలో 750కి పైగా రాజకీయ పార్టీలు నమోదై ఉన్నాయి! కానీ గుర్తింపు పొందిన పార్టీలకే ప్రత్యేక ఎన్నికల చిహ్నం దక్కుతుంది.","qz":[["ఎన్నికల్లో పోటీ చేసి అధికారం చేపట్టడానికి కలిసే ప్రజల సమూహం?","రాజకీయ పార్టీ","ఒత్తిడి వర్గం","ఉద్యమం","కూటమి ప్రభుత్వం"],["రాజకీయ పార్టీ భాగం కానిది?","న్యాయమూర్తులు","నాయకులు","క్రియాశీల సభ్యులు","అనుచరులు"],["ఏకపార్టీ వ్యవస్థ ఉన్న దేశం?","చైనా","అమెరికా","భారత్","బ్రిటన్"],["ద్విపార్టీ వ్యవస్థకు ఉదాహరణ?","అమెరికా","భారత్","చైనా","నేపాల్"],["భారత్‌లో ఉన్న పార్టీ వ్యవస్థ?","బహుళపార్టీ","ఏకపార్టీ","ద్విపార్టీ","పార్టీ రహితం"],["భారత ఎన్నికల సంఘంలో నమోదైన పార్టీలు?","750కి పైగా","6","50","100"],["రాష్ట్ర పార్టీ గుర్తింపుకు కావలసిన కనీస ఓట్ల శాతం?","6%","4%","10%","2%"],["2023 నాటికి జాతీయ పార్టీల సంఖ్య?","ఆరు","ఏడు","ఎనిమిది","నాలుగు"],["బహుజన్ సమాజ్ పార్టీ స్థాపకుడు?","కాన్షీరామ్","సాహు మహరాజ్","బి.ఆర్. అంబేద్కర్","జ్యోతిబా ఫూలే"],["BJP మార్గదర్శక తత్వం?","సమగ్ర మానవతావాదం","బహుజన సమాజం","విప్లవాత్మక ప్రజాస్వామ్యం","ఆధునికత"],["ఈశాన్యం నుండి జాతీయ హోదా పొందిన తొలి పార్టీ?","నేషనల్ పీపుల్స్ పార్టీ","మిజో నేషనల్ ఫ్రంట్","సిక్కిం డెమోక్రటిక్ ఫ్రంట్","ఆమ్ ఆద్మీ పార్టీ"],["భారత జాతీయ కాంగ్రెస్ స్థాపన?","1885","1964","1980","1947"],["CPI(M) వరుసగా 34 ఏళ్లు పాలించిన రాష్ట్రం?","పశ్చిమ బెంగాల్","కేరళ","త్రిపుర","పంజాబ్"],["ఎన్నికైన పార్టీని వదిలి మరో పార్టీలో చేరడం?","ఫిరాయింపు","అఫిడవిట్","సంకీర్ణం","వారసత్వం"],["అభ్యర్థులు ఆస్తులు, నేర కేసుల అఫిడవిట్ ఇవ్వాలని ఆదేశించినది?","సుప్రీంకోర్టు","పార్లమెంటు","రాష్ట్రపతి","ప్రధానమంత్రి"],["ఒకే కుటుంబం చేతిలో అగ్ర పదవులు ఉండటం – ఏ సవాలు?","వారసత్వ రాజకీయాలు","ఫిరాయింపు","బహుళపార్టీ వ్యవస్థ","అంతర్గత ఎన్నికలు"]],"wb":{"mis":"పార్టీలు ప్రజలను విడదీయడానికే అనేది తప్పు – అవి ప్రాతినిధ్య ప్రజాస్వామ్యానికి తప్పనిసరి. ప్రాంతీయ పార్టీల ఆలోచన ప్రాంతీయమే కానవసరం లేదు. పార్టీ వ్యవస్థను దేశాలు కోరి ఎంచుకోవు – కాలక్రమంలో ఏర్పడుతుంది.","pg":"94–127","f":"books/10/Class10_Social_Civics_Textbook.pdf","p":96,"lb":"పాఠ్యపుస్తకం","ws":["ఆలోచించండి – “పార్టీలు ప్రజలను విడదీస్తాయి” (పుట 96)","ఆలోచించండి – ప్రజలు పార్టీకి ఎందుకు మద్దతిస్తారు? (పుట 100)","కృత్యం – ఫోటోలను పార్టీ విధుల వారీగా (పుట 102)","కృత్యం – రాష్ట్రాల్లో పార్టీ వ్యవస్థలు (పుట 104)","కార్టూన్ – “Crunching the Numbers” (పుట 108)","ఆలోచించండి – మహిళలకు టికెట్లు ఎందుకు తక్కువ? (పుట 116)","ఆలోచించండి – కార్టూన్లు, డబ్బు–కండబలం (పుట 120)","ఆలోచించండి – పార్టీల అంతర్గత వ్యవహారాలపై చట్టం (పుట 122)","అభ్యాసాలు – ప్రశ్నలు 1–3 (పుట 124)","అభ్యాసాలు – ప్రశ్నలు 4–9 (పుట 124)","అభ్యాసాలు – ప్రశ్నలు 10–11 (పుట 126)"]},"tg":[["ఆలోచించండి – “పార్టీలు ప్రజలను విడదీస్తాయి” (పుట 96)",["1) పార్టీ (party) అంటేనే సమాజంలోని ఒక “భాగం” – భిన్న అభిప్రాయాలు, ప్రయోజనాలు ఉండటం ప్రజాస్వామ్యంలో సహజం.","2) పార్టీలు ఆ భిన్నత్వాన్ని శాంతియుత పోటీ, చర్చ ద్వారా వ్యక్తం చేస్తాయి; ఇది విభజన కాదు, ప్రజల ముందు ఎంపికలు ఉంచడం.","3) పార్టీలు లేకపోతే ప్రభుత్వం ఏర్పాటు, విధానాల తయారీ, బాధ్యత అసాధ్యం. కాబట్టి “విడదీయడమే వాటి పని” అనడం సరికాదు.","గోడ రాతలు (ఫోటోలు): ఎన్నికల సంఘం నిషేధించింది – గోడలు పాడవడం, ప్రైవేటు ఆస్తి దుర్వినియోగం; పార్టీలకు చౌక ప్రచారం అయినా పరిశుభ్రత, నియమావళి ముఖ్యం."]],["ఆలోచించండి – ప్రజలు పార్టీకి ఎందుకు మద్దతిస్తారు? (పుట 100)",["1) పార్టీ విధానాలు, కార్యక్రమాలు, సిద్ధాంతం నచ్చడం.","2) నాయకుడి ప్రజాదరణ, నిజాయితీ, పనితీరు.","3) ప్రభుత్వంలో ఉన్నప్పుడు చేసిన అభివృద్ధి, సంక్షేమ పథకాలు.","4) తమ వర్గం/ప్రాంతం ప్రయోజనాలు కాపాడుతుందనే నమ్మకం; కుటుంబ సంప్రదాయం."]],["కృత్యం – ఫోటోలను పార్టీ విధుల వారీగా (పుట 102)",["1) విశాఖపట్నంలో ఉల్లి, LPG ధరల పెంపుపై BJP మహిళా మోర్చా నిరసన → ప్రతిపక్ష పాత్ర, ప్రజాభిప్రాయం రూపొందించడం (సమస్యలు లేవనెత్తడం).","2) కల్తీ సారా బాధిత కుటుంబాలకు మంత్రి రూ.1 లక్ష చెక్కులు పంపిణీ → ప్రభుత్వ నిర్వహణ, సంక్షేమ పథకాలు ప్రజలకు అందించడం.","3) భువనేశ్వర్‌లో POSCO కు ఇనుప ఖనిజ ఎగుమతి అనుమతిపై CPI(M), CPI, OGP, JD(S) ర్యాలీ → ప్రతిపక్షం, ప్రజాభిప్రాయం సమీకరణ.","4) మీ ప్రాంతం నుండి ఒక్కో విధికి ఒక ఫోటో/వార్త సేకరించండి – ఉదా: అభ్యర్థి నామినేషన్ (ఎన్నికల్లో పోటీ), ఎన్నికల మేనిఫెస్టో (విధానాలు), అసెంబ్లీ చర్చ (చట్టాలు), ధర్నా (ప్రతిపక్షం). (విద్యార్థుల సొంత పని)"]],["కృత్యం – రాష్ట్రాల్లో పార్టీ వ్యవస్థలు (పుట 104)",["1) ద్విపార్టీ వ్యవస్థ: రాజస్థాన్, మధ్యప్రదేశ్, గుజరాత్, హిమాచల్ ప్రదేశ్ (ప్రధానంగా BJP vs కాంగ్రెస్).","2) రెండు కూటములతో బహుళపార్టీ వ్యవస్థ: కేరళ (LDF vs UDF), తమిళనాడు (DMK కూటమి vs AIADMK కూటమి); ఆంధ్రప్రదేశ్ 2024 (TDP–జనసేన–BJP కూటమి vs YSRCP) కూడా ఉదాహరణగా చెప్పవచ్చు.","3) బహుళపార్టీ వ్యవస్థ: ఉత్తర్‌ప్రదేశ్ (BJP, SP, BSP, కాంగ్రెస్), బీహార్, పశ్చిమ బెంగాల్. (ఎన్నికల తర్వాత పరిస్థితి మారవచ్చు – తాజా సమాచారంతో సరిచూడండి.)","“ఇన్ని పార్టీల కూటములను నాయకులు ఎలా నడుపుతారు?” – ఉమ్మడి కనీస కార్యక్రమం, పదవుల పంపకం, సమన్వయ కమిటీ, తరచూ సంప్రదింపులతో."]],["కార్టూన్ – “Crunching the Numbers” (పుట 108)",["1) అవును – కార్టూన్ ముందు పుటలోని గణాంకాలను ప్రతిబింబిస్తుంది.","2) ఏ పార్టీ అధికారంలో ఉండాలో ప్రజల మద్దతు చీలి (27%, 35%) ఉంది; కానీ 98% మంది రాజకీయ నాయకులందరి పట్ల తీవ్ర అసంతృప్తితో ఉన్నారు.","3) అంటే పార్టీలు, నాయకులు ప్రపంచమంతా అత్యంత తక్కువ నమ్మకం ఉన్న సంస్థలు – భారత్‌లోనూ ఇదే; అయినా భారత్‌లో పార్టీ సభ్యత్వం, భాగస్వామ్యం ఎక్కువ."]],["ఆలోచించండి – మహిళలకు టికెట్లు ఎందుకు తక్కువ? (పుట 116)",["1) అవును, ఇది అంతర్గత ప్రజాస్వామ్య లోపానికి సంబంధించినదే – టికెట్ల నిర్ణయం కొద్దిమంది అగ్ర నాయకుల చేతిలో ఉంటుంది; వారు ఎక్కువగా పురుషులు.","2) “గెలిచే అవకాశం”, డబ్బు, కండబలం చూసి టికెట్లు ఇవ్వడం; మహిళలకు ఆర్థిక బలం, నెట్‌వర్క్ తక్కువ.","3) పితృస్వామ్య భావనలు. పరిష్కారం: పార్టీల్లో మహిళలకు 1/3 టికెట్లు, నిర్ణయ సంస్థల్లో కోటా.","బెర్లుస్కోనీ కార్టూన్: ఇటలీ ప్రధాని, పెద్ద వ్యాపారవేత్త – టీవీ ఛానళ్లు, ప్రచురణ సంస్థ, ఫుట్‌బాల్ క్లబ్, బ్యాంకు యజమాని; డబ్బు, మీడియా బలంతో రాజకీయాలను “తోలుబొమ్మలాట”లా నడపడం – డబ్బు బలం, అంతర్గత ప్రజాస్వామ్య లోపం."]],["ఆలోచించండి – కార్టూన్లు, డబ్బు–కండబలం (పుట 120)",["“ప్రజాస్వామ్యంలో డబ్బు సంపాదనకే ఎన్నికల్లో పోటీ చేస్తారా?” – కార్టూన్ డబ్బున్నవారే పోటీ చేస్తూ, రాజకీయాల్ని మరింత డబ్బుకు వాడుకుంటున్న ధోరణిని విమర్శిస్తుంది. కానీ అందరూ అలా కాదు – ప్రజా సంక్షేమం కోసం నిజాయితీగా పనిచేసే నాయకులూ ఉన్నారు (ఉదా: సాధారణ కుటుంబాల నుండి వచ్చి సేవకు గుర్తింపు పొందిన నాయకులు).","కార్టూన్లలో సవాళ్లు: బెర్లుస్కోనీ తోలుబొమ్మలాట – డబ్బు/మీడియా బలం, అంతర్గత ప్రజాస్వామ్య లోపం; ఏనుగు (రిపబ్లికన్ పార్టీ) – కార్పొరేట్ అమెరికా ప్రభావం = డబ్బు బలం; “మీ దగ్గర ఇప్పటికే చాలా డబ్బుంది…” – డబ్బు బలం.","డబ్బు, కండబలం అరికట్టే మార్గాలు: 1) అభ్యర్థుల ఆస్తులు, నేర కేసుల అఫిడవిట్ – సమాచారాన్ని నిజమో కాదో తనిఖీ చేయాలి.","2) నేరచరితులు పోటీ చేయకుండా కఠిన నిబంధనలు.","3) ఎన్నికలకు ప్రభుత్వ నిధులు (state funding).","4) పార్టీల ఆదాయ–వ్యయాల పారదర్శకత, ఆడిట్.","5) ఎన్నికల ఖర్చు పరిమితి కఠిన అమలు.","6) ఓటర్ల చైతన్యం – డబ్బు, మద్యం తీసుకోకుండా ఓటు వేయడం; మీడియా నిఘా."]],["ఆలోచించండి – పార్టీల అంతర్గత వ్యవహారాలపై చట్టం (పుట 122)",["1) పార్టీలు ఈ చట్టాన్ని సులభంగా అంగీకరించవు – నాయకుల అధికారం తగ్గుతుంది; చట్టం చేసేది కూడా వారే.","2) అతి నియంత్రణ వల్ల పార్టీలు చట్టాన్ని మోసగించే మార్గాలు వెతుకుతాయి.","3) అందుకే ప్రజల ఒత్తిడి, మీడియా, ఉద్యమాలు, మంచివారు పార్టీల్లో చేరడం వంటి మార్గాలు కూడా అవసరం."]],["అభ్యాసాలు – ప్రశ్నలు 1–3 (పుట 124)",["1) ప్రజాస్వామ్యంలో పార్టీల విధులు:","(i) ఎన్నికల్లో పోటీ – అభ్యర్థులను ఎంచుకొని నిలబెడతాయి.","(ii) విభిన్న విధానాలు, కార్యక్రమాలు ప్రజల ముందు ఉంచుతాయి – ప్రజలు ఎంచుకుంటారు.","(iii) దేశానికి చట్టాలు చేయడంలో నిర్ణయాత్మక పాత్ర.","(iv) ప్రభుత్వాలను ఏర్పాటు చేసి నడుపుతాయి; నాయకులను తయారుచేస్తాయి.","(v) ఓడిన పార్టీలు ప్రతిపక్షంగా ప్రభుత్వాన్ని విమర్శించి, ప్రజలను సమీకరిస్తాయి.","(vi) సమస్యలు లేవనెత్తి ప్రజాభిప్రాయాన్ని రూపొందిస్తాయి.","(vii) ప్రభుత్వ యంత్రాంగం, సంక్షేమ పథకాలు ప్రజలకు అందేలా చేస్తాయి.","2) పార్టీలు ఎదుర్కొనే సవాళ్లు:","(i) అంతర్గత ప్రజాస్వామ్య లోపం – అధికారం ఒకరిద్దరు అగ్ర నాయకుల చేతిలో; సభ్యత్వ రిజిస్టర్లు, సమావేశాలు, అంతర్గత ఎన్నికలు లేవు; భిన్నాభిప్రాయం ఉన్నవారు పార్టీలో ఉండలేరు.","(ii) వారసత్వ రాజకీయాలు – అగ్ర పదవులు ఒకే కుటుంబం చేతిలో; సామాన్య కార్యకర్తకు అవకాశం లేదు.","(iii) డబ్బు, కండబలం – ధనవంతులైన అభ్యర్థులు, కంపెనీల ప్రభావం, నేరచరితులకు మద్దతు.","(iv) అర్థవంతమైన ఎంపిక లేకపోవడం – పార్టీల మధ్య సైద్ధాంతిక తేడాలు తగ్గడం, అవే నాయకులు పార్టీలు మారడం.","3) పార్టీలను బలోపేతం చేసే సంస్కరణలు:","(i) పార్టీల అంతర్గత వ్యవహారాలపై చట్టం – సభ్యత్వ రిజిస్టర్, పార్టీ రాజ్యాంగం పాటించడం, వివాదాలకు స్వతంత్ర సంస్థ, అగ్ర పదవులకు బహిరంగ ఎన్నికలు.","(ii) మహిళలకు కనీసం 1/3 టికెట్లు, పార్టీ నిర్ణయ సంస్థల్లో కోటా.","(iii) ఎన్నికలకు ప్రభుత్వ నిధులు – పెట్రోలు, కాగితం, ఫోన్ వంటివి లేదా గత ఎన్నికల ఓట్ల ఆధారంగా నగదు.","(iv) ఫిరాయింపు నిరోధక చట్టం, అఫిడవిట్, సంస్థాగత ఎన్నికలు, ఆదాయపన్ను రిటర్నుల వంటి నిబంధనల కఠిన అమలు.","(v) ప్రజలు, మీడియా, ఉద్యమాల ఒత్తిడి; సంస్కరణ కోరే పౌరులు పార్టీల్లో చేరడం."]],["అభ్యాసాలు – ప్రశ్నలు 4–9 (పుట 124)",["4) రాజకీయ పార్టీ: ఎన్నికల్లో పోటీ చేసి ప్రభుత్వంలో అధికారం చేపట్టడానికి కలిసే ప్రజల సమూహం. సమాజ సమష్టి శ్రేయస్సు కోసం కొన్ని విధానాలు, కార్యక్రమాలపై వారు ఏకీభవిస్తారు; తమ విధానాలు మంచివని ప్రజలను ఒప్పించి ఎన్నికల్లో గెలిచి వాటిని అమలు చేయాలని చూస్తారు.","5) రాజకీయ పార్టీ లక్షణాలు:","(i) ఉమ్మడి విధానాలు, కార్యక్రమాలు, సిద్ధాంతం ఉన్న ప్రజల సమూహం.","(ii) ఎన్నికల్లో పోటీ చేసి అధికారం చేపట్టడం లక్ష్యం.","(iii) సమాజంలో ఒక భాగానికి ప్రాతినిధ్యం (పక్షపాతం) – ఏ వర్గం వైపో దాని ద్వారా గుర్తింపు.","(iv) మూడు భాగాలు – నాయకులు, క్రియాశీల సభ్యులు, అనుచరులు.","(v) ప్రజల మద్దతు కూడగట్టి, సమాజ సమష్టి శ్రేయస్సు కోసం పనిచేస్తామని చెబుతుంది.","6) ఖాళీ: రాజకీయ పార్టీ (Political party).","7) జవాబు: (c) – 1-C (కాంగ్రెస్ పార్టీ – UPA), 2-A (BJP – NDA), 3-D (CPI(M) – వామపక్ష ఫ్రంట్), 4-B (తెలుగుదేశం పార్టీ – రాష్ట్ర పార్టీ).","8) జవాబు: A. కాన్షీరామ్.","9) జవాబు: C. సమగ్ర మానవతావాదం (Integral humanism)."]],["అభ్యాసాలు – ప్రశ్నలు 10–11 (పుట 126)",["10) జవాబు: (b) A, B.","(C తప్పు – ప్రభుత్వాలు నడపడానికి పార్టీలు అవసరం.)","11) యూనస్ కొత్త పార్టీ – (నమూనా జవాబు):","(i) నిర్ణయం సరైనదే – ప్రజాస్వామ్యంలో ఏ పౌరుడైనా పార్టీ పెట్టవచ్చు; అవినీతి లేని, సుపరిపాలన ఇచ్చే కొత్త ప్రత్యామ్నాయం ప్రజలకు అర్థవంతమైన ఎంపికను ఇస్తుంది (“చెడు రాజకీయాలకు పరిష్కారం మంచి రాజకీయాలు”).","(ii) షాహెదుల్ ఇస్లాం ఆశతో ఏకీభవిస్తాను; పాత పార్టీల భయం వారి అధికారం పోతుందనే ఆందోళనే; “విదేశీ శక్తుల మద్దతు” అనే అనుమానానికి ఆధారం లేదు – ఆరోపణ కాదు, పనితీరే కొలమానం కావాలి.","(iii) పార్టీ నిర్మాణం: సభ్యత్వ రిజిస్టర్, క్రమం తప్పని అంతర్గత ఎన్నికలు, అట్టడుగు స్థాయి నుండి ప్రజాస్వామ్యం, వారసత్వ రాజకీయాలు లేకపోవడం, మహిళలకు 1/3 టికెట్లు, నిధుల పారదర్శకత (ఆడిట్, ఆదాయపన్ను రిటర్నులు), నేరచరితులకు టికెట్ లేదు.","(iv) సమర్థన: “మా పార్టీ అధికారం కోసం కాదు, కొత్త రాజకీయ సంస్కృతి కోసం; ప్రజలే మా బలం; మా లెక్కలు, నిర్ణయాలు అందరికీ బహిరంగం; మా పనితీరు చూసి తీర్పు చెప్పండి.”"]]]}];
